import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

// Helper to determine faction style based on color
// Red/Purple/Green(Poison) = Chaos/Horde
// Blue/Gold/White = Order/Alliance
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    // Red, Dark Red, Orange, Purple, Poison Green
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58');
}

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         const grad = ctx.createRadialGradient(cx, cy, r * 0.1, cx, cy, r);
         grad.addColorStop(0, '#fff');        
         grad.addColorStop(0.3, color);       
         grad.addColorStop(1, 'transparent'); 

         ctx.fillStyle = grad;

         if (isChaos) {
             // Chaos: Unstable blob
             ctx.beginPath();
             for(let i=0; i<8; i++) {
                 const angle = (i / 8) * Math.PI * 2;
                 const rad = r * (0.8 + Math.random() * 0.2);
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();
         } else {
             // Order: Perfect Sphere or Star
             ctx.beginPath(); 
             ctx.arc(cx, cy, r, 0, Math.PI * 2); 
             ctx.fill();

             // Lens flare cross
             ctx.fillStyle = '#fff';
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.ellipse(cx, cy, r*0.8, r*0.1, 0, 0, Math.PI*2);
             ctx.ellipse(cx, cy, r*0.1, r*0.8, 0, 0, Math.PI*2);
             ctx.fill();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(0.6, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.5;

        // Irregular Cloud Shape
        const parts = 5;
        for(let i=0; i<parts; i++) {
            const angle = (i / parts) * Math.PI * 2;
            const dist = FOG_SIZE * 0.2;
            const r = FOG_SIZE * (0.2 + Math.random() * 0.2);
            ctx.beginPath(); 
            ctx.arc(cx + Math.cos(angle)*dist, cy + Math.sin(angle)*dist, r, 0, Math.PI*2); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = 50;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        if (isChaos) {
            // --- CHAOS RUNE (Jagged, asymmetrical) ---
            ctx.beginPath();
            const points = 7;
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 2 / points);
                const r = radius * (0.8 + Math.random() * 0.4); // Wobbly
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();

            // Inner scribble
            ctx.beginPath();
            ctx.moveTo(cx - 20, cy - 20); ctx.lineTo(cx + 20, cy + 20);
            ctx.moveTo(cx + 20, cy - 20); ctx.lineTo(cx - 20, cy + 20);
            ctx.stroke();

        } else {
            // --- ORDER RUNE (Geometric, Symmetrical) ---
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1;
            if (isUlt) {
                // Complex Hexagram
                ctx.beginPath();
                for (let i = 0; i < 6; i++) {
                    const angle = (i * Math.PI * 2) / 6;
                    const x = cx + Math.cos(angle) * radius;
                    const y = cy + Math.sin(angle) * radius;
                    const x2 = cx + Math.cos(angle + 2 * Math.PI / 3) * radius;
                    const y2 = cy + Math.sin(angle + 2 * Math.PI / 3) * radius;
                    ctx.moveTo(x, y); ctx.lineTo(x2, y2);
                }
                ctx.stroke();
            } else {
                // Simple Square/Diamond
                ctx.beginPath();
                ctx.rect(cx - 30, cy - 30, 60, 60);
                ctx.stroke();
                ctx.beginPath();
                ctx.moveTo(cx, cy - 40); ctx.lineTo(cx + 40, cy); 
                ctx.lineTo(cx, cy + 40); ctx.lineTo(cx - 40, cy); 
                ctx.closePath();
                ctx.stroke();
            }
        }

        // Core Glow
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.2;
        ctx.beginPath(); 
        ctx.arc(cx, cy, 20, 0, Math.PI * 2); 
        ctx.fill();

        return canvas;
    },

    generateWarningRune(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64;
        const cy = 32;
        const color = '#ef4444'; 

        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.scale(1, 0.5); 

        ctx.beginPath(); 
        ctx.arc(cx, cy * 2, 40, 0, Math.PI * 2); 
        ctx.stroke();

        // Danger Skull-ish X
        ctx.beginPath();
        ctx.moveTo(cx - 15, cy * 2 - 25); ctx.lineTo(cx + 15, cy * 2 + 25);
        ctx.moveTo(cx + 15, cy * 2 - 25); ctx.lineTo(cx - 15, cy * 2 + 25);
        ctx.stroke();

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                // Arrow is consistent, but style the head
                ctx.strokeStyle = isChaos ? '#525252' : '#e2e8f0'; 
                ctx.lineWidth = 3;
                ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();

                ctx.fillStyle = isChaos ? '#7f1d1d' : '#f8fafc';
                ctx.beginPath();
                if (isChaos) {
                    // Barbed Head
                    ctx.moveTo(85, cy); ctx.lineTo(65, cy - 10); ctx.lineTo(70, cy); ctx.lineTo(65, cy + 10);
                } else {
                    // Clean Head
                    ctx.moveTo(85, cy); ctx.lineTo(65, cy - 8); ctx.lineTo(65, cy + 8);
                }
                ctx.closePath();
                ctx.fill();

                // Fletching (Energy)
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(15, cy); ctx.lineTo(5, cy - 8);
                ctx.moveTo(15, cy); ctx.lineTo(5, cy + 8);
                ctx.stroke();
                break;

            case 'FIREBALL':
            case 'BOMB':
                // Core
                ctx.fillStyle = isChaos ? '#1c1917' : '#fff';
                ctx.beginPath(); ctx.arc(cx + 25, cy, 12, 0, Math.PI * 2); ctx.fill();

                // Trail / Flame
                const grad = ctx.createLinearGradient(cx + 30, cy, 0, cy);
                grad.addColorStop(0, color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;

                ctx.beginPath();
                if (isChaos) {
                    // Jagged Flame
                    ctx.moveTo(cx + 25, cy - 10);
                    ctx.lineTo(cx, cy - 15); ctx.lineTo(cx - 20, cy - 5);
                    ctx.lineTo(cx - 30, cy);
                    ctx.lineTo(cx - 20, cy + 5); ctx.lineTo(cx, cy + 15);
                    ctx.lineTo(cx + 25, cy + 10);
                } else {
                    // Smooth Comit
                    ctx.ellipse(cx, cy, 40, 15, 0, 0, Math.PI * 2);
                }
                ctx.fill();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                if (isChaos) {
                    // --- CHAOS BOLT (Skull / Jagged Energy) ---
                    ctx.fillStyle = '#fff';
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 3;

                    // Jagged Core
                    ctx.beginPath();
                    ctx.moveTo(cx + 30, cy);
                    ctx.lineTo(cx + 10, cy - 15);
                    ctx.lineTo(cx - 10, cy - 5);
                    ctx.lineTo(cx - 30, cy);
                    ctx.lineTo(cx - 10, cy + 5);
                    ctx.lineTo(cx + 10, cy + 15);
                    ctx.closePath();
                    ctx.fill(); ctx.stroke();

                    // Lightning Arcs
                    ctx.beginPath();
                    ctx.moveTo(cx + 30, cy); ctx.lineTo(cx + 40, cy - 10);
                    ctx.moveTo(cx + 30, cy); ctx.lineTo(cx + 40, cy + 10);
                    ctx.stroke();

                } else {
                    // --- HOLY BOLT (Diamond / Star) ---
                    const boltGrad = ctx.createRadialGradient(cx, cy, 5, cx, cy, 25); 
                    boltGrad.addColorStop(0, '#fff');
                    boltGrad.addColorStop(0.4, color);
                    boltGrad.addColorStop(1, 'transparent');
                    ctx.fillStyle = boltGrad;
                    ctx.beginPath(); ctx.arc(cx, cy, 25, 0, Math.PI * 2); ctx.fill();

                    // Geometric Core
                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 10;
                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx, cy - 15);
                    ctx.lineTo(cx - 15, cy); ctx.lineTo(cx, cy + 15);
                    ctx.closePath();
                    ctx.fill();

                    // Rings
                    ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
                    ctx.beginPath(); ctx.arc(cx, cy, 10, 0, Math.PI*2); ctx.stroke();
                }
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.scale(1, 0.5); 

        const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 50);
        grad.addColorStop(0, '#000'); 
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.7;

        if (isChaos) {
            // Splatter / Cracks
            ctx.beginPath();
            for(let i=0; i<12; i++) {
                const angle = (i / 12) * Math.PI * 2;
                const r = 40 + Math.random() * 20;
                const x = cx + Math.cos(angle) * r;
                const y = cy * 2 + Math.sin(angle) * r;
                ctx.lineTo(x, y);
            }
            ctx.fill();
        } else {
            // Clean Circle
            ctx.beginPath(); ctx.arc(cx, cy * 2, 50, 0, Math.PI * 2); ctx.fill();
        }

        // Edge Detail
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalCompositeOperation = 'lighter';

        if (isChaos) {
            // Random lightning cracks
            for(let i=0; i<5; i++) {
                ctx.beginPath();
                ctx.moveTo(cx, cy * 2);
                ctx.lineTo(cx + (Math.random()-0.5)*100, cy * 2 + (Math.random()-0.5)*100);
                ctx.stroke();
            }
        } else {
            // Concentric Rings
            ctx.beginPath(); ctx.arc(cx, cy * 2, 45, 0, Math.PI * 2); ctx.stroke();
            ctx.beginPath(); ctx.arc(cx, cy * 2, 35, 0, Math.PI * 2); ctx.stroke();
        }

        return canvas;
    }
};

import { GameEngine } from "../../game";
import { HexUtils, Vector, MapConfig } from "../../utils";
import { AssetManager } from "../../assets";
import { RenderableItem } from "../grid";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { Particle } from "../vfx/state"; 

const UNIT_CHEST_HEIGHT = 40;

// Helper: Determine if a color is "Chaos" (Red/Dark) or "Order" (Blue/Light)
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58');
}

export class VFXRenderer {

    // --- Helper to calculate vertical offset during map transition ---
    private getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const centerQ = Math.floor(mapConfig.w / 2);
        const centerR = Math.floor(mapConfig.h / 2);
        const hex = HexUtils.fromPx(x, y, mapConfig);
        const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
        const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);
        const d = dist / maxDist;

        if (phase === 'OUT') {
            const trigger = d * 0.3;
            if (t > trigger) {
                const fallT = Math.min(1, (t - trigger) * 2.5);
                return fallT * fallT * fallT * 1000;
            }
        } else if (phase === 'IN') {
            const trigger = d * 0.3;
            const riseT = Math.max(0, Math.min(1, (t - trigger) * 2.5));
            const easedRise = 1 - Math.pow(1 - riseT, 3);
            return (1 - easedRise) * 1000;
        }
        return 0;
    }

    // --- Rendering Collections ---

    public collectRenderables(
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = this.getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Projectiles
        engine.projectiles.forEach(p => {
             const offsetP = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             const getVisualPos = (lx: number, ly: number) => {
                 const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: lx, y: ly});
                 const t = Math.min(1, Math.max(0, currentDist / totalDist));
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'FIREBALL' || p.skill.visual === 'BOMB') {
                     const apex = Math.min(150, totalDist * 0.3);
                     arcOffset = Math.sin(t * Math.PI) * apex; 
                 }

                 const off = this.getTransitionOffset(lx, ly, mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const headVis = getVisualPos(p.x, p.y);

             // Direction Logic
             const lookAheadDist = 5;
             const currentDir = Vector.sub(p.targetPos, {x: p.x, y: p.y});
             const distRemaining = Vector.mag(currentDir);
             let dir;
             if (distRemaining > 0.1) {
                 dir = Vector.normalize(currentDir);
             } else {
                 const totalTrajectory = Vector.sub(p.targetPos, {x: p.startX, y: p.startY});
                 const totalMag = Vector.mag(totalTrajectory);
                 dir = totalMag > 0.1 ? Vector.normalize(totalTrajectory) : {x: 1, y: 0};
             }

             const nextLx = p.x + dir.x * lookAheadDist;
             const nextLy = p.y + dir.y * lookAheadDist;
             const nextVis = getVisualPos(nextLx, nextLy);
             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y}) * 0.1) : 0;

             // Style Logic
             const isChaos = isChaosStyle(p.skill.color);

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        const trailVis = p.trail.map(t => getVisualPos(t.x, t.y));
                        trailVis.push(headVis);

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // Thin faint line
                            ctx.beginPath();
                            ctx.moveTo(trailVis[0].x, trailVis[0].y);
                            for (let i = 1; i < trailVis.length; i++) ctx.lineTo(trailVis[i].x, trailVis[i].y);
                            ctx.strokeStyle = `rgba(255, 255, 255, 0.2)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGICAL RIBBON
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            for (let i = 0; i < trailVis.length - 1; i++) {
                                const pt = trailVis[i];
                                const next = trailVis[i+1];
                                const ratio = i / (trailVis.length - 1); 

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;

                                if (isChaos) {
                                    // CHAOS: Jittery, dark core
                                    ctx.strokeStyle = p.skill.color;
                                    const jitter = (Math.random() - 0.5) * 5 * (1-ratio);
                                    ctx.moveTo(pt.x + jitter, pt.y + jitter);
                                    ctx.lineTo(next.x + jitter, next.y + jitter);
                                    ctx.stroke();
                                } else {
                                    // ORDER: Smooth, glowing center
                                    ctx.strokeStyle = p.skill.color;
                                    ctx.globalAlpha = ratio * 0.5; 
                                    ctx.stroke();

                                    // White core for Order
                                    ctx.lineWidth = baseWidth * ratio * 0.4;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 10, 5, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            const offset = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            if (p.type === 'PILLAR' || p.type === 'SHOCKWAVE' || p.type === 'DOMAIN') {
                ctx.save();
                ctx.translate(p.x, drawY - 20); 
                if (p.type === 'PILLAR') this.drawPillar(ctx, p, progress, isChaos);
                else if (p.type === 'SHOCKWAVE') this.drawShockwave(ctx, p, progress, isChaos);
                else if (p.type === 'DOMAIN') this.drawDomain(ctx, p, progress, isChaos);
                ctx.restore();
                return;
            }

            ctx.save();
            ctx.translate(p.x, drawY);

            if (p.type === 'BEAM') {
                if (p.targetX !== undefined && p.targetY !== undefined) {
                    ctx.globalCompositeOperation = 'lighter';
                    const tx = p.targetX - p.x;
                    const ty = p.targetY - p.y;

                    if (isChaos) {
                        // Siphon / Lightning
                        ctx.strokeStyle = p.color;
                        ctx.lineWidth = 3;
                        ctx.beginPath();
                        ctx.moveTo(0, 0);
                        // Jagged line
                        const segs = 10;
                        for(let i=1; i<segs; i++) {
                            const ratio = i/segs;
                            const jit = (Math.random()-0.5) * 20;
                            ctx.lineTo(tx * ratio + jit, ty * ratio + jit);
                        }
                        ctx.lineTo(tx, ty);
                        ctx.stroke();
                    } else {
                        // Holy Beam
                        ctx.strokeStyle = p.color;
                        ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                        ctx.lineCap = 'round';
                        ctx.beginPath();
                        ctx.moveTo(0, 0);
                        ctx.lineTo(tx, ty); 
                        ctx.stroke();

                        ctx.lineWidth /= 2;
                        ctx.strokeStyle = '#fff';
                        ctx.stroke();
                    }
                }
            } else if (p.type === 'RING') {
                ctx.scale(1, 0.55); 
                const r = progress * 40;
                ctx.strokeStyle = p.color;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath(); 
                if(isChaos) {
                    // Jagged Ring
                    for(let i=0; i<=16; i++) {
                        const a = (i/16)*Math.PI*2;
                        const rr = r * (1 + (Math.random()-0.5)*0.2);
                        if(i===0) ctx.moveTo(Math.cos(a)*rr, Math.sin(a)*rr);
                        else ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
                    }
                } else {
                    ctx.arc(0, 0, r, 0, Math.PI * 2); 
                }
                ctx.stroke();
            } else if (p.type === 'SPARK') {
                const r = p.size;
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#fff'); 
                grad.addColorStop(0.3, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.globalAlpha = 1 - Math.pow(progress, 3); 
                ctx.globalCompositeOperation = 'lighter'; 
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
            } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                ctx.fillStyle = p.color;
                ctx.rotate(p.rotation);
                ctx.beginPath();
                const s = p.size;
                if (p.type === 'SHARD') {
                    ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
                } else {
                    ctx.rect(-s/2, -s/2, s, s);
                }
                ctx.fill();
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }
            ctx.restore();
        });
    }

    private drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        const pulse = 1 + Math.sin(progress * 20) * 0.2;
        const baseWidth = 50 * (lifeRatio < 0.2 ? lifeRatio * 5 : 1) * pulse;
        const height = 1200; 
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 

        ctx.save();
        ctx.scale(1, 0.55); 

        // Ground Blast Ring
        const ringSize = baseWidth * 1.8;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.3, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : 'rgba(255,255,255,0.8)');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        // BEAM COLUMN
        const coreWidth = baseWidth * 0.3;

        if (isChaos) {
            // CHAOS PILLAR: Dark Core, Messy Edges
            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.6, 'transparent');

            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.8;

            ctx.beginPath();
            ctx.moveTo(-baseWidth, 0);
            ctx.lineTo(-baseWidth*0.5, -height);
            ctx.lineTo(baseWidth*0.5, -height);
            ctx.lineTo(baseWidth, 0);
            ctx.fill();

            // Inner black void
            ctx.fillStyle = '#000';
            ctx.globalAlpha = alpha * 0.5;
            ctx.fillRect(-coreWidth/2, -height, coreWidth, height);

        } else {
            // ORDER PILLAR: Bright Core, Straight
            const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
            coreGrad.addColorStop(0, '#ffffff');
            coreGrad.addColorStop(0.2, '#ffffff');
            coreGrad.addColorStop(1, 'transparent');

            ctx.fillStyle = coreGrad;
            ctx.globalAlpha = alpha;
            ctx.fillRect(-coreWidth/2, -height, coreWidth, height);

            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.6, 'transparent');

            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.6;
            ctx.fillRect(-baseWidth * 0.8, -height, baseWidth * 1.6, height);
        }
    }

    private drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';

        const r = progress * 250; 
        const width = 20 * (1 - progress);

        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress) * 0.9;

        ctx.beginPath(); 
        if (isChaos) {
            // Messy Shockwave
            for(let i=0; i<=20; i++) {
                const a = (i/20)*Math.PI*2;
                const d = r + (Math.random()-0.5)*20;
                if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
            }
        } else {
            ctx.arc(0, 0, r, 0, Math.PI * 2); 
        }
        ctx.stroke();
    }

    private drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         ctx.scale(1, 0.55); 
         const time = performance.now() / 1000;
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;

         ctx.globalCompositeOperation = 'lighter'; 

         // Base Field
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 
         grad.addColorStop(0.7, p.color + '33'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');

         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.6 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Rune Rings
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;

         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         if (isChaos) {
             ctx.setLineDash([10, 20]); // Jagged dash
             // Irregular shape
             ctx.beginPath();
             for(let i=0; i<=8; i++) {
                 const a = (i/8)*Math.PI*2;
                 const d = r * 0.9 + (i%2===0 ? 10 : -10);
                 if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                 else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
             }
             ctx.stroke();
         } else {
             ctx.setLineDash([40, 60]); 
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
         }
         ctx.restore();

         // Vertical Spikes/Walls
         ctx.globalAlpha = 0.4 * (1 - progress);
         const spikeCount = 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + time;
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;
             ctx.beginPath();
             ctx.moveTo(sx, sy);
             // Order = Straight, Chaos = Angled
             ctx.lineTo(sx + (isChaos ? (Math.random()-0.5)*20 : 0), sy - 80); 
             ctx.lineWidth = 4;

             const beamGrad = ctx.createLinearGradient(sx, sy, sx, sy - 80);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
}

import { GameEngine } from "../../game";
import { HexUtils, Vector, MapConfig } from "../../utils";
import { AssetManager } from "../../assets";
import { RenderableItem } from "../grid";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { Particle } from "../vfx/state"; 

const UNIT_CHEST_HEIGHT = 40;

// Helper: Determine if a color is "Chaos" (Red/Dark) or "Order" (Blue/Light)
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58');
}

export class VFXRenderer {

    // --- Helper to calculate vertical offset during map transition ---
    private getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const centerQ = Math.floor(mapConfig.w / 2);
        const centerR = Math.floor(mapConfig.h / 2);
        const hex = HexUtils.fromPx(x, y, mapConfig);
        const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
        const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);
        const d = dist / maxDist;

        if (phase === 'OUT') {
            const trigger = d * 0.3;
            if (t > trigger) {
                const fallT = Math.min(1, (t - trigger) * 2.5);
                return fallT * fallT * fallT * 1000;
            }
        } else if (phase === 'IN') {
            const trigger = d * 0.3;
            const riseT = Math.max(0, Math.min(1, (t - trigger) * 2.5));
            const easedRise = 1 - Math.pow(1 - riseT, 3);
            return (1 - easedRise) * 1000;
        }
        return 0;
    }

    // --- Rendering Collections ---

    public collectRenderables(
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = this.getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Projectiles
        engine.projectiles.forEach(p => {
             const offsetP = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             const getVisualPos = (lx: number, ly: number) => {
                 const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: lx, y: ly});
                 const t = Math.min(1, Math.max(0, currentDist / totalDist));
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'FIREBALL' || p.skill.visual === 'BOMB') {
                     const apex = Math.min(150, totalDist * 0.3);
                     arcOffset = Math.sin(t * Math.PI) * apex; 
                 }

                 const off = this.getTransitionOffset(lx, ly, mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const headVis = getVisualPos(p.x, p.y);

             // Direction Logic
             const lookAheadDist = 5;
             const currentDir = Vector.sub(p.targetPos, {x: p.x, y: p.y});
             const distRemaining = Vector.mag(currentDir);
             let dir;
             if (distRemaining > 0.1) {
                 dir = Vector.normalize(currentDir);
             } else {
                 const totalTrajectory = Vector.sub(p.targetPos, {x: p.startX, y: p.startY});
                 const totalMag = Vector.mag(totalTrajectory);
                 dir = totalMag > 0.1 ? Vector.normalize(totalTrajectory) : {x: 1, y: 0};
             }

             const nextLx = p.x + dir.x * lookAheadDist;
             const nextLy = p.y + dir.y * lookAheadDist;
             const nextVis = getVisualPos(nextLx, nextLy);
             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y}) * 0.1) : 0;

             // Style Logic
             const isChaos = isChaosStyle(p.skill.color);

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        const trailVis = p.trail.map(t => getVisualPos(t.x, t.y));
                        trailVis.push(headVis);

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // Thin faint line
                            ctx.beginPath();
                            ctx.moveTo(trailVis[0].x, trailVis[0].y);
                            for (let i = 1; i < trailVis.length; i++) ctx.lineTo(trailVis[i].x, trailVis[i].y);
                            ctx.strokeStyle = `rgba(255, 255, 255, 0.2)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGICAL RIBBON
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            for (let i = 0; i < trailVis.length - 1; i++) {
                                const pt = trailVis[i];
                                const next = trailVis[i+1];
                                const ratio = i / (trailVis.length - 1); 

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;

                                if (isChaos) {
                                    // CHAOS: Jittery, dark core
                                    ctx.strokeStyle = p.skill.color;
                                    const jitter = (Math.random() - 0.5) * 5 * (1-ratio);
                                    ctx.moveTo(pt.x + jitter, pt.y + jitter);
                                    ctx.lineTo(next.x + jitter, next.y + jitter);
                                    ctx.stroke();
                                } else {
                                    // ORDER: Smooth, glowing center
                                    ctx.strokeStyle = p.skill.color;
                                    ctx.globalAlpha = ratio * 0.5; 
                                    ctx.stroke();

                                    // White core for Order
                                    ctx.lineWidth = baseWidth * ratio * 0.4;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 10, 5, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            const offset = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            if (p.type === 'PILLAR' || p.type === 'SHOCKWAVE' || p.type === 'DOMAIN') {
                ctx.save();
                ctx.translate(p.x, drawY - 20); 
                if (p.type === 'PILLAR') this.drawPillar(ctx, p, progress, isChaos);
                else if (p.type === 'SHOCKWAVE') this.drawShockwave(ctx, p, progress, isChaos);
                else if (p.type === 'DOMAIN') this.drawDomain(ctx, p, progress, isChaos);
                ctx.restore();
                return;
            }

            ctx.save();
            ctx.translate(p.x, drawY);

            if (p.type === 'BEAM') {
                if (p.targetX !== undefined && p.targetY !== undefined) {
                    ctx.globalCompositeOperation = 'lighter';
                    const tx = p.targetX - p.x;
                    const ty = p.targetY - p.y;

                    if (isChaos) {
                        // Siphon / Lightning
                        ctx.strokeStyle = p.color;
                        ctx.lineWidth = 3;
                        ctx.beginPath();
                        ctx.moveTo(0, 0);
                        // Jagged line
                        const segs = 10;
                        for(let i=1; i<segs; i++) {
                            const ratio = i/segs;
                            const jit = (Math.random()-0.5) * 20;
                            ctx.lineTo(tx * ratio + jit, ty * ratio + jit);
                        }
                        ctx.lineTo(tx, ty);
                        ctx.stroke();
                    } else {
                        // Holy Beam
                        ctx.strokeStyle = p.color;
                        ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                        ctx.lineCap = 'round';
                        ctx.beginPath();
                        ctx.moveTo(0, 0);
                        ctx.lineTo(tx, ty); 
                        ctx.stroke();

                        ctx.lineWidth /= 2;
                        ctx.strokeStyle = '#fff';
                        ctx.stroke();
                    }
                }
            } else if (p.type === 'RING') {
                ctx.scale(1, 0.55); 
                const r = progress * 40;
                ctx.strokeStyle = p.color;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath(); 
                if(isChaos) {
                    // Jagged Ring
                    for(let i=0; i<=16; i++) {
                        const a = (i/16)*Math.PI*2;
                        const rr = r * (1 + (Math.random()-0.5)*0.2);
                        if(i===0) ctx.moveTo(Math.cos(a)*rr, Math.sin(a)*rr);
                        else ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
                    }
                } else {
                    ctx.arc(0, 0, r, 0, Math.PI * 2); 
                }
                ctx.stroke();
            } else if (p.type === 'SPARK') {
                const r = p.size;
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#fff'); 
                grad.addColorStop(0.3, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.globalAlpha = 1 - Math.pow(progress, 3); 
                ctx.globalCompositeOperation = 'lighter'; 
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
            } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                ctx.fillStyle = p.color;
                ctx.rotate(p.rotation);
                ctx.beginPath();
                const s = p.size;
                if (p.type === 'SHARD') {
                    ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
                } else {
                    ctx.rect(-s/2, -s/2, s, s);
                }
                ctx.fill();
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }
            ctx.restore();
        });
    }

    private drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        const pulse = 1 + Math.sin(progress * 20) * 0.2;
        const baseWidth = 50 * (lifeRatio < 0.2 ? lifeRatio * 5 : 1) * pulse;
        const height = 1200; 
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 

        ctx.save();
        ctx.scale(1, 0.55); 

        // Ground Blast Ring
        const ringSize = baseWidth * 1.8;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.3, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : 'rgba(255,255,255,0.8)');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        // BEAM COLUMN
        const coreWidth = baseWidth * 0.3;

        if (isChaos) {
            // CHAOS PILLAR: Dark Core, Messy Edges
            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.6, 'transparent');

            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.8;

            ctx.beginPath();
            ctx.moveTo(-baseWidth, 0);
            ctx.lineTo(-baseWidth*0.5, -height);
            ctx.lineTo(baseWidth*0.5, -height);
            ctx.lineTo(baseWidth, 0);
            ctx.fill();

            // Inner black void
            ctx.fillStyle = '#000';
            ctx.globalAlpha = alpha * 0.5;
            ctx.fillRect(-coreWidth/2, -height, coreWidth, height);

        } else {
            // ORDER PILLAR: Bright Core, Straight
            const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
            coreGrad.addColorStop(0, '#ffffff');
            coreGrad.addColorStop(0.2, '#ffffff');
            coreGrad.addColorStop(1, 'transparent');

            ctx.fillStyle = coreGrad;
            ctx.globalAlpha = alpha;
            ctx.fillRect(-coreWidth/2, -height, coreWidth, height);

            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.6, 'transparent');

            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.6;
            ctx.fillRect(-baseWidth * 0.8, -height, baseWidth * 1.6, height);
        }
    }

    private drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';

        const r = progress * 250; 
        const width = 20 * (1 - progress);

        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress) * 0.9;

        ctx.beginPath(); 
        if (isChaos) {
            // Messy Shockwave
            for(let i=0; i<=20; i++) {
                const a = (i/20)*Math.PI*2;
                const d = r + (Math.random()-0.5)*20;
                if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
            }
        } else {
            ctx.arc(0, 0, r, 0, Math.PI * 2); 
        }
        ctx.stroke();
    }

    private drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         ctx.scale(1, 0.55); 
         const time = performance.now() / 1000;
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;

         ctx.globalCompositeOperation = 'lighter'; 

         // Base Field
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 

         // Safe color for alpha blending
         let safeColor = p.color;
         if (p.color.startsWith('#') && p.color.length === 4) {
             safeColor = '#' + p.color[1].repeat(2) + p.color[2].repeat(2) + p.color[3].repeat(2);
         }

         grad.addColorStop(0.7, safeColor + '33'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');

         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.6 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Rune Rings
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;

         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         if (isChaos) {
             ctx.setLineDash([10, 20]); // Jagged dash
             // Irregular shape
             ctx.beginPath();
             for(let i=0; i<=8; i++) {
                 const a = (i/8)*Math.PI*2;
                 const d = r * 0.9 + (i%2===0 ? 10 : -10);
                 if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                 else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
             }
             ctx.stroke();
         } else {
             ctx.setLineDash([40, 60]); 
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
         }
         ctx.restore();

         // Vertical Spikes/Walls
         ctx.globalAlpha = 0.4 * (1 - progress);
         const spikeCount = 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + time;
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;
             ctx.beginPath();
             ctx.moveTo(sx, sy);
             // Order = Straight, Chaos = Angled
             ctx.lineTo(sx + (isChaos ? (Math.random()-0.5)*20 : 0), sy - 80); 
             ctx.lineWidth = 4;

             const beamGrad = ctx.createLinearGradient(sx, sy, sx, sy - 80);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
}

import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

// Helper: Chaos color detection
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') ||
           c.includes('#1c');
}

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         const grad = ctx.createRadialGradient(cx, cy, r * 0.1, cx, cy, r);
         grad.addColorStop(0, '#fff');        
         grad.addColorStop(0.4, color);       
         grad.addColorStop(1, 'transparent'); 

         ctx.fillStyle = grad;

         if (isChaos) {
             // Chaos: Unstable plasma blob
             ctx.beginPath();
             const spikes = 12;
             for(let i=0; i<spikes; i++) {
                 const angle = (i / spikes) * Math.PI * 2;
                 // Randomize radius for "wobbly" look
                 const rad = r * (0.6 + Math.random() * 0.4);
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();
         } else {
             // Order: Perfect Sphere with Cross Flare
             ctx.beginPath(); 
             ctx.arc(cx, cy, r * 0.8, 0, Math.PI * 2); 
             ctx.fill();

             // Lens flare cross
             ctx.fillStyle = '#fff';
             ctx.globalAlpha = 0.8;
             ctx.beginPath();
             // Horizontal soft beam
             ctx.ellipse(cx, cy, r, r*0.15, 0, 0, Math.PI*2);
             // Vertical sharp beam
             ctx.ellipse(cx, cy, r*0.15, r, 0, 0, Math.PI*2);
             ctx.fill();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.4;

        // Perlin-ish blobs
        for(let i=0; i<8; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * (FOG_SIZE * 0.25);
            const r = FOG_SIZE * (0.15 + Math.random() * 0.15);

            ctx.beginPath(); 
            ctx.arc(cx + Math.cos(angle)*dist, cy + Math.sin(angle)*dist, r, 0, Math.PI*2); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = 50;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        if (isChaos) {
            // --- CHAOS RUNE (Jagged, asymmetrical, blood-like) ---
            ctx.beginPath();
            const points = 9;
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 2 / points);
                // Heavy distortion
                const r = radius * (0.85 + Math.random() * 0.3); 
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();

            // Inner scribble / Eye
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - 25, cy); 
            ctx.quadraticCurveTo(cx, cy - 15, cx + 25, cy);
            ctx.quadraticCurveTo(cx, cy + 15, cx - 25, cy);
            ctx.stroke();

            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI*2); ctx.fill();

        } else {
            // --- ORDER RUNE (Geometric, Symmetrical, Mandalas) ---
            // Outer Ring
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1.5;
            if (isUlt) {
                // Complex Hexagram (Star of David style)
                const drawPoly = (sides: number, r: number, offset: number) => {
                    ctx.beginPath();
                    for (let i = 0; i <= sides; i++) {
                        const angle = offset + (i * Math.PI * 2) / sides;
                        const x = cx + Math.cos(angle) * r;
                        const y = cy + Math.sin(angle) * r;
                        if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    }
                    ctx.stroke();
                };

                drawPoly(3, radius, -Math.PI/2); // Triangle Up
                drawPoly(3, radius, Math.PI/2);  // Triangle Down

                // Inner Circle
                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.5, 0, Math.PI*2); ctx.stroke();

            } else {
                // Simple Square/Diamond
                ctx.save();
                ctx.translate(cx, cy);
                ctx.rotate(Math.PI/4);
                ctx.strokeRect(-radius * 0.7, -radius * 0.7, radius * 1.4, radius * 1.4);
                ctx.restore();

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.3, 0, Math.PI*2); ctx.stroke();
            }
        }

        return canvas;
    },

    generateWarningRune(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64;
        const cy = 32;
        const color = '#ef4444'; 

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.scale(1, 0.5); 

        // Skull-like Hazard Symbol
        ctx.beginPath(); 
        ctx.arc(cx, cy * 2, 40, 0, Math.PI * 2); 
        ctx.stroke();

        ctx.beginPath();
        // X mark
        ctx.moveTo(cx - 15, cy * 2 - 25); ctx.lineTo(cx + 15, cy * 2 + 25);
        ctx.moveTo(cx + 15, cy * 2 - 25); ctx.lineTo(cx - 15, cy * 2 + 25);
        ctx.stroke();

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 12;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                // Chaos: Barbed bone arrow | Order: Energy light arrow
                ctx.strokeStyle = isChaos ? '#a8a29e' : '#e2e8f0'; 
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(75, cy); ctx.stroke();

                ctx.fillStyle = isChaos ? '#7f1d1d' : '#f0f9ff';
                ctx.beginPath();
                if (isChaos) {
                    // Jagged Head
                    ctx.moveTo(85, cy); 
                    ctx.lineTo(65, cy - 8); ctx.lineTo(70, cy); ctx.lineTo(65, cy + 8);
                } else {
                    // Clean Bodkin
                    ctx.moveTo(90, cy); ctx.lineTo(70, cy - 6); ctx.lineTo(70, cy + 6);
                }
                ctx.closePath();
                ctx.fill();

                // Trail feather / energy
                ctx.strokeStyle = color;
                ctx.beginPath();
                if (isChaos) {
                    ctx.moveTo(20, cy); ctx.lineTo(5, cy - 10);
                    ctx.moveTo(20, cy); ctx.lineTo(5, cy + 10);
                } else {
                    // Glowing flight
                    ctx.moveTo(15, cy - 5); ctx.lineTo(5, cy); ctx.lineTo(15, cy + 5);
                }
                ctx.stroke();
                break;

            case 'FIREBALL':
            case 'BOMB':
                // Core
                const coreGrad = ctx.createRadialGradient(cx+20, cy, 0, cx+20, cy, 15);
                coreGrad.addColorStop(0, '#fff');
                coreGrad.addColorStop(0.5, color);
                coreGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = coreGrad;

                ctx.beginPath(); ctx.arc(cx + 20, cy, 14, 0, Math.PI * 2); ctx.fill();

                // Tail / Comet
                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.beginPath();
                if (isChaos) {
                    // Wild Flame
                    ctx.moveTo(cx + 20, cy - 12);
                    ctx.lineTo(cx, cy - 20); ctx.lineTo(cx - 20, cy - 5);
                    ctx.lineTo(cx - 35, cy);
                    ctx.lineTo(cx - 20, cy + 8); ctx.lineTo(cx, cy + 22);
                    ctx.lineTo(cx + 20, cy + 12);
                } else {
                    // Smooth Streamline
                    ctx.ellipse(cx + 5, cy, 35, 12, 0, 0, Math.PI * 2);
                }
                ctx.fill();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                if (isChaos) {
                    // --- CHAOS BOLT (Dark Energy Skull/Claw) ---
                    ctx.fillStyle = '#1c1917'; // Dark core
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 3;

                    ctx.beginPath();
                    // Jagged shape
                    ctx.moveTo(cx + 35, cy);
                    ctx.lineTo(cx + 10, cy - 15);
                    ctx.lineTo(cx - 10, cy - 5);
                    ctx.lineTo(cx - 30, cy);
                    ctx.lineTo(cx - 10, cy + 5);
                    ctx.lineTo(cx + 10, cy + 15);
                    ctx.closePath();
                    ctx.fill(); ctx.stroke();

                    // Lightning Arcs
                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx + 45, cy - 12);
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx + 45, cy + 12);
                    ctx.stroke();

                } else {
                    // --- HOLY BOLT (Geometric Star/Diamond) ---
                    // Inner Light
                    const boltGrad = ctx.createRadialGradient(cx, cy, 2, cx, cy, 25); 
                    boltGrad.addColorStop(0, '#fff');
                    boltGrad.addColorStop(0.5, color);
                    boltGrad.addColorStop(1, 'transparent');
                    ctx.fillStyle = boltGrad;
                    ctx.beginPath(); ctx.arc(cx, cy, 25, 0, Math.PI * 2); ctx.fill();

                    // Hard Core Shape
                    ctx.fillStyle = '#fff';
                    ctx.shadowColor = '#fff';
                    ctx.beginPath();
                    // Diamond
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx, cy - 12);
                    ctx.lineTo(cx - 15, cy); ctx.lineTo(cx, cy + 12);
                    ctx.closePath();
                    ctx.fill();

                    // Orbital Rings
                    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.shadowBlur = 5;
                    ctx.beginPath(); 
                    ctx.ellipse(cx, cy, 15, 8, 0, 0, Math.PI*2); 
                    ctx.stroke();
                }
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.scale(1, 0.5); 

        const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 50);
        grad.addColorStop(0, isChaos ? '#000' : '#fff'); 
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.8;

        if (isChaos) {
            // Splatter / Cracks
            ctx.beginPath();
            for(let i=0; i<16; i++) {
                const angle = (i / 16) * Math.PI * 2;
                const r = 35 + Math.random() * 25;
                const x = cx + Math.cos(angle) * r;
                const y = cy * 2 + Math.sin(angle) * r;
                ctx.lineTo(x, y);
            }
            ctx.fill();

            // Inner cracks
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalCompositeOperation = 'source-over';
            for(let i=0; i<5; i++) {
                ctx.beginPath();
                ctx.moveTo(cx, cy*2);
                const a = Math.random() * Math.PI * 2;
                ctx.lineTo(cx + Math.cos(a)*40, cy*2 + Math.sin(a)*40);
                ctx.stroke();
            }

        } else {
            // Clean Shockwave Ring
            ctx.beginPath(); ctx.arc(cx, cy * 2, 45, 0, Math.PI * 2); ctx.fill();

            // Energy Rings
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.arc(cx, cy * 2, 48, 0, Math.PI * 2); ctx.stroke();
            ctx.lineWidth = 1;
            ctx.strokeStyle = '#fff';
            ctx.beginPath(); ctx.arc(cx, cy * 2, 35, 0, Math.PI * 2); ctx.stroke();
        }

        return canvas;
    }
};

import { GameEngine } from "../../game";
import { HexUtils, Vector, MapConfig } from "../../utils";
import { AssetManager } from "../../assets";
import { RenderableItem } from "../grid";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { Particle } from "../vfx/state"; 

const UNIT_CHEST_HEIGHT = 40;

// Helper: Determine if a color is "Chaos" (Red/Dark) or "Order" (Blue/Light)
// Chaos colors: Red, Deep Purple, Poison Green, Dark Orange
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') || 
           c.includes('#1c');
}

// Helper: Ensure 6-digit hex for alpha appending logic
function normalizeHex(color: string): string {
    if (color.startsWith('#') && color.length === 4) {
        return '#' + color[1] + color[1] + color[2] + color[2] + color[3] + color[3];
    }
    return color;
}

export class VFXRenderer {

    // --- Helper to calculate vertical offset during map transition ---
    private getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const centerQ = Math.floor(mapConfig.w / 2);
        const centerR = Math.floor(mapConfig.h / 2);
        const hex = HexUtils.fromPx(x, y, mapConfig);
        const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
        const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);
        const d = dist / maxDist;

        if (phase === 'OUT') {
            const trigger = d * 0.3;
            if (t > trigger) {
                const fallT = Math.min(1, (t - trigger) * 2.5);
                return fallT * fallT * fallT * 1000;
            }
        } else if (phase === 'IN') {
            const trigger = d * 0.3;
            const riseT = Math.max(0, Math.min(1, (t - trigger) * 2.5));
            const easedRise = 1 - Math.pow(1 - riseT, 3);
            return (1 - easedRise) * 1000;
        }
        return 0;
    }

    // --- Rendering Collections ---

    public collectRenderables(
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = this.getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Projectiles
        engine.projectiles.forEach(p => {
             const offsetP = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             const getVisualPos = (lx: number, ly: number) => {
                 const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: lx, y: ly});
                 const t = Math.min(1, Math.max(0, currentDist / totalDist));
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'FIREBALL' || p.skill.visual === 'BOMB') {
                     const apex = Math.min(150, totalDist * 0.3);
                     arcOffset = Math.sin(t * Math.PI) * apex; 
                 }

                 const off = this.getTransitionOffset(lx, ly, mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const headVis = getVisualPos(p.x, p.y);

             // Direction Logic
             const lookAheadDist = 5;
             const currentDir = Vector.sub(p.targetPos, {x: p.x, y: p.y});
             const distRemaining = Vector.mag(currentDir);
             let dir;
             if (distRemaining > 0.1) {
                 dir = Vector.normalize(currentDir);
             } else {
                 const totalTrajectory = Vector.sub(p.targetPos, {x: p.startX, y: p.startY});
                 const totalMag = Vector.mag(totalTrajectory);
                 dir = totalMag > 0.1 ? Vector.normalize(totalTrajectory) : {x: 1, y: 0};
             }

             const nextLx = p.x + dir.x * lookAheadDist;
             const nextLy = p.y + dir.y * lookAheadDist;
             const nextVis = getVisualPos(nextLx, nextLy);
             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y}) * 0.1) : 0;

             // Style Logic
             const isChaos = isChaosStyle(p.skill.color);

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        const trailVis = p.trail.map(t => getVisualPos(t.x, t.y));
                        trailVis.push(headVis);

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // Thin faint line
                            ctx.beginPath();
                            ctx.moveTo(trailVis[0].x, trailVis[0].y);
                            for (let i = 1; i < trailVis.length; i++) ctx.lineTo(trailVis[i].x, trailVis[i].y);
                            ctx.strokeStyle = `rgba(255, 255, 255, 0.2)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGICAL RIBBON
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            // Draw segment by segment to allow for jitter/style
                            for (let i = 0; i < trailVis.length - 1; i++) {
                                const pt = trailVis[i];
                                const next = trailVis[i+1];
                                const ratio = i / (trailVis.length - 1); 

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;
                                ctx.strokeStyle = p.skill.color;

                                ctx.beginPath();

                                if (isChaos) {
                                    // CHAOS: Jittery, Electric Arc
                                    const jitterX = (Math.random() - 0.5) * 5 * (1-ratio);
                                    const jitterY = (Math.random() - 0.5) * 5 * (1-ratio);
                                    ctx.moveTo(pt.x + jitterX, pt.y + jitterY);
                                    ctx.lineTo(next.x + jitterX, next.y + jitterY);
                                    ctx.globalAlpha = ratio; 
                                } else {
                                    // ORDER: Smooth, glowing center
                                    ctx.moveTo(pt.x, pt.y);
                                    ctx.lineTo(next.x, next.y);
                                    ctx.globalAlpha = ratio * 0.6;
                                }
                                ctx.stroke();

                                if (!isChaos) {
                                    // White core for Order
                                    ctx.lineWidth = baseWidth * ratio * 0.4;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            const offset = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            // Major VFX drawn relative to ground or anchor
            if (p.type === 'PILLAR' || p.type === 'SHOCKWAVE' || p.type === 'DOMAIN') {
                ctx.save();
                ctx.translate(p.x, drawY - 20); // slightly above ground anchor
                if (p.type === 'PILLAR') this.drawPillar(ctx, p, progress, isChaos);
                else if (p.type === 'SHOCKWAVE') this.drawShockwave(ctx, p, progress, isChaos);
                else if (p.type === 'DOMAIN') this.drawDomain(ctx, p, progress, isChaos);
                ctx.restore();
                return;
            }

            // Standard Particles
            ctx.save();
            ctx.translate(p.x, drawY);

            if (p.type === 'BEAM') {
                if (p.targetX !== undefined && p.targetY !== undefined) {
                    ctx.globalCompositeOperation = 'lighter';
                    const tx = p.targetX - p.x;
                    const ty = p.targetY - p.y;

                    if (isChaos) {
                        // Siphon / Lightning / Life Drain
                        ctx.strokeStyle = p.color;
                        ctx.lineWidth = 3;
                        ctx.beginPath();
                        ctx.moveTo(0, 0);
                        // Jagged line
                        const segs = 10;
                        for(let i=1; i<segs; i++) {
                            const ratio = i/segs;
                            const jit = (Math.random()-0.5) * 20;
                            ctx.lineTo(tx * ratio + jit, ty * ratio + jit);
                        }
                        ctx.lineTo(tx, ty);
                        ctx.stroke();

                        // Dark Core
                        ctx.lineWidth = 1;
                        ctx.strokeStyle = '#000';
                        ctx.stroke();

                    } else {
                        // Holy Beam / Laser
                        ctx.strokeStyle = p.color;
                        ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                        ctx.lineCap = 'round';
                        ctx.beginPath();
                        ctx.moveTo(0, 0); ctx.lineTo(tx, ty); ctx.stroke();

                        // White Hot Center
                        ctx.lineWidth /= 2;
                        ctx.strokeStyle = '#fff';
                        ctx.stroke();
                    }
                }
            } else if (p.type === 'RING') {
                ctx.scale(1, 0.55); 
                const r = progress * 40;
                ctx.strokeStyle = p.color;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath(); 
                if(isChaos) {
                    // Jagged Ring
                    for(let i=0; i<=16; i++) {
                        const a = (i/16)*Math.PI*2;
                        const rr = r * (1 + (Math.random()-0.5)*0.2);
                        if(i===0) ctx.moveTo(Math.cos(a)*rr, Math.sin(a)*rr);
                        else ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
                    }
                } else {
                    ctx.arc(0, 0, r, 0, Math.PI * 2); 
                }
                ctx.stroke();
                ctx.closePath();

            } else if (p.type === 'SPARK') {
                const r = p.size;
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#fff'); 
                grad.addColorStop(0.3, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.globalAlpha = 1 - Math.pow(progress, 3); 
                ctx.globalCompositeOperation = 'lighter'; 
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                ctx.fillStyle = p.color;
                ctx.rotate(p.rotation);
                ctx.beginPath();
                const s = p.size;
                if (p.type === 'SHARD') {
                    ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
                } else {
                    ctx.rect(-s/2, -s/2, s, s);
                }
                ctx.fill();
                // Highlight edge
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }
            ctx.restore();
        });
    }

    private drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        // Ease-in and Ease-out
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 
        const height = 1200; 
        const baseWidth = 60 * (1 + Math.sin(progress * 20) * 0.1); // Pulse width

        ctx.save();
        ctx.scale(1, 0.55); 

        // Ground Blast Ring
        const ringSize = baseWidth * 2;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.2, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : '#fff');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        // BEAM COLUMN
        if (isChaos) {
            // CHAOS PILLAR: Dark Core, Unstable, Jagged
            const chaosGrad = ctx.createLinearGradient(0, 0, 0, -height);
            chaosGrad.addColorStop(0, p.color);
            chaosGrad.addColorStop(0.5, 'transparent');

            ctx.fillStyle = chaosGrad;
            ctx.globalAlpha = alpha * 0.8;

            // Draw a slightly jagged rect
            ctx.beginPath();
            const segs = 10;
            const hw = baseWidth / 2;
            ctx.moveTo(-hw, 0);
            for(let i=1; i<=segs; i++) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(-hw + xOff, y);
            }
            for(let i=segs; i>=0; i--) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(hw + xOff, y);
            }
            ctx.closePath();
            ctx.fill();

            // Inner black void (Negative Energy)
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = '#000';
            ctx.globalAlpha = alpha * 0.6;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

        } else {
            // ORDER PILLAR: Bright Core, Straight, Holy Light
            const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
            coreGrad.addColorStop(0, '#ffffff');
            coreGrad.addColorStop(0.3, '#ffffff');
            coreGrad.addColorStop(1, 'transparent');

            // White hot core
            ctx.fillStyle = coreGrad;
            ctx.globalAlpha = alpha;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

            // Colored Glow
            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.7, 'transparent');

            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.5;
            ctx.fillRect(-baseWidth, -height, baseWidth * 2, height);
        }
    }

    private drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';

        const r = progress * 300; 
        const width = 30 * (1 - progress);

        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress);

        ctx.beginPath(); 
        if (isChaos) {
            // Messy Shockwave
            for(let i=0; i<=32; i++) {
                const a = (i/32)*Math.PI*2;
                const d = r + (Math.random()-0.5) * 30;
                if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
            }
        } else {
            // Clean Shockwave
            ctx.arc(0, 0, r, 0, Math.PI * 2); 
        }
        ctx.closePath();
        ctx.stroke();
    }

    private drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         ctx.scale(1, 0.55); 
         const time = performance.now() / 1000;
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;

         ctx.globalCompositeOperation = 'lighter'; 

         // Base Field
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 

         // Safe color for alpha blending to prevent SyntaxError
         const safeColor = normalizeHex(p.color);

         grad.addColorStop(0.7, safeColor + '4D'); // approx 30% alpha
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');

         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.5 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Rune Rings
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;

         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         if (isChaos) {
             ctx.setLineDash([10, 25]); // Jagged dash
             // Irregular shape
             ctx.beginPath();
             for(let i=0; i<=12; i++) {
                 const a = (i/12)*Math.PI*2;
                 const d = r * 0.95 + (i%2===0 ? 15 : -15);
                 if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                 else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
             }
             ctx.closePath();
             ctx.stroke();
         } else {
             ctx.setLineDash([50, 20]); 
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
             // Inner ring rotating opposite
             ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); 
             ctx.setLineDash([20, 10]);
             ctx.stroke();
         }
         ctx.restore();

         // Vertical Energy Walls
         ctx.globalAlpha = 0.3 * (1 - progress);
         const spikeCount = isChaos ? 8 : 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + (isChaos ? -time : time);
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;

             ctx.beginPath();
             ctx.moveTo(sx, sy);
             // Order = Straight walls, Chaos = Angled spikes
             const topX = sx + (isChaos ? (Math.random()-0.5)*40 : 0);
             ctx.lineTo(topX, sy - 100); 
             ctx.lineWidth = 4;

             const beamGrad = ctx.createLinearGradient(sx, sy, topX, sy - 100);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";

// Optimization: Precompute Hex Polygon Offsets
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

// Procedural Noise function
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

export const TerrainRenderer = {

    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any
    ) {
        const BASE_THICKNESS = 12; // Visual foundation thickness
        const topY = height; 

        // 1. Draw Side Faces (The Stack)
        // Rotated 45deg: Front faces are 5, 0, 1 (Right-Down, Down, Left-Down)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight;
            grad.addColorStop(0, baseColor);
            grad.addColorStop(1, '#020617'); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // "Layer Lines" for Block Stack Effect
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            // Outline Side
            ctx.strokeStyle = 'rgba(255,255,255,0.05)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face (Base)
        this.traceTopFace(ctx, x, y - topY);

        const topGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.detail); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // 3. Rim Light (New) - Adds a highlight to the top edge closest to light source
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        ctx.beginPath();
        // Highlight top-left and top-right edges
        ctx.moveTo(x + HEX_CORNERS[4].x, y - topY + HEX_CORNERS[4].y);
        ctx.lineTo(x + HEX_CORNERS[3].x, y - topY + HEX_CORNERS[3].y); // Top
        ctx.lineTo(x + HEX_CORNERS[2].x, y - topY + HEX_CORNERS[2].y); // Top Left
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;
        ctx.globalAlpha = 0.3; 

        const n = noise(q, r);
        const n2 = noise(r, q);

        if (type === 'VOID') {
            if (n > 0.6) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            } else if (n < 0.3) {
                ctx.beginPath();
                ctx.arc(cx + n2 * 10, cy + n * 10, 2, 0, Math.PI * 2);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            const tufts = Math.floor(n * 3) + 1;
            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 10;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox - 3, cy + oy - 5);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox + 3, cy + oy - 5);
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.5;
            ctx.fillStyle = '#fff';
            if (n > 0.5) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 5);
                ctx.lineTo(cx + 15, cy - 5);
                ctx.lineTo(cx + 18, cy - 4);
                ctx.lineTo(cx - 12, cy + 6);
                ctx.fill();
            }
        } else if (type === 'MAGMA') {
            // Glowing cracks
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 0.6 + Math.sin(performance.now() * 0.005 + n * 10) * 0.2;
            ctx.beginPath();
            ctx.moveTo(cx - 10, cy);
            ctx.lineTo(cx - 5, cy + 5 * n);
            ctx.lineTo(cx + 5, cy - 5 * n2);
            ctx.lineTo(cx + 10, cy);
            ctx.stroke();

            if (n > 0.8) {
                ctx.fillStyle = '#fb923c';
                ctx.globalAlpha = 0.8;
                ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.2;
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 10, 30, 0.5, 2.0);
            ctx.stroke();
        }

        ctx.restore();
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

import { HexUtils, MapConfig } from "../../utils";

// Helper: Determine if a color is "Chaos" (Red/Dark) or "Order" (Blue/Light)
export function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') || 
           c.includes('#1c');
}

// Helper: Ensure 6-digit hex for alpha appending logic
export function normalizeHex(color: string): string {
    if (color.startsWith('#') && color.length === 4) {
        return '#' + color[1] + color[1] + color[2] + color[2] + color[3] + color[3];
    }
    return color;
}

// Helper: Calculate vertical offset during map transition
export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;
    const centerQ = Math.floor(mapConfig.w / 2);
    const centerR = Math.floor(mapConfig.h / 2);
    const hex = HexUtils.fromPx(x, y, mapConfig);
    const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
    const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);
    const d = dist / maxDist;

    if (phase === 'OUT') {
        const trigger = d * 0.3;
        if (t > trigger) {
            const fallT = Math.min(1, (t - trigger) * 2.5);
            return fallT * fallT * fallT * 1000;
        }
    } else if (phase === 'IN') {
        const trigger = d * 0.3;
        const riseT = Math.max(0, Math.min(1, (t - trigger) * 2.5));
        const easedRise = 1 - Math.pow(1 - riseT, 3);
        return (1 - easedRise) * 1000;
    }
    return 0;
}

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderableItem } from "../../grid";
import { getTransitionOffset, isChaosStyle } from "../utils";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    collect(
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             const getVisualPos = (lx: number, ly: number) => {
                 const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: lx, y: ly});
                 const t = Math.min(1, Math.max(0, currentDist / totalDist));
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'FIREBALL' || p.skill.visual === 'BOMB') {
                     const apex = Math.min(150, totalDist * 0.3);
                     arcOffset = Math.sin(t * Math.PI) * apex; 
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const headVis = getVisualPos(p.x, p.y);

             // Direction Logic
             const lookAheadDist = 5;
             const currentDir = Vector.sub(p.targetPos, {x: p.x, y: p.y});
             const distRemaining = Vector.mag(currentDir);
             let dir;
             if (distRemaining > 0.1) {
                 dir = Vector.normalize(currentDir);
             } else {
                 const totalTrajectory = Vector.sub(p.targetPos, {x: p.startX, y: p.startY});
                 const totalMag = Vector.mag(totalTrajectory);
                 dir = totalMag > 0.1 ? Vector.normalize(totalTrajectory) : {x: 1, y: 0};
             }

             const nextLx = p.x + dir.x * lookAheadDist;
             const nextLy = p.y + dir.y * lookAheadDist;
             const nextVis = getVisualPos(nextLx, nextLy);
             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y}) * 0.1) : 0;

             // Style Logic
             const isChaos = isChaosStyle(p.skill.color);

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        const trailVis = p.trail.map(t => getVisualPos(t.x, t.y));
                        trailVis.push(headVis);

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // Thin faint line
                            ctx.beginPath();
                            ctx.moveTo(trailVis[0].x, trailVis[0].y);
                            for (let i = 1; i < trailVis.length; i++) ctx.lineTo(trailVis[i].x, trailVis[i].y);
                            ctx.strokeStyle = `rgba(255, 255, 255, 0.2)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGICAL RIBBON
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            // Draw segment by segment to allow for jitter/style
                            for (let i = 0; i < trailVis.length - 1; i++) {
                                const pt = trailVis[i];
                                const next = trailVis[i+1];
                                const ratio = i / (trailVis.length - 1); 

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;
                                ctx.strokeStyle = p.skill.color;

                                ctx.beginPath();

                                if (isChaos) {
                                    // CHAOS: Jittery, Electric Arc
                                    const jitterX = (Math.random() - 0.5) * 5 * (1-ratio);
                                    const jitterY = (Math.random() - 0.5) * 5 * (1-ratio);
                                    ctx.moveTo(pt.x + jitterX, pt.y + jitterY);
                                    ctx.lineTo(next.x + jitterX, next.y + jitterY);
                                    ctx.globalAlpha = ratio; 
                                } else {
                                    // ORDER: Smooth, glowing center
                                    ctx.moveTo(pt.x, pt.y);
                                    ctx.lineTo(next.x, next.y);
                                    ctx.globalAlpha = ratio * 0.6;
                                }
                                ctx.stroke();

                                if (!isChaos) {
                                    // White core for Order
                                    ctx.lineWidth = baseWidth * ratio * 0.4;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }
};

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(p.x, p.y);
                ctx.globalCompositeOperation = 'lighter';
                const tx = p.targetX - p.x;
                const ty = p.targetY - p.y;

                if (isChaos) {
                    // Siphon / Lightning
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(0, 0);
                    // Jagged line
                    const segs = 10;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(tx * ratio + jit, ty * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    // Dark Core
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    // Holy Beam
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(tx, ty); ctx.stroke();
                    // White Hot Center
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.translate(p.x, p.y);
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); 
            if(isChaos) {
                // Jagged Ring
                for(let i=0; i<=16; i++) {
                    const a = (i/16)*Math.PI*2;
                    const rr = r * (1 + (Math.random()-0.5)*0.2);
                    if(i===0) ctx.moveTo(Math.cos(a)*rr, Math.sin(a)*rr);
                    else ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
                }
            } else {
                ctx.arc(0, 0, r, 0, Math.PI * 2); 
            }
            ctx.stroke();
            ctx.closePath();

        } else if (p.type === 'SPARK') {
            ctx.translate(p.x, p.y);
            const r = p.size;
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.3, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
            ctx.translate(p.x, p.y);
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.beginPath();
            const s = p.size;
            if (p.type === 'SHARD') {
                ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            } else {
                ctx.rect(-s/2, -s/2, s, s);
            }
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.3)';
            ctx.lineWidth = 1;
            ctx.stroke();
        } else if (p.type === 'PILLAR') {
            ctx.translate(p.x, p.y - 20); // slightly above ground
            this.drawPillar(ctx, p, progress, isChaos);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(p.x, p.y - 20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(p.x, p.y - 20);
            this.drawDomain(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 
        const height = 1200; 
        const baseWidth = 60 * (1 + Math.sin(progress * 20) * 0.1);

        ctx.save();
        ctx.scale(1, 0.55); 

        // Ground Blast Ring
        const ringSize = baseWidth * 2;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.2, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : '#fff');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        // BEAM COLUMN
        if (isChaos) {
            // CHAOS PILLAR: Dark Core, Unstable
            const chaosGrad = ctx.createLinearGradient(0, 0, 0, -height);
            chaosGrad.addColorStop(0, p.color);
            chaosGrad.addColorStop(0.5, 'transparent');

            ctx.fillStyle = chaosGrad;
            ctx.globalAlpha = alpha * 0.8;

            ctx.beginPath();
            const segs = 10;
            const hw = baseWidth / 2;
            ctx.moveTo(-hw, 0);
            for(let i=1; i<=segs; i++) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(-hw + xOff, y);
            }
            for(let i=segs; i>=0; i--) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(hw + xOff, y);
            }
            ctx.closePath();
            ctx.fill();

            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = '#000';
            ctx.globalAlpha = alpha * 0.6;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

        } else {
            // ORDER PILLAR: Bright Core
            const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
            coreGrad.addColorStop(0, '#ffffff');
            coreGrad.addColorStop(0.3, '#ffffff');
            coreGrad.addColorStop(1, 'transparent');

            ctx.fillStyle = coreGrad;
            ctx.globalAlpha = alpha;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.7, 'transparent');

            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.5;
            ctx.fillRect(-baseWidth, -height, baseWidth * 2, height);
        }
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';

        const r = progress * 300; 
        const width = 30 * (1 - progress);

        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress);

        ctx.beginPath(); 
        if (isChaos) {
            for(let i=0; i<=32; i++) {
                const a = (i/32)*Math.PI*2;
                const d = r + (Math.random()-0.5) * 30;
                if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
            }
        } else {
            ctx.arc(0, 0, r, 0, Math.PI * 2); 
        }
        ctx.closePath();
        ctx.stroke();
    },

    drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         ctx.scale(1, 0.55); 
         const time = performance.now() / 1000;
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;

         ctx.globalCompositeOperation = 'lighter'; 

         // Base Field
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 
         const safeColor = normalizeHex(p.color);
         grad.addColorStop(0.7, safeColor + '4D'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');

         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.5 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Rune Rings
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;

         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         if (isChaos) {
             ctx.setLineDash([10, 25]); 
             ctx.beginPath();
             for(let i=0; i<=12; i++) {
                 const a = (i/12)*Math.PI*2;
                 const d = r * 0.95 + (i%2===0 ? 15 : -15);
                 if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                 else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
             }
             ctx.closePath();
             ctx.stroke();
         } else {
             ctx.setLineDash([50, 20]); 
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
             ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); 
             ctx.setLineDash([20, 10]);
             ctx.stroke();
         }
         ctx.restore();

         // Vertical Energy Walls
         ctx.globalAlpha = 0.3 * (1 - progress);
         const spikeCount = isChaos ? 8 : 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + (isChaos ? -time : time);
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;

             ctx.beginPath();
             ctx.moveTo(sx, sy);
             const topX = sx + (isChaos ? (Math.random()-0.5)*40 : 0);
             ctx.lineTo(topX, sy - 100); 
             ctx.lineWidth = 4;

             const beamGrad = ctx.createLinearGradient(sx, sy, topX, sy - 100);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
};

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderableItem } from "../grid";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    // --- Rendering Collections ---

    public collectRenderables(
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Projectiles (Delegated)
        list.push(...ProjectileRenderer.collect(engine, getTerrainHeight, transitionT, transitionPhase));

        return list;
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            // DrawY logic included in Particle Renderer translation if needed, 
            // but we need to pass the offset-adjusted Y to the renderer.
            // However, the renderer functions assume they handle translation.
            // Let's modify the particle position temporarily or pass the adjusted Y.

            // To avoid mutating the particle state, we handle translation here 
            // BUT ParticleRenderer expects to handle specific sub-translations (like -20 for Pillars).
            // So we just update the Y passed to the renderer context? No, Renderer uses p.x/p.y.

            // Solution: We apply the global transition offset here in the context,
            // then ParticleRenderer draws at (0,0) relative to that, OR we update P copy.

            // Simpler: Pass the actual draw coordinate to a draw function is better, 
            // but current architecture stores state in P.

            // We will modify the Y in a temporary object or just translate the context here
            // BEFORE calling the renderer.

            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            // We temporarily override P.y for the draw call to ensure it draws at the transition offset
            // efficient way: just translate context to the draw position and tell renderer to draw at 0,0 relative?
            // ParticleRenderer uses `ctx.translate(p.x, p.y...)`. 
            // Let's create a proxy particle or just modify the draw call to accept x/y overrides.
            // For now, to minimize changes to the signature, let's mutate a temporary clone if needed, 
            // OR just let the ParticleRenderer handle the `p` object but we handle the context transform?

            // Re-reading ParticleRenderer: It does `ctx.translate(p.x, p.y)`. 
            // Let's update ParticleRenderer to accept an override Y if we want to be clean, 
            // OR just rely on the fact that we can cheat by modifying p temporarily (unsafe).

            // SAFEST: Let's manually translate the context by the offset, 
            // and tell ParticleRenderer to draw `p` but assuming `p.y` is 0-relative? No that breaks logic.

            // Let's update ParticleRenderer to take x/y arguments! 
            // Actually, I already refactored ParticleRenderer to use p.x/p.y inside.
            // I will cheat slightly: I will mutate p.y, draw, then restore it. 
            // It's single threaded JS, it's fine for this frame.

            const originalY = p.y;
            p.y = drawY; // Apply transition offset & Z

            // Note: p.z is already handled in drawY calculation above? 
            // The original code was: `const drawY = p.y + offset - p.z;`
            // Then `ctx.translate(p.x, drawY);`
            // The new ParticleRenderer does `ctx.translate(p.x, p.y);`
            // So setting `p.y = drawY` works perfectly.

            ParticleRenderer.drawSingleParticle(ctx, p, progress, isChaos);

            p.y = originalY; // Restore
        });
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { Hex, GameEvent, Skill, Team } from "../types";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../constants";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import * as VFXSpawners from "./systems/vfx/spawners"; 
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";

// NEW Renderers
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";

// Constants
const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20; 
const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_OFFSET_Y = 80; 

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;

    // New Composition Renderers
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;

    // --- SENIOR TA UPGRADE: TRAUMA SYSTEM ---
    // Instead of linear shake, we use trauma (0 to 1).
    // Shake = trauma^2 * maxShake.
    // Trauma decays linearly over time.
    private trauma: number = 0;
    private maxShakeOffset: number = 25;
    private maxShakeAngle: number = 0.05; // Radians

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();

        // Initialize sub-renderers
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;

        // Trauma Decay
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * 0.8); // Recover speed
        }

        // Delegate updates
        this.tacticalRenderer.update(dt, engine);
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    // Add trauma. Clamps to 1.0.
    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     color = val > 100 ? '#ef4444' : '#fff'; 
                     size = val > 100 ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(this.vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         this.addTrauma(0.6); // Heavy Shake
                     }
                 }
            }

            // 2. VFX Handling
            switch (event.type) {
                case 'DAMAGE': 
                    const isHeavy = Math.abs(event.value || 0) > 50;
                    VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY - 20, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');

                    if (isHeavy) {
                        this.addTrauma(0.3);
                        VFXSpawners.spawnDebris(this.vfx, event.pos.x, visualY - 20, event.color || '#fff', 3);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = this.grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualY - 20; 

                            VFXSpawners.spawnBeam(this.vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(this.vfx, tx, ty, 0, 8, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    VFXSpawners.spawnUnitShatter(this.vfx, event.pos.x, visualY, team);
                    this.addTrauma(0.5);
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(this.vfx, event.pos.x, visualY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    // Trigger the physics-based domain shatter
                    VFXSpawners.spawnDomainShatter(this.vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    this.addTrauma(0.2);
                    break;
            }
        });
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, visualY: number): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            this.addTrauma(0.8); // Massive Impact
            VFXSpawners.spawnDivinePillar(this.vfx, event.pos.x, visualY, color, 1.5);
            VFXSpawners.spawnShockwave(this.vfx, event.pos.x, visualY, color, 2.0);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = this.grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const distToCenter = Math.abs(h.q - centerHex.q) + Math.abs(h.r - centerHex.r);
                        if (distToCenter > 0) {
                            const delay = distToCenter * 0.05;
                            VFXSpawners.spawnDivinePillar(this.vfx, tilePos.x, tileVisualY, color, 0.7, delay);
                            VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        } else {
                            VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        }
                    }
                });
            } else {
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 3.0);
                VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY, 0, 50, color, 2.0, 1.0, 'SPARK');
            }
        } else {
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(this.vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 1.2);
            } else {
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 0.8);
                VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY, 0, 8, color, 1.2, 0.6, 'SPARK');
            }
        }
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const defaultStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Clear & Background
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.backgroundRenderer.draw(ctx, canvasWidth, canvasHeight, scene, engine.mapConfig, this.globalTime);

        // 2. Calculate Trauma Shake
        // Non-linear shake: trauma^2
        const shakeFactor = this.trauma * this.trauma;
        const offsetX = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        const offsetY = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        const offsetRot = (Math.random() * 2 - 1) * this.maxShakeAngle * shakeFactor;

        ctx.save();

        // 3. Apply Camera + Shake
        ctx.translate(canvasWidth / 2 + offsetX, canvasHeight / 2 + offsetY);
        ctx.rotate(offsetRot);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x - canvasWidth / 2 / camera.zoom, -camera.y - canvasHeight / 2 / camera.zoom);

        // 4. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfxRenderer.collectRenderables(
            engine,
            this.vfx,
            (q, r) => this.grid.getTerrainHeight(q, r, engine),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), this.globalTime, highlight, engine.mapConfig
        ));

        // Iterate over Obstacles
        engine.obstacles.forEach((type, key) => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r, engine);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         const sprite = SpriteManager.getObstacleSprite(type || defaultStyle);
                         c.drawImage(sprite, pos.x - 32, visualY - terrainH - OBSTACLE_OFFSET_Y);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 5. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 6. Tactical Overlay Lines
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 7. Top VFX
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 8. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        // 9. Holographic Director HUD
        if (engine.directorTargetId) {
            ctx.restore(); 
            this.tacticalRenderer.drawHUD(ctx, engine, canvasWidth, canvasHeight, camera, this.globalTime);
            ctx.save();
        } else {
            ctx.restore();
            ctx.save();
        }

        // --- POST PROCESSING: CHROMATIC ABERRATION ---
        // Efficient Glitch: If trauma is high, copy strips of the canvas and offset them RGB channels
        if (this.trauma > 0.3) {
            ctx.restore(); // Get out of Camera space
            ctx.save();

            // Only apply cheap full-screen aberration
            const glitchIntensity = this.trauma * 10;

            // 1. Red Channel Offset (Composite Multiply or Screen trick)
            // Since we can't easily channel split in 2D Canvas without getImageData (slow),
            // We fake it by drawing the canvas over itself with a specific blending mode and tint.
            // A performant fake: Slice random strips

            const strips = Math.floor(this.trauma * 10);
            for(let i=0; i<strips; i++) {
                const y = Math.random() * canvasHeight;
                const h = Math.random() * 50 + 10;
                const offX = (Math.random() - 0.5) * glitchIntensity * 4;

                // Draw a slice offset
                // Source: x, y, w, h
                // Dest: x+off, y, w, h
                ctx.drawImage(ctx.canvas, 
                    0, y, canvasWidth, h, 
                    offX, y, canvasWidth, h
                );
            }

            // 2. Color Tint Overlay during heavy hits
            if (this.trauma > 0.6) {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = `rgba(255, 0, 0, ${this.trauma * 0.1})`;
                ctx.fillRect(0, 0, canvasWidth, canvasHeight);
            }

            ctx.restore();
            ctx.save(); // Restore state for final restore
        }

        ctx.restore(); // Final restore

        // 10. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }
}

import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

// Helper: Chaos color detection
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') ||
           c.includes('#1c');
}

// Pseudo-Random Noise generator for textures
function pseudoNoise(x: number, y: number, seed: number) {
    const n = Math.sin(x * 12.9898 + y * 78.233 + seed) * 43758.5453;
    return n - Math.floor(n);
}

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         const grad = ctx.createRadialGradient(cx, cy, r * 0.1, cx, cy, r);
         grad.addColorStop(0, '#fff');        
         grad.addColorStop(0.4, color);       
         grad.addColorStop(1, 'transparent'); 

         ctx.fillStyle = grad;

         if (isChaos) {
             // Chaos: Unstable plasma blob
             ctx.beginPath();
             const spikes = 12;
             for(let i=0; i<spikes; i++) {
                 const angle = (i / spikes) * Math.PI * 2;
                 // Randomize radius for "wobbly" look
                 const rad = r * (0.6 + Math.random() * 0.4);
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();
         } else {
             // Order: Perfect Sphere with Cross Flare
             ctx.beginPath(); 
             ctx.arc(cx, cy, r * 0.8, 0, Math.PI * 2); 
             ctx.fill();

             // Lens flare cross
             ctx.fillStyle = '#fff';
             ctx.globalAlpha = 0.8;
             ctx.beginPath();
             // Horizontal soft beam
             ctx.ellipse(cx, cy, r, r*0.15, 0, 0, Math.PI*2);
             // Vertical sharp beam
             ctx.ellipse(cx, cy, r*0.15, r, 0, 0, Math.PI*2);
             ctx.fill();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        // Use Noise for Fog
        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(0.6, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.3;

        // Fractal Summation for detail
        for(let i=0; i<12; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * (FOG_SIZE * 0.3);
            const size = FOG_SIZE * (0.1 + Math.random() * 0.2);

            ctx.beginPath(); 
            ctx.arc(cx + Math.cos(angle)*dist, cy + Math.sin(angle)*dist, size, 0, Math.PI*2); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = 50;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        if (isChaos) {
            // --- CHAOS RUNE (Jagged, asymmetrical, blood-like) ---
            ctx.beginPath();
            const points = 9;
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 2 / points);
                // Heavy distortion
                const r = radius * (0.85 + Math.random() * 0.3); 
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();

            // Inner scribble / Eye
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - 25, cy); 
            ctx.quadraticCurveTo(cx, cy - 15, cx + 25, cy);
            ctx.quadraticCurveTo(cx, cy + 15, cx - 25, cy);
            ctx.stroke();

            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI*2); ctx.fill();

        } else {
            // --- ORDER RUNE (Geometric, Symmetrical, Mandalas) ---
            // Outer Ring
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1.5;
            if (isUlt) {
                // Complex Hexagram (Star of David style)
                const drawPoly = (sides: number, r: number, offset: number) => {
                    ctx.beginPath();
                    for (let i = 0; i <= sides; i++) {
                        const angle = offset + (i * Math.PI * 2) / sides;
                        const x = cx + Math.cos(angle) * r;
                        const y = cy + Math.sin(angle) * r;
                        if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    }
                    ctx.stroke();
                };

                drawPoly(3, radius, -Math.PI/2); // Triangle Up
                drawPoly(3, radius, Math.PI/2);  // Triangle Down

                // Inner Circle
                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.5, 0, Math.PI*2); ctx.stroke();

            } else {
                // Simple Square/Diamond
                ctx.save();
                ctx.translate(cx, cy);
                ctx.rotate(Math.PI/4);
                ctx.strokeRect(-radius * 0.7, -radius * 0.7, radius * 1.4, radius * 1.4);
                ctx.restore();

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.3, 0, Math.PI*2); ctx.stroke();
            }
        }

        return canvas;
    },

    generateWarningRune(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64;
        const cy = 32;
        const color = '#ef4444'; 

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.scale(1, 0.5); 

        // Skull-like Hazard Symbol
        ctx.beginPath(); 
        ctx.arc(cx, cy * 2, 40, 0, Math.PI * 2); 
        ctx.stroke();

        ctx.beginPath();
        // X mark
        ctx.moveTo(cx - 15, cy * 2 - 25); ctx.lineTo(cx + 15, cy * 2 + 25);
        ctx.moveTo(cx + 15, cy * 2 - 25); ctx.lineTo(cx - 15, cy * 2 + 25);
        ctx.stroke();

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 12;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                // Chaos: Barbed bone arrow | Order: Energy light arrow
                ctx.strokeStyle = isChaos ? '#a8a29e' : '#e2e8f0'; 
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(75, cy); ctx.stroke();

                ctx.fillStyle = isChaos ? '#7f1d1d' : '#f0f9ff';
                ctx.beginPath();
                if (isChaos) {
                    // Jagged Head
                    ctx.moveTo(85, cy); 
                    ctx.lineTo(65, cy - 8); ctx.lineTo(70, cy); ctx.lineTo(65, cy + 8);
                } else {
                    // Clean Bodkin
                    ctx.moveTo(90, cy); ctx.lineTo(70, cy - 6); ctx.lineTo(70, cy + 6);
                }
                ctx.closePath();
                ctx.fill();

                // Trail feather / energy
                ctx.strokeStyle = color;
                ctx.beginPath();
                if (isChaos) {
                    ctx.moveTo(20, cy); ctx.lineTo(5, cy - 10);
                    ctx.moveTo(20, cy); ctx.lineTo(5, cy + 10);
                } else {
                    // Glowing flight
                    ctx.moveTo(15, cy - 5); ctx.lineTo(5, cy); ctx.lineTo(15, cy + 5);
                }
                ctx.stroke();
                break;

            case 'FIREBALL':
            case 'BOMB':
                // Core
                const coreGrad = ctx.createRadialGradient(cx+20, cy, 0, cx+20, cy, 15);
                coreGrad.addColorStop(0, '#fff');
                coreGrad.addColorStop(0.5, color);
                coreGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = coreGrad;

                ctx.beginPath(); ctx.arc(cx + 20, cy, 14, 0, Math.PI * 2); ctx.fill();

                // Tail / Comet
                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.beginPath();
                if (isChaos) {
                    // Wild Flame
                    ctx.moveTo(cx + 20, cy - 12);
                    ctx.lineTo(cx, cy - 20); ctx.lineTo(cx - 20, cy - 5);
                    ctx.lineTo(cx - 35, cy);
                    ctx.lineTo(cx - 20, cy + 8); ctx.lineTo(cx, cy + 22);
                    ctx.lineTo(cx + 20, cy + 12);
                } else {
                    // Smooth Streamline
                    ctx.ellipse(cx + 5, cy, 35, 12, 0, 0, Math.PI * 2);
                }
                ctx.fill();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                if (isChaos) {
                    // --- CHAOS BOLT (Dark Energy Skull/Claw) ---
                    ctx.fillStyle = '#1c1917'; // Dark core
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 3;

                    ctx.beginPath();
                    // Jagged shape
                    ctx.moveTo(cx + 35, cy);
                    ctx.lineTo(cx + 10, cy - 15);
                    ctx.lineTo(cx - 10, cy - 5);
                    ctx.lineTo(cx - 30, cy);
                    ctx.lineTo(cx - 10, cy + 5);
                    ctx.lineTo(cx + 10, cy + 15);
                    ctx.closePath();
                    ctx.fill(); ctx.stroke();

                    // Lightning Arcs
                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx + 45, cy - 12);
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx + 45, cy + 12);
                    ctx.stroke();

                } else {
                    // --- HOLY BOLT (Geometric Star/Diamond) ---
                    // Inner Light
                    const boltGrad = ctx.createRadialGradient(cx, cy, 2, cx, cy, 25); 
                    boltGrad.addColorStop(0, '#fff');
                    boltGrad.addColorStop(0.5, color);
                    boltGrad.addColorStop(1, 'transparent');
                    ctx.fillStyle = boltGrad;
                    ctx.beginPath(); ctx.arc(cx, cy, 25, 0, Math.PI * 2); ctx.fill();

                    // Hard Core Shape
                    ctx.fillStyle = '#fff';
                    ctx.shadowColor = '#fff';
                    ctx.beginPath();
                    // Diamond
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx, cy - 12);
                    ctx.lineTo(cx - 15, cy); ctx.lineTo(cx, cy + 12);
                    ctx.closePath();
                    ctx.fill();

                    // Orbital Rings
                    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.shadowBlur = 5;
                    ctx.beginPath(); 
                    ctx.ellipse(cx, cy, 15, 8, 0, 0, Math.PI*2); 
                    ctx.stroke();
                }
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.scale(1, 0.5); 

        // Procedural Noise Rings instead of simple gradient
        const rings = 5;
        for(let i = 0; i < rings; i++) {
            const r = (50 / rings) * (i + 1);
            const alpha = 1.0 - (i / rings);

            ctx.beginPath();
            ctx.strokeStyle = color;
            ctx.lineWidth = 2 + Math.random() * 2;
            ctx.globalAlpha = alpha * 0.5;

            // Noisy circle
            const segments = 24;
            for(let j=0; j<=segments; j++) {
                const a = (j/segments) * Math.PI * 2;
                const offset = pseudoNoise(j, i, 100) * 10;
                const radius = r + offset;
                const px = cx + Math.cos(a) * radius;
                const py = cy * 2 + Math.sin(a) * radius;
                if (j===0) ctx.moveTo(px, py);
                else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        }

        // Inner Core
        const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 25);
        grad.addColorStop(0, isChaos ? '#000' : '#fff'); 
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.8;
        ctx.beginPath(); ctx.arc(cx, cy * 2, 25, 0, Math.PI*2); ctx.fill();

        return canvas;
    }
};

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Shared translation
        ctx.translate(p.x, p.y);

        if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                // Beams are world-space endpoints, undo translate for now or calculate relative
                // Easier to undo translate
                ctx.translate(-p.x, -p.y);

                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    // Siphon / Lightning
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    // Jagged line
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    // Dark Core
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    // Holy Beam
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    // White Hot Center
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); 
            if(isChaos) {
                // Jagged Ring
                for(let i=0; i<=16; i++) {
                    const a = (i/16)*Math.PI*2;
                    const rr = r * (1 + (Math.random()-0.5)*0.2);
                    if(i===0) ctx.moveTo(Math.cos(a)*rr, Math.sin(a)*rr);
                    else ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
                }
            } else {
                ctx.arc(0, 0, r, 0, Math.PI * 2); 
            }
            ctx.stroke();
            ctx.closePath();

        } else if (p.type === 'SPARK') {
            // High Tech Upgrade: Velocity Stretch (Motion Blur)
            const speedSq = p.vx * p.vx + p.vy * p.vy;
            if (speedSq > 100) {
                const angle = Math.atan2(p.vy, p.vx);
                ctx.rotate(angle);
                // Stretch based on speed
                const stretch = Math.min(4.0, 1.0 + Math.sqrt(speedSq) * 0.005);
                ctx.scale(stretch, 1.0 / Math.max(1.0, stretch * 0.5));
            }

            const r = p.size;
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.4, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
            // Physics rotation applied in VFXSystem, render here
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.beginPath();
            const s = p.size;
            if (p.type === 'SHARD') {
                ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            } else {
                ctx.rect(-s/2, -s/2, s, s);
            }
            ctx.fill();
            // Rim Light
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.lineWidth = 1;
            ctx.stroke();
        } else if (p.type === 'PILLAR') {
            // Undo translate to use relative coord logic inside func (or refactor, but keeping consistent)
            ctx.translate(0, -20); 
            this.drawPillar(ctx, p, progress, isChaos);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawDomain(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 
        const height = 1200; 
        const baseWidth = 60 * (1 + Math.sin(progress * 20) * 0.1);

        ctx.save();
        ctx.scale(1, 0.55); 

        // Ground Blast Ring
        const ringSize = baseWidth * 2;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.2, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : '#fff');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        // BEAM COLUMN
        if (isChaos) {
            // CHAOS PILLAR: Dark Core, Unstable
            const chaosGrad = ctx.createLinearGradient(0, 0, 0, -height);
            chaosGrad.addColorStop(0, p.color);
            chaosGrad.addColorStop(0.5, 'transparent');

            ctx.fillStyle = chaosGrad;
            ctx.globalAlpha = alpha * 0.8;

            ctx.beginPath();
            const segs = 10;
            const hw = baseWidth / 2;
            ctx.moveTo(-hw, 0);
            for(let i=1; i<=segs; i++) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(-hw + xOff, y);
            }
            for(let i=segs; i>=0; i--) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(hw + xOff, y);
            }
            ctx.closePath();
            ctx.fill();

            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = '#000';
            ctx.globalAlpha = alpha * 0.6;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

        } else {
            // ORDER PILLAR: Bright Core
            const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
            coreGrad.addColorStop(0, '#ffffff');
            coreGrad.addColorStop(0.3, '#ffffff');
            coreGrad.addColorStop(1, 'transparent');

            ctx.fillStyle = coreGrad;
            ctx.globalAlpha = alpha;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.7, 'transparent');

            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.5;
            ctx.fillRect(-baseWidth, -height, baseWidth * 2, height);
        }
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';

        const r = progress * 300; 
        const width = 30 * (1 - progress);

        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress);

        ctx.beginPath(); 
        if (isChaos) {
            for(let i=0; i<=32; i++) {
                const a = (i/32)*Math.PI*2;
                const d = r + (Math.random()-0.5) * 30;
                if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
            }
        } else {
            ctx.arc(0, 0, r, 0, Math.PI * 2); 
        }
        ctx.closePath();
        ctx.stroke();
    },

    drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         ctx.scale(1, 0.55); 
         const time = performance.now() / 1000;
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;

         ctx.globalCompositeOperation = 'lighter'; 

         // Base Field
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 
         const safeColor = normalizeHex(p.color);
         grad.addColorStop(0.7, safeColor + '4D'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');

         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.5 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Rune Rings
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;

         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         if (isChaos) {
             ctx.setLineDash([10, 25]); 
             ctx.beginPath();
             for(let i=0; i<=12; i++) {
                 const a = (i/12)*Math.PI*2;
                 const d = r * 0.95 + (i%2===0 ? 15 : -15);
                 if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                 else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
             }
             ctx.closePath();
             ctx.stroke();
         } else {
             ctx.setLineDash([50, 20]); 
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
             ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); 
             ctx.setLineDash([20, 10]);
             ctx.stroke();
         }
         ctx.restore();

         // Vertical Energy Walls
         ctx.globalAlpha = 0.3 * (1 - progress);
         const spikeCount = isChaos ? 8 : 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + (isChaos ? -time : time);
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;

             ctx.beginPath();
             ctx.moveTo(sx, sy);
             const topX = sx + (isChaos ? (Math.random()-0.5)*40 : 0);
             ctx.lineTo(topX, sy - 100); 
             ctx.lineWidth = 4;

             const beamGrad = ctx.createLinearGradient(sx, sy, topX, sy - 100);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
};

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { Hex, GameEvent, Skill, Team } from "../types";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../constants";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import * as VFXSpawners from "./systems/vfx/spawners"; 
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";

// NEW Renderers
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";

// Constants
const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20; 
const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_OFFSET_Y = 80; 

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;

    // New Composition Renderers
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;

    // --- SENIOR TA UPGRADE: TRAUMA SYSTEM (Rebalanced) ---
    // Instead of linear shake, we use trauma (0 to 1).
    // Shake = trauma^2 * maxShake.
    // Trauma decays linearly over time.
    private trauma: number = 0;

    // Toned down values for better readability
    private maxShakeOffset: number = 12; // Was 25
    private maxShakeAngle: number = 0.02; // Was 0.05

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();

        // Initialize sub-renderers
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;

        // Trauma Decay
        if (this.trauma > 0) {
            // Decay faster to recover clarity quickly
            this.trauma = Math.max(0, this.trauma - dt * 1.2); 
        }

        // Delegate updates
        this.tacticalRenderer.update(dt, engine);
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    // Add trauma. Clamps to 1.0.
    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     color = val > 100 ? '#ef4444' : '#fff'; 
                     size = val > 100 ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(this.vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         // Reduced cast impact
                         this.addTrauma(0.3); 
                     }
                 }
            }

            // 2. VFX Handling
            switch (event.type) {
                case 'DAMAGE': 
                    const isHeavy = Math.abs(event.value || 0) > 50;
                    VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY - 20, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');

                    if (isHeavy) {
                        // Reduced hit impact
                        this.addTrauma(0.15);
                        VFXSpawners.spawnDebris(this.vfx, event.pos.x, visualY - 20, event.color || '#fff', 3);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = this.grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualY - 20; 

                            VFXSpawners.spawnBeam(this.vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(this.vfx, tx, ty, 0, 8, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    VFXSpawners.spawnUnitShatter(this.vfx, event.pos.x, visualY, team);
                    this.addTrauma(0.3); // Reduced from 0.5
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(this.vfx, event.pos.x, visualY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    // Trigger the physics-based domain shatter
                    VFXSpawners.spawnDomainShatter(this.vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    this.addTrauma(0.15); // Reduced
                    break;
            }
        });
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, visualY: number): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            this.addTrauma(0.5); // Massive Impact (Reduced from 0.8)
            VFXSpawners.spawnDivinePillar(this.vfx, event.pos.x, visualY, color, 1.5);
            VFXSpawners.spawnShockwave(this.vfx, event.pos.x, visualY, color, 2.0);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = this.grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const distToCenter = Math.abs(h.q - centerHex.q) + Math.abs(h.r - centerHex.r);
                        if (distToCenter > 0) {
                            const delay = distToCenter * 0.05;
                            VFXSpawners.spawnDivinePillar(this.vfx, tilePos.x, tileVisualY, color, 0.7, delay);
                            VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        } else {
                            VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        }
                    }
                });
            } else {
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 3.0);
                VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY, 0, 50, color, 2.0, 1.0, 'SPARK');
            }
        } else {
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(this.vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 1.2);
            } else {
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 0.8);
                VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY, 0, 8, color, 1.2, 0.6, 'SPARK');
            }
        }
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const defaultStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Clear & Background
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.backgroundRenderer.draw(ctx, canvasWidth, canvasHeight, scene, engine.mapConfig, this.globalTime);

        // 2. Calculate Trauma Shake (Damped)
        const shakeFactor = this.trauma * this.trauma;
        const offsetX = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        const offsetY = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        const offsetRot = (Math.random() * 2 - 1) * this.maxShakeAngle * shakeFactor;

        ctx.save();

        // 3. Apply Camera + Shake
        ctx.translate(canvasWidth / 2 + offsetX, canvasHeight / 2 + offsetY);
        ctx.rotate(offsetRot);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x - canvasWidth / 2 / camera.zoom, -camera.y - canvasHeight / 2 / camera.zoom);

        // 4. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfxRenderer.collectRenderables(
            engine,
            this.vfx,
            (q, r) => this.grid.getTerrainHeight(q, r, engine),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), this.globalTime, highlight, engine.mapConfig
        ));

        // Iterate over Obstacles
        engine.obstacles.forEach((type, key) => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r, engine);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         const sprite = SpriteManager.getObstacleSprite(type || defaultStyle);
                         c.drawImage(sprite, pos.x - 32, visualY - terrainH - OBSTACLE_OFFSET_Y);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 5. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 6. Tactical Overlay Lines
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 7. Top VFX
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 8. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        // 9. Holographic Director HUD
        if (engine.directorTargetId) {
            ctx.restore(); 
            this.tacticalRenderer.drawHUD(ctx, engine, canvasWidth, canvasHeight, camera, this.globalTime);
            ctx.save();
        } else {
            ctx.restore();
            ctx.save();
        }

        // --- POST PROCESSING: CHROMATIC ABERRATION (Optimization) ---
        // Raised threshold to 0.55 so only massive hits trigger glitch.
        if (this.trauma > 0.55) {
            ctx.restore(); // Get out of Camera space
            ctx.save();

            // Reduced intensity
            const glitchIntensity = this.trauma * 6; 

            // Reduced strip count (Max 3) to prevent total visual chaos
            const strips = Math.floor(Math.min(3, this.trauma * 5));

            ctx.globalAlpha = 0.5 * this.trauma; // Make glitch semi-transparent

            for(let i=0; i<strips; i++) {
                const y = Math.random() * canvasHeight;
                const h = Math.random() * 30 + 10;
                const offX = (Math.random() - 0.5) * glitchIntensity * 4;

                // Draw a slice offset
                ctx.drawImage(ctx.canvas, 
                    0, y, canvasWidth, h, 
                    offX, y, canvasWidth, h
                );
            }

            // Color Tint Overlay: Only very subtle vignette
            if (this.trauma > 0.8) {
                ctx.globalCompositeOperation = 'overlay';
                // Very faint red vignette
                const grad = ctx.createRadialGradient(canvasWidth/2, canvasHeight/2, canvasHeight*0.4, canvasWidth/2, canvasHeight/2, canvasHeight);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(1, `rgba(255, 0, 0, ${this.trauma * 0.15})`);
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, canvasWidth, canvasHeight);
            }

            ctx.restore();
            ctx.save(); // Restore state for final restore
        }

        ctx.restore(); // Final restore

        // 10. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }
}

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current State
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Trauma System (0.0 to 1.0)
    private trauma: number = 0;

    // Config
    private maxShakeOffset: number = 12;
    private maxShakeAngle: number = 0.02;

    // Current Frame Shake Values (Calculated in update)
    private currentShakeX: number = 0;
    private currentShakeY: number = 0;
    private currentShakeRot: number = 0;

    constructor() {}

    public sync(camera: Camera) {
        this.x = camera.x;
        this.y = camera.y;
        this.zoom = camera.zoom;
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        // Trauma Decay
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * 1.2);
        }

        // Calculate Shake (Trauma^2)
        const shakeFactor = this.trauma * this.trauma;
        this.currentShakeX = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeY = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeRot = (Math.random() * 2 - 1) * this.maxShakeAngle * shakeFactor;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) {
        ctx.translate(canvasWidth / 2 + this.currentShakeX, canvasHeight / 2 + this.currentShakeY);
        ctx.rotate(this.currentShakeRot);
        ctx.scale(this.zoom, this.zoom);
        ctx.translate(-this.x - canvasWidth / 2 / this.zoom, -this.y - canvasHeight / 2 / this.zoom);
    }

    public applyPostProcessing(ctx: CanvasRenderingContext2D, width: number, height: number) {
        // Threshold check
        if (this.trauma <= 0.55) return;

        ctx.save();

        // Glitch Strips
        const glitchIntensity = this.trauma * 6;
        const strips = Math.floor(Math.min(3, this.trauma * 5));

        ctx.globalAlpha = 0.5 * this.trauma;

        for(let i=0; i<strips; i++) {
            const y = Math.random() * height;
            const h = Math.random() * 30 + 10;
            const offX = (Math.random() - 0.5) * glitchIntensity * 4;

            ctx.drawImage(ctx.canvas, 
                0, y, width, h, 
                offX, y, width, h
            );
        }

        // Vignette Tint
        if (this.trauma > 0.8) {
            ctx.globalCompositeOperation = 'overlay';
            const grad = ctx.createRadialGradient(width/2, height/2, height*0.4, width/2, height/2, height);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(1, `rgba(255, 0, 0, ${this.trauma * 0.15})`);
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, width, height);
        }

        ctx.restore();
    }
}

import { GameEngine } from "../game";
import { GameEvent, Team } from "../../types";
import { HexUtils } from "../utils";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";

// Systems
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import * as VFXSpawners from "./vfx/spawners";

const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20;

export class VisualEventListener {

    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     color = val > 100 ? '#ef4444' : '#fff'; 
                     size = val > 100 ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         camera.addTrauma(0.3); 
                     }
                 }
            }

            // 2. VFX Handling
            switch (event.type) {
                case 'DAMAGE': 
                    const isHeavy = Math.abs(event.value || 0) > 50;
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY - 20, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');

                    if (isHeavy) {
                        camera.addTrauma(0.15);
                        VFXSpawners.spawnDebris(vfx, event.pos.x, visualY - 20, event.color || '#fff', 3);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualY - 20; 

                            VFXSpawners.spawnBeam(vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(vfx, tx, ty, 0, 8, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY, vfx, grid, camera); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualY, team);
                    camera.addTrauma(0.3); 
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(vfx, event.pos.x, visualY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    VFXSpawners.spawnDomainShatter(vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    camera.addTrauma(0.15);
                    break;
            }
        });
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            camera.addTrauma(0.5); 
            VFXSpawners.spawnDivinePillar(vfx, event.pos.x, visualY, color, 1.5);
            VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, color, 2.0);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const distToCenter = Math.abs(h.q - centerHex.q) + Math.abs(h.r - centerHex.r);
                        if (distToCenter > 0) {
                            const delay = distToCenter * 0.05;
                            VFXSpawners.spawnDivinePillar(vfx, tilePos.x, tileVisualY, color, 0.7, delay);
                            VFXSpawners.addGridFlash(vfx, h.q, h.r, color);
                        } else {
                            VFXSpawners.addGridFlash(vfx, h.q, h.r, color);
                        }
                    }
                });
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 3.0);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, color, 2.0, 1.0, 'SPARK');
            }
        } else {
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        VFXSpawners.addGridFlash(vfx, h.q, h.r, color);
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 1.2);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 0.8);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 8, color, 1.2, 0.6, 'SPARK');
            }
        }
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// NEW Renderers
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_OFFSET_Y = 80; 

// Re-export Camera for compatibility
export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    // New Composition Renderers
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();

        // Initialize sub-renderers
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;

        // Update Sub-systems
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const defaultStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Clear & Background
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.backgroundRenderer.draw(ctx, canvasWidth, canvasHeight, scene, engine.mapConfig, this.globalTime);

        // 2. Camera Transform (Delegated)
        ctx.save();
        this.camera.sync(camera);
        this.camera.applyTransform(ctx, canvasWidth, canvasHeight);

        // 3. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfxRenderer.collectRenderables(
            engine,
            this.vfx,
            (q, r) => this.grid.getTerrainHeight(q, r, engine),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), this.globalTime, highlight, engine.mapConfig
        ));

        // Iterate over Obstacles
        engine.obstacles.forEach((type, key) => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r, engine);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         const sprite = SpriteManager.getObstacleSprite(type || defaultStyle);
                         c.drawImage(sprite, pos.x - 32, visualY - terrainH - OBSTACLE_OFFSET_Y);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 4. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 5. Tactical Overlay Lines
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 6. Top VFX
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 7. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        // 8. Holographic Director HUD
        if (engine.directorTargetId) {
            ctx.restore(); // Undo Camera
            this.tacticalRenderer.drawHUD(ctx, engine, canvasWidth, canvasHeight, camera, this.globalTime);
            ctx.save(); // Restore dummy state for symmetric restore below
        } else {
            ctx.restore();
            ctx.save();
        }

        // 9. Post Processing (Delegated)
        ctx.restore(); // Ensure we are in Screen Space
        this.camera.applyPostProcessing(ctx, canvasWidth, canvasHeight);

        // 10. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }
}

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current State
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Trauma System (0.0 to 1.0)
    private trauma: number = 0;

    // Config - SENIOR TA ADJUSTMENT: Values significantly lowered for clarity
    private maxShakeOffset: number = 6;   // Was 12. Subtle thud > Wild shake.
    private maxShakeAngle: number = 0.005; // Was 0.02. Almost no rotation to prevent motion sickness.

    // Current Frame Shake Values (Calculated in update)
    private currentShakeX: number = 0;
    private currentShakeY: number = 0;
    private currentShakeRot: number = 0;

    constructor() {}

    public sync(camera: Camera) {
        this.x = camera.x;
        this.y = camera.y;
        this.zoom = camera.zoom;
    }

    public addTrauma(amount: number) {
        // Non-linear addition could be added here, but clamping is fine.
        // We rely on the input side to send smaller values.
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        // Trauma Decay - SENIOR TA ADJUSTMENT: Fast recovery (2.0)
        // Snappy impacts are better than lingering wobbles.
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * 2.0);
        }

        // Calculate Shake (Trauma^2)
        const shakeFactor = this.trauma * this.trauma;
        this.currentShakeX = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeY = (Math.random() * 2 - 1) * this.maxShakeOffset * shakeFactor;
        this.currentShakeRot = (Math.random() * 2 - 1) * this.maxShakeAngle * shakeFactor;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) {
        ctx.translate(canvasWidth / 2 + this.currentShakeX, canvasHeight / 2 + this.currentShakeY);
        ctx.rotate(this.currentShakeRot);
        ctx.scale(this.zoom, this.zoom);
        ctx.translate(-this.x - canvasWidth / 2 / this.zoom, -this.y - canvasHeight / 2 / this.zoom);
    }

    public applyPostProcessing(ctx: CanvasRenderingContext2D, width: number, height: number) {
        // Threshold check - SENIOR TA ADJUSTMENT: Only Glitch on MASSIVE hits (>0.75)
        // This keeps the game clean 95% of the time.
        if (this.trauma <= 0.75) return;

        ctx.save();

        // Glitch Strips
        const glitchIntensity = this.trauma * 6;
        const strips = Math.floor(Math.min(2, this.trauma * 3)); // Max 2 strips

        ctx.globalAlpha = 0.3 * this.trauma; // Lower opacity

        for(let i=0; i<strips; i++) {
            const y = Math.random() * height;
            const h = Math.random() * 20 + 5; // Thinner strips
            const offX = (Math.random() - 0.5) * glitchIntensity * 4;

            ctx.drawImage(ctx.canvas, 
                0, y, width, h, 
                offX, y, width, h
            );
        }

        // Vignette Tint - Subtle
        if (this.trauma > 0.9) {
            ctx.globalCompositeOperation = 'overlay';
            const grad = ctx.createRadialGradient(width/2, height/2, height*0.5, width/2, height/2, height);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(1, `rgba(255, 0, 0, ${this.trauma * 0.1})`);
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, width, height);
        }

        ctx.restore();
    }
}

import { VFXSystem } from "../vfx";
import { Team } from "../../../types";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team) {
    // Colors
    const armorColor = team === Team.BLUE ? '#e2e8f0' : '#27272a';
    const trimColor = team === Team.BLUE ? '#fbbf24' : '#a1a1aa';
    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';

    // 1. Armor Shards (Heavy chunks) - KEEP FOR DEATH
    for (let i = 0; i < 6; i++) { 
        const angle = Math.random() * Math.PI * 2;
        const speed = 100 + Math.random() * 150;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = 30 + Math.random() * 30; 
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 200; 

        p.life = 2.0; p.maxLife = 2.0; 
        p.color = Math.random() > 0.5 ? armorColor : trimColor;
        p.size = 5 + Math.random() * 4; 
        p.type = 'SHARD'; 
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 20;
        p.delay = 0;
        system.state.particles.push(p);
    }

    // 2. Core Sparks
    spawnExplosion(system, x, y, 30, 15, coreColor, 1.2, 0.6, 'SPARK');

    // 3. Shockwave
    addImpact(system, x, y, coreColor, 'RING', 0.5);

    // 4. Ground Scorch
    addDecal(system, x, y, '#000');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); // Reduced count

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 

        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 20 + Math.random() * 30;

        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Center "Poof"
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
    addImpact(system, x, y, '#ffffff', 'RING', 0.15);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; // Shorter life
    p.color = color; p.size = 4;
    p.type = 'BEAM';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    // SENIOR TA OPTIMIZATION: Cap max particles per explosion to avoid overdraw
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);

    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd;
        p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4);
        p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type;
        p.delay = 0;

        system.state.particles.push(p);
    }
}

export function spawnDebris(system: VFXSystem, x: number, y: number, color: string, count: number) {
    // SUBTRACTION DESIGN: 
    // Standard hits produce too much noise with debris.
    // We comment this out for general usage, effectively disabling it unless explicitly needed for major events.
    /*
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 50 + 20;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = 20;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = Math.random() * 100 + 100;
        p.life = 1.5; p.maxLife = 1.5;
        p.color = color; p.size = Math.random() * 3 + 2;
        p.type = 'DEBRIS';
        p.delay = 0;

        system.state.particles.push(p);
    }
    */
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnPillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, color, 'RING', 0.8);
}

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    spawnPillar(system, x, y, color, life, delay);
}

export function spawnPillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100;
    p.type = 'PILLAR';
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addGridFlash(system: VFXSystem, q: number, r: number, color: string) {
    system.state.gridFlashes.push({ q, r, color, life: 0.5 }); // Reduced life
}

export function addImpact(system: VFXSystem, x: number, y: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 5;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
