    spawnPillar(system, x, y, color, life, delay);
}

export function spawnPillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100;
    p.type = 'PILLAR';
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addGridFlash(system: VFXSystem, q: number, r: number, color: string) {
    system.state.gridFlashes.push({ q, r, color, life: 0.5 }); // Reduced life
}

export function addImpact(system: VFXSystem, x: number, y: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 5;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderableItem } from "../../grid";
import { getTransitionOffset, isChaosStyle } from "../utils";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    collect(
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             // Calculate Visual Position with Arcing/Wobble
             const getVisualPos = (lx: number, ly: number, flightProgress: number) => {
                 const t = flightProgress;
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;

                 // TYPE 1: PHYSICAL ARC (Arrow, Bomb) - Gravity based
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'BOMB') {
                     // High arc for bombs, shallow for arrows
                     const arcHeight = p.skill.visual === 'BOMB' ? 250 : 80; 
                     // Parabola: 4 * h * t * (1-t)
                     arcOffset = 4 * arcHeight * t * (1 - t);
                 } 
                 // TYPE 2: MAGICAL (Bolt, Fireball) - Wobble/Straight
                 else if (p.skill.visual === 'BOLT' || p.skill.visual === 'FIREBALL') {
                     // Sine wave wobble based on distance traveled
                     const wobbleFreq = 0.2; 
                     const wobbleAmp = 10;
                     arcOffset = Math.sin(lx * wobbleFreq + ly * wobbleFreq) * wobbleAmp;
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // Look-Ahead Rotation Calculation
             // We sample a point slightly ahead on the ideal trajectory to determine angle
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));

             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (progress * 15) : 0;

             // Style Logic
             const isChaos = isChaosStyle(p.skill.color);

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        // Re-calculate trail visual positions based on their stored world pos
                        // Note: trails store just {x, y}, we need to derive progress for height

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // Thin faint line
                            ctx.beginPath();
                            // Move to tail
                            const tail = p.trail[0];
                            const tailDist = Vector.dist({x: p.startX, y: p.startY}, tail);
                            const tailVis = getVisualPos(tail.x, tail.y, tailDist/totalDist);
                            ctx.moveTo(tailVis.x, tailVis.y);
                            ctx.lineTo(headVis.x, headVis.y);

                            ctx.strokeStyle = `rgba(255, 255, 255, 0.4)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGICAL RIBBON
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            const trailPoints = p.trail.map(t => {
                                const d = Vector.dist({x: p.startX, y: p.startY}, t);
                                return getVisualPos(t.x, t.y, d/totalDist);
                            });
                            trailPoints.push(headVis);

                            // Draw segment by segment
                            for (let i = 0; i < trailPoints.length - 1; i++) {
                                const pt = trailPoints[i];
                                const next = trailPoints[i+1];
                                const ratio = i / (trailPoints.length - 1); 

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;
                                ctx.strokeStyle = p.skill.color;

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                if (isChaos) {
                                    ctx.globalAlpha = ratio * 0.8; 
                                } else {
                                    ctx.globalAlpha = ratio * 0.5;
                                }
                                ctx.stroke();

                                if (!isChaos) {
                                    ctx.lineWidth = baseWidth * ratio * 0.3;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    const altitude = headVis.shadowY - headVis.y;
                    const shadowScale = Math.max(0.2, 1 - altitude/300);
                    ctx.scale(shadowScale, shadowScale);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }
};

import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

// Helper: Chaos color detection
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') ||
           c.includes('#1c');
}

// Pseudo-Random Noise generator for textures
function pseudoNoise(x: number, y: number, seed: number) {
    const n = Math.sin(x * 12.9898 + y * 78.233 + seed) * 43758.5453;
    return n - Math.floor(n);
}

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         const grad = ctx.createRadialGradient(cx, cy, r * 0.1, cx, cy, r);
         grad.addColorStop(0, '#fff');        
         grad.addColorStop(0.4, color);       
         grad.addColorStop(1, 'transparent'); 

         ctx.fillStyle = grad;

         if (isChaos) {
             // Chaos: Unstable plasma blob
             ctx.beginPath();
             const spikes = 12;
             for(let i=0; i<spikes; i++) {
                 const angle = (i / spikes) * Math.PI * 2;
                 const rad = r * (0.6 + Math.random() * 0.4);
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();
         } else {
             // Order: Perfect Sphere with Cross Flare
             ctx.beginPath(); 
             ctx.arc(cx, cy, r * 0.8, 0, Math.PI * 2); 
             ctx.fill();

             ctx.fillStyle = '#fff';
             ctx.globalAlpha = 0.8;
             ctx.beginPath();
             ctx.ellipse(cx, cy, r, r*0.15, 0, 0, Math.PI*2);
             ctx.ellipse(cx, cy, r*0.15, r, 0, 0, Math.PI*2);
             ctx.fill();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(0.6, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.3;

        for(let i=0; i<12; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * (FOG_SIZE * 0.3);
            const size = FOG_SIZE * (0.1 + Math.random() * 0.2);

            ctx.beginPath(); 
            ctx.arc(cx + Math.cos(angle)*dist, cy + Math.sin(angle)*dist, size, 0, Math.PI*2); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = 50;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        if (isChaos) {
            ctx.beginPath();
            const points = 9;
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 2 / points);
                const r = radius * (0.85 + Math.random() * 0.3); 
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();

            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - 25, cy); 
            ctx.quadraticCurveTo(cx, cy - 15, cx + 25, cy);
            ctx.quadraticCurveTo(cx, cy + 15, cx - 25, cy);
            ctx.stroke();

            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI*2); ctx.fill();

        } else {
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1.5;
            if (isUlt) {
                const drawPoly = (sides: number, r: number, offset: number) => {
                    ctx.beginPath();
                    for (let i = 0; i <= sides; i++) {
                        const angle = offset + (i * Math.PI * 2) / sides;
                        const x = cx + Math.cos(angle) * r;
                        const y = cy + Math.sin(angle) * r;
                        if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    }
                    ctx.stroke();
                };

                drawPoly(3, radius, -Math.PI/2); 
                drawPoly(3, radius, Math.PI/2);  

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.5, 0, Math.PI*2); ctx.stroke();

            } else {
                ctx.save();
                ctx.translate(cx, cy);
                ctx.rotate(Math.PI/4);
                ctx.strokeRect(-radius * 0.7, -radius * 0.7, radius * 1.4, radius * 1.4);
                ctx.restore();

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.3, 0, Math.PI*2); ctx.stroke();
            }
        }

        return canvas;
    },

    generateWarningRune(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64;
        const cy = 32;
        const color = '#ef4444'; 

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.scale(1, 0.5); 

        ctx.beginPath(); 
        ctx.arc(cx, cy * 2, 40, 0, Math.PI * 2); 
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(cx - 15, cy * 2 - 25); ctx.lineTo(cx + 15, cy * 2 + 25);
        ctx.moveTo(cx + 15, cy * 2 - 25); ctx.lineTo(cx - 15, cy * 2 + 25);
        ctx.stroke();

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 12;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                ctx.strokeStyle = isChaos ? '#a8a29e' : '#e2e8f0'; 
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(75, cy); ctx.stroke();

                ctx.fillStyle = isChaos ? '#7f1d1d' : '#f0f9ff';
                ctx.beginPath();
                if (isChaos) {
                    ctx.moveTo(85, cy); 
                    ctx.lineTo(65, cy - 8); ctx.lineTo(70, cy); ctx.lineTo(65, cy + 8);
                } else {
                    ctx.moveTo(90, cy); ctx.lineTo(70, cy - 6); ctx.lineTo(70, cy + 6);
                }
                ctx.closePath();
                ctx.fill();

                ctx.strokeStyle = color;
                ctx.beginPath();
                if (isChaos) {
                    ctx.moveTo(20, cy); ctx.lineTo(5, cy - 10);
                    ctx.moveTo(20, cy); ctx.lineTo(5, cy + 10);
                } else {
                    ctx.moveTo(15, cy - 5); ctx.lineTo(5, cy); ctx.lineTo(15, cy + 5);
                }
                ctx.stroke();
                break;

            case 'FIREBALL':
            case 'BOMB':
                const coreGrad = ctx.createRadialGradient(cx+20, cy, 0, cx+20, cy, 15);
                coreGrad.addColorStop(0, '#fff');
                coreGrad.addColorStop(0.5, color);
                coreGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = coreGrad;

                ctx.beginPath(); ctx.arc(cx + 20, cy, 14, 0, Math.PI * 2); ctx.fill();

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.beginPath();
                if (isChaos) {
                    ctx.moveTo(cx + 20, cy - 12);
                    ctx.lineTo(cx, cy - 20); ctx.lineTo(cx - 20, cy - 5);
                    ctx.lineTo(cx - 35, cy);
                    ctx.lineTo(cx - 20, cy + 8); ctx.lineTo(cx, cy + 22);
                    ctx.lineTo(cx + 20, cy + 12);
                } else {
                    ctx.ellipse(cx + 5, cy, 35, 12, 0, 0, Math.PI * 2);
                }
                ctx.fill();
                break;

            case 'SLASH':
                // New specialized slash shape for 2-tile attacks
                ctx.translate(cx, cy);
                // Draw a crescent moon shape
                ctx.beginPath();
                ctx.arc(0, 0, 30, -Math.PI/3, Math.PI/3, false);
                ctx.arc(-10, 0, 30, Math.PI/3, -Math.PI/3, true);
                ctx.closePath();
                ctx.fillStyle = '#fff';
                ctx.fill();

                ctx.shadowColor = color;
                ctx.shadowBlur = 15;
                ctx.strokeStyle = color;
                ctx.lineWidth = 3;
                ctx.stroke();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                if (isChaos) {
                    ctx.fillStyle = '#1c1917'; 
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 3;

                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy);
                    ctx.lineTo(cx + 10, cy - 15);
                    ctx.lineTo(cx - 10, cy - 5);
                    ctx.lineTo(cx - 30, cy);
                    ctx.lineTo(cx - 10, cy + 5);
                    ctx.lineTo(cx + 10, cy + 15);
                    ctx.closePath();
                    ctx.fill(); ctx.stroke();

                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx + 45, cy - 12);
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx + 45, cy + 12);
                    ctx.stroke();

                } else {
                    const boltGrad = ctx.createRadialGradient(cx, cy, 2, cx, cy, 25); 
                    boltGrad.addColorStop(0, '#fff');
                    boltGrad.addColorStop(0.5, color);
                    boltGrad.addColorStop(1, 'transparent');
                    ctx.fillStyle = boltGrad;
                    ctx.beginPath(); ctx.arc(cx, cy, 25, 0, Math.PI * 2); ctx.fill();

                    ctx.fillStyle = '#fff';
                    ctx.shadowColor = '#fff';
                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx, cy - 12);
                    ctx.lineTo(cx - 15, cy); ctx.lineTo(cx, cy + 12);
                    ctx.closePath();
                    ctx.fill();

                    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.shadowBlur = 5;
                    ctx.beginPath(); 
                    ctx.ellipse(cx, cy, 15, 8, 0, 0, Math.PI*2); 
                    ctx.stroke();
                }
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.scale(1, 0.5); 

        const rings = 5;
        for(let i = 0; i < rings; i++) {
            const r = (50 / rings) * (i + 1);
            const alpha = 1.0 - (i / rings);

            ctx.beginPath();
            ctx.strokeStyle = color;
            ctx.lineWidth = 2 + Math.random() * 2;
            ctx.globalAlpha = alpha * 0.5;

            const segments = 24;
            for(let j=0; j<=segments; j++) {
                const a = (j/segments) * Math.PI * 2;
                const offset = pseudoNoise(j, i, 100) * 10;
                const radius = r + offset;
                const px = cx + Math.cos(a) * radius;
                const py = cy * 2 + Math.sin(a) * radius;
                if (j===0) ctx.moveTo(px, py);
                else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        }

        const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 25);
        grad.addColorStop(0, isChaos ? '#000' : '#fff'); 
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.8;
        ctx.beginPath(); ctx.arc(cx, cy * 2, 25, 0, Math.PI*2); ctx.fill();

        return canvas;
    }
};

