import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { BLOCK_HEIGHT } from "../../../constants";

const HIT_IMPULSE_MAX = 20;
const HIT_IMPULSE_MIN = 5;

export class SkillResolutionSystem {

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interrupt Checks (Stun / Silence / Banish / Death)
        if (a.stunTimer > 0 || a.banished || a.silenceTimer > 0 || a.hp <= 0) {
            const skillIdx = a.castingSkillIdx;

            if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
                const s = a.skills[skillIdx]!;
                const skillName = s.name;
                engine.log(a, 'CC', '中斷', skillName, '詠唱被打斷');

                let centerHex = { q: a.q, r: a.r };
                let centerPos = { x: a.px, y: a.py };

                if (s.type === 'AOE') {
                    if (a.targetHex) {
                        centerHex = a.targetHex;
                        centerPos = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
                        const h = engine.map.getTerrainHeight(centerHex.q, centerHex.r);
                        centerPos.y -= h;
                    }
                    else if (a.target) {
                        centerHex = {q: a.target.q, r: a.target.r};
                        centerPos = {x: a.target.px, y: a.target.py};
                    } else {
                        const h = engine.map.getTerrainHeight(centerHex.q, centerHex.r);
                        centerPos.y -= h;
                    }
                } else {
                    const h = engine.map.getTerrainHeight(centerHex.q, centerHex.r);
                    centerPos.y -= h;
                }

                engine.events.push({
                    type: 'CAST_BREAK',
                    pos: centerPos,
                    value: s.aoeRadius || 1, 
                    color: s.color,
                    skill: s
                });
            }

            a.castingSkillIdx = -1;
            a.castTimer = 0;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.IDLE); 
            return;
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        // Cast Completion
        if (a.castTimer <= 0) {
            const s = a.skills[a.castingSkillIdx]!;

            // Mana Cost & Gain
            a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
            a.curCDs[a.castingSkillIdx] = s.cd;

            // Execution Branch: Projectile vs Instant
            if (s.projectileSpeed && s.projectileSpeed > 0) {
                 engine.combat.spawnProjectile(a, s, engine);
            } else {
                this.executeInstantSkill(a, s, engine);
            }

            // Reset State
            a.castingSkillIdx = -1;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.COMBAT_IDLE);
        }
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let centerHex: { q: number, r: number } | null = null;

        // 1. Identify Targets
        if (skill.type === 'AOE') {
            if (source.targetHex) {
                centerHex = source.targetHex;
            } else if (source.target) {
                centerHex = { q: source.target.q, r: source.target.r };
            } else {
                centerHex = { q: source.q, r: source.r };
            }

            if (centerHex) {
                targets = engine.agents.filter(e => 
                    e.team !== source.team && 
                    e.hp > 0 && !e.banished &&
                    HexUtils.dist(centerHex!, e) <= radius
                );
            }
        } else {
            // Single Target - Verify Height-Aware Range
            if (source.target && !source.target.banished && source.target.hp > 0) {
                const effectiveRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                const actualDist = HexUtils.dist(source, source.target);

                if (actualDist <= effectiveRange) {
                    targets = [source.target];
                }
            }
        }

        const origin = {x: source.px, y: source.py};

        // 2. VISUAL HANDLING
        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);

            // A. Long Range Instant (Beams)
            if (dist > 2) {
                engine.events.push({
                    type: 'VISUAL_BEAM',
                    pos: { x: t.px, y: t.py },
                    sourceId: source.id,
                    targetId: t.id,
                    skill: skill,
                    color: skill.color
                });
            } 
            // B. Extended Melee (Range 2) - "Lunge" or "Phantom Strike"
            else if (dist === 2) {
                engine.events.push({
                    type: 'VISUAL_SLASH',
                    pos: { x: t.px, y: t.py },
                    sourceId: source.id,
                    targetId: t.id,
                    skill: skill,
                    color: skill.color
                });
            }
            // C. Close Melee (Range 1) - Standard impact handled in resolveHit

            this.resolveHit(source, t, skill, origin, engine);
        });

        // 3. Melee / Self / Miss Visuals
        if (targets.length === 0 && skill.type === 'AOE' && centerHex) {
             // Ground Hit logic...
        }

        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        let rawDmg = skill.power;

        // Execute Logic
        const isExecute1 = skill.effectType === 'EXECUTE';
        const isExecute2 = skill.effectType2 === 'EXECUTE';
        if ((isExecute1 || isExecute2) && target.hp < target.maxHp * 0.3) {
            const multiplier = (isExecute1 ? skill.effectVal : skill.effectVal2) || 1.5;
            rawDmg = Math.floor(rawDmg * multiplier);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        }

        let evtType: GameEventType = 'DAMAGE';
        let val = 0;
        const oldHp = Math.ceil(target.hp);

        // --- PHYSICS & DIRECTIONAL IMPACT CALCULATION ---
        const originX = origin ? origin.x : source.px;
        const originY = origin ? origin.y : source.py;
        let dx = target.px - originX;
        let dy = target.py - originY;
        const len = Math.sqrt(dx * dx + dy * dy);
        let impactDir = { x: 0, y: 0 };

        if (len > 0) {
            impactDir = { x: dx / len, y: dy / len };
        }

        if (rawDmg > 0) {
            target.hp -= rawDmg;
            val = -rawDmg;
            evtType = 'DAMAGE';
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Physics Impulse
            if (len > 0) {
                const impactForce = Math.min(HIT_IMPULSE_MAX, Math.max(HIT_IMPULSE_MIN, rawDmg * 0.3));
                target.physics.vx += impactDir.x * impactForce;
                target.physics.vy += impactDir.y * impactForce;
                target.physics.vAngle += (Math.random() - 0.5) * impactForce * 0.05;
            }

            // Vamp Logic
            const isVamp1 = skill.effectType === 'VAMP';
            const isVamp2 = skill.effectType2 === 'VAMP';
            if ((isVamp1 || isVamp2) && source.hp > 0) {
                const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || 0.5;
                const healAmt = Math.floor(rawDmg * vampPct);
                if (healAmt > 0) {
                    source.hp = Math.min(source.maxHp, source.hp + healAmt);
                    engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: healAmt, color: '#86efac' });
                }
            }

        } else if (rawDmg < 0) {
            const heal = -rawDmg;
            target.hp = Math.min(target.maxHp, target.hp + heal);
            val = heal;
            evtType = 'HEAL';
        }

        const newHp = Math.ceil(target.hp);

        // Mana Burn
        const isBurn1 = skill.effectType === 'MANA_BURN';
        const isBurn2 = skill.effectType2 === 'MANA_BURN';
        if (isBurn1 || isBurn2) {
            const burnAmt = (isBurn1 ? skill.effectVal : skill.effectVal2) || 30;
            target.mp = Math.max(0, target.mp - burnAmt);
            source.mp = Math.min(source.maxMp, source.mp + burnAmt);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${burnAmt} MP`, color: "#3b82f6" });
        }

        // Mana Restore
        const isRestore1 = skill.effectType === 'MANA_RESTORE';
        const isRestore2 = skill.effectType2 === 'MANA_RESTORE';
        if (isRestore1 || isRestore2) {
             const amt = (isRestore1 ? skill.effectVal : skill.effectVal2) || 30;
             target.mp = Math.min(target.maxMp, target.mp + amt);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${amt} MP`, color: "#60a5fa" });
        }

        // EMIT EVENT
        engine.events.push({
            type: evtType,
            pos: { x: target.px, y: target.py },
            value: val,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        // RICH LOG: Hit
        engine.log(
            source, 
            rawDmg < 0 ? 'HEAL' : 'HIT', 
            skill.name, 
            target.id, 
            `${rawDmg > 0 ? '造成傷害' : '回復生命'} ${Math.abs(rawDmg)} (HP: ${oldHp} -> ${newHp})`
        );

        // RICH LOG: Kill
        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
        }
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type) return;
        const duration = dur || 0;
        const power = force || 0;

        if (type === 'STUN') {
            target.stunTimer = Math.max(target.stunTimer, duration);
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暈眩", color: "#facc15" });

            const isIce = skill.color.toLowerCase().includes('blue') || 
                          skill.color.includes('#60a5fa') || 
                          skill.color.includes('#e0f2fe') || 
                          skill.name.includes("冰") || 
                          skill.name.includes("凍") || 
                          skill.name.includes("雪");

            if (isIce) {
                target.visualStatus = 'FROZEN';
            }
        } else if (type === 'SILENCE') {
            target.silenceTimer = Math.max(target.silenceTimer, duration);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "沉默", color: "#94a3b8" });
        } else if (type === 'BANISH') {
            target.banishTimer = Math.max(target.banishTimer, duration);
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "放逐", color: "#c084fc" });

            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; 
            } else {
                target.visualStatus = 'STASIS'; 
            }
        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            const rawForce = Math.max(1, power);
            const resistance = target.weight || 1; 
            const tilesToPush = Math.max(0, rawForce - resistance);

            if (tilesToPush === 0) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
                return;
            }

            const originPx = origin ? origin : {x: source.px, y: source.py};
            const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
            const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

            let currentH = {q: target.q, r: target.r};
            let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
            let finalH = currentH;

            for(let k=0; k<tilesToPush; k++) {
                const neighbors = HexUtils.neighbors(currentH);
                let bestN = null;
                let bestDot = -99;

                for(const n of neighbors) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                    const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                    const dot = nDir.x * vector.x + nDir.y * vector.y;

                    if (dot > bestDot) {
                        bestDot = dot;
                        bestN = n;
                    }
                }

                if (bestN) {
                    if (!engine.isValid(bestN.q, bestN.r)) break; 
                    if (engine.hasObstacle(bestN.q, bestN.r)) break; 

                    const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                    if (nextHeight > currentHeight + BLOCK_HEIGHT) break; 
                    if (nextHeight < currentHeight - BLOCK_HEIGHT * 2) break; 

                    currentH = bestN;
                    currentHeight = nextHeight;
                    finalH = bestN;
                } else {
                    break;
                }
            }

            if (finalH.q !== target.q || finalH.r !== target.r) {
                engine.updateAgentPosition(target, finalH.q, finalH.r);
                target.isMoving = false; 
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: type === 'PULL' ? "牽引" : "擊退", color: "#fff" });
                target.setAnim(AnimState.HIT);
                target.physics.vz += 200;
            }
        } else if (type === 'DOT') {
            target.dotDmg = power || 5;
            target.dotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "中毒", color: "#10b981" });
        } else if (type === 'HOT') {
            target.hotVal = power || 5;
            target.hotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "再生", color: "#86efac" });
        }
    }
}

import { GameEngine } from "../game";
import { GameEvent, Team } from "../../types";
import { HexUtils } from "../utils";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";

// Systems
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import * as VFXSpawners from "./vfx/spawners";

const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20;

export class VisualEventListener {

    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     // Highlight high damage
                     const isCrit = val > 100;
                     color = isCrit ? '#ef4444' : '#fff'; 
                     size = isCrit ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         // Reduced cast impact
                         camera.addTrauma(0.2); 
                     }
                 }
            }

            // 2. VFX Handling
            switch (event.type) {
                case 'VISUAL_SLASH':
                    if (event.sourceId && event.targetId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        const target = engine.agents.find(a => a.id === event.targetId);
                        if (source && target) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                            const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                            const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                            VFXSpawners.spawnConnectorSlash(
                                vfx,
                                source.px, source.py - sH,
                                target.px, target.py - tH,
                                event.color || '#fff',
                                event.skill?.visual || 'SLASH'
                            );
                        }
                    }
                    break;

                case 'DAMAGE': 
                    const dmg = Math.abs(event.value || 0);
                    const isHeavy = dmg > 50; 

                    // Directional Impact Logic
                    let handled = false;
                    if (event.sourceId && event.targetId) {
                        const s = engine.agents.find(a => a.id === event.sourceId);
                        const t = engine.agents.find(a => a.id === event.targetId);
                        if (s && t) {
                            // Calc direction
                            // We use world coordinates (px, py) from Agent, which are flat.
                            const dx = t.px - s.px;
                            const dy = t.py - s.py;
                            const len = Math.sqrt(dx*dx + dy*dy);
                            if (len > 0) {
                                const dirX = dx / len;
                                const dirY = dy / len;

                                const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';

                                VFXSpawners.spawnDirectionalImpact(
                                    vfx,
                                    event.pos.x, visualY - 20,
                                    dirX, dirY,
                                    event.color || '#fff',
                                    type
                                );
                                handled = true;
                            }
                        }
                    }

                    if (!handled) {
                        // Fallback generic explosion
                        // Reduced particle count via factory
                        VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY - 20, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
                    }

                    if (isHeavy) {
                        // Only shake on heavy hits
                        camera.addTrauma(0.15);
                        // Debris is now disabled in spawner, but we could re-enable for crits here if desired
                        // VFXSpawners.spawnDebris(vfx, event.pos.x, visualY - 20, event.color || '#fff', 3);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualY - 20; 

                            VFXSpawners.spawnBeam(vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(vfx, tx, ty, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY, vfx, grid, camera); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualY, team);
                    camera.addTrauma(0.3); 
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(vfx, event.pos.x, visualY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    VFXSpawners.spawnDomainShatter(vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    camera.addTrauma(0.1);
                    break;
            }
        });
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            camera.addTrauma(0.4); // Ult impact
            VFXSpawners.spawnDivinePillar(vfx, event.pos.x, visualY, color, 1.2);
            VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, color, 1.5);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        // Reduced visual density for AOE tiles
                        if (Math.random() < 0.3) { 
                            VFXSpawners.spawnExplosion(vfx, tilePos.x, tileVisualY, 0, 3, color, 1.0, 0.5, 'SPARK');
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 2.0);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 2.0);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 30, color, 1.5, 0.8, 'SPARK');
            }
        } else {
            // Normal Projectile
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        // REMOVED: GridFlash on normal hits (Too noisy)
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 0.8);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 0.6);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 5, color, 1.0, 0.5, 'SPARK');
            }
        }
    }
}

import { useRef, useEffect, RefObject } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT } from '../constants';

export const useGameCamera = (
    wrapperRef: RefObject<HTMLDivElement>,
    canvasRef: RefObject<HTMLCanvasElement>,
    engine: GameEngine,
    isShowcaseMode: boolean,
    transitionPhase: string,
    onResize?: () => void
) => {
    const cameraRef = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        cameraRef.current.x = p.x - (canvasRef.current.width / cameraRef.current.zoom) / 2;
        cameraRef.current.y = p.y + verticalOffset - (canvasRef.current.height / cameraRef.current.zoom) / 2;

        if (onResize) onResize();
    };

    // Auto-center triggers
    useEffect(() => {
        if (isShowcaseMode || transitionPhase === 'IN') {
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    // Resize Observer
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;
        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;
                if (engine.agents.length === 0) centerCamera();
                if (onResize) onResize();
            }
        });
        resizeObserver.observe(wrapperRef.current);
        centerCamera();
        return () => resizeObserver.disconnect();
    }, [engine]);

    return {
        cameraRef,
        centerCamera
    };
};

import { useRef, useEffect, RefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: RefObject<HTMLCanvasElement>;
    cameraRef: RefObject<{ x: number, y: number, zoom: number }>;
    rendererRef: RefObject<GameRenderer>;
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    onSelect: (a: Agent | null) => void;
    winner: Team | null;
}

export const useGameInput = ({
    canvasRef,
    cameraRef,
    rendererRef,
    engine,
    tool,
    selectedObstacle,
    hpInput,
    spawnMode,
    draftRole,
    onSelect,
    winner
}: GameInputProps) => {

    // --- INTERACTION STATE ---
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Unit Dragging
    const pressedAgentRef = useRef<Agent | null>(null);

    // Obstacle Dragging
    const draggedObstacleRef = useRef<{ 
        type: string; 
        originQ: number; 
        originR: number; 
        px: number; 
        py: number; 
    } | null>(null);

    // General Input State
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    // Touch specific state
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);

    // Visual feedback state (exposed to Render Loop)
    const hoveredHexRef = useRef<Hex | null>(null);

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs || !cameraRef.current || !rendererRef.current) return;

        const getScreenCoords = (x: number, y: number) => {
            const rect = cvs.getBoundingClientRect();
            return { x: x - rect.left, y: y - rect.top };
        };

        const getHexFromCoords = (sx: number, sy: number) => {
            const hex = rendererRef.current!.getHexAtScreenPoint(sx, sy, cameraRef.current!, engine);
            if (hex) return hex;
            return HexUtils.fromPx(
                sx / cameraRef.current!.zoom + cameraRef.current!.x,
                sy / cameraRef.current!.zoom + cameraRef.current!.y,
                engine.mapConfig
            );
        };

        const getHitAgentFromCoords = (sx: number, sy: number) => {
            const wx = sx / cameraRef.current!.zoom + cameraRef.current!.x;
            const wy = sy / cameraRef.current!.zoom + cameraRef.current!.y;
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;
                const h = rendererRef.current!.getTerrainHeight(agent.q, agent.r, engine);
                const baseX = agent.px;
                const baseY = agent.py - h;
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 
                if (dx < 35 && Math.abs(dy) < 60) return agent;
            }
            return null;
        };

        const getWorldPosFromCoords = (sx: number, sy: number) => {
            const wx = sx / cameraRef.current!.zoom + cameraRef.current!.x;
            const hex = rendererRef.current!.getHexAtScreenPoint(sx, sy, cameraRef.current!, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current!.getTerrainHeight(hex.q, hex.r, engine);
            const wy = sy / cameraRef.current!.zoom + cameraRef.current!.y + h;
            return { x: wx, y: wy };
        };

        const executeToolAction = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; 

            lastPaintHex.current = k;
            const existingAgent = engine.getAgentAt(h.q, h.r);
            let agent: Agent | null = null;

            if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (existingAgent) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
                return;
            }

            if (tool === ToolType.OBSTACLE) {
                if (existingAgent) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
                return;
            }

            if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
                if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
            }

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        };

        // --- UNIFIED INPUT HANDLER ---

        const handleDown = (sx: number, sy: number, button: number = 0) => {
            pressStartPos.current = { x: sx, y: sy };
            lastPaintHex.current = "";
            interactionMode.current = 'DOWN';

            // Right Click always Pans
            if (button === 2) {
                interactionMode.current = 'PAN';
                return;
            }

            if (engine.isRunning) {
                interactionMode.current = 'PAN';
                return;
            }

            // Identify potential targets for drag start
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (hitAgent) {
                pressedAgentRef.current = hitAgent;
                if (tool !== ToolType.DELETE) {
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                }
                return;
            }

            // Check Obstacle
            const h = getHexFromCoords(sx, sy);
            const validGrid = engine.isValid(h.q, h.r);

            if (validGrid && engine.hasObstacle(h.q, h.r)) {
                if (tool !== ToolType.DELETE) {
                    const obsType = engine.obstacles.get(HexUtils.key(h));
                    if (obsType) {
                        draggedObstacleRef.current = {
                            type: obsType,
                            originQ: h.q, originR: h.r,
                            px: 0, py: 0
                        };
                    }
                }
            }
        };

        const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
            const h = getHexFromCoords(sx, sy);
            hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

            // Cursor Logic
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (cvs) {
                if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
                else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
                else if (hitAgent) cvs.style.cursor = 'pointer'; 
                else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
                else if (tool === ToolType.SELECT) cvs.style.cursor = 'default';
                else cvs.style.cursor = 'crosshair'; 
            }

            if (interactionMode.current === 'IDLE') return;

            if (interactionMode.current === 'PAN') {
                cameraRef.current!.x -= dx / cameraRef.current!.zoom;
                cameraRef.current!.y -= dy / cameraRef.current!.zoom;
                return;
            }

            if (interactionMode.current === 'PAINT') {
                if (engine.isValid(h.q, h.r)) {
                    executeToolAction(h);
                }
                return;
            }

            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                pressedAgentRef.current.px = wPos.x;
                pressedAgentRef.current.py = wPos.y;
                return;
            }

            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                draggedObstacleRef.current.px = wPos.x;
                draggedObstacleRef.current.py = wPos.y;
                return;
            }

            if (interactionMode.current === 'DOWN' && pressStartPos.current) {
                const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);

                if (dist > 10) {
                    if (pressedAgentRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_UNIT';
                        pressedAgentRef.current.physics.z = 20; 
                        onSelect(pressedAgentRef.current);
                        return;
                    }

                    if (draggedObstacleRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_OBS';
                        const { originQ, originR } = draggedObstacleRef.current;
                        engine.removeObstacle(originQ, originR);
                        onSelect(null);

                        const wPos = getWorldPosFromCoords(sx, sy);
                        draggedObstacleRef.current.px = wPos.x;
                        draggedObstacleRef.current.py = wPos.y;
                        return;
                    }

                    if (engine.isValid(h.q, h.r) && (tool === ToolType.OBSTACLE || tool === ToolType.DELETE)) {
                        interactionMode.current = 'PAINT';
                        executeToolAction(h);
                    } else {
                        interactionMode.current = 'PAN';
                        cameraRef.current!.x -= dx / cameraRef.current!.zoom;
                        cameraRef.current!.y -= dy / cameraRef.current!.zoom;
                    }
                }
            }
        };

        const handleUp = (sx: number, sy: number) => {
            const h = getHexFromCoords(sx, sy);

            if (interactionMode.current === 'DOWN') {
                if (pressedAgentRef.current) {
                    if (tool === ToolType.DELETE) {
                        const a = pressedAgentRef.current;
                        engine.removeAgent(a.q, a.r);
                        onSelect(null);
                    } else {
                        onSelect(pressedAgentRef.current);
                    }
                } else if (engine.hasObstacle(h.q, h.r)) {
                    if (tool === ToolType.DELETE) {
                        engine.removeObstacle(h.q, h.r);
                    }
                } else if (tool !== ToolType.SELECT && tool !== ToolType.DELETE) {
                    if (engine.isValid(h.q, h.r)) executeToolAction(h);
                } else {
                    onSelect(null);
                }
            }

            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const agent = pressedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                agent.physics.z = 0; 

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    engine.updateAgentPosition(agent, h.q, h.r);
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x; agent.py = p.y;
                } else {
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x; agent.py = p.y;
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }
                onSelect(agent);
            }

            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const { type, originQ, originR } = draggedObstacleRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const occupant = engine.getAgentAt(h.q, h.r);
                const hasExistingObstacle = engine.hasObstacle(h.q, h.r);

                if (isValidHex && !occupant && !hasExistingObstacle) {
                    engine.setObstacle(h.q, h.r, type);
                } else {
                    engine.setObstacle(originQ, originR, type); 
                }
            }

            interactionMode.current = 'IDLE';
            pressedAgentRef.current = null;
            draggedObstacleRef.current = null;
            pressStartPos.current = null;
            lastPaintHex.current = "";
            if (cvs) cvs.style.cursor = 'default';
        };

        // Event Listeners
        const handleMouseDown = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleDown(pos.x, pos.y, e.button);
        };
        const handleMouseMove = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleMove(pos.x, pos.y, e.movementX, e.movementY);
        };
        const handleMouseUp = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleUp(pos.x, pos.y);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                lastTouchPos.current = pos;
                handleDown(pos.x, pos.y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault(); 
            if (e.touches.length === 1 && lastTouchPos.current) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const dx = pos.x - lastTouchPos.current.x;
                const dy = pos.y - lastTouchPos.current.y;
                handleMove(pos.x, pos.y, dx, dy);
                lastTouchPos.current = pos;
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                const currentDist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinchDist.current > 0) {
                    const delta = currentDist - lastPinchDist.current;
                    const zoomSensitivity = 0.005;
                    cameraRef.current!.zoom = Math.max(0.5, Math.min(3.0, cameraRef.current!.zoom + delta * zoomSensitivity));
                }
                lastPinchDist.current = currentDist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const pos = getScreenCoords(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
                handleUp(pos.x, pos.y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            cameraRef.current!.zoom = Math.max(0.5, Math.min(3.0, cameraRef.current!.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner, spawnMode, draftRole]);

    return {
        hoveredHexRef,
        pressedAgentRef,
        draggedObstacleRef
    };
};

import { useRef, useEffect, RefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { GameEvent, Skill, Team, Hex } from '../types';

interface GameLoopProps {
    canvasRef: RefObject<HTMLCanvasElement>;
    rendererRef: RefObject<GameRenderer>;
    cameraRef: RefObject<{ x: number, y: number, zoom: number }>;
    engine: GameEngine;
    hoveredHexRef: RefObject<Hex | null>;
    pressedAgentRef: RefObject<Agent | null>;
    draggedObstacleRef: RefObject<{ type: string; px: number; py: number } | null>;
    selectedAgent: Agent | null;
    hoveredSkill: Skill | null;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
    onWin: (team: Team) => void;
}

export const useGameLoop = ({
    canvasRef,
    rendererRef,
    cameraRef,
    engine,
    hoveredHexRef,
    pressedAgentRef,
    draggedObstacleRef,
    selectedAgent,
    hoveredSkill,
    transitionPhase,
    onWin
}: GameLoopProps) => {

    const fpsRef = useRef(60);
    const transitionStartTime = useRef(0);

    // Exposed draw function for forced redraws (e.g. on resize)
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx && canvasRef.current && rendererRef.current && cameraRef.current) {
                const highlight = pressedAgentRef.current || selectedAgent || null;

                rendererRef.current.draw(
                    ctx, 
                    engine, 
                    cameraRef.current, 
                    highlight, 
                    fpsRef.current, 
                    hoveredHexRef.current, 
                    hoveredSkill
                ); 

                // Draw Dragged Obstacle Ghost
                if (draggedObstacleRef.current) {
                    const { type, px, py } = draggedObstacleRef.current;
                    const { x, y, zoom } = cameraRef.current;
                    const { width, height } = canvasRef.current;

                    ctx.save();
                    ctx.translate(width / 2, height / 2);
                    ctx.scale(zoom, zoom);
                    ctx.translate(-x - width / 2 / zoom, -y - height / 2 / zoom);

                    const sprite = SpriteManager.getObstacleSprite(type);
                    const liftOffset = 40; 
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 30;
                    ctx.shadowOffsetY = 30;
                    ctx.globalAlpha = 0.9;
                    ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
                    ctx.restore();
                }
            }
        };

        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;
                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }
                if (frameEvents.length > 0 && rendererRef.current) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            if (rendererRef.current) {
                rendererRef.current.update(dt / 1000, engine);

                if (transitionPhase !== 'IDLE') {
                    const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                    const progress = Math.min(1.0, elapsed / 1.2);
                    rendererRef.current.setTransition(progress, transitionPhase);
                } else {
                    rendererRef.current.setTransition(0, 'IDLE');
                }
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => { onWin(team); };
        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase, selectedAgent]);

    return {
        fps: fpsRef.current,
        drawCurrentFrame: () => drawCurrentFrameRef.current()
    };
};

import React, { useRef } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { useGameLoop } from '../hooks/useGameLoop';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, 
        hoveredSkill, isShowcaseMode, spawnMode, draftRole, 
        onSelect, onWin, winner, rematch, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const rendererRef = useRef(new GameRenderer());

    // 1. Camera Logic
    // We pass a callback to trigger a redraw when resize happens
    const { cameraRef } = useGameCamera(
        wrapperRef, 
        canvasRef, 
        engine, 
        isShowcaseMode, 
        transitionPhase,
        () => drawCurrentFrame() // Hoisted from useGameLoop return
    );

    // 2. Input Logic
    const { 
        hoveredHexRef, 
        pressedAgentRef, 
        draggedObstacleRef 
    } = useGameInput({
        canvasRef,
        cameraRef,
        rendererRef,
        engine,
        tool,
        selectedObstacle,
        hpInput,
        spawnMode,
        draftRole,
        onSelect,
        winner
    });

    // 3. Render Loop
    const { drawCurrentFrame } = useGameLoop({
        canvasRef,
        rendererRef,
        cameraRef,
        engine,
        hoveredHexRef,
        pressedAgentRef,
        draggedObstacleRef,
        selectedAgent,
        hoveredSkill,
        transitionPhase,
        onWin
    });

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50 pointer-events-auto">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderableItem } from "../../grid";
import { getTransitionOffset, isChaosStyle } from "../utils";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    collect(
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             // Calculate Visual Position with Arcing/Wobble
             const getVisualPos = (lx: number, ly: number, flightProgress: number) => {
                 const t = flightProgress;
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;

                 // TYPE 1: PHYSICAL ARC (Arrow, Bomb) - Gravity based
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'BOMB') {
                     // FIX: Dynamic Arc Height based on Distance
                     // Previously hardcoded to 80, which looked like a missile launch for short range.
                     let baseArc = 0;

                     if (p.skill.visual === 'BOMB') {
                         baseArc = 200; // Mortar shell style (High arc)
                     } else {
                         // Arrow: Flat trajectory for short range, slight arc for long range
                         // roughly 15px height per 100px distance, capped at 100px
                         baseArc = Math.min(100, totalDist * 0.15); 
                     }

                     // Parabola: 4 * h * t * (1-t)
                     arcOffset = 4 * baseArc * t * (1 - t);
                 } 
                 // TYPE 2: MAGICAL (Bolt, Fireball) - Wobble/Straight
                 else if (p.skill.visual === 'BOLT' || p.skill.visual === 'FIREBALL') {
                     // Reduced wobble amplitude for cleaner look (was 10)
                     const wobbleFreq = 0.2; 
                     const wobbleAmp = 6; 
                     arcOffset = Math.sin(lx * wobbleFreq + ly * wobbleFreq) * wobbleAmp;
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // Look-Ahead Rotation Calculation
             // We sample a point slightly ahead on the ideal trajectory to determine angle
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));

             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (progress * 15) : 0;

             // Style Logic
             const isChaos = isChaosStyle(p.skill.color);

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        // Re-calculate trail visual positions based on their stored world pos
                        // Note: trails store just {x, y}, we need to derive progress for height

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // Thin faint line
                            ctx.beginPath();
                            // Move to tail
                            const tail = p.trail[0];
                            const tailDist = Vector.dist({x: p.startX, y: p.startY}, tail);
                            const tailVis = getVisualPos(tail.x, tail.y, tailDist/totalDist);
                            ctx.moveTo(tailVis.x, tailVis.y);
                            ctx.lineTo(headVis.x, headVis.y);

                            ctx.strokeStyle = `rgba(255, 255, 255, 0.4)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGICAL RIBBON
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            const trailPoints = p.trail.map(t => {
                                const d = Vector.dist({x: p.startX, y: p.startY}, t);
                                return getVisualPos(t.x, t.y, d/totalDist);
                            });
                            trailPoints.push(headVis);

                            // Draw segment by segment
                            for (let i = 0; i < trailPoints.length - 1; i++) {
                                const pt = trailPoints[i];
                                const next = trailPoints[i+1];
                                const ratio = i / (trailPoints.length - 1); 

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;
                                ctx.strokeStyle = p.skill.color;

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                if (isChaos) {
                                    ctx.globalAlpha = ratio * 0.8; 
                                } else {
                                    ctx.globalAlpha = ratio * 0.5;
                                }
                                ctx.stroke();

                                if (!isChaos) {
                                    ctx.lineWidth = baseWidth * ratio * 0.3;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    const altitude = headVis.shadowY - headVis.y;
                    const shadowScale = Math.max(0.2, 1 - altitude/300);
                    ctx.scale(shadowScale, shadowScale);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }
};

import { VFXSystem } from "../vfx";
import { Team } from "../../../types";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

export function spawnDirectionalImpact(
    system: VFXSystem, 
    x: number, y: number, 
    dirX: number, dirY: number, 
    color: string, 
    type: 'PHYSICAL' | 'MAGICAL'
) {
    const isPhysical = type === 'PHYSICAL';

    // 1. Main Spark/Splatter Cone (Opposite to hit direction = Blowback)
    const baseAngle = Math.atan2(dirY, dirX);
    const cone = 1.0; // Spread radians

    // TA TWEAK: Increased particle count for juiciness
    const count = isPhysical ? 10 : 16; 
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * cone;
        const speed = (isPhysical ? 180 : 250) + Math.random() * 120;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = 25; // Hit height
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 80 + Math.random() * 120; // Higher kick

        // TA TWEAK: Longer life
        p.life = 0.5 + Math.random() * 0.4;
        p.maxLife = p.life;
        p.color = color;
        p.size = Math.random() * 4 + 3; // Slightly bigger
        p.type = isPhysical ? 'SPARK' : 'GLOW';
        p.delay = 0;

        system.state.particles.push(p);
    }

    // 2. Ring Burst (Perpendicular to hit)
    addImpact(system, x, y - 25, color, 'RING', isPhysical ? 0.4 : 0.6);

    // TA TWEAK: 3. Instant White Flash (Retinal Burn)
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y - 25; flash.z = 25;
    flash.vx = 0; flash.vy = 0; flash.vz = 0;
    flash.life = 0.15; // Very fast
    flash.maxLife = 0.15;
    flash.color = '#ffffff';
    flash.size = 60; // Big flash
    flash.type = 'GLOW'; // Reuse GLOW logic
    system.state.particles.push(flash);
}

export function spawnConnectorSlash(
    system: VFXSystem,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string,
    visual: string
) {
    // Spawns a beam-like particle but styled as a slash
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; // Waist height
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;

    p.life = 0.25; 
    p.maxLife = 0.25;
    p.color = color;
    p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team) {
    // Colors
    const armorColor = team === Team.BLUE ? '#e2e8f0' : '#27272a';
    const trimColor = team === Team.BLUE ? '#fbbf24' : '#a1a1aa';
    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';

    // 1. Armor Shards (Heavy chunks)
    for (let i = 0; i < 8; i++) { 
        const angle = Math.random() * Math.PI * 2;
        const speed = 120 + Math.random() * 180;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = 30 + Math.random() * 30; 
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 250 + Math.random() * 200; 

        p.life = 2.0; p.maxLife = 2.0; 
        p.color = Math.random() > 0.5 ? armorColor : trimColor;
        p.size = 6 + Math.random() * 5; 
        p.type = 'SHARD'; 
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 20;
        p.delay = 0;
        system.state.particles.push(p);
    }

    // 2. Core Sparks
    spawnExplosion(system, x, y, 30, 20, coreColor, 1.2, 0.8, 'SPARK');

    // 3. Shockwave
    addImpact(system, x, y, coreColor, 'RING', 0.5);

    // 4. Ground Scorch
    addDecal(system, x, y, '#000');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); // Reduced count

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 

        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 20 + Math.random() * 30;

        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Center "Poof"
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
    addImpact(system, x, y, '#ffffff', 'RING', 0.15);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; // Shorter life
    p.color = color; p.size = 4;
    p.type = 'BEAM';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 20 : 10, count);

    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd;
        p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4);
        p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type;
        p.delay = 0;

        system.state.particles.push(p);
    }
}

