import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";

// Optimization: Precompute Hex Polygon Offsets
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

// Procedural Noise function
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

export const TerrainRenderer = {

    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any
    ) {
        const BASE_THICKNESS = 12; // Visual foundation thickness
        const topY = height; 

        // 1. Draw Side Faces (The Stack)
        // Rotated 45deg: Front faces are 5, 0, 1 (Right-Down, Down, Left-Down)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            // Rich Gradient for Sides
            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; // Front face darker

            // Add Ambient Occlusion to bottom of gradient
            grad.addColorStop(0, baseColor);
            grad.addColorStop(0.7, baseColor);
            grad.addColorStop(1, '#020617'); // Fade to black at bottom

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // "Layer Lines" for Block Stack Effect
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            // Outline Side
            ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face (Base)
        this.traceTopFace(ctx, x, y - topY);

        // Use a slight gradient for the top to simulate light falloff
        const topGrad = ctx.createLinearGradient(x - size, y - topY - size, x + size, y - topY + size);
        topGrad.addColorStop(0, theme.rim); // Highlight corner
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow corner

        ctx.fillStyle = topGrad;
        ctx.fill();

        // 3. Rim Light (Edge Highlighting)
        // This makes the terrain pop by highlighting the edges facing the "light source" (Top-Left)
        ctx.lineCap = 'round';
        ctx.lineWidth = 2; // Thicker rim for style
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.6; // Blend it

        ctx.beginPath();
        // Highlight top-left and top-right edges (Indices 2, 3, 4)
        // 4 is Left-Up, 3 is Up, 2 is Right-Up
        const c4 = HEX_CORNERS[4];
        const c3 = HEX_CORNERS[3];
        const c2 = HEX_CORNERS[2];

        ctx.moveTo(x + c4.x, y - topY + c4.y);
        ctx.lineTo(x + c3.x, y - topY + c3.y); // Topmost point
        ctx.lineTo(x + c2.x, y - topY + c2.y); 
        ctx.stroke();

        ctx.globalAlpha = 1.0;

        // 4. Subtle Top Outline (Rest of the hex)
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.beginPath();
        ctx.moveTo(x + HEX_CORNERS[2].x, y - topY + HEX_CORNERS[2].y);
        ctx.lineTo(x + HEX_CORNERS[1].x, y - topY + HEX_CORNERS[1].y);
        ctx.lineTo(x + HEX_CORNERS[0].x, y - topY + HEX_CORNERS[0].y);
        ctx.lineTo(x + HEX_CORNERS[5].x, y - topY + HEX_CORNERS[5].y);
        ctx.lineTo(x + HEX_CORNERS[4].x, y - topY + HEX_CORNERS[4].y);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;

        const n = noise(q, r);
        const n2 = noise(r, q);
        const time = performance.now() / 1000;

        if (type === 'VOID') {
            ctx.globalAlpha = 0.2;
            // Digital circuit lines
            if (n > 0.5) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
                ctx.beginPath(); ctx.arc(cx + 10, cy - 2, 1.5, 0, Math.PI*2); ctx.fill();
            } else if (n < 0.2) {
                ctx.beginPath();
                ctx.rect(cx - 5, cy - 5, 4, 4);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            ctx.globalAlpha = 0.6;
            // Grass Tufts
            const tufts = Math.floor(n * 4) + 2;
            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 12;

                // Wind effect
                const wind = Math.sin(time + cx * 0.01) * 2;

                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox - 2 + wind, cy + oy - 6, cx + ox - 4 + wind*2, cy + oy - 8);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox + 2 + wind, cy + oy - 5, cx + ox + 4 + wind*2, cy + oy - 7);
                ctx.lineWidth = 1.5;
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.4;
            ctx.fillStyle = '#fff';
            // Ice sheets / Reflections
            if (n > 0.4) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 2);
                ctx.lineTo(cx + 5, cy - 8);
                ctx.lineTo(cx + 15, cy - 4);
                ctx.lineTo(cx - 5, cy + 8);
                ctx.fill();

                // Glint
                const glint = Math.sin(time * 2 + n * 10);
                if (glint > 0.8) {
                    ctx.globalAlpha = (glint - 0.8) * 2;
                    ctx.fillStyle = '#fff';
                    ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2); ctx.fill();
                }
            }
        } else if (type === 'MAGMA') {
            // Pulsing Magma Cracks
            const pulse = 0.5 + Math.sin(time * 2 + n * 10) * 0.5;
            ctx.globalAlpha = 0.6 + pulse * 0.4;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 1.5 + pulse;
            ctx.shadowColor = '#f87171';
            ctx.shadowBlur = 5 * pulse;

            ctx.beginPath();
            ctx.moveTo(cx - 12, cy + 5);
            ctx.lineTo(cx - 5, cy - 2);
            ctx.lineTo(cx + 8, cy + 3);
            ctx.lineTo(cx + 15, cy - 5);
            ctx.stroke();

            ctx.shadowBlur = 0;
        } else if (type === 'DESERT') {
            ctx.globalAlpha = 0.3;
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            // Dunes / Ripples
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 5, 20, 0.5, 1.5);
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(cx + 5, cy + 5, 20, 0.5, 1.5);
            ctx.stroke();
        }

        ctx.restore();
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";

export class BackgroundRenderer {

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Base Gradient & Complex Background
        this.drawComplexBackground(ctx, width, height, scene, globalTime);

        // 2. Atmospheric Fog (Screen Space overlay)
        // Map dimensions in pixels for fog scrolling
        const mapPxW = mapConfig.w * HEX_SIZE * 2;
        const mapPxH = mapConfig.h * HEX_SIZE * 2;
        this.drawAtmosphericFog(ctx, mapPxW, mapPxH, scene, globalTime);

        // 3. Vignette (Focus attention on center)
        const rad = Math.min(width, height) * 0.8;
        const vig = ctx.createRadialGradient(width/2, height/2, rad * 0.5, width/2, height/2, rad * 1.5);
        vig.addColorStop(0, 'transparent');
        vig.addColorStop(1, 'rgba(0,0,0,0.6)');
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, width, height);
    }

    private drawComplexBackground(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number): void {
        // 1. Base Gradient (Sky + Horizon)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background); // Sky Top
        bgGrad.addColorStop(0.6, scene.horizon);  // Horizon Line
        bgGrad.addColorStop(1, '#020617');        // Ground Blend
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        ctx.save();

        // 2. Dynamic Moving Clouds (Parallax Layers)
        if (scene.id !== 'VOID') {
            this.drawMovingClouds(ctx, w, h, scene, t);
        }

        // 3. Stars / Nebula (For Space/Ice/Night themes)
        if (scene.id === 'VOID' || scene.id === 'ICE' || scene.id === 'FOREST') {
             // Nebula clouds
             ctx.globalCompositeOperation = 'screen';
             const cloudCount = 3;
             for(let i=0; i<cloudCount; i++) {
                 const x = (Math.sin(i * 1.5 + t * 0.05) * 0.5 + 0.5) * w;
                 const y = (Math.cos(i * 1.2 + t * 0.03) * 0.3 + 0.3) * h;
                 const radius = w * 0.4;
                 const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
                 grad.addColorStop(0, scene.ambientColor);
                 grad.addColorStop(1, 'transparent');
                 ctx.fillStyle = grad;
                 ctx.globalAlpha = 0.15;
                 ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI*2); ctx.fill();
             }

             // Stars
             ctx.fillStyle = '#fff';
             const seed = 123; 
             for(let i=0; i<80; i++) {
                 const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
                 const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.8; // Keep stars in upper sky
                 const size = Math.random() * 2;
                 const alpha = Math.sin(t + i) * 0.5 + 0.5;
                 ctx.globalAlpha = alpha * (scene.id === 'VOID' ? 0.8 : 0.4);
                 ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
             }
        }

        // 4. Distant Silhouette (Mountains) - Filled Polygon for depth
        if (scene.id === 'FOREST' || scene.id === 'ICE' || scene.id === 'DESERT' || scene.id === 'MAGMA') {
            ctx.globalCompositeOperation = 'source-over';

            const drawMountainLayer = (speed: number, yOffset: number, color: string, roughness: number) => {
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const n = Math.sin(x * 0.01 + t * speed) * Math.cos(x * 0.03) * roughness;
                    ctx.lineTo(x, h * 0.55 + yOffset + n);
                }
                ctx.lineTo(w, h);
                ctx.fill();
            };

            // Far Layer (Lighter/Foggy)
            ctx.globalAlpha = 0.3;
            drawMountainLayer(0.005, 0, scene.fogColor, 60);

            // Near Layer (Darker)
            ctx.globalAlpha = 0.5;
            drawMountainLayer(0.01, 60, scene.horizon, 40);
        }

        // 5. Special Sky Features & God Rays
        this.drawGodRays(ctx, w, h, t);
        this.drawSkyFeatures(ctx, w, h, scene, t);

        ctx.restore();
    }

    private drawMovingClouds(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        // Multi-layered clouds
        const layers = 2;
        ctx.globalCompositeOperation = 'soft-light';
        ctx.fillStyle = scene.fogColor;

        for(let l=0; l<layers; l++) {
            const speed = (l + 1) * 10;
            const yBase = h * (0.1 + l * 0.2);
            const scale = 100 + l * 50;

            ctx.globalAlpha = 0.1 + l * 0.1;

            for(let i=0; i<6; i++) {
                // Moving X
                const x = ((t * speed + i * (w/4)) % (w + scale*2)) - scale;
                const y = yBase + Math.sin(t * 0.5 + i) * 20;

                ctx.beginPath();
                ctx.ellipse(x, y, scale, scale * 0.4, 0, 0, Math.PI*2);
                ctx.fill();
            }
        }
    }

    private drawGodRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'overlay';

        // Source position moves slowly
        const sourceX = w * 0.8 + Math.sin(t * 0.1) * 100;
        const sourceY = -100;

        const grad = ctx.createRadialGradient(sourceX, sourceY, 50, sourceX, sourceY, w);
        grad.addColorStop(0, 'rgba(255, 255, 255, 0.15)'); 
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;

        // Draw Angular Rays
        for(let i=0; i<5; i++) {
            const angle = Math.PI / 2 + 0.3 + Math.sin(t * 0.05 + i) * 0.1 + (i * 0.15);
            const width = Math.PI / 32 * (1 + Math.sin(t + i)*0.2);
            const rayLen = w * 1.5;

            ctx.beginPath();
            ctx.moveTo(sourceX, sourceY);
            ctx.lineTo(sourceX + Math.cos(angle - width) * rayLen, sourceY + Math.sin(angle - width) * rayLen);
            ctx.lineTo(sourceX + Math.cos(angle + width) * rayLen, sourceY + Math.sin(angle + width) * rayLen);
            ctx.fill();
        }
        ctx.restore();
    }

    private drawSkyFeatures(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, t: number) {
        if (scene.bgFeature === 'NONE') return;

        ctx.globalCompositeOperation = 'screen';

        if (scene.bgFeature === 'SKY_RIVER') {
            // --- COSMIC RIVER ---
            const color = scene.ambientColor; // Purple

            for(let i=0; i<5; i++) {
                const lineWidth = 30 + i * 10;
                const amplitude = 30 + i * 10;
                const phase = t * (0.2 + i * 0.05);
                const yBase = h * 0.3 + i * 20;

                ctx.strokeStyle = color;
                ctx.lineWidth = lineWidth;
                ctx.globalAlpha = 0.1 - (i * 0.01);
                ctx.beginPath();
                for(let x=0; x<=w; x+=10) {
                    const y = yBase + Math.sin(x * 0.005 + phase) * amplitude + Math.cos(x * 0.01 - t*0.5) * 20;
                    if (x===0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.stroke();
            }

            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.6;
            for(let i=0; i<20; i++) {
                const prog = (t * 0.1 + i / 20) % 1;
                const x = prog * w;
                const y = h * 0.3 + 50 + Math.sin(x * 0.005 + t * 0.2) * 40;
                ctx.beginPath(); ctx.arc(x, y, Math.random()*2 + 1, 0, Math.PI*2); ctx.fill();
            }

        } else if (scene.bgFeature === 'AURORA') {
            const colors = ['#34d399', '#22d3ee', '#818cf8']; 

            for(let i=0; i<3; i++) {
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.2, colors[i]);
                grad.addColorStop(0.8, 'transparent');

                ctx.fillStyle = grad;
                ctx.globalAlpha = 0.15;

                const phase = t * 0.5 + i * 2;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const y = h * 0.4 + Math.sin(x * 0.01 + phase) * 100 * Math.sin(x*0.002);
                    ctx.lineTo(x, y);
                }
                ctx.lineTo(w, 0); 
                ctx.lineTo(0, 0); 
                ctx.fill();
            }

        } else if (scene.bgFeature === 'HEAT_WAVE') {
            ctx.fillStyle = '#fca5a5';
            ctx.globalAlpha = 0.05;
            for(let i=0; i<10; i++) {
                const x = (i / 10) * w;
                const height = h * 0.5 + Math.sin(t * 2 + i) * 50;
                const width = w / 10;
                ctx.fillRect(x, h - height, width, height);
            }
        }
    }

    private drawAtmosphericFog(ctx: CanvasRenderingContext2D, mapW: number, mapH: number, scene: SceneTheme, t: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'screen';

        const fogColor = scene.fogColor || '#fff';
        const fogSprite = AssetManager.getFogCloud(fogColor); 
        const numClouds = 8;

        for (let i = 0; i < numClouds; i++) {
            // Clouds moving diagonally
            const speed = 20;
            const x = ((t * speed + i * (mapW / numClouds)) % (mapW * 1.5)) - mapW * 0.25;
            const y = (Math.sin(i * 123 + t * 0.1) * 0.5 + 0.5) * mapH;
            const size = 300 + Math.sin(i) * 100;

            ctx.globalAlpha = 0.1 + Math.sin(t * 0.5 + i) * 0.05; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.6);
        }

        ctx.restore();
    }
}

import { VFXStateManager } from "./vfx/state";

const GRAVITY = 1800; // Gravity for particles

export class VFXSystem {
    // Encapsulated State
    public state: VFXStateManager = new VFXStateManager();

    // Ambient Spawn State
    private ambientTimer: number = 0;

    update(dt: number, globalTime: number, ambientType: string) {
        // Update Particles
        // Iterate backwards to allow safe removal
        for (let i = this.state.particles.length - 1; i >= 0; i--) {
            const p = this.state.particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                this.state.particles.splice(i, 1);
                continue;
            }

            // Physics Integration
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            p.z += p.vz * dt;
            p.rotation += p.vRotation * dt;

            // Gravity & Environment Logic
            if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                p.vz -= GRAVITY * dt; // Gravity

                // Ground Bounce
                if (p.z < 0) {
                    p.z = 0;
                    if (Math.abs(p.vz) > 100) {
                        p.vz = -p.vz * 0.5; // Bounce
                        p.vx *= 0.6; // Friction
                        p.vy *= 0.6;
                        p.vRotation *= 0.5;
                    } else {
                        p.vz = 0;
                        p.vx *= 0.1; // Stop sliding
                        p.vy *= 0.1;
                    }
                }
            } else if (p.type === 'SPARK' || p.type === 'SMOKE') {
                p.vx *= 0.90; 
                p.vy *= 0.90;
                p.vz *= 0.90; // Drag
            } else if (p.type === 'GLOW') {
                // Ambient particles float/wobble
                p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) this.state.decals.splice(i, 1);
        }

        // Update Grid Flashes
        for (let i = this.state.gridFlashes.length - 1; i >= 0; i--) {
            this.state.gridFlashes[i].life -= dt * 2.0;
            if (this.state.gridFlashes[i].life <= 0) this.state.gridFlashes.splice(i, 1);
        }

        // --- AMBIENT SPAWNER ---
        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;

        this.ambientTimer += dt;
        // Spawn rate based on type
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            this.spawnAmbientParticle(type);
        }
    }

    private spawnAmbientParticle(type: string) {
        // Spawn randomly in a large area around center
        // Hardcoded viewport assumption roughly 1000x800, better to pass camera but this works for ambient
        const x = Math.random() * 1200 - 100;
        const y = Math.random() * 800 - 100;

        const p = this.state.getParticle();
        p.x = x; p.y = y; p.z = Math.random() * 200 + 50; // Keep off ground
        p.type = 'GLOW';

        if (type === 'SNOW') {
            p.color = '#fff';
            p.size = Math.random() * 3 + 1;
            p.vx = 20 + Math.random() * 20; // Wind
            p.vy = 50 + Math.random() * 30; // Fall
            p.life = 3.0; p.maxLife = 3.0;
        } else if (type === 'ASH') {
            p.color = '#78350f'; // Dark grey/brown
            p.size = Math.random() * 4 + 1;
            p.vx = 30 + Math.random() * 30;
            p.vy = 20 + Math.random() * 20;
            p.life = 4.0; p.maxLife = 4.0;
        } else if (type === 'EMBER') {
            p.color = '#fbbf24';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 20;
            p.vy = -30 - Math.random() * 20; // Rise
            p.life = 2.0; p.maxLife = 2.0;
        } else if (type === 'SPORES') {
            p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 10;
            p.vy = (Math.random() - 0.5) * 10; // Float
            p.life = 5.0; p.maxLife = 5.0;
        }

        this.state.particles.push(p);
    }
}

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Increased canvas height to accommodate tall structures without clipping
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Ground Ambient Occlusion)
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath();
        ctx.ellipse(cx, cy - 5, 24, 12, 0, 0, Math.PI*2);
        ctx.fill();

        if (styleKey === 'TREE') {
            // --- ANCIENT TREE (Stylized Ghibli-esque) ---

            // 1. Trunk (Twisted)
            const trunkGrad = ctx.createLinearGradient(cx - 10, cy, cx + 10, cy);
            trunkGrad.addColorStop(0, '#271c19');
            trunkGrad.addColorStop(0.3, '#5D4037'); // Highlight side
            trunkGrad.addColorStop(1, '#1a1210');   // Shadow side

            ctx.fillStyle = trunkGrad;
            ctx.beginPath();
            ctx.moveTo(cx - 12, cy); 
            ctx.quadraticCurveTo(cx - 5, cy - 20, cx - 8, cy - 50); // Left curve
            ctx.lineTo(cx + 8, cy - 50); 
            ctx.quadraticCurveTo(cx + 5, cy - 20, cx + 12, cy); // Right curve
            ctx.fill();

            // Roots
            ctx.beginPath();
            ctx.moveTo(cx - 12, cy); ctx.quadraticCurveTo(cx - 18, cy + 5, cx - 22, cy + 2); ctx.lineTo(cx - 12, cy - 5);
            ctx.moveTo(cx + 12, cy); ctx.quadraticCurveTo(cx + 18, cy + 5, cx + 22, cy + 2); ctx.lineTo(cx + 12, cy - 5);
            ctx.fill();

            // 2. Foliage Layers (Bottom to Top)
            const drawLeafBlob = (x: number, y: number, r: number, color: string, shadow: string) => {
                ctx.save();
                // Shadow / Underside
                ctx.fillStyle = shadow;
                ctx.beginPath(); ctx.arc(x, y + 3, r, 0, Math.PI*2); ctx.fill();
                // Main Leaf
                const leafGrad = ctx.createRadialGradient(x - r*0.3, y - r*0.3, 0, x, y, r);
                leafGrad.addColorStop(0, '#86efac'); // Highlight
                leafGrad.addColorStop(1, color);
                ctx.fillStyle = leafGrad;
                ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
                ctx.restore();
            };

            const leafBase = style.detail; 
            const leafDark = style.dark;   

            // Layer 1 (Back/Bottom)
            drawLeafBlob(cx - 18, cy - 55, 18, leafBase, leafDark);
            drawLeafBlob(cx + 18, cy - 50, 16, leafBase, leafDark);

            // Layer 2 (Mid)
            drawLeafBlob(cx, cy - 65, 22, leafBase, leafDark);
            drawLeafBlob(cx - 10, cy - 75, 15, leafBase, leafDark);

            // Layer 3 (Top)
            drawLeafBlob(cx + 5, cy - 85, 14, '#4ade80', leafBase);

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- ICE SPIKES (Translucent Facets) ---

            const drawShard = (x: number, yBase: number, w: number, h: number, angle: number) => {
                ctx.save();
                ctx.translate(x, yBase);
                ctx.rotate(angle);

                // Crystal Gradient
                const iceGrad = ctx.createLinearGradient(-w, -h, w, 0);
                iceGrad.addColorStop(0, 'rgba(255,255,255,0.9)');
                iceGrad.addColorStop(0.5, style.light); 
                iceGrad.addColorStop(1, style.dark);

                ctx.fillStyle = iceGrad;
                ctx.beginPath();
                ctx.moveTo(-w, 0);
                ctx.lineTo(0, -h); // Tip
                ctx.lineTo(w, 0);
                ctx.lineTo(0, 5);  // Base dip
                ctx.closePath();
                ctx.fill();

                // Rim Light
                ctx.strokeStyle = 'rgba(255,255,255,0.8)';
                ctx.lineWidth = 1;
                ctx.stroke();

                // Internal fracture
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-2, 0); ctx.stroke();

                ctx.restore();
            };

            // Cluster
            drawShard(cx - 10, cy - 5, 12, 50, -0.3);
            drawShard(cx + 12, cy, 14, 45, 0.4);
            drawShard(cx, cy + 2, 18, 70, 0); // Main spire

            // Ground Frost
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.3;
            ctx.beginPath(); ctx.ellipse(cx, cy, 25, 10, 0, 0, Math.PI*2); ctx.fill();

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MAGMA ROCK (Jagged & Emissive) ---

            // Silhouette
            ctx.beginPath();
            ctx.moveTo(cx - 15, cy);
            ctx.lineTo(cx - 20, cy - 30);
            ctx.lineTo(cx - 10, cy - 85); // Top Left
            ctx.lineTo(cx + 5, cy - 90);  // Top
            ctx.lineTo(cx + 20, cy - 70); // Top Right
            ctx.lineTo(cx + 25, cy - 20);
            ctx.lineTo(cx + 15, cy);
            ctx.closePath();

            // Dark Stone Gradient
            const rockGrad = ctx.createLinearGradient(cx - 20, cy - 90, cx + 20, cy);
            rockGrad.addColorStop(0, '#52525b'); // Highlight edge
            rockGrad.addColorStop(0.3, '#18181b'); // Main body
            rockGrad.addColorStop(1, '#09090b');   // Base
            ctx.fillStyle = rockGrad;
            ctx.fill();

            // Emissive Cracks
            ctx.strokeStyle = '#ef4444';
            ctx.shadowColor = '#f87171';
            ctx.shadowBlur = 8;
            ctx.lineWidth = 2;
            ctx.lineJoin = 'round';

            ctx.beginPath();
            ctx.moveTo(cx - 5, cy - 10); 
            ctx.lineTo(cx, cy - 40); 
            ctx.lineTo(cx + 10, cy - 50);
            ctx.lineTo(cx + 5, cy - 75);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(cx + 15, cy - 20); ctx.lineTo(cx + 10, cy - 30);
            ctx.stroke();

        } else if (styleKey === 'SANDSTONE') {
            // --- ERODED ROCK (Layered Sediment) ---

            // Shape: Rounded by wind
            ctx.beginPath();
            ctx.moveTo(cx - 25, cy);
            ctx.lineTo(cx - 22, cy - 40);
            ctx.quadraticCurveTo(cx - 20, cy - 80, cx, cy - 85); // Top
            ctx.quadraticCurveTo(cx + 20, cy - 80, cx + 22, cy - 30);
            ctx.lineTo(cx + 25, cy);
            ctx.fill(); // Masking fill

            // Draw Layers (Clip)
            ctx.save();
            ctx.clip();

            const layers = 6;
            const layerH = 90 / layers;
            for(let i=0; i<layers; i++) {
                const yPos = cy - 90 + i * layerH;
                // Alternating bands
                ctx.fillStyle = i % 2 === 0 ? style.main : style.dark;
                ctx.fillRect(0, yPos, width, layerH);

                // Texture noise
                ctx.fillStyle = 'rgba(0,0,0,0.1)';
                if (i%3===0) ctx.fillRect(0, yPos, width, 5);
            }

            // Highlight Side (Wind side)
            const sunGrad = ctx.createLinearGradient(0, 0, width, 0);
            sunGrad.addColorStop(0, 'rgba(255,255,255,0.2)');
            sunGrad.addColorStop(0.5, 'transparent');
            sunGrad.addColorStop(1, 'rgba(0,0,0,0.3)');
            ctx.fillStyle = sunGrad;
            ctx.fillRect(0, 0, width, height);

            ctx.restore();

            // Outline
            ctx.strokeStyle = style.dark;
            ctx.lineWidth = 2;
            ctx.stroke();

        } else {
            // --- STONE WALL (Isometric Block) ---
            const w = 40; // Total width
            const h = 50; // Block height
            const d = 15; // Depth (Top face height)

            const topY = cy - h;

            // 1. Right Face (Shadow)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w/2, topY - d/2);
            ctx.lineTo(cx + w/2, cy - d/2);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // 2. Left Face (Mid)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w/2, topY - d/2);
            ctx.lineTo(cx - w/2, cy - d/2);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // 3. Top Face (Light)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w/2, topY - d/2);
            ctx.lineTo(cx, topY - d);
            ctx.lineTo(cx + w/2, topY - d/2);
            ctx.fill();

            // 4. Details (Cracks & Moss)
            ctx.strokeStyle = 'rgba(0,0,0,0.3)';
            ctx.lineWidth = 2;

            // Brick lines Left
            ctx.beginPath(); ctx.moveTo(cx - w/4, topY); ctx.lineTo(cx - w/4, cy - d/4); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(cx - w/2, topY - d/2 + 20); ctx.lineTo(cx, topY + 20); ctx.stroke();

            // Moss on top
            if (style.detail) {
                ctx.fillStyle = style.detail;
                ctx.beginPath();
                ctx.arc(cx - 10, topY - d/2, 6, 0, Math.PI*2);
                ctx.arc(cx - 5, topY - d/2 - 2, 4, 0, Math.PI*2);
                ctx.fill();
            }

            // Outline
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1;
            ctx.beginPath();
            // Outer contour
            ctx.moveTo(cx, topY - d);
            ctx.lineTo(cx + w/2, topY - d/2);
            ctx.lineTo(cx + w/2, cy - d/2);
            ctx.lineTo(cx, cy);
            ctx.lineTo(cx - w/2, cy - d/2);
            ctx.lineTo(cx - w/2, topY - d/2);
            ctx.closePath();
            ctx.stroke();
            // Inner corner
            ctx.beginPath(); ctx.moveTo(cx, topY - d); ctx.lineTo(cx, cy); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(cx, topY); ctx.lineTo(cx - w/2, topY - d/2); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(cx, topY); ctx.lineTo(cx + w/2, topY - d/2); ctx.stroke();
        }

        return canvas;
    },

    // Updated Ice Block for Status Effect (Frozen) to match the new style
    generateIceBlock(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 128);
        const cx = 48, cy = 110;

        const grad = ctx.createLinearGradient(0, 0, 96, 128);
        grad.addColorStop(0, 'rgba(255, 255, 255, 0.9)');
        grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.6)'); // Sky-400
        grad.addColorStop(1, 'rgba(3, 105, 161, 0.8)');    // Sky-700

        ctx.fillStyle = grad;
        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
        ctx.lineWidth = 2;

        // Massive Block Shape
        ctx.beginPath();
        ctx.moveTo(cx - 30, cy);
        ctx.lineTo(cx - 40, cy - 40);
        ctx.lineTo(cx - 20, cy - 100); // Top Left
        ctx.lineTo(cx + 20, cy - 90);  // Top Right
        ctx.lineTo(cx + 40, cy - 30);
        ctx.lineTo(cx + 30, cy);
        ctx.closePath();

        ctx.fill();
        ctx.stroke();

        // Internal Reflections (Facets)
        ctx.beginPath(); ctx.moveTo(cx, cy - 100); ctx.lineTo(cx - 10, cy - 40); ctx.lineTo(cx - 30, cy); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(cx, cy - 100); ctx.lineTo(cx + 15, cy - 30); ctx.lineTo(cx + 30, cy); ctx.stroke();

        // Ground freeze
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.4;
        ctx.beginPath(); ctx.ellipse(cx, cy, 35, 12, 0, 0, Math.PI*2); ctx.fill();

        return canvas;
    }
};

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// NEW Renderers
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";

const OBSTACLE_Z_INDEX = 10;
// SPRITE ANCHOR: The factory generates 80x110 sprites.
// The "feet" or base of the obstacle is defined at y=95 in the factory.
const OBSTACLE_ANCHOR_Y = 95; 
const OBSTACLE_HALF_WIDTH = 40; // 80 / 2

// Re-export Camera for compatibility
export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    // New Composition Renderers
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();

        // Initialize sub-renderers
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;

        // Update Sub-systems
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const defaultStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Clear & Background
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.backgroundRenderer.draw(ctx, canvasWidth, canvasHeight, scene, engine.mapConfig, this.globalTime);

        // 2. Camera Transform (Delegated)
        ctx.save();
        this.camera.sync(camera);
        this.camera.applyTransform(ctx, canvasWidth, canvasHeight);

        // 3. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfxRenderer.collectRenderables(
            engine,
            this.vfx,
            (q, r) => this.grid.getTerrainHeight(q, r, engine),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), this.globalTime, highlight, engine.mapConfig
        ));

        // Iterate over Obstacles
        engine.obstacles.forEach((type, key) => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             // Transition Logic
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r, engine);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         const sprite = SpriteManager.getObstacleSprite(type || defaultStyle);
                         // Center Correctly: -40 for 80px width, -95 for anchor offset
                         c.drawImage(sprite, pos.x - OBSTACLE_HALF_WIDTH, visualY - terrainH - OBSTACLE_ANCHOR_Y);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 4. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 5. Tactical Overlay Lines
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 6. Top VFX
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 7. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        // 8. Holographic Director HUD
        if (engine.directorTargetId) {
            ctx.restore(); // Undo Camera
            this.tacticalRenderer.drawHUD(ctx, engine, canvasWidth, canvasHeight, camera, this.globalTime);
            ctx.save(); // Restore dummy state for symmetric restore below
        } else {
            ctx.restore();
            ctx.save();
        }

        // 9. Post Processing (Delegated)
        ctx.restore(); // Ensure we are in Screen Space
        this.camera.applyPostProcessing(ctx, canvasWidth, canvasHeight);

        // 10. Debug Overlay
        this.tacticalRenderer.drawDebug(ctx, fps);
    }
}

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Dimensions
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point (Ground level)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Ground Ambient Occlusion) - Cleaner ellipse
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.beginPath();
        ctx.ellipse(cx, cy - 2, 28, 14, 0, 0, Math.PI*2);
        ctx.fill();

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE (Clean Geometric Layers) ---

            // Trunk
            ctx.fillStyle = '#3e2723'; // Dark Wood
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy); 
            ctx.lineTo(cx + 6, cy);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 90;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const nextY = topY + (bottomY - topY) * ((i+1)/layers);
                const spread = 15 + i * 12;

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, '#4ade80'); // Bright Green Top
                grad.addColorStop(1, '#14532d'); // Dark Green Bottom

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 15); // Tip
                // Left Flare
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                // Bottom Curve (Concave up)
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                // Right Flare
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 15);
                ctx.fill();

                // Shadow underneath layer
                ctx.fillStyle = 'rgba(0,0,0,0.2)';
                ctx.beginPath();
                ctx.moveTo(cx, layerY + 10);
                ctx.lineTo(cx + spread, layerY + 15);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.fill();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---

            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number, color: string) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Facet 1 (Left/Dark)
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Facet 2 (Right/Light)
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(1, style.light);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Rim
                ctx.strokeStyle = 'rgba(255,255,255,0.8)';
                ctx.lineWidth = 1;
                ctx.stroke();

                ctx.restore();
            };

            drawCrystal(cx - 15, cy - 5, 10, 40, -0.2, '#fff');
            drawCrystal(cx + 12, cy, 12, 35, 0.3, '#fff');
            drawCrystal(cx, cy + 5, 16, 65, 0, '#fff'); // Main

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Dark Geometric) ---

            const topY = cy - 75;
            const w = 25;

            // Main Body Gradient
            const rockGrad = ctx.createLinearGradient(cx - w, topY, cx + w, cy);
            rockGrad.addColorStop(0, '#52525b');
            rockGrad.addColorStop(0.4, '#18181b');
            rockGrad.addColorStop(1, '#09090b');
            ctx.fillStyle = rockGrad;

            ctx.beginPath();
            ctx.moveTo(cx, topY); // Top tip
            ctx.lineTo(cx + w, cy - 20); // Right mid
            ctx.lineTo(cx + 10, cy); // Base Right
            ctx.lineTo(cx - 10, cy); // Base Left
            ctx.lineTo(cx - w, cy - 20); // Left mid
            ctx.closePath();
            ctx.fill();

            // Facet Highlights (Edges)
            ctx.strokeStyle = '#3f3f46';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx - w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy); // Center spine
            ctx.stroke();

            // Emissive Veins
            ctx.strokeStyle = '#ef4444';
            ctx.shadowColor = '#f87171';
            ctx.shadowBlur = 10;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 5, cy - 10); ctx.lineTo(cx + 5, cy - 30); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else if (styleKey === 'SANDSTONE') {
            // --- MESA STACK (Rounded Layers) ---

            const layers = 5;
            const w = 35;
            let currentW = w;
            let currentY = cy;

            for(let i=0; i<layers; i++) {
                const h = 15 + Math.random() * 5;
                const nextY = currentY - h;
                const nextW = currentW * (0.6 + Math.random() * 0.2); // Taper up

                ctx.fillStyle = i % 2 === 0 ? style.main : style.light;

                ctx.beginPath();
                ctx.ellipse(cx, currentY, currentW, 10, 0, 0, Math.PI*2);
                ctx.fill();

                // Block body
                ctx.fillRect(cx - nextW, nextY, nextW * 2, currentY - nextY);

                // Side shading
                ctx.fillStyle = 'rgba(0,0,0,0.1)';
                ctx.fillRect(cx, nextY, nextW, currentY - nextY);

                currentY = nextY;
                currentW = nextW;
            }
            // Top Cap
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.ellipse(cx, currentY, currentW, 6, 0, 0, Math.PI*2);
            ctx.fill();

        } else {
            // --- STONE PILLAR (Stylized Fortification) ---
            const w = 30; // Half width
            const h = 60; // Height
            const topY = cy - h;

            // 1. Right Face (Shadow)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10); // Isometric top-right
            ctx.lineTo(cx + w, cy - 10);   // Bottom-right
            ctx.lineTo(cx, cy);            // Bottom-center
            ctx.fill();

            // 2. Left Face (Mid)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w, topY + 10);
            ctx.lineTo(cx - w, cy - 10);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // 3. Top Face (Light)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10);
            ctx.lineTo(cx, topY + 20); // Center-down
            ctx.lineTo(cx - w, topY + 10);
            ctx.fill();

            // 4. Edges / Outline
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;

            ctx.beginPath();
            // Central Spine
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy);
            // Top Diamond
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, topY + 10); ctx.lineTo(cx, topY + 20); ctx.lineTo(cx - w, topY + 10); ctx.lineTo(cx, topY);
            ctx.stroke();

            // Rivet Details
            ctx.fillStyle = '#1e293b';
            ctx.beginPath(); ctx.arc(cx, topY + 30, 3, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 128);
        const cx = 48, cy = 110;

        // Crystalline Prism
        const grad = ctx.createLinearGradient(0, 0, 96, 128);
        grad.addColorStop(0, 'rgba(255, 255, 255, 0.95)');
        grad.addColorStop(0.5, 'rgba(125, 211, 252, 0.7)'); 
        grad.addColorStop(1, 'rgba(3, 105, 161, 0.8)');    

        ctx.fillStyle = grad;
        ctx.strokeStyle = 'rgba(255,255,255,0.9)';
        ctx.lineWidth = 1.5;

        ctx.beginPath();
        ctx.moveTo(cx, cy - 105); // Top Tip
        ctx.lineTo(cx + 35, cy - 80); // Right Shoulder
        ctx.lineTo(cx + 30, cy - 5);  // Right Base
        ctx.lineTo(cx, cy);           // Bottom Center
        ctx.lineTo(cx - 30, cy - 5);  // Left Base
        ctx.lineTo(cx - 35, cy - 80); // Left Shoulder
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Inner Facets
        ctx.beginPath(); 
        ctx.moveTo(cx, cy - 105); ctx.lineTo(cx, cy); // Spine
        ctx.moveTo(cx - 35, cy - 80); ctx.lineTo(cx, cy - 40); ctx.lineTo(cx + 35, cy - 80); // Cross cut
        ctx.stroke();

        // Ground Frost
        ctx.fillStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath(); ctx.ellipse(cx, cy, 35, 12, 0, 0, Math.PI*2); ctx.fill();

        return canvas;
    }
};

import { Agent } from "../../../game";
import { AssetManager } from "../../../assets";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // Animation Transforms
        const breathe = (agent.hp > 0) ? Math.sin(t * 3) * 1.5 : 0;
        let thrustX = 0;
        let armRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.3) { // Windup
                thrustX = -8 * (progress / 0.3);
                armRot = -0.4;
            } else if (progress < 0.5) { // Strike
                thrustX = 20;
                armRot = 1.2;
            } else { // Recovery
                thrustX = 20 * (1 - (progress - 0.5)/0.5);
                armRot = 1.2 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);

        // --- 1. CAPE / BACK ACCESSORIES (Back Layer) ---
        if (!isSilhouette) {
            ctx.fillStyle = '#1e3a8a'; // Deep Royal Blue
            ctx.beginPath();
            ctx.moveTo(-12, -35);
            ctx.quadraticCurveTo(0, -25, 12, -35); // Shoulders
            ctx.lineTo(18, 20 + breathe); // Flare out
            ctx.quadraticCurveTo(0, 25 + breathe, -18, 20 + breathe);
            ctx.closePath();
            ctx.fill();
            // Cape trim
            ctx.strokeStyle = '#fbbf24'; 
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        // --- 2. WEAPON (Back Hand) ---
        // For Rangers/Mages, weapon might be in front. For Warrior/Tank, main hand is usually right (visual front or back depending on pose)
        // Standard Isometric Pose: Left side is "Back", Right side is "Front".
        // Let's put weapon in Back Hand for Warrior to allow Shield in Front.
        if (agent.role === Role.WARRIOR || agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.save();
            ctx.translate(12, -15); // Shoulder pivot
            ctx.rotate(armRot);
            if(agent.role === Role.MAGE) ctx.rotate(-Math.PI/8); // Staff upright
            drawImperialWeapon(ctx, agent.role, isSilhouette);
            ctx.restore();
        }

        // --- 3. BODY (Armor) ---
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent'; 
        } else {
            // Shiny Metal Gradient
            const armorGrad = ctx.createLinearGradient(-15, -40, 15, 20);
            armorGrad.addColorStop(0, '#f1f5f9'); // Highlight
            armorGrad.addColorStop(0.4, '#94a3b8'); // Mid
            armorGrad.addColorStop(1, '#475569');   // Shadow
            ctx.fillStyle = armorGrad;
            ctx.strokeStyle = '#1e293b'; 
            ctx.lineWidth = 1;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Heavy Plate (Bulky)
            ctx.moveTo(-20, -35); ctx.lineTo(20, -35);  // Shoulders
            ctx.lineTo(15, 10); ctx.lineTo(-15, 10);    // Waist
            ctx.lineTo(-20, -35);
        } else if (agent.role === Role.RANGER) {
            // Light Chainmail (Slim)
            ctx.fillStyle = isSilhouette ? 'transparent' : '#cbd5e1';
            ctx.moveTo(-12, -30); ctx.lineTo(12, -30);
            ctx.lineTo(8, 10); ctx.lineTo(-8, 10);
            ctx.lineTo(-12, -30);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            // Robes (Cloth)
            if(!isSilhouette) ctx.fillStyle = '#1d4ed8'; // Blue Robe
            ctx.moveTo(-14, -30); ctx.lineTo(14, -30);
            ctx.lineTo(18, 20); ctx.lineTo(-18, 20);
            ctx.lineTo(-14, -30);
        } else {
            // Warrior Breastplate
            ctx.moveTo(-16, -32); ctx.lineTo(16, -32);
            ctx.lineTo(10, 10); ctx.lineTo(-10, 10);
            ctx.lineTo(-16, -32);
        }
        ctx.closePath();

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill();
            ctx.stroke();

            // Gold Trim / Tabard
            if (agent.role === Role.TANK || agent.role === Role.WARRIOR) {
                ctx.fillStyle = '#fbbf24';
                ctx.beginPath(); 
                ctx.moveTo(-6, -32); ctx.lineTo(6, -32); ctx.lineTo(4, 5); ctx.lineTo(-4, 5); 
                ctx.fill();
            }
        }

        // --- 4. HEAD ---
        ctx.save();
        const headY = agent.role === Role.TANK ? -42 : -38;
        ctx.translate(0, headY + breathe * 0.5);

        // Helmet Design
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.beginPath(); ctx.rect(-10, -12, 20, 15); ctx.stroke();
        } else {
            // Silver Helm Base
            const helmGrad = ctx.createRadialGradient(-5, -5, 2, 0, 0, 15);
            helmGrad.addColorStop(0, '#fff');
            helmGrad.addColorStop(1, '#94a3b8');
            ctx.fillStyle = helmGrad;

            ctx.beginPath();
            if (agent.role === Role.MAGE) {
                // Hood
                ctx.fillStyle = '#1e3a8a';
                ctx.moveTo(0, -18); ctx.lineTo(12, 5); ctx.lineTo(-12, 5);
                ctx.fill();
            } else if (agent.role === Role.SUPPORT) {
                // Mitre / Crown
                ctx.fillStyle = '#f1f5f9';
                ctx.moveTo(-8, 5); ctx.lineTo(-8, -10); ctx.lineTo(0, -15); ctx.lineTo(8, -10); ctx.lineTo(8, 5);
                ctx.fill();
                ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2; ctx.stroke();
            } else if (agent.role === Role.TANK) {
                // Full Great Helm
                ctx.fillRect(-11, -14, 22, 18);
                // Gold Cross
                ctx.fillStyle = '#fbbf24'; ctx.fillRect(-11, -8, 22, 4); ctx.fillRect(-2, -14, 4, 18);
            } else {
                // Standard Helm
                ctx.fillRect(-9, -12, 18, 14);
                // Visor
                ctx.fillStyle = '#0f172a'; ctx.fillRect(-9, -4, 18, 3);
            }
        }
        ctx.restore();

        // --- 5. FRONT ARM / OFF-HAND ---
        ctx.save();
        ctx.translate(-14, -12); // Left Shoulder

        if (agent.role === Role.TANK) {
            // Shield Arm
            ctx.rotate(armRot * 0.5);
            ctx.translate(0, 10);
            drawImperialShield(ctx, isSilhouette);
        } else if (agent.role === Role.RANGER) {
            // Bow Arm (Front)
            ctx.rotate(armRot);
            ctx.translate(10, 5);
            drawImperialWeapon(ctx, Role.RANGER, isSilhouette);
        } else {
            // Empty Hand / Small Buckler
            ctx.beginPath(); ctx.arc(0, 5, 5, 0, Math.PI*2);
            if(isSilhouette) { ctx.strokeStyle = silhouetteColor; ctx.stroke(); }
            else { ctx.fillStyle = '#cbd5e1'; ctx.fill(); ctx.stroke(); }
        }
        ctx.restore();

        ctx.restore(); 
    }
};

function drawImperialShield(ctx: CanvasRenderingContext2D, isSilhouette: boolean) {
    if (isSilhouette) {
        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 2;
        ctx.strokeRect(-12, -20, 24, 40);
        return;
    }

    // Tower Shield Body
    const grad = ctx.createLinearGradient(-15, 0, 15, 0);
    grad.addColorStop(0, '#1d4ed8');
    grad.addColorStop(0.5, '#60a5fa');
    grad.addColorStop(1, '#1e3a8a');

    ctx.fillStyle = grad;
    ctx.strokeStyle = '#fcd34d'; // Gold Rim
    ctx.lineWidth = 3;

    ctx.beginPath();
    ctx.moveTo(-14, -24); 
    ctx.lineTo(14, -24);
    ctx.lineTo(14, 10); 
    ctx.lineTo(0, 30); // Pointy bottom
    ctx.lineTo(-14, 10);
    ctx.closePath();

    ctx.fill();
    ctx.stroke();

    // Emblem (Lion/Sun)
    ctx.fillStyle = '#fcd34d';
    ctx.beginPath(); ctx.arc(0, -5, 6, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(0, 5); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(10, -5); ctx.stroke();
}

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, isSilhouette: boolean) {
    if (isSilhouette) {
        ctx.strokeStyle = '#60a5fa'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(0, 10); ctx.lineTo(0, -40); ctx.stroke();
        return;
    }

    ctx.shadowBlur = 0;

    if (role === Role.WARRIOR) {
        // Broadsword
        ctx.rotate(-Math.PI/6);
        // Hilt
        ctx.fillStyle = '#451a03'; ctx.fillRect(-2, 0, 4, 15);
        // Guard
        ctx.fillStyle = '#fbbf24'; ctx.fillRect(-10, -5, 20, 5);
        // Blade (Gradient for sharpness)
        const bladeGrad = ctx.createLinearGradient(0, -5, 0, -60);
        bladeGrad.addColorStop(0, '#94a3b8'); bladeGrad.addColorStop(0.5, '#f8fafc'); bladeGrad.addColorStop(1, '#94a3b8');
        ctx.fillStyle = bladeGrad;
        ctx.beginPath(); ctx.moveTo(-4, -5); ctx.lineTo(4, -5); ctx.lineTo(0, -60); ctx.fill();
        // Blood Groove
        ctx.strokeStyle = '#475569'; ctx.lineWidth = 1; 
        ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(0, -50); ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // Staff
        ctx.fillStyle = '#854d0e'; ctx.fillRect(-3, -40, 6, 60); // Wood
        // Head
        ctx.fillStyle = '#fbbf24'; // Gold setting
        ctx.beginPath(); ctx.arc(0, -45, 8, 0, Math.PI*2); ctx.stroke();
        // Crystal
        ctx.fillStyle = role === Role.MAGE ? '#3b82f6' : '#a855f7';
        ctx.beginPath(); ctx.moveTo(0, -55); ctx.lineTo(6, -45); ctx.lineTo(0, -35); ctx.lineTo(-6, -45); ctx.fill();

    } else if (role === Role.RANGER) {
        // Longbow
        ctx.strokeStyle = '#854d0e'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(-5, 0, 30, -Math.PI/2, Math.PI/2); ctx.stroke();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(-5, -30); ctx.lineTo(-5, 30); ctx.stroke();
    }
}

import { Agent } from "../../../game";
import { AssetManager } from "../../../assets";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 

        // Animation Vars
        // Covenant units "Heave" rather than breathe evenly
        const heave = (agent.hp > 0) ? Math.abs(Math.sin(t * 3)) * 2 : 0;
        let jitterX = 0; let jitterY = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.5) { // Windup (Shake)
                jitterX = (Math.random() - 0.5) * 4;
                jitterY = (Math.random() - 0.5) * 4;
            } else { // Lunge
                jitterX = 25 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(jitterX, heave + jitterY);

        // --- 1. SPIKES / BACK GEAR ---
        if (!isSilhouette) {
            ctx.fillStyle = '#1c1917'; // Dark Iron
            ctx.beginPath();
            // Spikes protruding from back
            ctx.moveTo(-10, -30); ctx.lineTo(-25, -50); ctx.lineTo(-15, -25);
            ctx.moveTo(10, -30); ctx.lineTo(25, -50); ctx.lineTo(15, -25);
            ctx.fill();
        }

        // --- 2. WEAPON (Back Hand) ---
        // Red team holds heavy weapons in back hand
        if (agent.role !== Role.RANGER) {
            ctx.save();
            ctx.translate(15, -10); 
            ctx.rotate(agent.animState === AnimState.ATTACK ? Math.PI/4 : 0);
            drawCovenantWeapon(ctx, agent.role, isSilhouette);
            ctx.restore();
        }

        // --- 3. BODY (Hunched) ---
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent';
        } else {
            // Rough/Rusty Gradient
            const bodyGrad = ctx.createLinearGradient(-15, -30, 15, 20);
            bodyGrad.addColorStop(0, '#7f1d1d'); // Rust Red
            bodyGrad.addColorStop(0.5, '#450a0a'); // Dark Blood
            bodyGrad.addColorStop(1, '#000000');   
            ctx.fillStyle = bodyGrad;
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
        }

        ctx.beginPath();
        // Hunched Shape: Lower neck, wider shoulders
        ctx.ellipse(0, -15, 22, 28, 0, 0, Math.PI*2);

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.stroke();

            // Warpaint / Runes
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(-10, -20); ctx.lineTo(0, -10); ctx.lineTo(10, -20); // V Shape
            ctx.stroke();
        }

        // --- 4. HEAD (Low and Mean) ---
        ctx.save();
        const headY = -25; // Lower than Blue team
        ctx.translate(0, headY + heave * 0.5);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.beginPath(); ctx.ellipse(0, 0, 12, 10, 0, 0, Math.PI*2); ctx.stroke();
        } else {
            // Dark Helmet / Mask
            ctx.fillStyle = '#27272a'; 
            ctx.beginPath();
            if (agent.role === Role.TANK) {
                // Horned Helm
                ctx.moveTo(-12, -5); ctx.lineTo(-18, -15); ctx.lineTo(-8, -5); // L Horn
                ctx.moveTo(12, -5); ctx.lineTo(18, -15); ctx.lineTo(8, -5);   // R Horn
                ctx.ellipse(0, 0, 14, 12, 0, 0, Math.PI*2);
            } else if (agent.role === Role.MAGE) {
                // Skull Mask
                ctx.fillStyle = '#e7e5e4'; // Bone
                ctx.ellipse(0, 0, 10, 14, 0, 0, Math.PI*2);
            } else {
                // Jaw Plate
                ctx.arc(0, 0, 11, 0, Math.PI*2);
            }
            ctx.fill();

            // Glowing Eyes (Signature)
            ctx.fillStyle = agent.role === Role.MAGE ? '#10b981' : '#ef4444'; // Green for warlock, Red for others
            ctx.shadowColor = ctx.fillStyle; ctx.shadowBlur = 10;
            ctx.beginPath(); ctx.arc(-4, 0, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(4, 0, 2, 0, Math.PI*2); ctx.fill();
            ctx.shadowBlur = 0;
        }
        ctx.restore();

        // --- 5. FRONT ARM / RANGER WEAPON ---
        ctx.save();
        ctx.translate(-15, -5);
        if (agent.role === Role.RANGER) {
            drawCovenantWeapon(ctx, Role.RANGER, isSilhouette);
        } else {
            // Big Fist / Gauntlet
            ctx.beginPath(); ctx.arc(0, 8, 8, 0, Math.PI*2);
            if(isSilhouette) { ctx.strokeStyle = silhouetteColor; ctx.stroke(); }
            else { 
                ctx.fillStyle = '#52525b'; ctx.fill(); ctx.stroke(); 
                // Spikes on knuckles
                ctx.fillStyle = '#d4d4d8';
                ctx.beginPath(); ctx.moveTo(-5, 8); ctx.lineTo(-8, 15); ctx.lineTo(0, 8); ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }
};

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role, isSilhouette: boolean) {
    if (isSilhouette) {
        ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
        ctx.strokeRect(-5, -30, 10, 40);
        return;
    }

    if (role === Role.WARRIOR) {
        // Battleaxe (Double Headed)
        ctx.fillStyle = '#3f2c22'; ctx.fillRect(-3, -10, 6, 60); // Handle
        ctx.translate(0, 40);
        // Blades
        ctx.fillStyle = '#52525b'; 
        ctx.beginPath();
        ctx.moveTo(0, -10); 
        ctx.quadraticCurveTo(-30, -20, -25, 20); ctx.lineTo(0, 10); // L
        ctx.quadraticCurveTo(30, -20, 25, 20); ctx.lineTo(0, 10);   // R
        ctx.fill();
        // Blood edge
        ctx.strokeStyle = '#991b1b'; ctx.lineWidth = 2; ctx.stroke();

    } else if (role === Role.TANK) {
        // Heavy Cleaver
        ctx.fillStyle = '#3f2c22'; ctx.fillRect(-3, -10, 6, 50);
        ctx.translate(0, 20);
        ctx.fillStyle = '#27272a';
        ctx.beginPath(); ctx.rect(-10, 0, 20, 40); ctx.fill(); // Slab
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.strokeRect(-10, 0, 20, 40); // Sharpened

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // Ritual Staff
        ctx.fillStyle = '#3f2c22'; ctx.fillRect(-3, -30, 6, 60);
        ctx.translate(0, -30);
        // Skulls/Totems
        ctx.fillStyle = '#e7e5e4'; 
        ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        // Glow
        ctx.fillStyle = role === Role.MAGE ? '#10b981' : '#a855f7';
        ctx.shadowColor = ctx.fillStyle; ctx.shadowBlur = 10;
        ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
        ctx.shadowBlur = 0;

    } else if (role === Role.RANGER) {
        // Heavy Crossbow
        ctx.rotate(Math.PI/2);
        ctx.fillStyle = '#3f2c22'; ctx.fillRect(-5, -5, 40, 10); // Stock
        ctx.strokeStyle = '#52525b'; ctx.lineWidth = 4;
        ctx.beginPath(); ctx.moveTo(30, -20); ctx.quadraticCurveTo(25, 0, 30, 20); ctx.stroke(); // Bow
        ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(30, -20); ctx.lineTo(0, 0); ctx.lineTo(30, 20); ctx.stroke(); // String
    }
}

import { Role, Team } from "../../types";
import { PALETTE } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;
const WEAPON_SIZE = 128;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2 + 15;
        const rx = 40;
        const ry = 20; 
        const height = 12; 

        // 1. Soft Shadow (Ambient Occlusion)
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.beginPath(); 
        ctx.ellipse(cx, cy + 5, rx + 10, ry + 10, 0, 0, Math.PI * 2); 
        ctx.fill();

        // 2. Base Side (3D Thickness)
        const isBlue = team === Team.BLUE;
        const baseColor = isBlue ? '#1e3a8a' : '#450a0a';
        const rimColor = isBlue ? '#fbbf24' : '#a1a1aa'; // Gold vs Iron

        const gradSide = ctx.createLinearGradient(0, cy - height, 0, cy + ry);
        gradSide.addColorStop(0, baseColor); 
        gradSide.addColorStop(0.5, '#000'); 
        gradSide.addColorStop(1, baseColor);
        ctx.fillStyle = gradSide;

        ctx.beginPath(); 
        ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI, false); 
        ctx.lineTo(cx + rx, cy - height); 
        ctx.ellipse(cx, cy - height, rx, ry, 0, 0, Math.PI, true); 
        ctx.lineTo(cx - rx, cy); 
        ctx.fill();

        // 3. Base Top Surface
        const gradTop = ctx.createRadialGradient(cx, cy - height, 0, cx, cy - height, rx);
        if (isBlue) {
            gradTop.addColorStop(0, '#f8fafc'); // Marble Center
            gradTop.addColorStop(0.8, '#cbd5e1');
            gradTop.addColorStop(1, '#94a3b8');
        } else {
            gradTop.addColorStop(0, '#27272a'); // Dark Stone
            gradTop.addColorStop(0.8, '#18181b');
            gradTop.addColorStop(1, '#000');
        }
        ctx.fillStyle = gradTop; 
        ctx.beginPath(); 
        ctx.ellipse(cx, cy - height, rx, ry, 0, 0, Math.PI * 2); 
        ctx.fill();

        // 4. Rim / Ring
        ctx.lineWidth = 3; 
        ctx.strokeStyle = rimColor;
        ctx.beginPath(); 
        ctx.ellipse(cx, cy - height, rx - 2, ry - 2, 0, 0, Math.PI * 2); 
        ctx.stroke();

        // 5. Team Emblem / Glow
        ctx.fillStyle = isBlue ? 'rgba(37, 99, 235, 0.3)' : 'rgba(220, 38, 38, 0.3)';
        ctx.beginPath();
        ctx.ellipse(cx, cy - height, rx * 0.6, ry * 0.6, 0, 0, Math.PI * 2);
        ctx.fill();

        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;
        const isBlue = team === Team.BLUE;
        const color = isBlue ? '#3b82f6' : '#ef4444';

        // Background Circle
        ctx.fillStyle = '#1e293b';
        ctx.beginPath(); ctx.arc(cx, cy, 28, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.stroke();

        // Icon Art
        ctx.fillStyle = '#fff';
        ctx.font = '24px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        let char = '?';
        switch (role) {
            case Role.TANK: char = '🛡️'; break;
            case Role.WARRIOR: char = '⚔️'; break;
            case Role.RANGER: char = '🏹'; break;
            case Role.MAGE: char = '🔮'; break;
            case Role.SUPPORT: char = '⚕️'; break;
        }
        ctx.fillText(char, cx, cy + 2);

        return canvas;
    },

    generateWeapon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(WEAPON_SIZE, WEAPON_SIZE);
        const isBlue = team === Team.BLUE;

        ctx.translate(WEAPON_SIZE / 2, WEAPON_SIZE / 2);
        ctx.scale(1.5, 1.5);
        ctx.rotate(Math.PI/4); // 45 deg base rotation

        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.shadowBlur = 4;

        if (isBlue) {
            // --- ALLIANCE WEAPONS (Clean, Gold/Silver) ---
            if (role === Role.WARRIOR) {
                // Greatsword
                ctx.fillStyle = '#cbd5e1'; // Blade
                ctx.beginPath(); ctx.moveTo(0, -40); ctx.lineTo(6, 0); ctx.lineTo(0, 40); ctx.lineTo(-6, 0); ctx.fill();
                ctx.fillStyle = '#fbbf24'; // Crossguard
                ctx.fillRect(-10, 0, 20, 4);
                ctx.fillStyle = '#475569'; // Grip
                ctx.fillRect(-2, 4, 4, 15);
            } else if (role === Role.TANK) {
                // Hammer
                ctx.fillStyle = '#475569'; ctx.fillRect(-3, -10, 6, 50); // Handle
                ctx.fillStyle = '#cbd5e1'; ctx.fillRect(-12, -25, 24, 20); // Head
                ctx.strokeStyle = '#fbbf24'; ctx.lineWidth=2; ctx.strokeRect(-12, -25, 24, 20);
            } else if (role === Role.MAGE) {
                // Crystal Staff
                ctx.fillStyle = '#b45309'; ctx.fillRect(-2, -30, 4, 70);
                ctx.fillStyle = '#60a5fa'; ctx.beginPath(); ctx.moveTo(0, -45); ctx.lineTo(8, -30); ctx.lineTo(0, -15); ctx.lineTo(-8, -30); ctx.fill();
            }
        } else {
            // --- HORDE WEAPONS (Rough, Iron/Red) ---
            if (role === Role.WARRIOR) {
                // Battle Axe
                ctx.fillStyle = '#3f2c22'; ctx.fillRect(-3, -10, 6, 60); // Handle
                ctx.translate(0, 30);
                ctx.fillStyle = '#52525b'; // Iron
                ctx.beginPath(); 
                ctx.moveTo(0, 0); ctx.quadraticCurveTo(25, -20, 20, 20); ctx.lineTo(0, 10);
                ctx.moveTo(0, 0); ctx.quadraticCurveTo(-25, -20, -20, 20); ctx.lineTo(0, 10);
                ctx.fill();
            } else if (role === Role.TANK) {
                // Cleaver
                ctx.fillStyle = '#3f2c22'; ctx.fillRect(-3, -10, 6, 50);
                ctx.fillStyle = '#27272a';
                ctx.beginPath(); ctx.moveTo(-3, 0); ctx.lineTo(15, -30); ctx.lineTo(15, 30); ctx.lineTo(-3, 20); ctx.fill();
            } else if (role === Role.MAGE) {
                // Skull Staff
                ctx.fillStyle = '#1c1917'; ctx.fillRect(-3, -30, 6, 70);
                ctx.fillStyle = '#e7e5e4'; ctx.beginPath(); ctx.arc(0, -35, 10, 0, Math.PI*2); ctx.fill();
                ctx.fillStyle = '#10b981'; ctx.beginPath(); ctx.arc(-3, -35, 3, 0, Math.PI*2); ctx.arc(3, -35, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        // Generic fallback for others is fine or handled by specific renderers
        return canvas;
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 4;

        // Wool
        ctx.fillStyle = '#f3f4f6';
        for(let i=0; i<6; i++) {
            const a = i * Math.PI / 3;
            ctx.beginPath(); ctx.arc(cx + Math.cos(a)*10, cy - 10 + Math.sin(a)*8, 10, 0, Math.PI*2); ctx.fill();
        }

        // Head
        ctx.fillStyle = '#1f2937';
        ctx.beginPath(); ctx.ellipse(cx - 15, cy - 10, 8, 5, 0, 0, Math.PI*2); ctx.fill();

        // Legs
        ctx.fillRect(cx - 5, cy, 3, 8);
        ctx.fillRect(cx + 5, cy, 3, 8);

        return canvas;
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // Animation: Gentle Float (Ethereal)
        const breathe = (agent.hp > 0) ? Math.sin(t * 2.5) * 3 : 0;
        const scalePulse = (agent.hp > 0) ? 1 + Math.sin(t * 3) * 0.02 : 1;

        let thrustX = 0;
        let rot = 0;

        // Attack Animation
        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.3) { 
                thrustX = -5 * (progress / 0.3); // Windup
                rot = -0.2;
            } else if (progress < 0.5) { 
                thrustX = 15; // Strike
                rot = 0.1;
            } else { 
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);
        ctx.rotate(rot);
        ctx.scale(scalePulse, scalePulse);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.ellipse(0, -30, 15, 30, 0, 0, Math.PI*2); ctx.stroke();
            ctx.restore();
            return;
        }

        // --- VISUAL STYLE: "HOLOGRAPHIC ORDER" ---
        // Clean gradients, Blue/Cyan/White, Transparent

        const mainColor = '#3b82f6';
        const lightColor = '#93c5fd';

        // 1. CORE BODY (Capsule)
        const bodyGrad = ctx.createLinearGradient(0, -60, 0, 0);
        bodyGrad.addColorStop(0, 'rgba(255, 255, 255, 0.9)');
        bodyGrad.addColorStop(0.4, 'rgba(59, 130, 246, 0.6)');
        bodyGrad.addColorStop(1, 'rgba(30, 58, 138, 0.1)'); // Fade out at bottom

        ctx.fillStyle = bodyGrad;
        ctx.shadowColor = mainColor;
        ctx.shadowBlur = 15;

        ctx.beginPath();
        // Modern capsule shape
        ctx.moveTo(-12, -50); 
        ctx.lineTo(12, -50);
        ctx.quadraticCurveTo(15, -50, 15, -10);
        ctx.quadraticCurveTo(0, 5, -15, -10);
        ctx.quadraticCurveTo(-15, -50, -12, -50);
        ctx.fill();

        // 2. INNER LIGHT (The Soul)
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.8;
        ctx.shadowBlur = 10;
        ctx.beginPath();
        ctx.ellipse(0, -35, 4, 8, 0, 0, Math.PI*2);
        ctx.fill();

        // 3. ROLE INDICATORS (Floating Geometry)
        ctx.shadowBlur = 0; // Reset blur for crisp lines
        ctx.lineWidth = 2;
        ctx.strokeStyle = '#bfdbfe';
        ctx.globalAlpha = 0.9;

        if (agent.role === Role.TANK) {
            // Floating Shield (Holographic Rect)
            ctx.fillStyle = 'rgba(59, 130, 246, 0.3)';
            ctx.beginPath();
            ctx.moveTo(15, -40);
            ctx.lineTo(25, -40);
            ctx.lineTo(25, -10);
            ctx.lineTo(15, 0);
            ctx.closePath();
            ctx.fill(); ctx.stroke();

            // Heavy Shoulder line
            ctx.beginPath(); ctx.moveTo(-18, -45); ctx.lineTo(18, -45); ctx.stroke();

        } else if (agent.role === Role.WARRIOR) {
            // Floating Blade Essence
            ctx.beginPath();
            ctx.moveTo(18, -50);
            ctx.lineTo(22, -20);
            ctx.lineTo(18, -10);
            ctx.stroke();

            // Halo
            ctx.beginPath(); ctx.ellipse(0, -60, 10, 3, 0, 0, Math.PI*2); ctx.stroke();

        } else if (agent.role === Role.RANGER) {
            // Agile Wings/Fins
            ctx.beginPath();
            ctx.moveTo(-12, -40); ctx.lineTo(-20, -55);
            ctx.moveTo(12, -40); ctx.lineTo(20, -55);
            ctx.stroke();

        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            // Orbiting Orbs
            const orbTime = t * 3;
            const ox = Math.cos(orbTime) * 20;
            const oy = Math.sin(orbTime) * 5; // Flat orbit

            ctx.fillStyle = '#fff';
            ctx.shadowColor = '#fff'; ctx.shadowBlur = 5;
            ctx.beginPath(); ctx.arc(ox, -65 + oy, 2, 0, Math.PI*2); ctx.fill();

            // Staff Line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(15, -60); ctx.lineTo(15, 0); ctx.stroke();
        }

        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 

        // Animation: Unstable Twitch
        const twitch = (agent.hp > 0) ? (Math.random() - 0.5) * 1.5 : 0;
        const breathe = (agent.hp > 0) ? Math.sin(t * 4) * 2 : 0;

        let thrustX = 0;
        let rot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.4) { 
                thrustX = -5; // Tense up
            } else { 
                thrustX = 20 * (1 - (progress - 0.4)/0.6); // Lunge
            }
        }

        ctx.save();
        ctx.translate(thrustX + twitch, breathe);
        ctx.rotate(rot);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(0, -50); ctx.lineTo(-15, -20); ctx.lineTo(0, 0); ctx.lineTo(15, -20); ctx.closePath(); ctx.stroke();
            ctx.restore();
            return;
        }

        // --- VISUAL STYLE: "CHAOS ENERGY" ---
        // Red/Black/Crimson, Jagged, Emissive

        const coreColor = '#ef4444';
        const darkColor = '#450a0a';

        // 1. DARK MATTER CORE (Inverted teardrop / Diamond)
        const bodyGrad = ctx.createRadialGradient(0, -30, 0, 0, -30, 25);
        bodyGrad.addColorStop(0, coreColor); // Hot center
        bodyGrad.addColorStop(0.3, '#000'); // Dark body
        bodyGrad.addColorStop(1, 'rgba(0,0,0,0)'); // Fade edge

        ctx.fillStyle = bodyGrad;
        ctx.shadowColor = '#dc2626';
        ctx.shadowBlur = 20;

        ctx.beginPath();
        // Jagged Shape
        ctx.moveTo(0, -60);
        ctx.lineTo(15, -35);
        ctx.lineTo(8, 0);
        ctx.lineTo(-8, 0);
        ctx.lineTo(-15, -35);
        ctx.closePath();
        ctx.fill();

        // 2. GLOWING EYES (Menacing)
        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 5;
        if (agent.role === Role.MAGE) {
            // Single Eye
            ctx.beginPath(); ctx.arc(0, -45, 2, 0, Math.PI*2); ctx.fill();
        } else {
            // Dual Eyes
            ctx.beginPath(); ctx.arc(-5, -45, 1.5, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5, -45, 1.5, 0, Math.PI*2); ctx.fill();
        }

        // 3. ROLE GEOMETRY (Sharp/Spiked)
        ctx.shadowBlur = 0;
        ctx.strokeStyle = '#fca5a5';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.9;

        if (agent.role === Role.TANK) {
            // Spiked Shoulders
            ctx.fillStyle = 'rgba(69, 10, 10, 0.8)';
            ctx.beginPath();
            ctx.moveTo(-20, -40); ctx.lineTo(-10, -30); ctx.lineTo(-25, -25);
            ctx.moveTo(20, -40); ctx.lineTo(10, -30); ctx.lineTo(25, -25);
            ctx.fill(); ctx.stroke();

        } else if (agent.role === Role.WARRIOR) {
            // Weapon Spike
            ctx.strokeStyle = coreColor;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(15, -20); ctx.lineTo(25, -50); ctx.stroke();

        } else if (agent.role === Role.RANGER) {
            // Crosshair / Visor
            ctx.beginPath(); ctx.moveTo(-10, -45); ctx.lineTo(10, -45); ctx.stroke();

        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            // Floating Runes
            const angle = t * 2;
            ctx.save();
            ctx.translate(0, -70);
            ctx.rotate(angle);
            ctx.fillStyle = coreColor;
            ctx.fillRect(-2, -10, 4, 4);
            ctx.fillRect(-2, 10, 4, 4);
            ctx.restore();
        }

        ctx.restore();
    }
};

import { Role, Team } from "../../types";
import { PALETTE } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;
const WEAPON_SIZE = 128;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 35; // Tighter radius

        const color = team === Team.BLUE ? '#3b82f6' : '#ef4444';

        // 1. Simple Glowing Ring
        ctx.translate(cx, cy);
        ctx.scale(1, 0.55); // Isometric squash

        // Inner Faint Fill
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, radius);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.8, team === Team.BLUE ? 'rgba(59, 130, 246, 0.1)' : 'rgba(239, 68, 68, 0.1)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

        // The Ring
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.shadowColor = color;
        ctx.shadowBlur = 8;

        ctx.beginPath(); 
        ctx.arc(0, 0, radius, 0, Math.PI*2); 
        ctx.stroke();

        // Decorative Ticks (Sci-fi touch)
        ctx.shadowBlur = 0;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let i=0; i<4; i++) {
            const angle = i * (Math.PI/2);
            const x = Math.cos(angle) * (radius + 5);
            const y = Math.sin(angle) * (radius + 5);
            ctx.moveTo(x, y);
            ctx.lineTo(Math.cos(angle) * (radius - 2), Math.sin(angle) * (radius - 2));
        }
        ctx.stroke();

        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;
        const color = team === Team.BLUE ? '#93c5fd' : '#fca5a5';

        // Minimalist Icon
        ctx.fillStyle = color;
        ctx.font = '32px sans-serif'; // Larger, cleaner font
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        let char = '';
        switch (role) {
            case Role.TANK: char = '🛡️'; break;
            case Role.WARRIOR: char = '⚔️'; break;
            case Role.RANGER: char = '🏹'; break;
            case Role.MAGE: char = '🔮'; break;
            case Role.SUPPORT: char = '⚕️'; break;
        }

        ctx.shadowColor = color;
        ctx.shadowBlur = 5;
        ctx.fillText(char, cx, cy + 2);

        return canvas;
    },

    generateWeapon(role: Role, team: Team): HTMLCanvasElement {
        // Minimalist style uses procedural drawing in Renderer mostly,
        // but this fallback generates a simple icon if needed.
        const { canvas, ctx } = createCanvas(WEAPON_SIZE, WEAPON_SIZE);
        return canvas; // Return empty, relying on renderer's vector drawing for cleaner look
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 10;

        // Just a fluffy cloud
        ctx.beginPath();
        ctx.arc(cx, cy, 15, 0, Math.PI*2);
        ctx.arc(cx-10, cy-5, 10, 0, Math.PI*2);
        ctx.arc(cx+10, cy-5, 10, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // Animation: Controlled Float (Maglev style)
        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 4 : 0;

        // Attack Animation
        let thrustX = 0;
        let rot = 0;
        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            // Elastic snap
            if (progress < 0.3) { 
                thrustX = -5 * (progress / 0.3); 
                rot = -0.1;
            } else if (progress < 0.5) { 
                thrustX = 15; 
                rot = 0.1;
            } else { 
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, floatY);
        ctx.rotate(rot);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.strokeRect(-12, -50, 24, 40);
            ctx.restore();
            return;
        }

        // --- STYLE: "SAPPHIRE GLASS" ---
        // Semi-transparent fills with solid outlines and a solid core.

        const primaryColor = '#3b82f6'; // Blue-500
        const lightColor = '#bfdbfe';   // Blue-200
        const strokeColor = '#ffffff';

        // 1. WEAPON (Back Layer)
        if (agent.role === Role.WARRIOR || agent.role === Role.MAGE) {
            ctx.save();
            ctx.translate(18, -25);
            ctx.rotate(Math.PI / 12);
            drawImperialWeapon(ctx, agent.role, primaryColor);
            ctx.restore();
        }

        // 2. BODY (Glass Armor)
        const bodyGrad = ctx.createLinearGradient(-10, -50, 10, 0);
        bodyGrad.addColorStop(0, 'rgba(59, 130, 246, 0.8)'); // Top: Opaque Blue
        bodyGrad.addColorStop(0.5, 'rgba(96, 165, 250, 0.5)'); // Mid: Semi-transparent
        bodyGrad.addColorStop(1, 'rgba(30, 58, 138, 0.8)'); // Bottom: Darker anchor

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = strokeColor;
        ctx.lineWidth = 2;

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Hexagon Body (Heavy)
            ctx.moveTo(-20, -45); ctx.lineTo(20, -45);
            ctx.lineTo(24, -15); ctx.lineTo(15, 5);
            ctx.lineTo(-15, 5); ctx.lineTo(-24, -15);
        } else if (agent.role === Role.RANGER) {
            // Slim Triangle
            ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
            ctx.lineTo(8, 0); ctx.lineTo(-8, 0);
        } else {
            // Standard Rounded Rect
            ctx.roundRect(-16, -45, 32, 45, 8);
        }
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // 3. INNER CORE (The "Soul")
        // A solid glowing shape inside giving it depth
        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#60a5fa';
        ctx.shadowBlur = 15;
        ctx.beginPath();
        if (agent.role === Role.TANK) ctx.rect(-8, -35, 16, 16);
        else ctx.arc(0, -25, 6, 0, Math.PI*2);
        ctx.fill();
        ctx.shadowBlur = 0; // Reset blur

        // 4. GLASS HIGHLIGHT (Reflective sheen)
        ctx.fillStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath();
        ctx.ellipse(-5, -35, 4, 10, -0.2, 0, Math.PI*2);
        ctx.fill();

        // 5. HEAD
        ctx.translate(0, -48);

        ctx.fillStyle = '#f8fafc'; // White ceramic
        ctx.strokeStyle = primaryColor;
        ctx.lineWidth = 1;

        ctx.beginPath();
        if (agent.role === Role.MAGE) {
            // Hood shape
            ctx.moveTo(0, -12); ctx.lineTo(10, 5); ctx.lineTo(-10, 5);
        } else if (agent.role === Role.TANK) {
            // Full Helm
            ctx.rect(-10, -12, 20, 16);
        } else {
            // Standard Helm
            ctx.ellipse(0, -2, 9, 10, 0, 0, Math.PI*2);
        }
        ctx.fill();
        ctx.stroke();

        // Visor / Eyes
        ctx.fillStyle = primaryColor;
        ctx.beginPath();
        ctx.rect(-6, -2, 12, 3);
        ctx.fill();

        // 6. OFF-HAND (Shield/Bow)
        ctx.translate(0, 48); // Reset
        if (agent.role === Role.TANK) {
            ctx.translate(-18, -15);
            // Tower Shield
            ctx.fillStyle = 'rgba(30, 58, 138, 0.9)';
            ctx.strokeStyle = '#fbbf24'; // Gold trim
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(-10, -20); ctx.lineTo(10, -20);
            ctx.lineTo(10, 10); ctx.lineTo(0, 25); ctx.lineTo(-10, 10);
            ctx.closePath();
            ctx.fill(); ctx.stroke();
        } else if (agent.role === Role.RANGER) {
            ctx.translate(15, -20);
            // Energy Bow
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.arc(0, 0, 20, -Math.PI/2, Math.PI/2); ctx.stroke();
            ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(0, 20); ctx.stroke();
        }

        ctx.restore();
    }
};

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, color: string) {
    ctx.fillStyle = color;
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;

    if (role === Role.WARRIOR) {
        // Broadsword
        ctx.beginPath();
        ctx.moveTo(-4, 0); ctx.lineTo(4, 0);
        ctx.lineTo(6, -40); ctx.lineTo(0, -50); ctx.lineTo(-6, -40);
        ctx.closePath();
        ctx.fill(); ctx.stroke();
    } else if (role === Role.MAGE) {
        // Staff
        ctx.fillStyle = '#fff';
        ctx.fillRect(-2, -40, 4, 50);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, -45, 8, 0, Math.PI*2); ctx.fill(); ctx.stroke();
    }
}

