        const darkColor = '#450a0a';    // Red-950
        const strokeColor = '#fca5a5';  // Red-300

        // 1. WEAPON (Back)
        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            ctx.save();
            ctx.translate(15, -20);
            ctx.rotate(Math.PI / 4);
            drawCovenantWeapon(ctx, agent.role, primaryColor);
            ctx.restore();
        }

        // 2. BODY (Crystal Armor)
        const bodyGrad = ctx.createLinearGradient(0, -50, 0, 0);
        bodyGrad.addColorStop(0, 'rgba(127, 29, 29, 0.9)'); // Dark Red
        bodyGrad.addColorStop(0.5, 'rgba(239, 68, 68, 0.6)'); // Bright Red transparent
        bodyGrad.addColorStop(1, 'rgba(69, 10, 10, 0.9)'); // Blackish Red

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = strokeColor;
        ctx.lineWidth = 2;

        ctx.beginPath();
        // Angular "Coffin" or Diamond shape
        ctx.moveTo(0, -55);
        ctx.lineTo(18, -35);
        ctx.lineTo(12, 0);
        ctx.lineTo(-12, 0);
        ctx.lineTo(-18, -35);
