        ctx.shadowBlur = 15;
        ctx.beginPath();
        ctx.moveTo(0, -35); ctx.lineTo(5, -25); ctx.lineTo(0, -15); ctx.lineTo(-5, -25);
        ctx.fill();
        ctx.shadowBlur = 0;

        // 4. SPIKES (Shoulders)
        ctx.fillStyle = 'rgba(0,0,0,0.8)';
        ctx.beginPath();
        ctx.moveTo(-18, -35); ctx.lineTo(-28, -45); ctx.lineTo(-15, -30);
        ctx.moveTo(18, -35); ctx.lineTo(28, -45); ctx.lineTo(15, -30);
        ctx.fill();

        // 5. HEAD
        ctx.translate(0, -50);
        ctx.fillStyle = '#18181b'; // Zinc-900 Mask
        ctx.strokeStyle = primaryColor;
        ctx.lineWidth = 1;

        ctx.beginPath();
        if (agent.role === Role.MAGE) {
            // Tall Crown
            ctx.moveTo(-8, 0); ctx.lineTo(-8, -15); ctx.lineTo(0, -5); ctx.lineTo(8, -15); ctx.lineTo(8, 0);
        } else {
            // Pointed Helm
            ctx.moveTo(-9, 0); ctx.lineTo(0, -15); ctx.lineTo(9, 0);
        }
        ctx.fill();
        ctx.stroke();

        // Single Cyclops Eye or Visor
        ctx.fillStyle = '#ef4444';
        ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;
        ctx.beginPath(); ctx.arc(0, -5, 2.5, 0, Math.PI*2); ctx.fill();
        ctx.shadowBlur = 0;

        // 6. OFF-HAND
        ctx.translate(0, 50);
        if (agent.role === Role.RANGER) {
            ctx.translate(15, -20);
            drawCovenantWeapon(ctx, Role.RANGER, primaryColor);
        } else if (agent.role === Role.MAGE) {
            ctx.translate(-15, -25);
            // Floating Orb
            ctx.fillStyle = primaryColor;
            ctx.shadowColor = primaryColor; ctx.shadowBlur = 10;
            ctx.beginPath(); ctx.arc(0, 0 + Math.sin(t*5)*3, 6, 0, Math.PI*2); ctx.fill();
            ctx.shadowBlur = 0;
        }

        ctx.restore();
    }
};

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role, color: string) {
    ctx.fillStyle = '#27272a'; // Iron handle
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;

    if (role === Role.WARRIOR) {
        // Axe
        ctx.fillRect(-2, -10, 4, 60);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(25, -10); ctx.lineTo(25, 20); ctx.lineTo(0, 10);
        ctx.fill(); ctx.stroke();
    } else if (role === Role.TANK) {
        // Cleaver
        ctx.fillRect(-3, -10, 6, 50);
        ctx.fillStyle = color; 
        ctx.globalAlpha = 0.8;
        ctx.fillRect(-10, 0, 20, 35);
        ctx.strokeRect(-10, 0, 20, 35);
    } else if (role === Role.RANGER) {
        // Crossbow
        ctx.rotate(-Math.PI/2);
        ctx.fillStyle = '#52525b';
        ctx.fillRect(-5, -10, 30, 6);
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(20, -20); ctx.quadraticCurveTo(15, 0, 20, 20); ctx.stroke();
    }
}

import { Role, Team } from "../../types";
import { PALETTE } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;
const WEAPON_SIZE = 128;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 38; 

        // Colors
        const isBlue = team === Team.BLUE;
        const mainColor = isBlue ? '#3b82f6' : '#ef4444';
        const glowColor = isBlue ? 'rgba(59, 130, 246, 0.4)' : 'rgba(239, 68, 68, 0.4)';

