        ctx.scale(1, 0.58); // Isometric projection

        // 1. Shadow (Lift effect)
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath(); 
        ctx.arc(0, 10, radius - 2, 0, Math.PI*2); 
        ctx.fill();

        // 2. Glass Disc Body
        const grad = ctx.createRadialGradient(0, 0, radius * 0.5, 0, 0, radius);
        grad.addColorStop(0, glowColor);
        grad.addColorStop(0.8, 'rgba(30, 41, 59, 0.6)'); // Dark slate rim
        grad.addColorStop(1, mainColor);

        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

        // 3. Glowing Rim
        ctx.strokeStyle = mainColor;
        ctx.lineWidth = 3;
        ctx.shadowColor = mainColor;
        ctx.shadowBlur = 10;
        ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.stroke();
        ctx.shadowBlur = 0;

        // 4. Inner Tech Ring
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, radius * 0.7, 0, Math.PI*2); ctx.stroke();

        // 5. Directional Arrow (Facing Right Default)
        // We render it facing right, the engine rotates the sprite context or we handle facing in renderer.
        // Actually Base is usually rotation-neutral. Let's just keep it radial.

        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;
        const color = team === Team.BLUE ? '#93c5fd' : '#fca5a5';

        // Crisp Icon
        ctx.fillStyle = color;
        ctx.font = '32px sans-serif'; 
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        let char = '';
        switch (role) {
            case Role.TANK: char = '🛡️'; break;
            case Role.WARRIOR: char = '⚔️'; break;
            case Role.RANGER: char = '🏹'; break;
            case Role.MAGE: char = '🔮'; break;
            case Role.SUPPORT: char = '⚕️'; break;
        }

        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.shadowBlur = 2;
        ctx.fillText(char, cx, cy + 2);

        return canvas;
    },

    generateWeapon(role: Role, team: Team): HTMLCanvasElement {
        // Procedurally handled in renderers now for sharper scaling
        const { canvas } = createCanvas(WEAPON_SIZE, WEAPON_SIZE);
        return canvas; 
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 10;

        // Just a fluffy cloud
        ctx.beginPath();
        ctx.arc(cx, cy, 15, 0, Math.PI*2);
        ctx.arc(cx-10, cy-5, 10, 0, Math.PI*2);
        ctx.arc(cx+10, cy-5, 10, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // Animation: Smooth, harmonic float
        const floatY = (agent.hp > 0) ? Math.sin(t * 1.5) * 3 : 0;

        let thrustX = 0;
        let rot = 0;
        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.3) { 
                thrustX = -5 * (progress / 0.3); 
                rot = -0.1;
            } else if (progress < 0.5) { 
                thrustX = 15; 
                rot = 0.1;
            } else { 
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, floatY);
        ctx.rotate(rot);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.roundRect(-15, -50, 30, 45, 10); ctx.stroke();
            ctx.restore();
            return;
        }

        // --- STYLE: "DIVINE ORDER" ---
        // Smooth, Gold, Blue, White.

        const primaryColor = '#2563eb'; // Royal Blue
        const accentColor = '#facc15';  // Gold
        const glassColor = 'rgba(239, 246, 255, 0.8)'; // White glass

        // 1. ENERGY CAPE (Back)
        // Two streams of light flowing down
        ctx.save();
        ctx.translate(0, -40);
        const capeW = Math.sin(t * 3) * 2;
        const gradCape = ctx.createLinearGradient(0, 0, 0, 40);
        gradCape.addColorStop(0, 'rgba(37, 99, 235, 0.8)');
        gradCape.addColorStop(1, 'rgba(37, 99, 235, 0.0)');
        ctx.fillStyle = gradCape;

        ctx.beginPath();
        ctx.moveTo(-10, 0); 
        ctx.quadraticCurveTo(-15 - capeW, 20, -20 - capeW, 40); // Left wing
        ctx.lineTo(-5, 40); ctx.lineTo(0, 10); // Center tuck
        ctx.lineTo(5, 40); ctx.lineTo(20 + capeW, 40); // Right wing
        ctx.quadraticCurveTo(15 + capeW, 20, 10, 0);
        ctx.fill();
        ctx.restore();

        // 2. WEAPON (Floating behind shoulder)
        if (agent.role !== Role.RANGER) {
            ctx.save();
            ctx.translate(18, -30 + Math.sin(t*2 + 1)*2); // Independent float
            drawImperialWeapon(ctx, agent.role);
            ctx.restore();
        }

        // 3. BODY (Smooth Armor)
        // Gradient simulating polished curve
        const bodyGrad = ctx.createLinearGradient(-15, -50, 15, 0);
        bodyGrad.addColorStop(0, '#eff6ff'); // Highlight Top Left
        bodyGrad.addColorStop(0.5, primaryColor);
        bodyGrad.addColorStop(1, '#1e3a8a'); // Shadow Bottom Right

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = accentColor; // Gold Trim
        ctx.lineWidth = 1.5;

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Heavy Shield Shape
            ctx.moveTo(-20, -45); ctx.lineTo(20, -45); // Shoulders
            ctx.quadraticCurveTo(22, -20, 15, 5);      // Sides
            ctx.lineTo(0, 15);                         // Point
            ctx.lineTo(-15, 5);
            ctx.quadraticCurveTo(-22, -20, -20, -45);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            // Robe/Pillar Shape
            ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
            ctx.lineTo(16, 10); ctx.lineTo(-16, 10);
        } else {
            // Standard Breastplate
            ctx.roundRect(-16, -45, 32, 45, 8);
        }
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // 4. CHEST EMBLEM (The Core)
        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#60a5fa';
        ctx.shadowBlur = 10;
        ctx.beginPath();
        ctx.moveTo(0, -35); ctx.lineTo(6, -25); ctx.lineTo(0, -15); ctx.lineTo(-6, -25);
        ctx.fill();
        ctx.shadowBlur = 0;

        // 5. HEAD (Helmet)
        ctx.translate(0, -52);

        // Halo (Floating Ring)
        if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.strokeStyle = accentColor;
            ctx.lineWidth = 1;
            ctx.beginPath(); 
            ctx.ellipse(0, -10, 15, 4, 0, 0, Math.PI*2);
            ctx.stroke();
        }

        ctx.fillStyle = '#f1f5f9'; // Silver
        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Great Helm
            ctx.rect(-10, -10, 20, 18);
        } else {
            // Sleek Helm
            ctx.ellipse(0, 0, 9, 11, 0, 0, Math.PI*2);
        }
        ctx.fill();

        // Visor (Clean line)
        ctx.fillStyle = primaryColor;
        ctx.fillRect(-8, -2, 16, 3);

        // 6. RANGER WEAPON (Front)
        if (agent.role === Role.RANGER) {
            ctx.translate(0, 52); // Reset
            ctx.translate(12, -25);
            drawImperialWeapon(ctx, Role.RANGER);
        }

        ctx.restore();
    }
};

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role) {
    ctx.fillStyle = '#bfdbfe'; // Energy Blue
    ctx.strokeStyle = '#facc15'; // Gold
    ctx.lineWidth = 1;

    if (role === Role.WARRIOR) {
        // Energy Claymore
        ctx.rotate(Math.PI/6);
        ctx.fillRect(-2, 0, 4, 15); // Hilt
        ctx.fillStyle = '#60a5fa';
        ctx.beginPath(); ctx.moveTo(-4, 0); ctx.lineTo(4, 0); ctx.lineTo(0, -50); ctx.fill(); // Blade
        ctx.stroke();
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // Floating Staff Head
        ctx.rotate(-Math.PI/6);
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, -35, 8, 0, Math.PI*2); ctx.stroke();
        ctx.fillStyle = role === Role.MAGE ? '#3b82f6' : '#a855f7';
        ctx.beginPath(); ctx.arc(0, -35, 4, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = '#b45309';
        ctx.fillRect(-2, -27, 4, 40); // Shaft
    } else if (role === Role.RANGER) {
        // Energy Bow
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, 20, -Math.PI/2, Math.PI/2); ctx.stroke();
        ctx.fillStyle = '#60a5fa';
        ctx.fillRect(-2, -20, 4, 40); // Grip/String
    } else if (role === Role.TANK) {
        // Hammer
        ctx.rotate(-Math.PI/6);
        ctx.fillStyle = '#e2e8f0';
        ctx.fillRect(-10, -30, 20, 15); // Head
        ctx.strokeStyle = '#facc15'; ctx.strokeRect(-10, -30, 20, 15);
        ctx.fillStyle = '#475569';
        ctx.fillRect(-3, -15, 6, 40); // Handle
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 

        // Animation: Aggressive, jerky float (unstable energy)
        const floatY = (agent.hp > 0) ? Math.sin(t * 3) * 2 + (Math.sin(t*10)*0.5) : 0;

        let thrustX = 0;
        let rot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.4) { 
                thrustX = -5; // Tense up
                rot = -0.2;   // Lean back
            } else { 
                thrustX = 20 * (1 - (progress - 0.4)/0.6); // Heavy lunge
                rot = 0.2;
            }
        }

        ctx.save();
        ctx.translate(thrustX, floatY);
        ctx.rotate(rot);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.beginPath(); 
            ctx.moveTo(0, -50); ctx.lineTo(-20, -30); ctx.lineTo(0, 0); ctx.lineTo(20, -30); 
            ctx.closePath(); ctx.stroke();
            ctx.restore();
            return;
        }

        // --- STYLE: "CHAOTIC OBSIDIAN" ---
        // Black, Red, Jagged, Asymmetric.

        const primaryColor = '#b91c1c'; // Dark Red
        const darkMetal = '#18181b';    // Obsidian/Iron
        const glowColor = '#ef4444';    // Bright Red

        // 1. SPIKES (Back Layer)
        ctx.save();
        ctx.fillStyle = darkMetal;
        ctx.beginPath();
        // Asymmetric spikes
        ctx.moveTo(-10, -30); ctx.lineTo(-25, -60); ctx.lineTo(-15, -20);
        ctx.moveTo(10, -30); ctx.lineTo(20, -50); ctx.lineTo(15, -20);
        ctx.fill();
        ctx.restore();

        // 2. WEAPON (Back - Held Low)
        if (agent.role !== Role.RANGER) {
            ctx.save();
            ctx.translate(20, -10); 
            ctx.rotate(Math.PI/4 + Math.sin(t)*0.1);
            drawCovenantWeapon(ctx, agent.role);
            ctx.restore();
        }

        // 3. BODY (Jagged Armor)
        // Dark metallic gradient
        const bodyGrad = ctx.createLinearGradient(-15, -50, 15, 10);
        bodyGrad.addColorStop(0, '#450a0a'); // Blood red top
        bodyGrad.addColorStop(0.4, '#09090b'); // Black mid
        bodyGrad.addColorStop(1, '#000000'); 

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = '#7f1d1d'; // Rust trim
        ctx.lineWidth = 1;

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Bulky, Hunched
            ctx.moveTo(-22, -40); ctx.lineTo(22, -35); // Wide shoulders
            ctx.lineTo(15, 10); ctx.lineTo(-15, 10);
            ctx.lineTo(-25, -20); // Spiked elbow
        } else {
            // Sharp Coffin Shape
            ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
            ctx.lineTo(10, 10); ctx.lineTo(0, 20); ctx.lineTo(-10, 10);
        }
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // 4. MAGMA FISSURE (The Soul)
        // An unstable crack in the armor
        ctx.strokeStyle = glowColor;
        ctx.lineWidth = 2;
        ctx.shadowColor = glowColor;
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.moveTo(-5, -35); 
        ctx.lineTo(2, -25); 
        ctx.lineTo(-3, -15);
        ctx.stroke();
        ctx.shadowBlur = 0;

        // 5. HEAD
        ctx.translate(0, -45);
        ctx.fillStyle = darkMetal;

        ctx.beginPath();
        if (agent.role === Role.MAGE) {
            // Skull-like Mask
            ctx.ellipse(0, 0, 10, 13, 0, 0, Math.PI*2);
        } else {
            // Horned Helm
            ctx.moveTo(-10, 5); ctx.lineTo(-12, -15); ctx.lineTo(-5, -5); // L Horn
            ctx.moveTo(10, 5); ctx.lineTo(12, -15); ctx.lineTo(5, -5);   // R Horn
            ctx.ellipse(0, 3, 11, 10, 0, 0, Math.PI*2);
        }
        ctx.fill();

        // Glowing Eye (Single or Slit)
        ctx.fillStyle = '#f87171'; // Light Red
        ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;
        if (agent.role === Role.WARRIOR) {
            ctx.beginPath(); ctx.rect(-8, 0, 16, 2); ctx.fill(); // Visor slit
        } else {
            ctx.beginPath(); ctx.arc(0, 2, 3, 0, Math.PI*2); ctx.fill(); // Cyclops eye
        }
        ctx.shadowBlur = 0;

        // 6. RANGER WEAPON
        if (agent.role === Role.RANGER) {
            ctx.translate(0, 45);
            ctx.translate(15, -15);
            drawCovenantWeapon(ctx, Role.RANGER);
        }

        ctx.restore();
    }
};

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role) {
    ctx.fillStyle = '#27272a'; // Iron
    ctx.strokeStyle = '#7f1d1d'; // Blood edge
    ctx.lineWidth = 1;

    if (role === Role.WARRIOR) {
        // Jagged Axe
        ctx.fillRect(-2, -10, 4, 50); // Haft
        ctx.fillStyle = '#52525b';
        ctx.beginPath();
        ctx.moveTo(0, 0); 
        ctx.lineTo(25, -15); // Top spike
        ctx.lineTo(20, 20);  // Bottom blade
        ctx.lineTo(0, 10);
        ctx.fill(); ctx.stroke();
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // Ritual Totem
        ctx.fillStyle = '#451a03';
        ctx.fillRect(-3, -30, 6, 50);
        ctx.fillStyle = '#ef4444'; // Red Orb
        ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;
        ctx.beginPath(); ctx.arc(0, -35, 6, 0, Math.PI*2); ctx.fill();
        ctx.shadowBlur = 0;
        // Spikes on staff
        ctx.strokeStyle = '#000'; ctx.beginPath(); ctx.moveTo(-3, -20); ctx.lineTo(-10, -25); ctx.stroke();
    } else if (role === Role.RANGER) {
        // Heavy Crossbow
        ctx.rotate(-Math.PI/2);
        ctx.fillStyle = '#3f3f46';
        ctx.fillRect(-5, -5, 30, 10);
        ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(25, -20); ctx.lineTo(15, 0); ctx.lineTo(25, 20); ctx.stroke();
    } else if (role === Role.TANK) {
        // Meat Cleaver
        ctx.fillStyle = '#52525b';
        ctx.beginPath(); ctx.rect(-10, -10, 20, 40); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.strokeRect(-10, -10, 20, 40);
        // Blood stain
        ctx.fillStyle = '#991b1b'; ctx.beginPath(); ctx.arc(0, 20, 8, 0, Math.PI*2); ctx.fill();
    }
}

import { Role, Team } from "../../types";
