import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;
const WEAPON_SIZE = 128;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 38; 
        const isBlue = team === Team.BLUE;

        ctx.translate(cx, cy);
        ctx.scale(1, 0.58); // Isometric projection

        // 1. Shadow (Common)
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath(); 
        ctx.arc(0, 10, radius - 2, 0, Math.PI*2); 
        ctx.fill();

        // 2. Base Fill
        const grad = ctx.createRadialGradient(0, 0, radius * 0.2, 0, 0, radius);
        if (isBlue) {
            // Blue: Clean, glowing center
            grad.addColorStop(0, 'rgba(59, 130, 246, 0.6)');
            grad.addColorStop(0.8, 'rgba(30, 58, 138, 0.8)');
            grad.addColorStop(1, 'rgba(37, 99, 235, 1.0)');
        } else {
            // Red: Dark, burning core
            grad.addColorStop(0, 'rgba(220, 38, 38, 0.8)'); 
            grad.addColorStop(0.6, 'rgba(69, 10, 10, 0.9)');
            grad.addColorStop(1, '#000');
        }
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

        // 3. Cultural Rim
        if (isBlue) {
            // IMPERIAL: Perfect Gold Ring
            ctx.strokeStyle = '#fbbf24'; // Gold
            ctx.lineWidth = 3;
            ctx.shadowColor = '#fbbf24'; ctx.shadowBlur = 5;
            ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.stroke();

            // Inner Runes
            ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.7, 0, Math.PI*2); ctx.stroke();
        } else {
            // COVENANT: Spiked Iron Ring
            ctx.strokeStyle = '#52525b'; // Iron
            ctx.lineWidth = 4;
            ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;

            ctx.beginPath();
            const spikes = 8;
            for(let i=0; i<=spikes; i++) {
                const a = (i/spikes) * Math.PI * 2;
                const rOuter = radius + (i%2===0 ? 4 : 0); // Jagged edge
                const x = Math.cos(a) * rOuter;
                const y = Math.sin(a) * rOuter;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();

            // Inner Cracks
            ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(5, 5); ctx.lineTo(0, 15); ctx.stroke();
        }

        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;
        const color = team === Team.BLUE ? '#93c5fd' : '#fca5a5';

        // Crisp Icon
        ctx.fillStyle = color;
        ctx.font = '32px sans-serif'; 
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        let char = '';
        switch (role) {
            case Role.TANK: char = '🛡️'; break;
            case Role.WARRIOR: char = '⚔️'; break;
            case Role.RANGER: char = '🏹'; break;
            case Role.MAGE: char = '🔮'; break;
            case Role.SUPPORT: char = '⚕️'; break;
        }

        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.shadowBlur = 2;
        ctx.fillText(char, cx, cy + 2);

        return canvas;
    },

    generateWeapon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas } = createCanvas(WEAPON_SIZE, WEAPON_SIZE);
        return canvas; 
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 10;

        // Just a fluffy cloud
        ctx.beginPath();
        ctx.arc(cx, cy, 15, 0, Math.PI*2);
        ctx.arc(cx-10, cy-5, 10, 0, Math.PI*2);
        ctx.arc(cx+10, cy-5, 10, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { Role, Team } from "../../types";
import { PALETTE } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;
const WEAPON_SIZE = 128;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 36; 
        const isBlue = team === Team.BLUE;

        ctx.translate(cx, cy);
        ctx.scale(1, 0.58); // Isometric projection

        // 1. Drop Shadow (Heavy grounding)
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.beginPath(); 
        ctx.arc(0, 8, radius + 2, 0, Math.PI*2); 
        ctx.fill();

        // 2. Physical Material Body
        if (isBlue) {
            // IMPERIAL: White Marble & Gold
            const grad = ctx.createLinearGradient(-radius, -radius, radius, radius);
            grad.addColorStop(0, '#f8fafc'); // White marble
            grad.addColorStop(1, '#94a3b8'); // Grey shading
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

            // Gold Rim (Solid metal)
            ctx.strokeStyle = '#d97706'; // Dark Gold border
            ctx.lineWidth = 6;
            ctx.stroke();
            ctx.strokeStyle = '#fbbf24'; // Bright Gold highlight
            ctx.lineWidth = 3;
            ctx.stroke();

            // Inner Tech Circuit (The Projector)
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.6, 0, Math.PI*2);
            ctx.fillStyle = '#1e3a8a'; // Dark Blue recessed area
            ctx.fill();
            ctx.strokeStyle = '#60a5fa'; // Glowing blue line
            ctx.lineWidth = 2;
            ctx.stroke();

        } else {
            // COVENANT: Dark Iron & Magma
            const grad = ctx.createLinearGradient(-radius, -radius, radius, radius);
            grad.addColorStop(0, '#27272a'); // Iron
            grad.addColorStop(1, '#000000'); 
            ctx.fillStyle = grad;

            // Jagged Shape base
            ctx.beginPath();
            const sides = 8;
            for(let i=0; i<=sides; i++) {
                const a = (i/sides) * Math.PI*2;
                const r = radius * (i%2===0 ? 1.0 : 0.9); // Gear/Spike shape
                const x = Math.cos(a)*r;
                const y = Math.sin(a)*r;
                if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.fill();

            // Iron Rim
            ctx.strokeStyle = '#52525b';
            ctx.lineWidth = 4;
            ctx.stroke();

            // Inner Magma Core (The Projector)
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.5, 0, Math.PI*2);
            ctx.fillStyle = '#450a0a'; // Dark Red
            ctx.fill();
            ctx.strokeStyle = '#ef4444'; // Glowing Red
            ctx.lineWidth = 2;
            ctx.stroke();
        }

        // 3. Projector Lens Flare (Center)
        // This suggests the unit is being projected FROM here
        ctx.fillStyle = isBlue ? '#fff' : '#fecaca';
        ctx.globalAlpha = 0.8;
        ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();

        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;

        // Emissive holographic text color
        const color = team === Team.BLUE ? '#e0f2fe' : '#fecaca';

        ctx.fillStyle = color;
        ctx.font = '900 28px sans-serif'; 
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        let char = '';
        switch (role) {
            case Role.TANK: char = '🛡️'; break;
            case Role.WARRIOR: char = '⚔️'; break;
            case Role.RANGER: char = '🏹'; break;
            case Role.MAGE: char = '🔮'; break;
            case Role.SUPPORT: char = '⚕️'; break;
        }

        // Heavy Glow to look like a projection
        ctx.shadowColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';
        ctx.shadowBlur = 15;
        ctx.fillText(char, cx, cy);

        return canvas;
    },

    generateWeapon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas } = createCanvas(WEAPON_SIZE, WEAPON_SIZE);
        return canvas; 
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 10;

        ctx.beginPath();
        ctx.arc(cx, cy, 15, 0, Math.PI*2);
        ctx.arc(cx-10, cy-5, 10, 0, Math.PI*2);
        ctx.arc(cx+10, cy-5, 10, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // Attack Animation
        let thrustX = 0;
        let rot = 0;
        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.3) { 
                thrustX = -5 * (progress / 0.3); 
                rot = -0.1;
            } else if (progress < 0.5) { 
                thrustX = 15; 
                rot = 0.1;
            } else { 
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, 0); // Note: We handle Y-float in UnitVisuals, not here
        ctx.rotate(rot);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.roundRect(-15, -50, 30, 45, 10); ctx.stroke();
            ctx.restore();
            return;
        }

        // --- VISUAL: IMPERIAL HOLOGRAM ---
        // Clean, Blue, Gold, Crystalline.

        const primaryColor = '#2563eb'; // Royal Blue
        const accentColor = '#facc15';  // Gold

        // 1. FLOATING ORBITALS (The "Alive" Detail)
        // Rings orbiting the unit body
        ctx.save();
        const floatH = Math.sin(t * 2) * 2;
        ctx.translate(0, floatH);

        ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        // Tilted Orbit
        ctx.ellipse(0, -25, 25, 8, Math.PI / 8 * Math.sin(t), 0, Math.PI * 2);
        ctx.stroke();

        // Orbiting Particle
        const orbitTime = t * 2;
        const ox = Math.cos(orbitTime) * 25;
        const oy = Math.sin(orbitTime) * 8;
        // Rotate orbit point
        const rotX = ox * Math.cos(Math.PI/8*Math.sin(t)) - oy * Math.sin(Math.PI/8*Math.sin(t));
        const rotY = ox * Math.sin(Math.PI/8*Math.sin(t)) + oy * Math.cos(Math.PI/8*Math.sin(t));

        ctx.fillStyle = accentColor;
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = 5;
        ctx.beginPath(); ctx.arc(rotX, -25 + rotY, 2, 0, Math.PI*2); ctx.fill();
        ctx.shadowBlur = 0;
        ctx.restore();

        // 2. ENERGY CAPE / WINGS
        ctx.save();
        ctx.translate(0, -40);
        const capeW = Math.sin(t * 3) * 2;
        const gradCape = ctx.createLinearGradient(0, 0, 0, 40);
        gradCape.addColorStop(0, 'rgba(37, 99, 235, 0.6)');
        gradCape.addColorStop(1, 'rgba(37, 99, 235, 0.0)');
        ctx.fillStyle = gradCape;

        ctx.beginPath();
        ctx.moveTo(-10, 0); 
        ctx.quadraticCurveTo(-15 - capeW, 20, -20 - capeW, 40); 
        ctx.lineTo(-5, 40); ctx.lineTo(0, 10); 
        ctx.lineTo(5, 40); ctx.lineTo(20 + capeW, 40); 
        ctx.quadraticCurveTo(15 + capeW, 20, 10, 0);
        ctx.fill();
        ctx.restore();

        // 3. WEAPON (Floating behind shoulder)
        if (agent.role !== Role.RANGER) {
            ctx.save();
            ctx.translate(18, -30 + Math.sin(t*2 + 1)*2); 
            drawImperialWeapon(ctx, agent.role);
            ctx.restore();
        }

        // 4. BODY (Crystalline Armor)
        // Semi-transparent fill to simulate projection
        const bodyGrad = ctx.createLinearGradient(-15, -50, 15, 0);
        bodyGrad.addColorStop(0, 'rgba(239, 246, 255, 0.9)'); // White top
        bodyGrad.addColorStop(0.5, 'rgba(37, 99, 235, 0.7)'); // Blue mid
        bodyGrad.addColorStop(1, 'rgba(30, 58, 138, 0.4)'); // Dark bottom fade

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = accentColor; 
        ctx.lineWidth = 1.5;

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Heavy Shield Shape
            ctx.moveTo(-20, -45); ctx.lineTo(20, -45); 
            ctx.quadraticCurveTo(22, -20, 15, 5);      
            ctx.lineTo(0, 15);                         
            ctx.lineTo(-15, 5);
            ctx.quadraticCurveTo(-22, -20, -20, -45);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            // Robe/Pillar Shape
            ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
            ctx.lineTo(16, 10); ctx.lineTo(-16, 10);
        } else {
            // Standard Breastplate
            ctx.roundRect(-16, -45, 32, 45, 8);
        }
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // 5. CORE (The Soul)
        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#60a5fa';
        ctx.shadowBlur = 15;
        ctx.beginPath();
        ctx.moveTo(0, -35); ctx.lineTo(6, -25); ctx.lineTo(0, -15); ctx.lineTo(-6, -25);
        ctx.fill();
        ctx.shadowBlur = 0;

        // 6. HEAD (Helmet)
        ctx.translate(0, -52);

        // Halo Ring above head
        ctx.strokeStyle = accentColor;
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.8;
        ctx.beginPath(); 
        ctx.ellipse(0, -12 + Math.sin(t*3)*2, 12, 4, 0, 0, Math.PI*2);
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        ctx.fillStyle = '#f1f5f9'; // Silver
        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.rect(-10, -10, 20, 18);
        } else {
            ctx.ellipse(0, 0, 9, 11, 0, 0, Math.PI*2);
        }
        ctx.fill();

        // Visor
        ctx.fillStyle = primaryColor;
        ctx.fillRect(-8, -2, 16, 3);

        // 7. RANGER WEAPON (Front)
        if (agent.role === Role.RANGER) {
            ctx.translate(0, 52); 
            ctx.translate(12, -25);
            drawImperialWeapon(ctx, Role.RANGER);
        }

        ctx.restore();
    }
};

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role) {
    ctx.fillStyle = 'rgba(191, 219, 254, 0.8)'; // Semi-transparent energy weapon
    ctx.strokeStyle = '#facc15'; // Gold outline
    ctx.lineWidth = 1;

    if (role === Role.WARRIOR) {
        ctx.rotate(Math.PI/6);
        ctx.fillRect(-2, 0, 4, 15); 
        ctx.fillStyle = '#60a5fa';
        ctx.beginPath(); ctx.moveTo(-4, 0); ctx.lineTo(4, 0); ctx.lineTo(0, -50); ctx.fill(); 
        ctx.stroke();
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.rotate(-Math.PI/6);
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, -35, 8, 0, Math.PI*2); ctx.stroke();
        ctx.fillStyle = role === Role.MAGE ? '#3b82f6' : '#a855f7';
        ctx.beginPath(); ctx.arc(0, -35, 4, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = '#b45309';
        ctx.fillRect(-2, -27, 4, 40); 
    } else if (role === Role.RANGER) {
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, 20, -Math.PI/2, Math.PI/2); ctx.stroke();
        ctx.fillStyle = '#60a5fa';
        ctx.fillRect(-2, -20, 4, 40); 
    } else if (role === Role.TANK) {
        ctx.rotate(-Math.PI/6);
        ctx.fillStyle = '#e2e8f0';
        ctx.fillRect(-10, -30, 20, 15); 
        ctx.strokeStyle = '#facc15'; ctx.strokeRect(-10, -30, 20, 15);
        ctx.fillStyle = '#475569';
        ctx.fillRect(-3, -15, 6, 40); 
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 

        let thrustX = 0;
        let rot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.4) { 
                thrustX = -5; 
                rot = -0.2;   
            } else { 
                thrustX = 20 * (1 - (progress - 0.4)/0.6); 
                rot = 0.2;
            }
        }

        ctx.save();
        ctx.translate(thrustX, 0);
        ctx.rotate(rot);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.beginPath(); 
            ctx.moveTo(0, -50); ctx.lineTo(-20, -30); ctx.lineTo(0, 0); ctx.lineTo(20, -30); 
            ctx.closePath(); ctx.stroke();
            ctx.restore();
            return;
        }

        // --- VISUAL: COVENANT CORRUPTION ---
        // Black, Red, Jagged, Unstable.

        const glowColor = '#ef4444';    // Bright Red

        // 1. FLOATING SHARDS (Debris Field)
        // Suggests the unit is holding itself together by will
        ctx.save();
        const shardCount = 3;
        for(let i=0; i<shardCount; i++) {
            const offset = i * (Math.PI * 2 / shardCount);
            const time = t * 1.5;
            // Elliptical erratic orbit
            const sx = Math.cos(time + offset) * 22;
            const sy = Math.sin(time * 1.2 + offset) * 15 - 30; // Around chest

            ctx.translate(sx, sy);
            ctx.rotate(time * 2);
            ctx.fillStyle = '#18181b'; // Obsidian
            ctx.strokeStyle = glowColor;
            ctx.lineWidth = 1;

            ctx.beginPath();
            ctx.moveTo(0, -4); ctx.lineTo(3, 2); ctx.lineTo(-3, 2);
            ctx.fill(); ctx.stroke();

            ctx.rotate(-time * 2);
            ctx.translate(-sx, -sy);
        }
        ctx.restore();

        // 2. WEAPON (Back - Held Low)
        if (agent.role !== Role.RANGER) {
            ctx.save();
            ctx.translate(20, -10); 
            ctx.rotate(Math.PI/4 + Math.sin(t)*0.1);
            drawCovenantWeapon(ctx, agent.role);
            ctx.restore();
        }

        // 3. BODY (Unstable Form)
        // Dark metallic gradient with alpha for transparency
        const bodyGrad = ctx.createLinearGradient(-15, -50, 15, 10);
        bodyGrad.addColorStop(0, 'rgba(69, 10, 10, 0.9)'); // Blood red top
        bodyGrad.addColorStop(0.4, 'rgba(9, 9, 11, 0.8)'); // Black mid
        bodyGrad.addColorStop(1, 'rgba(0, 0, 0, 0.5)');    // Fade bottom

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = '#7f1d1d'; 
        ctx.lineWidth = 1;

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Bulky, Hunched
            ctx.moveTo(-22, -40); ctx.lineTo(22, -35); // Wide shoulders
            ctx.lineTo(15, 10); ctx.lineTo(-15, 10);
            ctx.lineTo(-25, -20); // Spiked elbow
        } else {
            // Sharp Coffin Shape
            ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
            ctx.lineTo(10, 10); ctx.lineTo(0, 20); ctx.lineTo(-10, 10);
        }
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // 4. MAGMA FISSURE (The Core)
        // An unstable crack in the armor that pulses
        ctx.strokeStyle = glowColor;
        ctx.lineWidth = 2;
        ctx.shadowColor = glowColor;
        const pulse = 5 + Math.random() * 10; // Glitch flicker
        ctx.shadowBlur = pulse;
        ctx.beginPath();
        ctx.moveTo(-5, -35); 
        ctx.lineTo(2, -25); 
        ctx.lineTo(-3, -15);
        ctx.stroke();
        ctx.shadowBlur = 0;

        // 5. HEAD
        ctx.translate(0, -45);
        ctx.fillStyle = '#18181b';

        ctx.beginPath();
        if (agent.role === Role.MAGE) {
            // Skull-like Mask
            ctx.ellipse(0, 0, 10, 13, 0, 0, Math.PI*2);
        } else {
            // Horned Helm
            ctx.moveTo(-10, 5); ctx.lineTo(-12, -15); ctx.lineTo(-5, -5); 
            ctx.moveTo(10, 5); ctx.lineTo(12, -15); ctx.lineTo(5, -5);   
            ctx.ellipse(0, 3, 11, 10, 0, 0, Math.PI*2);
        }
        ctx.fill();

        // Glowing Eye (Single or Slit)
        ctx.fillStyle = '#f87171'; 
        ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;
        if (agent.role === Role.WARRIOR) {
            ctx.beginPath(); ctx.rect(-8, 0, 16, 2); ctx.fill(); 
        } else {
            ctx.beginPath(); ctx.arc(0, 2, 3, 0, Math.PI*2); ctx.fill(); 
        }
        ctx.shadowBlur = 0;

        // 6. RANGER WEAPON
        if (agent.role === Role.RANGER) {
            ctx.translate(0, 45);
            ctx.translate(15, -15);
            drawCovenantWeapon(ctx, Role.RANGER);
        }

        ctx.restore();
    }
};

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role) {
    ctx.fillStyle = '#27272a'; // Iron
    ctx.strokeStyle = '#7f1d1d'; // Blood edge
    ctx.lineWidth = 1;

    if (role === Role.WARRIOR) {
        // Jagged Axe
        ctx.fillRect(-2, -10, 4, 50); 
        ctx.fillStyle = '#52525b';
        ctx.beginPath();
        ctx.moveTo(0, 0); 
        ctx.lineTo(25, -15); // Top spike
        ctx.lineTo(20, 20);  // Bottom blade
        ctx.lineTo(0, 10);
        ctx.fill(); ctx.stroke();
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // Ritual Totem
        ctx.fillStyle = '#451a03';
        ctx.fillRect(-3, -30, 6, 50);
        ctx.fillStyle = '#ef4444'; // Red Orb
        ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;
        ctx.beginPath(); ctx.arc(0, -35, 6, 0, Math.PI*2); ctx.fill();
        ctx.shadowBlur = 0;
        ctx.strokeStyle = '#000'; ctx.beginPath(); ctx.moveTo(-3, -20); ctx.lineTo(-10, -25); ctx.stroke();
    } else if (role === Role.RANGER) {
        // Heavy Crossbow
        ctx.rotate(-Math.PI/2);
        ctx.fillStyle = '#3f3f46';
        ctx.fillRect(-5, -5, 30, 10);
        ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(25, -20); ctx.lineTo(15, 0); ctx.lineTo(25, 20); ctx.stroke();
    } else if (role === Role.TANK) {
        // Meat Cleaver
        ctx.fillStyle = '#52525b';
        ctx.beginPath(); ctx.rect(-10, -10, 20, 40); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.strokeRect(-10, -10, 20, 40);
        ctx.fillStyle = '#991b1b'; ctx.beginPath(); ctx.arc(0, 20, 8, 0, Math.PI*2); ctx.fill();
    }
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171'; // Blue-400 : Red-400

    // We are at Ground Level (0,0).
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. "Divine Light" Lift Column (Gradient Fill)
    const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
    // Transparent at bottom to blend with ground, stronger at top to show lift source
    grad.addColorStop(0, isBlue ? 'rgba(96, 165, 250, 0.0)' : 'rgba(248, 113, 113, 0.0)');
    grad.addColorStop(0.3, isBlue ? 'rgba(96, 165, 250, 0.1)' : 'rgba(248, 113, 113, 0.1)');
    grad.addColorStop(1.0, isBlue ? 'rgba(96, 165, 250, 0.3)' : 'rgba(248, 113, 113, 0.3)');

    // Column Shape (Tapered Cylinder)
    const baseW = 15; 
    const topW = 10;  

    ctx.beginPath();
    ctx.moveTo(-baseW, 0);
    ctx.lineTo(feetX - topW, feetY);
    ctx.lineTo(feetX + topW, feetY);
    ctx.lineTo(baseW, 0);
    ctx.fill();

    // 2. Rising Energy Streams / Rings
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;

    const height = Math.abs(feetY);
    const ringCount = Math.max(2, Math.floor(height / 25));

    for(let i=0; i<ringCount; i++) {
        const phase = (t * 1.5 + i / ringCount) % 1; 
        const curX = feetX * phase;
        const curY = feetY * phase;
        const curW = baseW + (topW - baseW) * phase;
        const alpha = Math.sin(phase * Math.PI); 

        ctx.globalAlpha = alpha * 0.5;
        ctx.beginPath();
        ctx.ellipse(curX, curY, curW, curW * 0.5, 0, 0, Math.PI * 2);
        ctx.stroke();
    }

    // 3. Ground Anchor Ring (The Mechanical Projector lens)
    ctx.globalAlpha = 1.0;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(0, 0, 20, 10, 0, 0, Math.PI * 2);
    ctx.stroke();

    // Crosshair Center
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-5, 0); ctx.lineTo(5, 0);
    ctx.moveTo(0, -3); ctx.lineTo(0, 3);
    ctx.stroke();

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 5); 

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    ctx.arc(0, 0, 15 + Math.sin(t * 15) * 2, 0, Math.PI * 1.5);
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.7;
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    // Undo facing flip so icons don't flip
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -75; // Adjusted head position for icons

    // 1. STUN
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        const icon = AssetManager.getStatusIcon('STUN');
        const angle = t * 5;
        ctx.drawImage(icon, -20 + Math.cos(angle)*10, HEAD_Y + Math.sin(angle)*5, 24, 24);
        ctx.drawImage(icon, -10 + Math.cos(angle + 2)*10, HEAD_Y - 10 + Math.sin(angle + 2)*5, 16, 16);
    }

    // 2. SILENCE
    if (agent.silenceTimer > 0) {
        const icon = AssetManager.getStatusIcon('SILENCE');
        ctx.drawImage(icon, 15, HEAD_Y - 5 + Math.sin(t * 3) * 3, 24, 24);
    }

    // 3. BANISH
    if (agent.banished && agent.visualStatus === 'NONE') {
        const icon = AssetManager.getStatusIcon('BANISH');
        ctx.globalAlpha = 0.7;
        ctx.drawImage(icon, -12, HEAD_Y - 20 + Math.sin(t * 2) * 5, 24, 24);
    }

    // 4. DoT
    if (agent.dotTimer > 0) {
        const pulse = 1 + Math.sin(t * 10) * 0.2;
        const iconSize = 28 * pulse; 
        const icon = AssetManager.getStatusIcon('POISON'); 
        const glow = AssetManager.getGlowSprite('#ef4444');
        ctx.globalCompositeOperation = 'lighter';
        ctx.drawImage(glow, -35 - iconSize/2, HEAD_Y - iconSize/2, iconSize*2, iconSize*2);
        ctx.globalCompositeOperation = 'source-over';
        ctx.drawImage(icon, -35, HEAD_Y, iconSize, iconSize);

        ctx.globalAlpha = 0.8;
        for(let i=0; i<5; i++) {
            const cycle = (t * 2 + i * 0.7) % 1;
            const yOff = -cycle * 60; 
            const xOff = Math.sin(t * 5 + i) * 15;
            const size = (1 - cycle) * 7;
            ctx.fillStyle = i % 2 === 0 ? '#10b981' : '#a855f7';
            if (cycle < 1) {
                ctx.beginPath(); ctx.arc(xOff, -20 + yOff, size, 0, Math.PI*2); ctx.fill();
            }
        }
    }

    // 5. HoT
    if (agent.hotTimer > 0) {
        const icon = AssetManager.getStatusIcon('REGEN');
        ctx.drawImage(icon, 25, HEAD_Y, 24, 24);
        ctx.globalAlpha = 0.8;
        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 14px sans-serif';
        for(let i=0; i<3; i++) {
            const cycle = (t * 1.5 + i * 0.4) % 1;
            const yOff = -cycle * 40;
            const xOff = Math.cos(t * 3 + i) * 15;
            if (cycle < 1) ctx.fillText('+', xOff, -20 + yOff);
        }
    }

    ctx.restore();
}

export function drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
    const assets = SpriteManager.getUnitImages(agent.role, agent.team);
    const totalDuration = 0.5;
    const alpha = Math.max(0, agent.spawnTimer / totalDuration);
    const yOffset = -85 * scale; 

    ctx.save();
    ctx.translate(x, y + yOffset);
    const popScale = 1.0 + alpha * 0.2;
    ctx.scale(popScale, popScale);
    ctx.globalAlpha = alpha;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
    ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

    ctx.drawImage(assets.icon, -12, -12, 24, 24);

    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 2;
    ctx.strokeText(agent.role, 0, 28);
    ctx.fillText(agent.role, 0, 28);

    ctx.restore();
}

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team, MovementType } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSpawnIndicator } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                // Movement Interpolation
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                // Static / Physics Drift
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Ground Y (The floor)
            const visualY = agent.py - h;

            list.push({
                y: agent.py + 1, // Sort by base position
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        // Consistent height logic for silhouettes
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }

        const visualY = agent.py - h;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY); // Base Position (Ground)
        ctx.scale(scaleFactor, scaleFactor);

        // Physics values scaled
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // --- 1. DRAW BASE (Solid physical object on Ground) ---
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);

            // Draw The Heavy Base
            ctx.save();
            ctx.drawImage(assets.base, -64, -79); 
            ctx.restore();

            // Flying Tether (If flying)
            if (agent.movementType === MovementType.FLYING) {
                drawFlyingAnchor(ctx, agent, globalTime, physX, physY, physZ);
            }

            // Ground Rune (If Casting)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
        }

        // --- 2. PREPARE BODY TRANSFORM (The Projection) ---
        // Move to physics offset (X, Y) and apply Lift (Z)
        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); 

        // Vertical Float Animation (Visual only, distinct from Physics Z)
        // Ground units breathe, Flyers are held up by Physics Z
        const BODY_GROUNDING_OFFSET = -35; 
        let bodyFloat = BODY_GROUNDING_OFFSET; 

        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             // Breathing float for ground units
             bodyFloat -= Math.sin(globalTime * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             // Flyers use Physics Z, but add micro-bob here
             bodyFloat -= Math.sin(globalTime * 4) * 2;
        }

        ctx.translate(0, bodyFloat);

        // Spawn Animation
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 

            spawnAlpha = eased;
            whiteOverlay = 1 - eased; 

            ctx.scale(1, 2.0 - eased); // Vertical stretch on spawn
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit/Death Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        // Flight Thrusters (For Flying Units)
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, globalTime);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // Silhouette Setup
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // --- 3. DRAW BODY ---
        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // DELEGATED RENDERERS (Blue vs Red)
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, globalTime, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, globalTime, isSilhouette);
            }

            // Casting Particles
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // --- 4. STATUS & UI ---
        if (!isSilhouette) {
            drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); 

        // Spawn Role Icon
        if (agent.spawnTimer > 0 && !isSilhouette) {
            drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // 1. ANIMATION STATE CALCULATION
        // Body Float: Gentle vertical motion
        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 2 : 0;

        // Attack Animation Vars
        let armRot = 0;     // Weapon rotation
        let armX = 0;       // Weapon reach
        let armY = 0;
        let bodyRecoil = 0; // Body moving back slightly during hit

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                // Ranged/Magic: Thrust forward / Recoil
                if (p < 0.3) { // Windup
                    armX = -5 * (p/0.3);
                    armRot = -0.2 * (p/0.3);
                } else if (p < 0.5) { // Shoot
                    armX = 10;
                    bodyRecoil = -2;
                } else { // Recover
                    armX = 10 * (1 - (p-0.5)/0.5);
                    bodyRecoil = -2 * (1 - (p-0.5)/0.5);
                }
            } else {
                // Melee: Swing Arc
                if (p < 0.3) { // Windup (Back)
                    armRot = -Math.PI / 3 * (p/0.3); 
                    armX = -5;
                } else if (p < 0.5) { // Swing (Forward Smash)
                    const swingP = (p - 0.3) / 0.2;
                    armRot = -Math.PI / 3 + (Math.PI / 1.5) * swingP; // Swing 120 degrees
                    armX = 15 * swingP;
                } else { // Recover
                    const recP = (p - 0.5) / 0.5;
                    armRot = Math.PI / 3 * (1 - recP);
                    armX = 15 * (1 - recP);
                }
            }
        }

        ctx.save();

        // Apply Silhouette settings if needed
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoil, floatY);
            // Simple box for occlusion
            ctx.strokeRect(-15, -60, 30, 60);
            ctx.restore();
            return;
        }

        // --- RENDER START ---

        // Apply Global Position Offsets
        ctx.translate(bodyRecoil, floatY);

        // --- 1. BACK WEAPON / CAPE (Layer 0) ---
        // Imperial Cape
        drawCape(ctx, t, '#2563eb');

        // --- 2. OFF-HAND (Shield/Book) - Right Hand (Screen Left) ---
        // For Tank/Support, they hold something here.
        ctx.save();
        ctx.translate(-20, -35); // Left Shoulder position
        // Idle bob for offhand
        ctx.translate(0, Math.sin(t * 2.5 + 1) * 2); 

        if (agent.role === Role.TANK) {
            drawImperialShield(ctx);
        } else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) {
            drawImperialTome(ctx, t);
        }
        ctx.restore();

        // --- 3. BODY (Torso + Head) ---
        drawImperialBody(ctx, agent.role);

        // --- 4. MAIN HAND (Weapon) - Left Hand (Screen Right) ---
        ctx.save();
        ctx.translate(20, -35); // Right Shoulder pivot
        ctx.rotate(armRot);     // Apply Attack Rotation
        ctx.translate(armX, armY); // Apply Reach

        drawImperialWeapon(ctx, agent.role, t);

        ctx.restore();

        ctx.restore();
    }
};

// --- SUB-COMPONENT RENDERERS ---

function drawImperialBody(ctx: CanvasRenderingContext2D, role: Role) {
    const primary = '#2563eb'; // Blue
    const secondary = '#facc15'; // Gold
    const armorLight = '#f8fafc'; // White ceramic
    const armorDark = '#1e3a8a';  // Dark Blue

    // Torso Gradient
    const grad = ctx.createLinearGradient(-15, -50, 15, 0);
    grad.addColorStop(0, armorLight);
    grad.addColorStop(0.5, armorDark);
    grad.addColorStop(1, primary);

    ctx.fillStyle = grad;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1.5;

    // Armor Shape
    ctx.beginPath();
    if (role === Role.TANK) {
        // Heavy Plate
        ctx.moveTo(-22, -45); ctx.lineTo(22, -45); // Wide Shoulders
        ctx.lineTo(15, 0); ctx.lineTo(-15, 0);     // Waist
        ctx.lineTo(-22, -45);
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // Robe Form
        ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
        ctx.lineTo(18, 10); ctx.lineTo(-18, 10);
        ctx.lineTo(-12, -45);
    } else {
        // Standard Plate
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(12, 5); ctx.lineTo(-12, 5);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    // Core Crystal (Soul)
    ctx.fillStyle = '#fff';
    ctx.shadowColor = '#60a5fa'; ctx.shadowBlur = 10;
    ctx.beginPath(); ctx.moveTo(0, -35); ctx.lineTo(6, -25); ctx.lineTo(0, -15); ctx.lineTo(-6, -25); ctx.fill();
    ctx.shadowBlur = 0;

    // Head
    ctx.save();
    ctx.translate(0, -50);

    // Halo
    if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.strokeStyle = secondary;
        ctx.beginPath(); ctx.arc(0, -5, 16, 0, Math.PI*2); ctx.stroke();
    }

    ctx.fillStyle = armorLight;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (role === Role.TANK) ctx.rect(-10, -12, 20, 18); // Square Helm
    else ctx.ellipse(0, -2, 9, 11, 0, 0, Math.PI*2);    // Round Helm
    ctx.fill(); ctx.stroke();

    // Visor
    ctx.fillStyle = primary;
    ctx.fillRect(-8, -4, 16, 3);

    ctx.restore();
}

function drawCape(ctx: CanvasRenderingContext2D, t: number, color: string) {
    ctx.save();
    ctx.translate(0, -45);
    const wave = Math.sin(t * 3) * 5;
    ctx.fillStyle = 'rgba(30, 58, 138, 0.8)'; // Dark Blue liner
    ctx.beginPath();
    ctx.moveTo(-10, 0);
    ctx.lineTo(-15 + wave, 50);
    ctx.lineTo(15 + wave, 50);
    ctx.lineTo(10, 0);
    ctx.fill();
    ctx.restore();
}

function drawImperialHand(ctx: CanvasRenderingContext2D) {
    // "Servo-Hand": A floating sphere that magnetically holds weapons
    ctx.fillStyle = '#1e293b'; // Dark joint
    ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#facc15'; // Gold plate
    ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
}

function drawImperialShield(ctx: CanvasRenderingContext2D) {
    drawImperialHand(ctx);

    // Tower Shield
    ctx.translate(-5, 10); // Offset from hand
    ctx.rotate(-Math.PI/12); // Tilt

    // Shield Body
    const grad = ctx.createLinearGradient(0, -30, 0, 30);
    grad.addColorStop(0, '#f8fafc');
    grad.addColorStop(1, '#2563eb');

    ctx.fillStyle = grad;
    ctx.strokeStyle = '#facc15';
    ctx.lineWidth = 3;

    ctx.beginPath();
    ctx.moveTo(-15, -30); ctx.lineTo(15, -30); // Top
    ctx.lineTo(15, 10);   // Right vertical
    ctx.lineTo(0, 40);    // Bottom tip
    ctx.lineTo(-15, 10);  // Left vertical
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Energy Cross
    ctx.fillStyle = '#60a5fa';
    ctx.shadowColor = '#60a5fa'; ctx.shadowBlur = 5;
    ctx.fillRect(-5, -20, 10, 40);
    ctx.fillRect(-12, -5, 24, 10);
    ctx.shadowBlur = 0;
}

function drawImperialTome(ctx: CanvasRenderingContext2D, t: number) {
    drawImperialHand(ctx);
    ctx.translate(0, -10);
    // Floating Book
    ctx.fillStyle = '#fff';
    ctx.fillRect(-10, -12, 20, 24); // Pages
    ctx.fillStyle = '#2563eb';
    ctx.fillRect(-12, -12, 4, 24); // Spine

    // Magic particles
    if (Math.sin(t*5) > 0) {
        ctx.fillStyle = '#facc15';
        ctx.fillRect(5, -20, 2, 2);
        ctx.fillRect(8, -25, 2, 2);
    }
}

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawImperialHand(ctx); // The Servo Hand

    if (role === Role.WARRIOR) {
        // ENERGY CLAYMORE
        ctx.rotate(Math.PI / 2); // Point forward

        // Hilt
        ctx.fillStyle = '#475569';
        ctx.fillRect(-4, -10, 8, 20); // Grip
        ctx.fillStyle = '#facc15';
        ctx.fillRect(-12, -10, 24, 4); // Crossguard

        // Blade (Energy)
        ctx.fillStyle = 'rgba(147, 197, 253, 0.8)'; // Light blue glass
        ctx.strokeStyle = '#2563eb';
        ctx.lineWidth = 2;
        ctx.shadowColor = '#60a5fa'; ctx.shadowBlur = 8;

        ctx.beginPath();
        ctx.moveTo(-6, -10); 
        ctx.lineTo(-4, -70); // Tip Left
        ctx.lineTo(0, -80);  // Point
        ctx.lineTo(4, -70);  // Tip Right
        ctx.lineTo(6, -10);  // Base
        ctx.fill(); ctx.stroke();
        ctx.shadowBlur = 0;

    } else if (role === Role.TANK) {
        // POWER MACE
        ctx.rotate(Math.PI / 3); // Held angled

        // Handle
        ctx.fillStyle = '#475569';
        ctx.fillRect(-3, -10, 6, 50);

        // Head
        ctx.translate(0, -50);
        ctx.fillStyle = '#f8fafc';
        ctx.strokeStyle = '#facc15';
        ctx.lineWidth = 2;

        // Central Block
        ctx.fillRect(-12, -15, 24, 30);
        ctx.strokeRect(-12, -15, 24, 30);

        // Flanges
        ctx.fillStyle = '#2563eb';
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(-20, 0); ctx.lineTo(0, 15); ctx.fill();
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(20, 0); ctx.lineTo(0, 15); ctx.fill();

    } else if (role === Role.RANGER) {
        // COMPOSITE BOW
        // Held vertically
        ctx.translate(10, 0);

        ctx.strokeStyle = '#f8fafc';
        ctx.lineWidth = 3;

        // Bow Arc
        ctx.beginPath();
        ctx.arc(0, 0, 30, -Math.PI/2 - 0.5, Math.PI/2 + 0.5);
        ctx.stroke();

        // Energy String
        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, -30); ctx.lineTo(0, 30);
        ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // STAFF
        ctx.rotate(-Math.PI / 6); // Angled back

        // Shaft
        ctx.fillStyle = '#b45309'; // Wood/Gold
        ctx.fillRect(-3, -40, 6, 80);

        // Head
        ctx.translate(0, -45);

        // Floating Crystal
        const float = Math.sin(t * 4) * 3;
        ctx.translate(0, float);

        ctx.fillStyle = role === Role.MAGE ? '#3b82f6' : '#facc15';
        ctx.shadowColor = ctx.fillStyle; ctx.shadowBlur = 10;

        ctx.beginPath();
        ctx.moveTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10); ctx.lineTo(-8, 0);
        ctx.fill();
        ctx.shadowBlur = 0;

        // Orbitals
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, 14, 0, Math.PI*2); ctx.stroke();
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 

        // 1. ANIMATION STATE
        // Jittery Hover (Unstable)
        const floatY = (agent.hp > 0) ? Math.sin(t * 5) * 1.5 + (Math.random()-0.5) : 0;

        // Attack Vars
        let armRot = 0;
        let armX = 0;
        let armY = 0;
        let bodyRecoil = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                // Ranged: Violent jerk
                if (p < 0.4) { // Tense up
                    armX = -2;
                    bodyRecoil = 1;
                } else if (p < 0.5) { // Fire
                    armX = 15;
                    armY = -5; // Recoil up
                    bodyRecoil = -5;
                } else { // Recover
                    const rec = (p-0.5)/0.5;
                    armX = 15 * (1-rec);
                    armY = -5 * (1-rec);
                    bodyRecoil = -5 * (1-rec);
                }
            } else {
                // Melee: Heavy Chop
                if (p < 0.4) { // Raise High
                    armRot = -Math.PI / 1.8 * (p/0.4); 
                    armX = -5;
                    armY = -10;
                } else if (p < 0.6) { // SLAM
                    const swingP = (p - 0.4) / 0.2;
                    // Overshoot rotation for impact feeling
                    armRot = -Math.PI / 1.8 + (Math.PI) * swingP; 
                    armX = 20 * swingP;
                    armY = 10 * swingP;
                } else { // Drag back
                    const recP = (p - 0.6) / 0.4;
                    armRot = (Math.PI - Math.PI/1.8) * (1 - recP); // Return from end pos
                    armX = 20 * (1 - recP);
                    armY = 10 * (1 - recP);
                }
            }
        }

        ctx.save();

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoil, floatY);
            // Spiky box
            ctx.beginPath();
            ctx.moveTo(-15, -60); ctx.lineTo(0, -70); ctx.lineTo(15, -60);
            ctx.lineTo(10, 0); ctx.lineTo(-10, 0); ctx.closePath();
            ctx.stroke();
            ctx.restore();
            return;
        }

        // --- RENDER START ---
        ctx.translate(bodyRecoil, floatY);

        // --- 1. BACK SPIKES (Layer 0) ---
        drawSpikes(ctx, t);

        // --- 2. OFF-HAND (Shield/Totem) - Screen Left ---
        ctx.save();
        ctx.translate(-22, -30);
        // Heavy breathing motion
        ctx.translate(0, Math.sin(t * 3) * 1);

        if (agent.role === Role.TANK) {
            drawCovenantShield(ctx);
        } else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) {
            drawCovenantTotem(ctx, t);
        }
        ctx.restore();

        // --- 3. BODY ---
        drawCovenantBody(ctx, agent.role);

        // --- 4. MAIN HAND (Weapon) - Screen Right ---
        ctx.save();
        ctx.translate(22, -30); // Shoulder
        ctx.rotate(armRot);
        ctx.translate(armX, armY);

        drawCovenantWeapon(ctx, agent.role, t);

        ctx.restore();

        ctx.restore();
    }
};

// --- SUB-RENDERERS ---

function drawCovenantBody(ctx: CanvasRenderingContext2D, role: Role) {
    const primary = '#b91c1c'; // Blood Red
    const darkMetal = '#18181b'; // Obsidian
    const glow = '#ef4444'; // Bright Red

    // Body Gradient
    const grad = ctx.createLinearGradient(-15, -50, 15, 10);
    grad.addColorStop(0, primary);
    grad.addColorStop(0.6, darkMetal);
    grad.addColorStop(1, '#000');

    ctx.fillStyle = grad;
    ctx.strokeStyle = '#7f1d1d'; // Rust
    ctx.lineWidth = 1;

    // Shape: Angular/Coffin
    ctx.beginPath();
    if (role === Role.TANK) {
        // Bulk
        ctx.moveTo(-25, -40); ctx.lineTo(25, -40); // Broad shoulders
        ctx.lineTo(15, 10); ctx.lineTo(-15, 10);
        ctx.lineTo(-25, -40);
    } else {
        // Sharp
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(8, 15); ctx.lineTo(-8, 15);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    // Magma Fissure (Center Chest)
    ctx.strokeStyle = glow;
    ctx.lineWidth = 2;
    ctx.shadowColor = glow; ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.moveTo(0, -35);
    ctx.lineTo((Math.random()-0.5)*5, -25);
    ctx.lineTo(0, -15);
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Head
    ctx.save();
    ctx.translate(0, -48);

    ctx.fillStyle = darkMetal;
    ctx.beginPath();
    // Horned Helm
    ctx.moveTo(-10, 5); ctx.lineTo(-12, -15); ctx.lineTo(-5, -5); 
    ctx.lineTo(5, -5); ctx.lineTo(12, -15); ctx.lineTo(10, 5);
    ctx.fill();

    // Cyclops Eye
    ctx.fillStyle = '#fca5a5';
    ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;
    ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();
    ctx.shadowBlur = 0;

    ctx.restore();
}

function drawSpikes(ctx: CanvasRenderingContext2D, t: number) {
    ctx.save();
    ctx.translate(0, -40);
    ctx.fillStyle = '#27272a';
    ctx.beginPath();
    // Asymmetric spikes
    ctx.moveTo(-10, 0); ctx.lineTo(-25, -30 + Math.sin(t*5)*2); ctx.lineTo(-15, 0);
    ctx.moveTo(10, 0); ctx.lineTo(20, -25 + Math.cos(t*4)*2); ctx.lineTo(15, 0);
    ctx.fill();
    ctx.restore();
}

function drawCovenantHand(ctx: CanvasRenderingContext2D) {
    // "Fused Gauntlet": Angular block attached to arm
    ctx.fillStyle = '#450a0a'; // Dark Red Iron
    ctx.beginPath(); 
    ctx.moveTo(-6, -6); ctx.lineTo(6, -6); ctx.lineTo(4, 8); ctx.lineTo(-4, 8);
    ctx.fill();
}

function drawCovenantShield(ctx: CanvasRenderingContext2D) {
    drawCovenantHand(ctx);
    ctx.translate(-5, 10);

    // Scrap Wall Shield
    ctx.fillStyle = '#27272a'; // Iron
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;

    ctx.beginPath();
    // Jagged Octagon
    ctx.moveTo(-15, -25); ctx.lineTo(15, -20);
    ctx.lineTo(20, 0); ctx.lineTo(10, 25);
    ctx.lineTo(-15, 20); ctx.lineTo(-20, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Spikes on shield
    ctx.fillStyle = '#7f1d1d';
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, -35); ctx.lineTo(5, -10); ctx.fill();
}

function drawCovenantTotem(ctx: CanvasRenderingContext2D, t: number) {
    drawCovenantHand(ctx);
    ctx.translate(0, 10); // Hold low

    // Totem Pole
    ctx.fillStyle = '#3f3f46';
    ctx.fillRect(-4, -40, 8, 50);

    // Skull/Orb top
    ctx.translate(0, -45);
    ctx.fillStyle = '#ef4444';
    ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 10 + Math.sin(t*10)*5;
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10);
    ctx.fill();
    ctx.shadowBlur = 0;
}

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawCovenantHand(ctx);

    if (role === Role.WARRIOR) {
        // BATTLE AXE
        ctx.rotate(Math.PI / 4); // Forward

        // Haft
        ctx.fillStyle = '#27272a';
        ctx.fillRect(-3, -10, 6, 60); // Long handle

        // Blade Head
        ctx.translate(0, -60); // Top of handle
        ctx.fillStyle = '#52525b'; // Steel
        ctx.strokeStyle = '#ef4444'; // Red edge
        ctx.lineWidth = 1;

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(-25, -10); // Top tip
        ctx.quadraticCurveTo(-15, 10, -25, 30); // Blade edge curve
        ctx.lineTo(0, 20);
        ctx.fill(); ctx.stroke();

        // Spike on back
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(10, 5); ctx.lineTo(0, 10); ctx.fill();

    } else if (role === Role.TANK) {
        // MEAT CLEAVER
        ctx.rotate(Math.PI / 3);

        ctx.fillStyle = '#27272a';
        ctx.fillRect(-4, -5, 8, 20); // Handle

        ctx.fillStyle = '#7f1d1d'; // Rusted Metal
        ctx.beginPath();
        ctx.moveTo(-10, -10);
        ctx.lineTo(-10, -60); // Back spine
        ctx.lineTo(20, -60);  // Top flat
        ctx.lineTo(20, -10);  // Blade edge vertical
        ctx.lineTo(0, 0);
        ctx.fill();

        // Blood edge
        ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(20, -60); ctx.lineTo(20, -10); ctx.stroke();

    } else if (role === Role.RANGER) {
        // HEAVY CROSSBOW
        ctx.rotate(-Math.PI / 2); // Pointing forward

        ctx.fillStyle = '#18181b';
        ctx.fillRect(-5, -30, 10, 40); // Stock

        // Bow Arms
        ctx.strokeStyle = '#7f1d1d';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-25, -25); ctx.lineTo(0, -30); ctx.lineTo(25, -25);
        ctx.stroke();

        // String
        ctx.strokeStyle = '#52525b'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, 0); ctx.lineTo(25, -25); ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // RITUAL DAGGER / WAND
        ctx.rotate(Math.PI / 6);

        ctx.fillStyle = '#450a0a';
        ctx.beginPath();
        ctx.moveTo(0, 10);
        ctx.lineTo(-5, -30); // Wavy blade
        ctx.lineTo(0, -50);  // Point
        ctx.lineTo(5, -30);
        ctx.fill();

        // Glow Tip
        ctx.fillStyle = '#ef4444';
        ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 8;
        ctx.beginPath(); ctx.arc(0, -50, 3, 0, Math.PI*2); ctx.fill();
        ctx.shadowBlur = 0;
    }
}

