import { Agent, GameEngine } from "../../game";
import { Projectile, Skill } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillResolutionSystem } from "./SkillResolutionSystem";

export class ProjectileSystem {
    public projectiles: Projectile[] = [];

    public update(dt: number, engine: GameEngine, skillResolver: SkillResolutionSystem) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            const isGroundTarget = p.targetId.startsWith('ground-');
            let target = isGroundTarget ? null : engine.agents.find(a => a.id === p.targetId);

            // Homing logic: update target position if unit moves
            if (target && !isGroundTarget) {
                p.targetPos = {x: target.px, y: target.py};
            }

            const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const moveDist = p.speed * dt;

            // Add current pos to trail
            // Limit trail length for performance
            p.trail.push({x: p.x, y: p.y});
            if (p.trail.length > 20) p.trail.shift();

            // Hit Detection
            if (dist <= moveDist || dist < 10) {
                const source = engine.agents.find(a => a.id === p.sourceId) || engine.agents[0]; 

                if (p.skill.type === 'AOE') {
                    const hitPos = p.targetPos; 
                    const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                    const radius = p.skill.aoeRadius || 1;
                    const targets = engine.agents.filter(e => e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius);

                    targets.forEach(t => { 
                        if (source) skillResolver.resolveHit(source, t, p.skill, hitPos, engine); 
                    });

                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: hitPos.x, y: hitPos.y}, skill: p.skill });
                } else {
                    if (target && target.hp > 0 && !target.banished) {
                        if (source) skillResolver.resolveHit(source, target, p.skill, undefined, engine);
                    }
                    engine.events.push({ type: 'PROJECTILE_HIT', pos: {x: p.x, y: p.y}, skill: p.skill });
                }

                const lastIdx = this.projectiles.length - 1;
                if (i !== lastIdx) {
                    this.projectiles[i] = this.projectiles[lastIdx];
                }
                this.projectiles.pop();

            } else {
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        // Fallback Visual: Ensure no invisible projectiles
        if (!skill.visual) {
            skill.visual = 'BOLT'; 
        }

        let tx = 0, ty = 0;
        let tid = "";
        let targetPos = {x: 0, y: 0};

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 tx = p.x; ty = p.y;
                 tid = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 tx = source.target.px; ty = source.target.py;
                 tid = source.target.id;
             } else {
                 return; // No target
             }
             targetPos = {x: tx, y: ty};
             this.createProjectile(source, skill, targetPos, tid, engine);
             engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: tid });

        } else {
            // Single Target Projectile
            const targets = (source.target && !source.target.banished && source.target.hp > 0 ? [source.target] : []);
            targets.forEach(t => {
                 targetPos = {x: t.px, y: t.py};
                 this.createProjectile(source, skill, targetPos, t.id, engine);
                 engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: t.id });
            });
        }
    }

    private createProjectile(source: Agent, skill: Skill, targetPos: {x: number, y: number}, targetId: string, engine: GameEngine) {
        this.projectiles.push({
            id: Math.random().toString(),
            x: source.px, 
            y: source.py, 
            startX: source.px, 
            startY: source.py,
            targetId: targetId,
            targetPos: targetPos,
            speed: skill.projectileSpeed || 600, // Safe default
            skill: skill,
            sourceId: source.id,
            team: source.team,
            trail: []
        });
    }
}

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderableItem } from "../../grid";
import { getTransitionOffset, isChaosStyle } from "../utils";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    collect(
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             // Calculate Visual Position with Arcing/Wobble
             const getVisualPos = (lx: number, ly: number, flightProgress: number) => {
                 const t = flightProgress;
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;

                 // TYPE 1: PHYSICAL ARC (Arrow, Bomb) - Gravity based
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'BOMB') {
                     // High arc for bombs, shallow for arrows
                     const arcHeight = p.skill.visual === 'BOMB' ? 250 : 80; 
                     // Parabola: 4 * h * t * (1-t)
                     arcOffset = 4 * arcHeight * t * (1 - t);
                 } 
                 // TYPE 2: MAGICAL (Bolt, Fireball) - Wobble/Straight
                 else if (p.skill.visual === 'BOLT' || p.skill.visual === 'FIREBALL') {
                     // Sine wave wobble based on distance traveled
                     const wobbleFreq = 0.2; 
                     const wobbleAmp = 10;
                     arcOffset = Math.sin(lx * wobbleFreq + ly * wobbleFreq) * wobbleAmp;
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // Look-Ahead Rotation Calculation
             // We sample a point slightly ahead on the ideal trajectory to determine angle
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));

             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (progress * 15) : 0;

             // Style Logic
             const isChaos = isChaosStyle(p.skill.color);

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        // Re-calculate trail visual positions based on their stored world pos
                        // Note: trails store just {x, y}, we need to derive progress for height

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // Thin faint line
                            ctx.beginPath();
                            // Move to tail
                            const tail = p.trail[0];
                            const tailDist = Vector.dist({x: p.startX, y: p.startY}, tail);
                            const tailVis = getVisualPos(tail.x, tail.y, tailDist/totalDist);
                            ctx.moveTo(tailVis.x, tailVis.y);
                            ctx.lineTo(headVis.x, headVis.y);

                            ctx.strokeStyle = `rgba(255, 255, 255, 0.4)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGICAL RIBBON
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            const trailPoints = p.trail.map(t => {
                                const d = Vector.dist({x: p.startX, y: p.startY}, t);
                                return getVisualPos(t.x, t.y, d/totalDist);
                            });
                            trailPoints.push(headVis);

                            // Draw segment by segment
                            for (let i = 0; i < trailPoints.length - 1; i++) {
                                const pt = trailPoints[i];
                                const next = trailPoints[i+1];
                                const ratio = i / (trailPoints.length - 1); 

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;
                                ctx.strokeStyle = p.skill.color;

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                if (isChaos) {
                                    ctx.globalAlpha = ratio * 0.8; 
                                } else {
                                    ctx.globalAlpha = ratio * 0.5;
                                }
                                ctx.stroke();

                                if (!isChaos) {
                                    ctx.lineWidth = baseWidth * ratio * 0.3;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    const altitude = headVis.shadowY - headVis.y;
                    const shadowScale = Math.max(0.2, 1 - altitude/300);
                    ctx.scale(shadowScale, shadowScale);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }
};

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Shared translation
        ctx.translate(p.x, p.y);

        if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                // Beams are world-space endpoints, undo translate for now or calculate relative
                // Easier to undo translate
                ctx.translate(-p.x, -p.y);

                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    // Siphon / Lightning
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    // Jagged line
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    // Dark Core
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    // Holy Beam
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    // White Hot Center
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); 
            if(isChaos) {
                // Jagged Ring
                for(let i=0; i<=16; i++) {
                    const a = (i/16)*Math.PI*2;
                    const rr = r * (1 + (Math.random()-0.5)*0.2);
                    if(i===0) ctx.moveTo(Math.cos(a)*rr, Math.sin(a)*rr);
                    else ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
                }
            } else {
                ctx.arc(0, 0, r, 0, Math.PI * 2); 
            }
            ctx.stroke();
            ctx.closePath();

        } else if (p.type === 'SPARK') {
            // High Tech Upgrade: Velocity Stretch (Motion Blur)
            const speedSq = p.vx * p.vx + p.vy * p.vy;
            if (speedSq > 100) {
                const angle = Math.atan2(p.vy, p.vx);
                ctx.rotate(angle);
                // Stretch based on speed
                const stretch = Math.min(4.0, 1.0 + Math.sqrt(speedSq) * 0.005);
                ctx.scale(stretch, 1.0 / Math.max(1.0, stretch * 0.5));
            }

            const r = p.size;
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.4, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
            // Physics rotation applied in VFXSystem, render here
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.beginPath();
            const s = p.size;
            if (p.type === 'SHARD') {
                ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            } else {
                ctx.rect(-s/2, -s/2, s, s);
            }
            ctx.fill();
            // Rim Light
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.lineWidth = 1;
            ctx.stroke();
        } else if (p.type === 'PILLAR') {
            // Undo translate to use relative coord logic inside func (or refactor, but keeping consistent)
            ctx.translate(0, -20); 
            this.drawPillar(ctx, p, progress, isChaos);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawDomain(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 
        const height = 1200; 
        const baseWidth = 60 * (1 + Math.sin(progress * 20) * 0.1);

        ctx.save();
        ctx.scale(1, 0.55); 

        // Ground Blast Ring
        const ringSize = baseWidth * 2;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.2, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : '#fff');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        // BEAM COLUMN
        if (isChaos) {
            // CHAOS PILLAR: Dark Core, Unstable
            const chaosGrad = ctx.createLinearGradient(0, 0, 0, -height);
            chaosGrad.addColorStop(0, p.color);
            chaosGrad.addColorStop(0.5, 'transparent');

            ctx.fillStyle = chaosGrad;
            ctx.globalAlpha = alpha * 0.8;

            ctx.beginPath();
            const segs = 10;
            const hw = baseWidth / 2;
            ctx.moveTo(-hw, 0);
            for(let i=1; i<=segs; i++) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(-hw + xOff, y);
            }
            for(let i=segs; i>=0; i--) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(hw + xOff, y);
            }
            ctx.closePath();
            ctx.fill();

            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = '#000';
            ctx.globalAlpha = alpha * 0.6;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

        } else {
            // ORDER PILLAR: Bright Core
            const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
            coreGrad.addColorStop(0, '#ffffff');
            coreGrad.addColorStop(0.3, '#ffffff');
            coreGrad.addColorStop(1, 'transparent');

            ctx.fillStyle = coreGrad;
            ctx.globalAlpha = alpha;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.7, 'transparent');

            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.5;
            ctx.fillRect(-baseWidth, -height, baseWidth * 2, height);
        }
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';

        const r = progress * 300; 
        const width = 30 * (1 - progress);

        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress);

        ctx.beginPath(); 
        if (isChaos) {
            for(let i=0; i<=32; i++) {
                const a = (i/32)*Math.PI*2;
                const d = r + (Math.random()-0.5) * 30;
                if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
            }
        } else {
            ctx.arc(0, 0, r, 0, Math.PI * 2); 
        }
        ctx.closePath();
        ctx.stroke();
    },

    drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         ctx.scale(1, 0.55); 
         const time = performance.now() / 1000;
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;

         ctx.globalCompositeOperation = 'lighter'; 

         // Base Field
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 
         const safeColor = normalizeHex(p.color);
         grad.addColorStop(0.7, safeColor + '4D'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');

         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.5 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Rune Rings
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;

         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         if (isChaos) {
             ctx.setLineDash([10, 25]); 
             ctx.beginPath();
             for(let i=0; i<=12; i++) {
                 const a = (i/12)*Math.PI*2;
                 const d = r * 0.95 + (i%2===0 ? 15 : -15);
                 if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                 else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
             }
             ctx.closePath();
             ctx.stroke();
         } else {
             ctx.setLineDash([50, 20]); 
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
             ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); 
             ctx.setLineDash([20, 10]);
             ctx.stroke();
         }
         ctx.restore();

         // Vertical Energy Walls
         ctx.globalAlpha = 0.3 * (1 - progress);
         const spikeCount = isChaos ? 8 : 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + (isChaos ? -time : time);
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;

             ctx.beginPath();
             ctx.moveTo(sx, sy);
             const topX = sx + (isChaos ? (Math.random()-0.5)*40 : 0);
             ctx.lineTo(topX, sy - 100); 
             ctx.lineWidth = 4;

             const beamGrad = ctx.createLinearGradient(sx, sy, topX, sy - 100);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
};

import { VFXSystem } from "../vfx";
import { Team } from "../../../types";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

export function spawnDirectionalImpact(
    system: VFXSystem, 
    x: number, y: number, 
    dirX: number, dirY: number, 
    color: string, 
    type: 'PHYSICAL' | 'MAGICAL'
) {
    const isPhysical = type === 'PHYSICAL';

    // 1. Main Spark/Splatter Cone (Opposite to hit direction = Blowback)
    // Actually, visually it looks better if sparks fly *through* the target (same direction as hit)
    // OR fly out from point of impact (radial but biased).
    // Let's bias towards the hit direction.
    const baseAngle = Math.atan2(dirY, dirX);
    const cone = 1.0; // Spread radians

    const count = isPhysical ? 8 : 12;
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * cone;
        const speed = (isPhysical ? 150 : 200) + Math.random() * 100;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = 25; // Hit height
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 100; // Upward kick

        p.life = 0.4 + Math.random() * 0.3;
        p.maxLife = p.life;
        p.color = color;
        p.size = Math.random() * 4 + 2;
        p.type = isPhysical ? 'SPARK' : 'GLOW'; // Use GLOW for magic
        p.delay = 0;

        system.state.particles.push(p);
    }

    // 2. Ring Burst (Perpendicular to hit)
    addImpact(system, x, y - 25, color, 'RING', isPhysical ? 0.4 : 0.6);
}

export function spawnConnectorSlash(
    system: VFXSystem,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string,
    visual: string
) {
    // Spawns a beam-like particle but styled as a slash
    // We use the BEAM type but with specific handling in renderer to look sharp
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; // Waist height
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;

    p.life = 0.25; // Very fast flash
    p.maxLife = 0.25;
    p.color = color;
    p.size = 10;
    p.type = 'BEAM'; // We reuse BEAM logic but style it in renderer based on Chaos check
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team) {
    // Colors
    const armorColor = team === Team.BLUE ? '#e2e8f0' : '#27272a';
    const trimColor = team === Team.BLUE ? '#fbbf24' : '#a1a1aa';
    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';

    // 1. Armor Shards (Heavy chunks) - KEEP FOR DEATH
    for (let i = 0; i < 6; i++) { 
        const angle = Math.random() * Math.PI * 2;
        const speed = 100 + Math.random() * 150;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = 30 + Math.random() * 30; 
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 200; 

        p.life = 2.0; p.maxLife = 2.0; 
        p.color = Math.random() > 0.5 ? armorColor : trimColor;
        p.size = 5 + Math.random() * 4; 
        p.type = 'SHARD'; 
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 20;
        p.delay = 0;
        system.state.particles.push(p);
    }

    // 2. Core Sparks
    spawnExplosion(system, x, y, 30, 15, coreColor, 1.2, 0.6, 'SPARK');

    // 3. Shockwave
    addImpact(system, x, y, coreColor, 'RING', 0.5);

    // 4. Ground Scorch
    addDecal(system, x, y, '#000');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); // Reduced count

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 

        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 20 + Math.random() * 30;

        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Center "Poof"
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
    addImpact(system, x, y, '#ffffff', 'RING', 0.15);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; // Shorter life
    p.color = color; p.size = 4;
    p.type = 'BEAM';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);

    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd;
        p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4);
        p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type;
        p.delay = 0;

        system.state.particles.push(p);
    }
}

export function spawnDebris(system: VFXSystem, x: number, y: number, color: string, count: number) {
    // Keeping disabled for normal hits to reduce noise, can be re-enabled for heavy hits specifically in SkillResolution
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnPillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, color, 'RING', 0.8);
}

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    spawnPillar(system, x, y, color, life, delay);
}

export function spawnPillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100;
    p.type = 'PILLAR';
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addGridFlash(system: VFXSystem, q: number, r: number, color: string) {
    system.state.gridFlashes.push({ q, r, color, life: 0.5 }); // Reduced life
}

export function addImpact(system: VFXSystem, x: number, y: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 5;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { GameEngine } from "../game";
import { GameEvent, Team } from "../../types";
import { HexUtils } from "../utils";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";

// Systems
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import * as VFXSpawners from "./vfx/spawners";

const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20;
// TA TUNING: Increased from 5.0s to 12.0s. 
// Auto-battler units have move/cast times that make 5s too strict for a Penta.
const KILL_STREAK_WINDOW = 12.0; 

export class VisualEventListener {
    // Kill Streak State: AgentID -> { Count, LastTime }
    private killStreaks = new Map<string, { count: number, lastTime: number }>();
    private firstBlood = false;

    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        // Reset Logic: If battle just started or reset, clear streaks
        if (engine.battleTime < 0.1) {
            this.killStreaks.clear();
            this.firstBlood = false;
        }

        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     // Highlight high damage
                     const isCrit = val > 100;
                     color = isCrit ? '#ef4444' : '#fff'; 
                     size = isCrit ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         // Reduced cast impact
                         camera.addTrauma(0.2); 
                     }
                 }
            }

            // 2. Kill Streaks (New)
            if (event.type === 'KILL' && event.sourceId) {
                const now = engine.battleTime;
                const killer = event.sourceId;
                const killerAgent = engine.agents.find(a => a.id === killer);

                // FIRST BLOOD LOGIC
                if (!this.firstBlood) {
                    this.firstBlood = true;
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        hud.addFloatingText(
                            killerAgent.px, 
                            killerAgent.py - kH - HUD_TEXT_OFFSET - 60, 
                            "FIRST BLOOD", 
                            "#ef4444", 
                            36, 
                            'KILL_STREAK'
                        );
                        camera.addTrauma(0.3);
                    }
                }

                let streak = 1;
                const existing = this.killStreaks.get(killer);

                if (existing) {
                    if (now - existing.lastTime <= KILL_STREAK_WINDOW) {
                        streak = existing.count + 1;
                    } else {
                        streak = 1; // Expired
                    }
                }

                this.killStreaks.set(killer, { count: streak, lastTime: now });

                // Trigger Visual if Streak > 1
                if (streak >= 2) {
                    let streakText = "";
                    let streakColor = "#fff";
                    let trauma = 0;

                    if (streak === 2) { streakText = "DOUBLE KILL"; streakColor = "#cbd5e1"; trauma = 0.2; }
                    else if (streak === 3) { streakText = "TRIPLE KILL"; streakColor = "#fcd34d"; trauma = 0.3; }
                    else if (streak === 4) { streakText = "QUADRA KILL"; streakColor = "#fb923c"; trauma = 0.4; }
                    else if (streak >= 5) { streakText = "PENTA KILL"; streakColor = "#ef4444"; trauma = 0.6; } // Epic

                    // Display above unit
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        // Offset higher than damage numbers
                        hud.addFloatingText(
                            killerAgent.px, 
                            killerAgent.py - kH - HUD_TEXT_OFFSET - 40, 
                            streakText, 
                            streakColor, 
                            32 + (streak * 4), // Scale up size with streak
                            'KILL_STREAK'
                        );

                        camera.addTrauma(trauma);
                    }
                }
            }

            // 3. VFX Handling
            switch (event.type) {
                case 'VISUAL_SLASH':
                    if (event.sourceId && event.targetId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        const target = engine.agents.find(a => a.id === event.targetId);
                        if (source && target) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                            const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                            const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                            VFXSpawners.spawnConnectorSlash(
                                vfx,
                                source.px, source.py - sH,
                                target.px, target.py - tH,
                                event.color || '#fff',
                                event.skill?.visual || 'SLASH'
                            );
                        }
                    }
                    break;

                case 'DAMAGE': 
                    const dmg = Math.abs(event.value || 0);
                    const isHeavy = dmg > 50; 

                    // Directional Impact Logic
                    let handled = false;
                    if (event.sourceId && event.targetId) {
                        const s = engine.agents.find(a => a.id === event.sourceId);
                        const t = engine.agents.find(a => a.id === event.targetId);
                        if (s && t) {
                            // Calc direction
                            // We use world coordinates (px, py) from Agent, which are flat.
                            const dx = t.px - s.px;
                            const dy = t.py - s.py;
                            const len = Math.sqrt(dx*dx + dy*dy);
                            if (len > 0) {
                                const dirX = dx / len;
                                const dirY = dy / len;

                                const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';

                                VFXSpawners.spawnDirectionalImpact(
                                    vfx,
                                    event.pos.x, visualY - 20,
                                    dirX, dirY,
                                    event.color || '#fff',
                                    type
                                );
                                handled = true;
                            }
                        }
                    }

                    if (!handled) {
                        // Fallback generic explosion
                        // Reduced particle count via factory
                        VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY - 20, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
                    }

                    if (isHeavy) {
                        // Only shake on heavy hits
                        camera.addTrauma(0.15);
                        // Debris is now disabled in spawner, but we could re-enable for crits here if desired
                        // VFXSpawners.spawnDebris(vfx, event.pos.x, visualY - 20, event.color || '#fff', 3);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualY - 20; 

                            VFXSpawners.spawnBeam(vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(vfx, tx, ty, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY, vfx, grid, camera); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualY, team);
                    camera.addTrauma(0.3); 
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(vfx, event.pos.x, visualY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    VFXSpawners.spawnDomainShatter(vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    camera.addTrauma(0.1);
                    break;
            }
        });
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            camera.addTrauma(0.4); // Ult impact
            VFXSpawners.spawnDivinePillar(vfx, event.pos.x, visualY, color, 1.2);
            VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, color, 1.5);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        // Reduced visual density for AOE tiles
                        if (Math.random() < 0.3) { 
                            VFXSpawners.spawnExplosion(vfx, tilePos.x, tileVisualY, 0, 3, color, 1.0, 0.5, 'SPARK');
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 2.0);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 2.0);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 30, color, 1.5, 0.8, 'SPARK');
            }
        } else {
            // Normal Projectile
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        // REMOVED: GridFlash on normal hits (Too noisy)
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 0.8);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, color, 'RING', 0.6);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 5, color, 1.0, 0.5, 'SPARK');
            }
        }
    }
}

