import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team, MovementType } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSpawnIndicator } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                // Movement Interpolation
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                // Static / Physics Drift
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Ground Y (The floor)
            const visualY = agent.py - h;

            list.push({
                y: agent.py + 1, // Sort by base position
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        // Consistent height logic for silhouettes
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }

        const visualY = agent.py - h;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY); // Base Position (Ground)
        ctx.scale(scaleFactor, scaleFactor);

        // Physics values scaled
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // --- 1. DRAW BASE (Solid physical object on Ground) ---
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);

            // Draw The Heavy Base
            ctx.save();
            ctx.drawImage(assets.base, -64, -79); 
            ctx.restore();

            // Flying Tether (If flying)
            if (agent.movementType === MovementType.FLYING) {
                drawFlyingAnchor(ctx, agent, globalTime, physX, physY, physZ);
            }

            // Ground Rune (If Casting)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
        }

        // --- 2. PREPARE BODY TRANSFORM (The Projection) ---
        // Move to physics offset (X, Y) and apply Lift (Z)
        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); 

        // Vertical Float Animation (Visual only, distinct from Physics Z)
        // Body is offset by UNIT_BODY_OFFSET to ensure it floats above base.
        // We use the negative of the constant because canvas Y-up is negative.
        let bodyFloat = -UNIT_BODY_OFFSET; 

        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             // Breathing float for ground units
             bodyFloat -= Math.sin(globalTime * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             // Flyers use Physics Z, but add micro-bob here
             bodyFloat -= Math.sin(globalTime * 4) * 2;
        }

        ctx.translate(0, bodyFloat);

        // Spawn Animation
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 

            spawnAlpha = eased;
            whiteOverlay = 1 - eased; 

            ctx.scale(1, 2.0 - eased); // Vertical stretch on spawn
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit/Death Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        // Flight Thrusters (For Flying Units)
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, globalTime);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // Silhouette Setup
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // --- 3. DRAW BODY ---
        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // DELEGATED RENDERERS (Blue vs Red)
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, globalTime, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, globalTime, isSilhouette);
            }

            // Casting Particles
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // --- 4. STATUS & UI ---
        if (!isSilhouette) {
            drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); 

        // Spawn Role Icon
        if (agent.spawnTimer > 0 && !isSilhouette) {
            drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }
}

import { GameEngine } from "../game";
import { GameEvent, Team } from "../../types";
import { HexUtils } from "../utils";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING, UNIT_BODY_OFFSET } from "../../constants";

// Systems
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import * as VFXSpawners from "./vfx/spawners";

const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20;
// TA TUNING: Increased from 5.0s to 12.0s. 
// Auto-battler units have move/cast times that make 5s too strict for a Penta.
const KILL_STREAK_WINDOW = 12.0; 

export class VisualEventListener {
    // Kill Streak State: AgentID -> { Count, LastTime }
    private killStreaks = new Map<string, { count: number, lastTime: number }>();
    private firstBlood = false;

    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        // Reset Logic: If battle just started or reset, clear streaks
        if (engine.battleTime < 0.1) {
            this.killStreaks.clear();
            this.firstBlood = false;
        }

        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
            // This is the GROUND visual Y
            const visualGroundY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualGroundY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     // Highlight high damage
                     const isCrit = val > 100;
                     color = isCrit ? '#ef4444' : '#fff'; 
                     size = isCrit ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualGroundY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         // Reduced cast impact
                         camera.addTrauma(0.2); 
                     }
                 }
            }

            // 2. Kill Streaks (New)
            if (event.type === 'KILL' && event.sourceId) {
                const now = engine.battleTime;
                const killer = event.sourceId;
                const killerAgent = engine.agents.find(a => a.id === killer);

                // FIRST BLOOD LOGIC
                if (!this.firstBlood) {
                    this.firstBlood = true;
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        hud.addFloatingText(
                            killerAgent.px, 
                            killerAgent.py - kH - HUD_TEXT_OFFSET - 60, 
                            "FIRST BLOOD", 
                            "#ef4444", 
                            36, 
                            'KILL_STREAK'
                        );
                        camera.addTrauma(0.3);
                    }
                }

                let streak = 1;
                const existing = this.killStreaks.get(killer);

                if (existing) {
                    if (now - existing.lastTime <= KILL_STREAK_WINDOW) {
                        streak = existing.count + 1;
                    } else {
                        streak = 1; // Expired
                    }
                }

                this.killStreaks.set(killer, { count: streak, lastTime: now });

                // Trigger Visual if Streak > 1
                if (streak >= 2) {
                    let streakText = "";
                    let streakColor = "#fff";
                    let trauma = 0;

                    if (streak === 2) { streakText = "DOUBLE KILL"; streakColor = "#cbd5e1"; trauma = 0.2; }
                    else if (streak === 3) { streakText = "TRIPLE KILL"; streakColor = "#fcd34d"; trauma = 0.3; }
                    else if (streak === 4) { streakText = "QUADRA KILL"; streakColor = "#fb923c"; trauma = 0.4; }
                    else if (streak >= 5) { streakText = "PENTA KILL"; streakColor = "#ef4444"; trauma = 0.6; } // Epic

                    // Display above unit
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        // Offset higher than damage numbers
                        hud.addFloatingText(
                            killerAgent.px, 
                            killerAgent.py - kH - HUD_TEXT_OFFSET - 40, 
                            streakText, 
                            streakColor, 
                            32 + (streak * 4), // Scale up size with streak
                            'KILL_STREAK'
                        );

                        camera.addTrauma(trauma);
                    }
                }
            }

            // 3. VFX Handling
            switch (event.type) {
                case 'VISUAL_SLASH':
                    if (event.sourceId && event.targetId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        const target = engine.agents.find(a => a.id === event.targetId);
                        if (source && target) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                            const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                            const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                            VFXSpawners.spawnConnectorSlash(
                                vfx,
                                source.px, source.py - sH,
                                target.px, target.py - tH,
                                event.color || '#fff',
                                event.skill?.visual || 'SLASH'
                            );
                        }
                    }
                    break;

                case 'DAMAGE': 
                    const dmg = Math.abs(event.value || 0);
                    const isHeavy = dmg > 50; 

                    // Directional Impact Logic
                    let handled = false;
                    if (event.sourceId && event.targetId) {
                        const s = engine.agents.find(a => a.id === event.sourceId);
                        const t = engine.agents.find(a => a.id === event.targetId);
                        if (s && t) {
                            // Calc direction
                            // We use world coordinates (px, py) from Agent, which are flat.
                            const dx = t.px - s.px;
                            const dy = t.py - s.py;
                            const len = Math.sqrt(dx*dx + dy*dy);
                            if (len > 0) {
                                const dirX = dx / len;
                                const dirY = dy / len;

                                const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';

                                // CALCULATE DYNAMIC HIT HEIGHT
                                // This ensures effects appear on the body, even if unit is floating or knocked up.
                                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;

                                VFXSpawners.spawnDirectionalImpact(
                                    vfx,
                                    event.pos.x, visualGroundY,
                                    bodyHeight, // Pass Z-height explicitly
                                    dirX, dirY,
                                    event.color || '#fff',
                                    type
                                );
                                handled = true;
                            }
                        }
                    }

                    if (!handled) {
                        // Fallback generic explosion
                        // Reduced particle count via factory
                        VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
                    }

                    if (isHeavy) {
                        // Only shake on heavy hits
                        camera.addTrauma(0.15);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualGroundY - 30; // Aim at chest

                            VFXSpawners.spawnBeam(vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(vfx, tx, ty, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, team);
                    camera.addTrauma(0.3); 
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    VFXSpawners.spawnDomainShatter(vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    camera.addTrauma(0.1);
                    break;
            }
        });
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        // Find target for Z correction
        const target = engine.agents.find(a => a.id === event.targetId);
        const hitZ = target ? (target.physics.z + UNIT_BODY_OFFSET) : 25;

        if (isUlt) {
            camera.addTrauma(0.4); // Ult impact
            VFXSpawners.spawnDivinePillar(vfx, event.pos.x, visualY, color, 1.2);
            VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, color, 1.5);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        // Reduced visual density for AOE tiles
                        if (Math.random() < 0.3) { 
                            VFXSpawners.spawnExplosion(vfx, tilePos.x, tileVisualY, 0, 3, color, 1.0, 0.5, 'SPARK');
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 2.0);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 2.0);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, hitZ, 30, color, 1.5, 0.8, 'SPARK');
            }
        } else {
            // Normal Projectile
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 0.8);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 0.6);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, hitZ, 12, color, 1.0, 0.5, 'SPARK');
            }
        }
    }
}

import { VFXSystem } from "../vfx";
import { Team } from "../../../types";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

export function spawnDirectionalImpact(
    system: VFXSystem, 
    x: number, y: number, z: number,
    dirX: number, dirY: number, 
    color: string, 
    type: 'PHYSICAL' | 'MAGICAL'
) {
    const isPhysical = type === 'PHYSICAL';

    // 1. Main Spark/Splatter Cone
    const baseAngle = Math.atan2(dirY, dirX);
    const cone = 1.0; // Spread radians

    // Increased count for better visibility
    const count = isPhysical ? 12 : 16;
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * cone;
        const speed = (isPhysical ? 200 : 250) + Math.random() * 150;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z; // Use correct Z
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 80 + Math.random() * 150; // Higher kick

        p.life = 0.4 + Math.random() * 0.3;
        p.maxLife = p.life;
        p.color = color;
        p.size = Math.random() * 5 + 3; // Bigger sparks
        p.type = isPhysical ? 'SPARK' : 'GLOW'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // 2. Ring Burst (Perpendicular to hit)
    addImpact(system, x, y, z, color, 'RING', isPhysical ? 0.4 : 0.6);

    // 3. Flash Pop (Immediate white burst for punch)
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = z;
    flash.vx = 0; flash.vy = 0; flash.vz = 0;
    flash.life = 0.1; flash.maxLife = 0.1;
    flash.color = '#fff';
    flash.size = 20; // Big initial flash
    flash.type = 'GLOW';
    system.state.particles.push(flash);
}

export function spawnConnectorSlash(
    system: VFXSystem,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string,
    visual: string
) {
    // Spawns a beam-like particle but styled as a slash
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; // Waist height
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;

    p.life = 0.25; // Very fast flash
    p.maxLife = 0.25;
    p.color = color;
    p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team) {
    const armorColor = team === Team.BLUE ? '#e2e8f0' : '#27272a';
    const trimColor = team === Team.BLUE ? '#fbbf24' : '#a1a1aa';
    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';

    // 1. Armor Shards
    for (let i = 0; i < 6; i++) { 
        const angle = Math.random() * Math.PI * 2;
        const speed = 100 + Math.random() * 150;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = 30 + Math.random() * 30; 
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 200; 

        p.life = 2.0; p.maxLife = 2.0; 
        p.color = Math.random() > 0.5 ? armorColor : trimColor;
        p.size = 5 + Math.random() * 4; 
        p.type = 'SHARD'; 
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 20;
        p.delay = 0;
        system.state.particles.push(p);
    }

    // 2. Core Sparks
    spawnExplosion(system, x, y, 30, 15, coreColor, 1.2, 0.6, 'SPARK');

    // 3. Shockwave
    addImpact(system, x, y, 5, coreColor, 'RING', 0.5);

    // 4. Ground Scorch
    addDecal(system, x, y, '#000');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); 

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 

        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 20 + Math.random() * 30;

        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Center "Poof"
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
    addImpact(system, x, y, 5, '#ffffff', 'RING', 0.15);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; 
    p.color = color; p.size = 4;
    p.type = 'BEAM';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);

    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd;
        p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4);
        p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type;
        p.delay = 0;

        system.state.particles.push(p);
    }
}

export function spawnDebris(system: VFXSystem, x: number, y: number, color: string, count: number) {
    // Disabled for normal hits
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnPillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    spawnPillar(system, x, y, color, life, delay);
}

export function spawnPillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100;
    p.type = 'PILLAR';
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addGridFlash(system: VFXSystem, q: number, r: number, color: string) {
    system.state.gridFlashes.push({ q, r, color, life: 0.5 }); 
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

export interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'RING' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST';
    targetX?: number; // For BEAM
    targetY?: number; // For BEAM
    delay?: number;
    image?: HTMLCanvasElement; // For SPRITE type (Unit parts)
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export interface GridFlash {
    q: number;
    r: number;
    color: string;
    life: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];
    public gridFlashes: GridFlash[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            p.image = undefined; // Reset image reference
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK' 
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        this.particlePool.push(p);
    }
}

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Shared translation
        ctx.translate(p.x, p.y);

        if (p.type === 'SPRITE') {
            // UNIT PARTS SHATTER
            // Renders the specific canvas element (Weapon, Icon, Base piece)
            if (p.image) {
                const alpha = Math.min(1, p.life * 2); // Fade out quickly at end
                ctx.globalAlpha = alpha;
                ctx.rotate(p.rotation);
                const scale = p.size / 64; // Normalize size
                ctx.scale(scale, scale);
                // Center the image
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'BLAST') {
            // IMPACT SHOCKWAVE (High velocity ring)
            ctx.scale(1, 0.55); // Isometric circle
            const r = p.size * (progress * 2); // Expands fast

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 10;
            ctx.globalAlpha = 1 - progress;

            ctx.beginPath();
            ctx.arc(0, 0, r, 0, Math.PI * 2);
            ctx.stroke();

            // Inner white flash
            if (progress < 0.2) {
                ctx.fillStyle = '#fff';
                ctx.globalAlpha = (0.2 - progress) * 5;
                ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI * 2); ctx.fill();
            }

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(-p.x, -p.y); // Undo translation for world coords

                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); 
            if(isChaos) {
                for(let i=0; i<=16; i++) {
                    const a = (i/16)*Math.PI*2;
                    const rr = r * (1 + (Math.random()-0.5)*0.2);
                    if(i===0) ctx.moveTo(Math.cos(a)*rr, Math.sin(a)*rr);
                    else ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
                }
            } else {
                ctx.arc(0, 0, r, 0, Math.PI * 2); 
            }
            ctx.stroke();
            ctx.closePath();

        } else if (p.type === 'SPARK') {
            const speedSq = p.vx * p.vx + p.vy * p.vy;
            if (speedSq > 100) {
                const angle = Math.atan2(p.vy, p.vx);
                ctx.rotate(angle);
                const stretch = Math.min(4.0, 1.0 + Math.sqrt(speedSq) * 0.005);
                ctx.scale(stretch, 1.0 / Math.max(1.0, stretch * 0.5));
            }

            const r = p.size;
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.4, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.beginPath();
            const s = p.size;
            if (p.type === 'SHARD') {
                ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            } else {
                ctx.rect(-s/2, -s/2, s, s);
            }
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.lineWidth = 1;
            ctx.stroke();
        } else if (p.type === 'PILLAR') {
            ctx.translate(0, -20); 
            this.drawPillar(ctx, p, progress, isChaos);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawDomain(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        // ... (Existing Pillar Logic kept same)
        ctx.globalCompositeOperation = 'lighter';
        const lifeRatio = p.life / p.maxLife;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 
        const height = 1200; 
        const baseWidth = 60 * (1 + Math.sin(progress * 20) * 0.1);

        ctx.save();
        ctx.scale(1, 0.55); 
        const ringSize = baseWidth * 2;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.2, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : '#fff');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        if (isChaos) {
            const chaosGrad = ctx.createLinearGradient(0, 0, 0, -height);
            chaosGrad.addColorStop(0, p.color);
            chaosGrad.addColorStop(0.5, 'transparent');
            ctx.fillStyle = chaosGrad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.beginPath();
            const segs = 10;
            const hw = baseWidth / 2;
            ctx.moveTo(-hw, 0);
            for(let i=1; i<=segs; i++) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(-hw + xOff, y);
            }
            for(let i=segs; i>=0; i--) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(hw + xOff, y);
            }
            ctx.closePath();
            ctx.fill();
        } else {
            const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
            coreGrad.addColorStop(0, '#ffffff');
            coreGrad.addColorStop(0.3, '#ffffff');
            coreGrad.addColorStop(1, 'transparent');
            ctx.fillStyle = coreGrad;
            ctx.globalAlpha = alpha;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);
            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.7, 'transparent');
            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.5;
            ctx.fillRect(-baseWidth, -height, baseWidth * 2, height);
        }
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        // ... (Existing Shockwave logic kept same)
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';
        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress);
        ctx.beginPath(); 
        if (isChaos) {
            for(let i=0; i<=32; i++) {
                const a = (i/32)*Math.PI*2;
                const d = r + (Math.random()-0.5) * 30;
                if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
            }
        } else {
            ctx.arc(0, 0, r, 0, Math.PI * 2); 
        }
        ctx.closePath();
        ctx.stroke();
    },

    drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         // ... (Existing Domain logic kept same)
         ctx.scale(1, 0.55); 
         const time = performance.now() / 1000;
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;
         ctx.globalCompositeOperation = 'lighter'; 
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 
         const safeColor = normalizeHex(p.color);
         grad.addColorStop(0.7, safeColor + '4D'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');
         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.5 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;
         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         if (isChaos) {
             ctx.setLineDash([10, 25]); 
             ctx.beginPath();
             for(let i=0; i<=12; i++) {
                 const a = (i/12)*Math.PI*2;
                 const d = r * 0.95 + (i%2===0 ? 15 : -15);
                 if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                 else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
             }
             ctx.closePath();
             ctx.stroke();
         } else {
             ctx.setLineDash([50, 20]); 
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
             ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); 
             ctx.setLineDash([20, 10]);
             ctx.stroke();
         }
         ctx.restore();
         ctx.globalAlpha = 0.3 * (1 - progress);
         const spikeCount = isChaos ? 8 : 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + (isChaos ? -time : time);
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;
             ctx.beginPath();
             ctx.moveTo(sx, sy);
             const topX = sx + (isChaos ? (Math.random()-0.5)*40 : 0);
             ctx.lineTo(topX, sy - 100); 
             ctx.lineWidth = 4;
             const beamGrad = ctx.createLinearGradient(sx, sy, topX, sy - 100);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

export function spawnDirectionalImpact(
    system: VFXSystem, 
    x: number, y: number, z: number,
    dirX: number, dirY: number, 
    color: string, 
    type: 'PHYSICAL' | 'MAGICAL'
) {
    const isPhysical = type === 'PHYSICAL';

    // 1. High Velocity BLAST RING (Immediate Shockwave)
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = z;
    blast.vx = 0; blast.vy = 0; blast.vz = 0;
    blast.life = 0.2; blast.maxLife = 0.2; // Snappy
    blast.color = '#fff';
    blast.size = 60;
    blast.type = 'BLAST';
    system.state.particles.push(blast);

    // 2. Main Spark/Splatter Cone (Blowback)
    // Sparks fly in the SAME direction as the impact (Punch through)
    const baseAngle = Math.atan2(dirY, dirX);
    const cone = 0.8; // Tighter cone

    const count = isPhysical ? 15 : 20;
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * cone;
        const speed = (isPhysical ? 300 : 400) + Math.random() * 200; // Much faster
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 100 + Math.random() * 200; // High vertical spray

        p.life = 0.3 + Math.random() * 0.2; // Short life for speed feel
        p.maxLife = p.life;
        p.color = color;
        p.size = Math.random() * 4 + 2; 
        p.type = isPhysical ? 'SPARK' : 'GLOW'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // 3. Central Flash
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = z;
    flash.vx = 0; flash.vy = 0; flash.vz = 0;
    flash.life = 0.1; flash.maxLife = 0.1;
    flash.color = color;
    flash.size = 30; 
    flash.type = 'GLOW';
    system.state.particles.push(flash);
}

export function spawnConnectorSlash(
    system: VFXSystem,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string,
    visual: string
) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;

    p.life = 0.25; 
    p.maxLife = 0.25;
    p.color = color;
    p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);

    // Helper to spawn a physical sprite chunk
    const spawnPart = (img: HTMLCanvasElement, scale: number, vZ: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 40; // Spawn at chest height
        const angle = Math.random() * Math.PI * 2;
        const speed = 100 + Math.random() * 150;

        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = vZ;

        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff';
        p.size = 64 * scale; // Base size ref
        p.type = 'SPRITE';
        p.image = img;

        // Random tumbling
        p.rotation = Math.random() * Math.PI * 2;
        p.vRotation = (Math.random() - 0.5) * 10;

        system.state.particles.push(p);
    };

    // 1. Weapon flies off high
    spawnPart(assets.weapon, 0.8, 400);

    // 2. Class Icon (Soul/Head) pops off
    spawnPart(assets.icon, 0.6, 300);

    // 3. Base/Torso (Uses base sprite) falls
    // We use the base sprite for the "heaviest" part
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 20;
    p.vx = (Math.random()-0.5) * 50; // Heavy, doesn't move much horizontally
    p.vy = (Math.random()-0.5) * 50;
    p.vz = 150; 
    p.life = 2.0; p.maxLife = 2.0;
    p.color = '#fff';
    p.size = 64; 
    p.type = 'SPRITE';
    p.image = assets.base;
    p.rotation = 0;
    p.vRotation = (Math.random() - 0.5) * 2; // Slow tumble
    system.state.particles.push(p);

    // 4. Core Explosion (Juice)
    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';
    spawnExplosion(system, x, y, 30, 20, coreColor, 1.5, 0.8, 'SPARK');
    addImpact(system, x, y, 5, coreColor, 'RING', 0.5);
    addDecal(system, x, y, '#000');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); 

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 

        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 20 + Math.random() * 30;

        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Center "Poof"
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
    addImpact(system, x, y, 5, '#ffffff', 'RING', 0.15);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; 
    p.color = color; p.size = 4;
    p.type = 'BEAM';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);

    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd;
        p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4);
        p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type;
        p.delay = 0;

        system.state.particles.push(p);
    }
}

export function spawnDebris(system: VFXSystem, x: number, y: number, color: string, count: number) {
    // Disabled for normal hits
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnPillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    spawnPillar(system, x, y, color, life, delay);
}

export function spawnPillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100;
    p.type = 'PILLAR';
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addGridFlash(system: VFXSystem, q: number, r: number, color: string) {
    system.state.gridFlashes.push({ q, r, color, life: 0.5 }); 
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171'; // Blue-400 : Red-400

    // We are at Ground Level (0,0).
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. "Divine Light" Lift Column (Gradient Fill)
    const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
    // Transparent at bottom to blend with ground, stronger at top to show lift source
    grad.addColorStop(0, isBlue ? 'rgba(96, 165, 250, 0.0)' : 'rgba(248, 113, 113, 0.0)');
    grad.addColorStop(0.3, isBlue ? 'rgba(96, 165, 250, 0.1)' : 'rgba(248, 113, 113, 0.1)');
    grad.addColorStop(1.0, isBlue ? 'rgba(96, 165, 250, 0.3)' : 'rgba(248, 113, 113, 0.3)');

    // Column Shape (Tapered Cylinder)
    const baseW = 15; 
    const topW = 10;  

    ctx.beginPath();
    ctx.moveTo(-baseW, 0);
    ctx.lineTo(feetX - topW, feetY);
    ctx.lineTo(feetX + topW, feetY);
    ctx.lineTo(baseW, 0);
    ctx.fill();

    // 2. Rising Energy Streams / Rings
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;

    const height = Math.abs(feetY);
    const ringCount = Math.max(2, Math.floor(height / 25));

    for(let i=0; i<ringCount; i++) {
        const phase = (t * 1.5 + i / ringCount) % 1; 
        const curX = feetX * phase;
        const curY = feetY * phase;
        const curW = baseW + (topW - baseW) * phase;
        const alpha = Math.sin(phase * Math.PI); 

        ctx.globalAlpha = alpha * 0.5;
        ctx.beginPath();
        ctx.ellipse(curX, curY, curW, curW * 0.5, 0, 0, Math.PI * 2);
        ctx.stroke();
    }

    // 3. Ground Anchor Ring (The Mechanical Projector lens)
    ctx.globalAlpha = 1.0;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(0, 0, 20, 10, 0, 0, Math.PI * 2);
    ctx.stroke();

    // Crosshair Center
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-5, 0); ctx.lineTo(5, 0);
    ctx.moveTo(0, -3); ctx.lineTo(0, 3);
    ctx.stroke();

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 5); 

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    ctx.arc(0, 0, 15 + Math.sin(t * 15) * 2, 0, Math.PI * 1.5);
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.7;
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    // Undo facing flip so CC effects look correct
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -60; // Approximate head height

    // 1. STUN - Dizzy Halo
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        const haloRadius = 25;
        ctx.translate(0, HEAD_Y);

        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = '#facc15';
        ctx.lineWidth = 3;

        // Rotating jagged ring
        ctx.save();
        ctx.scale(1, 0.4); // Isometric ring
        ctx.rotate(t * 5);
        ctx.beginPath();
        const pts = 8;
        for(let i=0; i<=pts; i++) {
            const a = (i/pts) * Math.PI * 2;
            const r = haloRadius + (i%2===0 ? 5 : -5);
            const x = Math.cos(a)*r; 
            const y = Math.sin(a)*r;
            if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
        }
        ctx.closePath();
        ctx.stroke();
        ctx.restore();

        // Stars
        for(let i=0; i<3; i++) {
            const a = t * 3 + i * (Math.PI*2/3);
            const r = haloRadius;
            const starX = Math.cos(a) * r;
            const starY = Math.sin(a) * r * 0.4;

            ctx.fillStyle = '#fff';
            ctx.shadowColor = '#facc15'; ctx.shadowBlur = 10;
            ctx.beginPath(); ctx.arc(starX, starY - 10, 3, 0, Math.PI*2); ctx.fill();
            ctx.shadowBlur = 0;
        }
    }

    // 2. SILENCE - Muzzle Seal
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y + 5); // Mouth area

        ctx.fillStyle = '#1e1b4b'; // Dark blue/purple
        ctx.strokeStyle = '#a855f7';
        ctx.lineWidth = 2;

        // Draw X mark
        const s = 10;
        ctx.beginPath();
        ctx.moveTo(-s, -s); ctx.lineTo(s, s);
        ctx.moveTo(s, -s); ctx.lineTo(-s, s);
        ctx.stroke();

        // Floating Runes
        ctx.font = '10px monospace';
        ctx.fillStyle = '#c084fc';
        ctx.textAlign = 'center';
        ctx.fillText('🤐', 0, -15 - Math.sin(t*5)*3);
    }

    // 3. BANISH - Ghostly Chains / Cage
    if (agent.banished && agent.visualStatus === 'NONE') {
        ctx.translate(0, -30); // Body center

        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.7;

        // Vertical Bars
        const w = 20;
        const h = 40;
        ctx.beginPath();
        ctx.moveTo(-w, -h); ctx.lineTo(-w, h);
        ctx.moveTo(w, -h); ctx.lineTo(w, h);
        ctx.stroke();

        // Orbiting Rings
        ctx.save();
        ctx.scale(1, 0.3);
        ctx.beginPath(); ctx.arc(0, Math.sin(t*2)*20, w+5, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 4. DoT - Rising Bubbles / Smoke
    if (agent.dotTimer > 0) {
        ctx.translate(0, -40);
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i/count) % 1;
            const y = -phase * 40;
            const x = Math.sin(phase * 10 + i) * 10;
            const size = (1-phase) * 6;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#a855f7'; // Poison/Shadow
            ctx.globalAlpha = (1-phase);
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
    }

    // 5. HoT - Spiraling +
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const angle = -t * 3;
        const radius = 25;

        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius * 0.3; // Flattened

        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('+', x, y);
    }

    ctx.restore();
}

export function drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
    const assets = SpriteManager.getUnitImages(agent.role, agent.team);
    const totalDuration = 0.5;
    const alpha = Math.max(0, agent.spawnTimer / totalDuration);
    const yOffset = -85 * scale; 

    ctx.save();
    ctx.translate(x, y + yOffset);
    const popScale = 1.0 + alpha * 0.2;
    ctx.scale(popScale, popScale);
    ctx.globalAlpha = alpha;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
    ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

    ctx.drawImage(assets.icon, -12, -12, 24, 24);

    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 2;
    ctx.strokeText(agent.role, 0, 28);
    ctx.fillText(agent.role, 0, 28);

    ctx.restore();
}

import { GameEngine, Agent } from "../game";
import { GameEvent, Team } from "../../types";
import { HexUtils } from "../utils";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING, UNIT_BODY_OFFSET } from "../../constants";

// Systems
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import * as VFXSpawners from "./vfx/spawners";

const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20;
// TA TUNING: Increased from 5.0s to 12.0s. 
// Auto-battler units have move/cast times that make 5s too strict for a Penta.
const KILL_STREAK_WINDOW = 12.0; 

export class VisualEventListener {
    // Kill Streak State: AgentID -> { Count, LastTime }
    private killStreaks = new Map<string, { count: number, lastTime: number }>();
    private firstBlood = false;

    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        // Reset Logic: If battle just started or reset, clear streaks
        if (engine.battleTime < 0.1) {
            this.killStreaks.clear();
            this.firstBlood = false;
        }

        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
            // This is the GROUND visual Y
            const visualGroundY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualGroundY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     // Highlight high damage
                     const isCrit = val > 100;
                     color = isCrit ? '#ef4444' : '#fff'; 
                     size = isCrit ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualGroundY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         // Reduced cast impact
                         camera.addTrauma(0.2); 
                     }
                 }
            }

            // 2. Kill Streaks (New)
            if (event.type === 'KILL' && event.sourceId) {
                const now = engine.battleTime;
                const killer = event.sourceId;
                const killerAgent = engine.agents.find(a => a.id === killer);

                // FIRST BLOOD LOGIC
                if (!this.firstBlood) {
                    this.firstBlood = true;
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        hud.addFloatingText(
                            killerAgent.px, 
                            killerAgent.py - kH - HUD_TEXT_OFFSET - 60, 
                            "FIRST BLOOD", 
                            "#ef4444", 
                            36, 
                            'KILL_STREAK'
                        );
                        camera.addTrauma(0.3);
                    }
                }

                let streak = 1;
                const existing = this.killStreaks.get(killer);

                if (existing) {
                    if (now - existing.lastTime <= KILL_STREAK_WINDOW) {
                        streak = existing.count + 1;
                    } else {
                        streak = 1; // Expired
                    }
                }

                this.killStreaks.set(killer, { count: streak, lastTime: now });

                // Trigger Visual if Streak > 1
                if (streak >= 2) {
                    let streakText = "";
                    let streakColor = "#fff";
                    let trauma = 0;

                    if (streak === 2) { streakText = "DOUBLE KILL"; streakColor = "#cbd5e1"; trauma = 0.2; }
                    else if (streak === 3) { streakText = "TRIPLE KILL"; streakColor = "#fcd34d"; trauma = 0.3; }
                    else if (streak === 4) { streakText = "QUADRA KILL"; streakColor = "#fb923c"; trauma = 0.4; }
                    else if (streak >= 5) { streakText = "PENTA KILL"; streakColor = "#ef4444"; trauma = 0.6; } // Epic

                    // Display above unit
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        // Offset higher than damage numbers
                        hud.addFloatingText(
                            killerAgent.px, 
                            killerAgent.py - kH - HUD_TEXT_OFFSET - 40, 
                            streakText, 
                            streakColor, 
                            32 + (streak * 4), // Scale up size with streak
                            'KILL_STREAK'
                        );

                        camera.addTrauma(trauma);
                    }
                }
            }

            // 3. VFX Handling
            switch (event.type) {
                case 'VISUAL_SLASH':
                    if (event.sourceId && event.targetId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        const target = engine.agents.find(a => a.id === event.targetId);
                        if (source && target) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                            const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                            const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                            VFXSpawners.spawnConnectorSlash(
                                vfx,
                                source.px, source.py - sH,
                                target.px, target.py - tH,
                                event.color || '#fff',
                                event.skill?.visual || 'SLASH'
                            );
                        }
                    }
                    break;

                case 'DAMAGE': 
                    const dmg = Math.abs(event.value || 0);
                    const isHeavy = dmg > 50; 

                    // Directional Impact Logic
                    let handled = false;
                    if (event.sourceId && event.targetId) {
                        const s = engine.agents.find(a => a.id === event.sourceId);
                        const t = engine.agents.find(a => a.id === event.targetId);
                        if (s && t) {
                            // Calc direction
                            // We use world coordinates (px, py) from Agent, which are flat.
                            const dx = t.px - s.px;
                            const dy = t.py - s.py;
                            const len = Math.sqrt(dx*dx + dy*dy);
                            if (len > 0) {
                                const dirX = dx / len;
                                const dirY = dy / len;

                                const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';

                                // CALCULATE DYNAMIC HIT HEIGHT
                                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;

                                VFXSpawners.spawnDirectionalImpact(
                                    vfx,
                                    event.pos.x, visualGroundY,
                                    bodyHeight, // Pass Z-height explicitly
                                    dirX, dirY,
                                    event.color || '#fff',
                                    type
                                );
                                handled = true;
                            }
                        }
                    }

                    if (!handled) {
                        // Fallback generic explosion
                        // Reduced particle count via factory
                        VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
                    }

                    if (isHeavy) {
                        // Only shake on heavy hits
                        camera.addTrauma(0.15);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualGroundY - 30; // Aim at chest

                            VFXSpawners.spawnBeam(vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(vfx, tx, ty, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    // Retrieve Role from sourceID mapping logic or store it in event
                    // Note: engine.agents might already have removed the dead unit, so we need to rely on the event data.
                    // Ideally, the event should carry the role. 
                    // Since GameEvent doesn't have 'role', we'll try to find the agent before it was removed (which is tricky here as Logic runs before visual).
                    // BUT: AgentManager sets 'fullyDead' flag but doesn't remove from array until restart/clear usually, or we can just fetch from id if available.

                    // Actually AgentManager removes from spatial map but keeps in agents list until clean up?
                    // Let's check GameEngine. It keeps agents in `this.agents` even if dead until `clear`.
                    const dyingAgent = engine.agents.find(a => a.id === event.sourceId);
                    if (dyingAgent) {
                        VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, team, dyingAgent.role);
                    }
                    camera.addTrauma(0.3); 
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    VFXSpawners.spawnDomainShatter(vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    camera.addTrauma(0.1);
                    break;
            }
        });
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        // Find target for Z correction
        const target = engine.agents.find(a => a.id === event.targetId);
        const hitZ = target ? (target.physics.z + UNIT_BODY_OFFSET) : 25;

        if (isUlt) {
            camera.addTrauma(0.4); // Ult impact
            VFXSpawners.spawnDivinePillar(vfx, event.pos.x, visualY, color, 1.2);
            VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, color, 1.5);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        // Reduced visual density for AOE tiles
                        if (Math.random() < 0.3) { 
                            VFXSpawners.spawnExplosion(vfx, tilePos.x, tileVisualY, 0, 3, color, 1.0, 0.5, 'SPARK');
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 2.0);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 2.0);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, hitZ, 30, color, 1.5, 0.8, 'SPARK');
            }
        } else {
            // Normal Projectile
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 0.8);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 0.6);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, hitZ, 12, color, 1.0, 0.5, 'SPARK');
            }
        }
    }
}

export interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'RING' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'SPIKE';
    targetX?: number; // For BEAM
    targetY?: number; // For BEAM
    delay?: number;
    image?: HTMLCanvasElement; // For SPRITE type (Unit parts)
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export interface GridFlash {
    q: number;
    r: number;
    color: string;
    life: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];
    public gridFlashes: GridFlash[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            p.image = undefined; // Reset image reference
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK' 
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        this.particlePool.push(p);
    }
}

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Shared translation
        ctx.translate(p.x, p.y);

        if (p.type === 'SPRITE') {
            // UNIT PARTS SHATTER
            if (p.image) {
                // Flash white at start of explosion
                if (progress < 0.1) {
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.filter = 'brightness(500%)';
                }

                const alpha = Math.min(1, (1 - progress) * 3); // Fade out only at very end
                ctx.globalAlpha = alpha;
                ctx.rotate(p.rotation);
                const scale = p.size / 64; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);

                ctx.filter = 'none';
            }

        } else if (p.type === 'SPIKE') {
            // DIRECTIONAL KINETIC IMPACT (Replaces Blast Ring)
            // Draws sharp, elongated triangles that stretch with velocity
            ctx.rotate(p.rotation); // Aligned with velocity in spawner

            const len = p.size * (1 + (1-progress) * 2); // Longer at start
            const width = p.size * 0.4 * (1-progress);   // Thinner over time

            ctx.fillStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10 * (1-progress);
            ctx.globalCompositeOperation = 'lighter';

            ctx.beginPath();
            ctx.moveTo(0, 0); // Tail
            ctx.lineTo(len, width); // Right wing
            ctx.lineTo(len * 1.5, 0); // Tip (extended)
            ctx.lineTo(len, -width); // Left wing
            ctx.closePath();
            ctx.fill();

            // Core streak
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(len * 1.2, 0);
            ctx.lineTo(0, 0);
            ctx.fill();

        } else if (p.type === 'SMOKE') {
            const r = p.size * (0.5 + progress * 2); // Expand
            ctx.globalAlpha = (1 - progress) * 0.5;
            ctx.fillStyle = p.color; // Usually grey/black
            ctx.beginPath();
            ctx.arc(0, 0, r, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'BLAST') {
            // Keeping legacy support but de-emphasized
            ctx.scale(1, 0.55); 
            const r = p.size * (progress * 2); 
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 10;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(-p.x, -p.y); 

                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); 
            if(isChaos) {
                for(let i=0; i<=16; i++) {
                    const a = (i/16)*Math.PI*2;
                    const rr = r * (1 + (Math.random()-0.5)*0.2);
                    if(i===0) ctx.moveTo(Math.cos(a)*rr, Math.sin(a)*rr);
                    else ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
                }
            } else {
                ctx.arc(0, 0, r, 0, Math.PI * 2); 
            }
            ctx.stroke();
            ctx.closePath();

        } else if (p.type === 'SPARK') {
            const speedSq = p.vx * p.vx + p.vy * p.vy;
            // Enhanced Stretch
            if (speedSq > 50) {
                const angle = Math.atan2(p.vy, p.vx);
                ctx.rotate(angle);
                const stretch = Math.min(6.0, 1.0 + Math.sqrt(speedSq) * 0.01);
                ctx.scale(stretch, 1.0 / Math.max(1.0, stretch * 0.3));
            }

            const r = p.size;
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.4, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.beginPath();
            const s = p.size;
            if (p.type === 'SHARD') {
                ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            } else {
                ctx.rect(-s/2, -s/2, s, s);
            }
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.lineWidth = 1;
            ctx.stroke();
        } else if (p.type === 'PILLAR') {
            ctx.translate(0, -20); 
            this.drawPillar(ctx, p, progress, isChaos);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawDomain(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        // ... (Existing Pillar Logic)
        ctx.globalCompositeOperation = 'lighter';
        const lifeRatio = p.life / p.maxLife;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 
        const height = 1200; 
        const baseWidth = 60 * (1 + Math.sin(progress * 20) * 0.1);

        ctx.save();
        ctx.scale(1, 0.55); 
        const ringSize = baseWidth * 2;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.2, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : '#fff');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        if (isChaos) {
            const chaosGrad = ctx.createLinearGradient(0, 0, 0, -height);
            chaosGrad.addColorStop(0, p.color);
            chaosGrad.addColorStop(0.5, 'transparent');
            ctx.fillStyle = chaosGrad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.beginPath();
            const segs = 10;
            const hw = baseWidth / 2;
            ctx.moveTo(-hw, 0);
            for(let i=1; i<=segs; i++) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(-hw + xOff, y);
            }
            for(let i=segs; i>=0; i--) {
                const y = -height * (i/segs);
                const xOff = (Math.random()-0.5) * 20;
                ctx.lineTo(hw + xOff, y);
            }
            ctx.closePath();
            ctx.fill();
        } else {
            const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
            coreGrad.addColorStop(0, '#ffffff');
            coreGrad.addColorStop(0.3, '#ffffff');
            coreGrad.addColorStop(1, 'transparent');
            ctx.fillStyle = coreGrad;
            ctx.globalAlpha = alpha;
            ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);
            const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
            glowGrad.addColorStop(0, p.color);
            glowGrad.addColorStop(0.7, 'transparent');
            ctx.fillStyle = glowGrad;
            ctx.globalAlpha = alpha * 0.5;
            ctx.fillRect(-baseWidth, -height, baseWidth * 2, height);
        }
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        // ... (Existing Shockwave logic)
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';
        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress);
        ctx.beginPath(); 
        if (isChaos) {
            for(let i=0; i<=32; i++) {
                const a = (i/32)*Math.PI*2;
                const d = r + (Math.random()-0.5) * 30;
                if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
            }
        } else {
            ctx.arc(0, 0, r, 0, Math.PI * 2); 
        }
        ctx.closePath();
        ctx.stroke();
    },

    drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         // ... (Existing Domain logic)
         ctx.scale(1, 0.55); 
         const time = performance.now() / 1000;
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;
         ctx.globalCompositeOperation = 'lighter'; 
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 
         const safeColor = normalizeHex(p.color);
         grad.addColorStop(0.7, safeColor + '4D'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');
         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.5 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;
         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         if (isChaos) {
             ctx.setLineDash([10, 25]); 
             ctx.beginPath();
             for(let i=0; i<=12; i++) {
                 const a = (i/12)*Math.PI*2;
                 const d = r * 0.95 + (i%2===0 ? 15 : -15);
                 if(i===0) ctx.moveTo(Math.cos(a)*d, Math.sin(a)*d);
                 else ctx.lineTo(Math.cos(a)*d, Math.sin(a)*d);
             }
             ctx.closePath();
             ctx.stroke();
         } else {
             ctx.setLineDash([50, 20]); 
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
             ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); 
             ctx.setLineDash([20, 10]);
             ctx.stroke();
         }
         ctx.restore();
         ctx.globalAlpha = 0.3 * (1 - progress);
         const spikeCount = isChaos ? 8 : 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + (isChaos ? -time : time);
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;
             ctx.beginPath();
             ctx.moveTo(sx, sy);
             const topX = sx + (isChaos ? (Math.random()-0.5)*40 : 0);
             ctx.lineTo(topX, sy - 100); 
             ctx.lineWidth = 4;
             const beamGrad = ctx.createLinearGradient(sx, sy, topX, sy - 100);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

export function spawnDirectionalImpact(
    system: VFXSystem, 
    x: number, y: number, z: number,
    dirX: number, dirY: number, 
    color: string, 
    type: 'PHYSICAL' | 'MAGICAL'
) {
    const isPhysical = type === 'PHYSICAL';

    // 1. DIRECTIONAL KINETIC SPIKES (The "Punch")
    const baseAngle = Math.atan2(dirY, dirX);
    const spikeCount = isPhysical ? 5 : 7;
    const spread = 0.6; // 30-40 degrees spread

    for (let i = 0; i < spikeCount; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 400 + Math.random() * 300; // Extremely fast
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = (Math.random() - 0.5) * 50; // Mostly flat trajectory

        p.life = 0.15 + Math.random() * 0.1; // Very short life (Snap)
        p.maxLife = p.life;
        p.color = color;
        p.size = 30 + Math.random() * 20; // Large spikes
        p.type = 'SPIKE';
        p.rotation = angle; // Point in direction of travel
        p.delay = 0;

        system.state.particles.push(p);
    }

    // 2. High Velocity Sparks (Debris)
    const count = isPhysical ? 12 : 16;
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * 1.5; // Wider cone
        const speed = 200 + Math.random() * 300;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 100 + Math.random() * 200; // High vertical spray

        p.life = 0.4 + Math.random() * 0.3;
        p.maxLife = p.life;
        p.color = color;
        p.size = Math.random() * 4 + 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // 3. Central Flash
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = z;
    flash.vx = 0; flash.vy = 0; flash.vz = 0;
    flash.life = 0.1; flash.maxLife = 0.1;
    flash.color = '#fff';
    flash.size = 40; 
    flash.type = 'GLOW';
    system.state.particles.push(flash);
}

export function spawnConnectorSlash(
    system: VFXSystem,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string,
    visual: string
) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;

    p.life = 0.25; 
    p.maxLife = 0.25;
    p.color = color;
    p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);

    // Helper to spawn a physical sprite chunk with EXPLOSIVE force
    const spawnPart = (img: HTMLCanvasElement, scale: number, zBase: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = zBase; 

        // Explosion Pattern: Outward from center
        const angle = Math.random() * Math.PI * 2;
        const dist = 300 + Math.random() * 200; // Strong horizontal push

        p.vx = Math.cos(angle) * dist;
        p.vy = Math.sin(angle) * dist;
        p.vz = 200 + Math.random() * 200; // Medium Upward pop

        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff';
        p.size = 64 * scale; 
        p.type = 'SPRITE';
        p.image = img;

        // Violent Tumbling
        p.rotation = Math.random() * Math.PI * 2;
        p.vRotation = (Math.random() - 0.5) * 30; 

        system.state.particles.push(p);
    };

    // 1. Parts flying EVERYWHERE
    spawnPart(assets.weapon, 0.8, 60);
    spawnPart(assets.icon, 0.6, 80);

    // 2. Base Plate - Heavy piece, stays lower but slides fast
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    const angle = Math.random() * Math.PI * 2;
    p.vx = Math.cos(angle) * 150; 
    p.vy = Math.sin(angle) * 150;
    p.vz = 100; 
    p.life = 2.0; p.maxLife = 2.0;
    p.color = '#fff';
    p.size = 64; 
    p.type = 'SPRITE';
    p.image = assets.base;
    p.rotation = 0;
    p.vRotation = (Math.random() - 0.5) * 5; 
    system.state.particles.push(p);

    // 3. Ground Scorch (Permanent Decal)
    addDecal(system, x, y, '#000'); // Black scorch

    // 4. Smoke Column (The "Poof")
    for(let i=0; i<5; i++) {
        const smk = system.state.getParticle();
        smk.x = x + (Math.random()-0.5)*20;
        smk.y = y + (Math.random()-0.5)*20;
        smk.z = 10;
        smk.vx = (Math.random()-0.5) * 50;
        smk.vy = (Math.random()-0.5) * 50;
        smk.vz = 50 + Math.random() * 100; // Rise up
        smk.life = 1.5; smk.maxLife = 1.5;
        smk.color = '#52525b'; // Dark grey
        smk.size = 20 + Math.random() * 20;
        smk.type = 'SMOKE';
        system.state.particles.push(smk);
    }

    // 5. Core Explosion (Juice)
    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';
    spawnExplosion(system, x, y, 30, 30, coreColor, 2.0, 0.5, 'SPARK');
    // Radial spikes for death burst
    for(let i=0; i<8; i++) {
        spawnDirectionalImpact(system, x, y, 20, Math.cos(i/8*Math.PI*2), Math.sin(i/8*Math.PI*2), coreColor, 'PHYSICAL');
    }
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); 

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 

        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 20 + Math.random() * 30;

        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Center "Poof"
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
    addImpact(system, x, y, 5, '#ffffff', 'RING', 0.15);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
