import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171'; // Blue-400 : Red-400

    // We are at Ground Level (0,0).
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. "Divine Light" Lift Column (Gradient Fill)
    const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
    // Transparent at bottom to blend with ground, stronger at top to show lift source
    grad.addColorStop(0, isBlue ? 'rgba(96, 165, 250, 0.0)' : 'rgba(248, 113, 113, 0.0)');
    grad.addColorStop(0.3, isBlue ? 'rgba(96, 165, 250, 0.1)' : 'rgba(248, 113, 113, 0.1)');
    grad.addColorStop(1.0, isBlue ? 'rgba(96, 165, 250, 0.3)' : 'rgba(248, 113, 113, 0.3)');

    // Column Shape (Tapered Cylinder)
    const baseW = 15; 
    const topW = 10;  

    ctx.beginPath();
    ctx.moveTo(-baseW, 0);
    ctx.lineTo(feetX - topW, feetY);
    ctx.lineTo(feetX + topW, feetY);
    ctx.lineTo(baseW, 0);
    ctx.fill();

    // 2. Rising Energy Streams / Rings
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;

    const height = Math.abs(feetY);
    const ringCount = Math.max(2, Math.floor(height / 25));

    for(let i=0; i<ringCount; i++) {
        const phase = (t * 1.5 + i / ringCount) % 1; 
        const curX = feetX * phase;
        const curY = feetY * phase;
        const curW = baseW + (topW - baseW) * phase;
        const alpha = Math.sin(phase * Math.PI); 

        ctx.globalAlpha = alpha * 0.5;
        ctx.beginPath();
        ctx.ellipse(curX, curY, curW, curW * 0.5, 0, 0, Math.PI * 2);
        ctx.stroke();
    }

    // 3. Ground Anchor Ring (The Mechanical Projector lens)
    ctx.globalAlpha = 1.0;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(0, 0, 20, 10, 0, 0, Math.PI * 2);
    ctx.stroke();

    // Crosshair Center
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-5, 0); ctx.lineTo(5, 0);
    ctx.moveTo(0, -3); ctx.lineTo(0, 3);
    ctx.stroke();

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 5); 

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    ctx.arc(0, 0, 15 + Math.sin(t * 15) * 2, 0, Math.PI * 1.5);
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.7;
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -60; 

    // 1. FROZEN - ICE PRISM (Encasing the unit)
    if (agent.visualStatus === 'FROZEN') {
        ctx.save();
        ctx.translate(0, -40); // Center of body

        // Draw Hexagonal Prism
        const w = 30;
        const h = 50;

        ctx.globalCompositeOperation = 'source-over';
        // Back Faces
        ctx.fillStyle = 'rgba(186, 230, 253, 0.4)'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(-w, -h); ctx.lineTo(w, -h); ctx.lineTo(w, h); ctx.lineTo(-w, h);
        ctx.fill();

        // Front Faces (Glassy)
        const grad = ctx.createLinearGradient(-w, -h, w, h);
        grad.addColorStop(0, 'rgba(255,255,255,0.6)');
        grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.3)');
        grad.addColorStop(1, 'rgba(14, 165, 233, 0.5)');

        ctx.fillStyle = grad;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(0, -h - 10); // Top Tip
        ctx.lineTo(w + 5, -h + 10);
        ctx.lineTo(w, h);
        ctx.lineTo(0, h + 10); // Bottom Tip
        ctx.lineTo(-w, h);
        ctx.lineTo(-w - 5, -h + 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Glint
        ctx.globalCompositeOperation = 'lighter';
        ctx.beginPath();
        ctx.moveTo(0, -h-10); ctx.lineTo(0, h+10);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.stroke();

        ctx.restore();
    }

    // 2. BANISH - GHOSTLY CAGE (Rotates around unit)
    if (agent.banished && agent.visualStatus !== 'POLYMORPH') {
        ctx.translate(0, -30); // Body center

        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;

        // Vertical Bars orbiting (Simulated 3D Cylinder)
        const bars = 5;
        const radius = 25;
        const height = 50;

        for(let i=0; i<bars; i++) {
            // Rotate bars over time
            const angle = t * 2 + (i / bars) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle); // Depth

            // Perspective scale
            const scale = 1 + z * 0.1;
            const alpha = 0.5 + (z + 1) * 0.25; // Fade back bars

            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(x, -height);
            ctx.lineTo(x, height);
            ctx.stroke();

            // Runes on bars
            if (i % 2 === 0) {
                ctx.fillStyle = '#d8b4fe';
                ctx.beginPath(); ctx.arc(x, -height/2 + Math.sin(t*3+i)*10, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        // Top and Bottom Rings
        ctx.globalAlpha = 0.6;
        ctx.save();
        ctx.scale(1, 0.3); // Isometric
        ctx.beginPath(); ctx.arc(0, -height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. STUN - 3D DIZZY RING
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        ctx.translate(0, HEAD_Y - 10);

        ctx.globalCompositeOperation = 'lighter';
        ctx.lineWidth = 3;

        const count = 5;
        const radius = 25;

        // Orbiting Stars
        for(let i=0; i<count; i++) {
            const angle = t * 4 + (i / count) * Math.PI * 2;
            // 3D Orbit: Y is squashed
            const x = Math.cos(angle) * radius;
            const y = Math.sin(angle) * radius * 0.3;
            // Z-sort simulation: if sin(angle) > 0, it's in front
            const scale = 1 + Math.sin(angle) * 0.3;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(scale, scale);

            ctx.fillStyle = '#facc15';
            ctx.shadowColor = '#fbbf24';
            ctx.shadowBlur = 10;

            // Draw Star
            ctx.beginPath();
            const starPts = 5;
            for(let j=0; j<starPts*2; j++) {
                const r = j%2===0 ? 6 : 2;
                const a = j * Math.PI / starPts;
                ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            }
            ctx.fill();
            ctx.restore();
        }
    }

    // 4. SILENCE - FLOATING RUNE SEAL
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y - 15);

        const scale = 1 + Math.sin(t * 5) * 0.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1e1b4b'; 
        ctx.strokeStyle = '#a855f7';
        ctx.lineWidth = 2;
        ctx.shadowColor = '#c084fc';
        ctx.shadowBlur = 10;

        // Rune Box
        ctx.beginPath();
        ctx.rect(-15, -10, 30, 20);
        ctx.fill();
        ctx.stroke();

        // "X" or Rune Text
        ctx.beginPath();
        ctx.moveTo(-8, -5); ctx.lineTo(8, 5);
        ctx.moveTo(8, -5); ctx.lineTo(-8, 5);
        ctx.stroke();
    }

    // 5. DoT - Rising Bubbles / Smoke
    if (agent.dotTimer > 0) {
        ctx.translate(0, -40);
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i/count) % 1;
            const y = -phase * 40;
            const x = Math.sin(phase * 10 + i) * 10;
            const size = (1-phase) * 6;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#a855f7'; 
            ctx.globalAlpha = (1-phase);
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
    }

    // 6. HoT - Spiraling +
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const angle = -t * 3;
        const radius = 25;

        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius * 0.3; // Flattened

        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('+', x, y);
    }

    ctx.restore();
}

export function drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
    const assets = SpriteManager.getUnitImages(agent.role, agent.team);
    const totalDuration = 0.5;
    const alpha = Math.max(0, agent.spawnTimer / totalDuration);
    const yOffset = -85 * scale; 

    ctx.save();
    ctx.translate(x, y + yOffset);
    const popScale = 1.0 + alpha * 0.2;
    ctx.scale(popScale, popScale);
    ctx.globalAlpha = alpha;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
    ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

    ctx.drawImage(assets.icon, -12, -12, 24, 24);

    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 2;
    ctx.strokeText(agent.role, 0, 28);
    ctx.fillText(agent.role, 0, 28);

    ctx.restore();
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // 1. ANIMATION STATE CALCULATION
        // Body Float: Gentle vertical motion
        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 2 : 0;

        // Attack Animation Vars
        let armRot = 0;     // Weapon rotation
        let armX = 0;       // Weapon reach
        let armY = 0;
        let bodyRecoil = 0; // Body moving back slightly during hit

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                // Ranged/Magic: Thrust forward / Recoil
                if (p < 0.3) { // Windup
                    armX = -5 * (p/0.3);
                    armRot = -0.2 * (p/0.3);
                } else if (p < 0.5) { // Shoot
                    armX = 10;
                    bodyRecoil = -2;
                } else { // Recover
                    armX = 10 * (1 - (p-0.5)/0.5);
                    bodyRecoil = -2 * (1 - (p-0.5)/0.5);
                }
            } else {
                // Melee: Swing Arc
                if (p < 0.3) { // Windup (Back)
                    armRot = -Math.PI / 3 * (p/0.3); 
                    armX = -5;
                } else if (p < 0.5) { // Swing (Forward Smash)
                    const swingP = (p - 0.3) / 0.2;
                    armRot = -Math.PI / 3 + (Math.PI / 1.5) * swingP; // Swing 120 degrees
                    armX = 15 * swingP;
                } else { // Recover
                    const recP = (p - 0.5) / 0.5;
                    armRot = Math.PI / 3 * (1 - recP);
                    armX = 15 * (1 - recP);
                }
            }
        }

        ctx.save();

        // Apply Silhouette settings if needed
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoil, floatY);
            // Simple box for occlusion
            ctx.strokeRect(-15, -60, 30, 60);
            ctx.restore();
            return;
        }

        // --- RIM LIGHT (OUTLINE) ---
        // Adds visibility on dark backgrounds
        if (agent.hp > 0) {
            ctx.shadowColor = 'rgba(255, 255, 255, 0.4)';
            ctx.shadowBlur = 10;
        }

        // --- RENDER START ---

        // Apply Global Position Offsets
        ctx.translate(bodyRecoil, floatY);

        // --- 1. BACK WEAPON / CAPE (Layer 0) ---
        // Imperial Cape
        drawCape(ctx, t, '#2563eb');

        // --- 2. OFF-HAND (Shield/Book) - Right Hand (Screen Left) ---
        // For Tank/Support, they hold something here.
        ctx.save();
        ctx.translate(-20, -35); // Left Shoulder position
        // Idle bob for offhand
        ctx.translate(0, Math.sin(t * 2.5 + 1) * 2); 

        if (agent.role === Role.TANK) {
            drawImperialShield(ctx);
        } else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) {
            drawImperialTome(ctx, t);
        }
        ctx.restore();

        // --- 3. BODY (Torso + Head) ---
        drawImperialBody(ctx, agent.role);

        // --- 4. MAIN HAND (Weapon) - Left Hand (Screen Right) ---
        ctx.save();
        ctx.translate(20, -35); // Right Shoulder pivot
        ctx.rotate(armRot);     // Apply Attack Rotation
        ctx.translate(armX, armY); // Apply Reach

        drawImperialWeapon(ctx, agent.role, t);

        ctx.restore();

        // Turn off glow for status effects
        ctx.shadowBlur = 0;

        ctx.restore();
    }
};

// --- SUB-COMPONENT RENDERERS ---

function drawImperialBody(ctx: CanvasRenderingContext2D, role: Role) {
    const primary = '#2563eb'; // Blue
    const secondary = '#facc15'; // Gold
    const armorLight = '#f8fafc'; // White ceramic
    const armorDark = '#1e3a8a';  // Dark Blue

    // Torso Gradient
    const grad = ctx.createLinearGradient(-15, -50, 15, 0);
    grad.addColorStop(0, armorLight);
    grad.addColorStop(0.5, armorDark);
    grad.addColorStop(1, primary);

    ctx.fillStyle = grad;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1.5;

    // Armor Shape
    ctx.beginPath();
    if (role === Role.TANK) {
        // Heavy Plate
        ctx.moveTo(-22, -45); ctx.lineTo(22, -45); // Wide Shoulders
        ctx.lineTo(15, 0); ctx.lineTo(-15, 0);     // Waist
        ctx.lineTo(-22, -45);
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // Robe Form
        ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
        ctx.lineTo(18, 10); ctx.lineTo(-18, 10);
        ctx.lineTo(-12, -45);
    } else {
        // Standard Plate
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(12, 5); ctx.lineTo(-12, 5);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    // Core Crystal (Soul)
    ctx.fillStyle = '#fff';
    // Inner glow
    ctx.beginPath(); ctx.moveTo(0, -35); ctx.lineTo(6, -25); ctx.lineTo(0, -15); ctx.lineTo(-6, -25); ctx.fill();

    // Head
    ctx.save();
    ctx.translate(0, -50);

    // Halo
    if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.strokeStyle = secondary;
        ctx.beginPath(); ctx.arc(0, -5, 16, 0, Math.PI*2); ctx.stroke();
    }

    ctx.fillStyle = armorLight;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (role === Role.TANK) ctx.rect(-10, -12, 20, 18); // Square Helm
    else ctx.ellipse(0, -2, 9, 11, 0, 0, Math.PI*2);    // Round Helm
    ctx.fill(); ctx.stroke();

    // Visor
    ctx.fillStyle = primary;
    ctx.fillRect(-8, -4, 16, 3);

    ctx.restore();
}

function drawCape(ctx: CanvasRenderingContext2D, t: number, color: string) {
    ctx.save();
    ctx.translate(0, -45);
    const wave = Math.sin(t * 3) * 5;
    ctx.fillStyle = 'rgba(30, 58, 138, 0.8)'; // Dark Blue liner
    ctx.beginPath();
    ctx.moveTo(-10, 0);
    ctx.lineTo(-15 + wave, 50);
    ctx.lineTo(15 + wave, 50);
    ctx.lineTo(10, 0);
    ctx.fill();
    ctx.restore();
}

function drawImperialHand(ctx: CanvasRenderingContext2D) {
    // "Servo-Hand": A floating sphere that magnetically holds weapons
    ctx.fillStyle = '#1e293b'; // Dark joint
    ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#facc15'; // Gold plate
    ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
}

function drawImperialShield(ctx: CanvasRenderingContext2D) {
    drawImperialHand(ctx);

    // Tower Shield
    ctx.translate(-5, 10); // Offset from hand
    ctx.rotate(-Math.PI/12); // Tilt

    // Shield Body
    const grad = ctx.createLinearGradient(0, -30, 0, 30);
    grad.addColorStop(0, '#f8fafc');
    grad.addColorStop(1, '#2563eb');

    ctx.fillStyle = grad;
    ctx.strokeStyle = '#facc15';
    ctx.lineWidth = 3;

    ctx.beginPath();
    ctx.moveTo(-15, -30); ctx.lineTo(15, -30); // Top
    ctx.lineTo(15, 10);   // Right vertical
    ctx.lineTo(0, 40);    // Bottom tip
    ctx.lineTo(-15, 10);  // Left vertical
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Energy Cross
    ctx.fillStyle = '#60a5fa';
    ctx.fillRect(-5, -20, 10, 40);
    ctx.fillRect(-12, -5, 24, 10);
}

function drawImperialTome(ctx: CanvasRenderingContext2D, t: number) {
    drawImperialHand(ctx);
    ctx.translate(0, -10);
    // Floating Book
    ctx.fillStyle = '#fff';
    ctx.fillRect(-10, -12, 20, 24); // Pages
    ctx.fillStyle = '#2563eb';
    ctx.fillRect(-12, -12, 4, 24); // Spine

    // Magic particles
    if (Math.sin(t*5) > 0) {
        ctx.fillStyle = '#facc15';
        ctx.fillRect(5, -20, 2, 2);
        ctx.fillRect(8, -25, 2, 2);
    }
}

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawImperialHand(ctx); // The Servo Hand

    if (role === Role.WARRIOR) {
        // ENERGY CLAYMORE
        ctx.rotate(Math.PI / 2); // Point forward

        // Hilt
        ctx.fillStyle = '#475569';
        ctx.fillRect(-4, -10, 8, 20); // Grip
        ctx.fillStyle = '#facc15';
        ctx.fillRect(-12, -10, 24, 4); // Crossguard

        // Blade (Energy)
        ctx.fillStyle = 'rgba(147, 197, 253, 0.8)'; // Light blue glass
        ctx.strokeStyle = '#2563eb';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(-6, -10); 
        ctx.lineTo(-4, -70); // Tip Left
        ctx.lineTo(0, -80);  // Point
        ctx.lineTo(4, -70);  // Tip Right
        ctx.lineTo(6, -10);  // Base
        ctx.fill(); ctx.stroke();

    } else if (role === Role.TANK) {
        // POWER MACE
        ctx.rotate(Math.PI / 3); // Held angled

        // Handle
        ctx.fillStyle = '#475569';
        ctx.fillRect(-3, -10, 6, 50);

        // Head
        ctx.translate(0, -50);
        ctx.fillStyle = '#f8fafc';
        ctx.strokeStyle = '#facc15';
        ctx.lineWidth = 2;

        // Central Block
        ctx.fillRect(-12, -15, 24, 30);
        ctx.strokeRect(-12, -15, 24, 30);

        // Flanges
        ctx.fillStyle = '#2563eb';
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(-20, 0); ctx.lineTo(0, 15); ctx.fill();
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(20, 0); ctx.lineTo(0, 15); ctx.fill();

    } else if (role === Role.RANGER) {
        // COMPOSITE BOW
        // Held vertically
        ctx.translate(10, 0);

        ctx.strokeStyle = '#f8fafc';
        ctx.lineWidth = 3;

        // Bow Arc
        ctx.beginPath();
        ctx.arc(0, 0, 30, -Math.PI/2 - 0.5, Math.PI/2 + 0.5);
        ctx.stroke();

        // Energy String
        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, -30); ctx.lineTo(0, 30);
        ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // STAFF
        ctx.rotate(-Math.PI / 6); // Angled back

        // Shaft
        ctx.fillStyle = '#b45309'; // Wood/Gold
        ctx.fillRect(-3, -40, 6, 80);

        // Head
        ctx.translate(0, -45);

        // Floating Crystal
        const float = Math.sin(t * 4) * 3;
        ctx.translate(0, float);

        ctx.fillStyle = role === Role.MAGE ? '#3b82f6' : '#facc15';

        ctx.beginPath();
        ctx.moveTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10); ctx.lineTo(-8, 0);
        ctx.fill();

        // Orbitals
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, 14, 0, Math.PI*2); ctx.stroke();
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 

        // 1. ANIMATION STATE
        // Jittery Hover (Unstable)
        const floatY = (agent.hp > 0) ? Math.sin(t * 5) * 1.5 + (Math.random()-0.5) : 0;

        // Attack Vars
        let armRot = 0;
        let armX = 0;
        let armY = 0;
        let bodyRecoil = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                // Ranged: Violent jerk
                if (p < 0.4) { // Tense up
                    armX = -2;
                    bodyRecoil = 1;
                } else if (p < 0.5) { // Fire
                    armX = 15;
                    armY = -5; // Recoil up
                    bodyRecoil = -5;
                } else { // Recover
                    const rec = (p-0.5)/0.5;
                    armX = 15 * (1-rec);
                    armY = -5 * (1-rec);
                    bodyRecoil = -5 * (1-rec);
                }
            } else {
                // Melee: Heavy Chop
                if (p < 0.4) { // Raise High
                    armRot = -Math.PI / 1.8 * (p/0.4); 
                    armX = -5;
                    armY = -10;
                } else if (p < 0.6) { // SLAM
                    const swingP = (p - 0.4) / 0.2;
                    // Overshoot rotation for impact feeling
                    armRot = -Math.PI / 1.8 + (Math.PI) * swingP; 
                    armX = 20 * swingP;
                    armY = 10 * swingP;
                } else { // Drag back
                    const recP = (p - 0.6) / 0.4;
                    armRot = (Math.PI - Math.PI/1.8) * (1 - recP); // Return from end pos
                    armX = 20 * (1 - recP);
                    armY = 10 * (1 - recP);
                }
            }
        }

        ctx.save();

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoil, floatY);
            // Spiky box
            ctx.beginPath();
            ctx.moveTo(-15, -60); ctx.lineTo(0, -70); ctx.lineTo(15, -60);
            ctx.lineTo(10, 0); ctx.lineTo(-10, 0); ctx.closePath();
            ctx.stroke();
            ctx.restore();
            return;
        }

        // --- RIM LIGHT (OUTLINE) ---
        // Adds visibility on dark backgrounds
        if (agent.hp > 0) {
            ctx.shadowColor = 'rgba(239, 68, 68, 0.4)'; // Reddish glow for Covenant
            ctx.shadowBlur = 10;
        }

        // --- RENDER START ---
        ctx.translate(bodyRecoil, floatY);

        // --- 1. BACK SPIKES (Layer 0) ---
        drawSpikes(ctx, t);

        // --- 2. OFF-HAND (Shield/Totem) - Screen Left ---
        ctx.save();
        ctx.translate(-22, -30);
        // Heavy breathing motion
        ctx.translate(0, Math.sin(t * 3) * 1);

        if (agent.role === Role.TANK) {
            drawCovenantShield(ctx);
        } else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) {
            drawCovenantTotem(ctx, t);
        }
        ctx.restore();

        // --- 3. BODY ---
        drawCovenantBody(ctx, agent.role);

        // --- 4. MAIN HAND (Weapon) - Screen Right ---
        ctx.save();
        ctx.translate(22, -30); // Shoulder
        ctx.rotate(armRot);
        ctx.translate(armX, armY);

        drawCovenantWeapon(ctx, agent.role, t);

        ctx.restore();

        // Turn off glow
        ctx.shadowBlur = 0;

        ctx.restore();
    }
};

// --- SUB-RENDERERS ---

function drawCovenantBody(ctx: CanvasRenderingContext2D, role: Role) {
    const primary = '#b91c1c'; // Blood Red
    const darkMetal = '#18181b'; // Obsidian
    const glow = '#ef4444'; // Bright Red

    // Body Gradient
    const grad = ctx.createLinearGradient(-15, -50, 15, 10);
    grad.addColorStop(0, primary);
    grad.addColorStop(0.6, darkMetal);
    grad.addColorStop(1, '#000');

    ctx.fillStyle = grad;
    ctx.strokeStyle = '#7f1d1d'; // Rust
    ctx.lineWidth = 1;

    // Shape: Angular/Coffin
    ctx.beginPath();
    if (role === Role.TANK) {
        // Bulk
        ctx.moveTo(-25, -40); ctx.lineTo(25, -40); // Broad shoulders
        ctx.lineTo(15, 10); ctx.lineTo(-15, 10);
        ctx.lineTo(-25, -40);
    } else {
        // Sharp
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(8, 15); ctx.lineTo(-8, 15);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    // Magma Fissure (Center Chest)
    ctx.strokeStyle = glow;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -35);
    ctx.lineTo((Math.random()-0.5)*5, -25);
    ctx.lineTo(0, -15);
    ctx.stroke();

    // Head
    ctx.save();
    ctx.translate(0, -48);

    ctx.fillStyle = darkMetal;
    ctx.beginPath();
    // Horned Helm
    ctx.moveTo(-10, 5); ctx.lineTo(-12, -15); ctx.lineTo(-5, -5); 
    ctx.lineTo(5, -5); ctx.lineTo(12, -15); ctx.lineTo(10, 5);
    ctx.fill();

    // Cyclops Eye
    ctx.fillStyle = '#fca5a5';
    ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

    ctx.restore();
}

function drawSpikes(ctx: CanvasRenderingContext2D, t: number) {
    ctx.save();
    ctx.translate(0, -40);
    ctx.fillStyle = '#27272a';
    ctx.beginPath();
    // Asymmetric spikes
    ctx.moveTo(-10, 0); ctx.lineTo(-25, -30 + Math.sin(t*5)*2); ctx.lineTo(-15, 0);
    ctx.moveTo(10, 0); ctx.lineTo(20, -25 + Math.cos(t*4)*2); ctx.lineTo(15, 0);
    ctx.fill();
    ctx.restore();
}

function drawCovenantHand(ctx: CanvasRenderingContext2D) {
    // "Fused Gauntlet": Angular block attached to arm
    ctx.fillStyle = '#450a0a'; // Dark Red Iron
    ctx.beginPath(); 
    ctx.moveTo(-6, -6); ctx.lineTo(6, -6); ctx.lineTo(4, 8); ctx.lineTo(-4, 8);
    ctx.fill();
}

function drawCovenantShield(ctx: CanvasRenderingContext2D) {
    drawCovenantHand(ctx);
    ctx.translate(-5, 10);

    // Scrap Wall Shield
    ctx.fillStyle = '#27272a'; // Iron
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;

    ctx.beginPath();
    // Jagged Octagon
    ctx.moveTo(-15, -25); ctx.lineTo(15, -20);
    ctx.lineTo(20, 0); ctx.lineTo(10, 25);
    ctx.lineTo(-15, 20); ctx.lineTo(-20, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Spikes on shield
    ctx.fillStyle = '#7f1d1d';
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, -35); ctx.lineTo(5, -10); ctx.fill();
}

function drawCovenantTotem(ctx: CanvasRenderingContext2D, t: number) {
    drawCovenantHand(ctx);
    ctx.translate(0, 10); // Hold low

    // Totem Pole
    ctx.fillStyle = '#3f3f46';
    ctx.fillRect(-4, -40, 8, 50);

    // Skull/Orb top
    ctx.translate(0, -45);
    ctx.fillStyle = '#ef4444';
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10);
    ctx.fill();
}

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawCovenantHand(ctx);

    if (role === Role.WARRIOR) {
        // BATTLE AXE
        ctx.rotate(Math.PI / 4); // Forward

        // Haft
        ctx.fillStyle = '#27272a';
        ctx.fillRect(-3, -10, 6, 60); // Long handle

        // Blade Head
        ctx.translate(0, -60); // Top of handle
        ctx.fillStyle = '#52525b'; // Steel
        ctx.strokeStyle = '#ef4444'; // Red edge
        ctx.lineWidth = 1;

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(-25, -10); // Top tip
        ctx.quadraticCurveTo(-15, 10, -25, 30); // Blade edge curve
        ctx.lineTo(0, 20);
        ctx.fill(); ctx.stroke();

        // Spike on back
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(10, 5); ctx.lineTo(0, 10); ctx.fill();

    } else if (role === Role.TANK) {
        // MEAT CLEAVER
        ctx.rotate(Math.PI / 3);

        ctx.fillStyle = '#27272a';
        ctx.fillRect(-4, -5, 8, 20); // Handle

        ctx.fillStyle = '#7f1d1d'; // Rusted Metal
        ctx.beginPath();
        ctx.moveTo(-10, -10);
        ctx.lineTo(-10, -60); // Back spine
        ctx.lineTo(20, -60);  // Top flat
        ctx.lineTo(20, -10);  // Blade edge vertical
        ctx.lineTo(0, 0);
        ctx.fill();

        // Blood edge
        ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(20, -60); ctx.lineTo(20, -10); ctx.stroke();

    } else if (role === Role.RANGER) {
        // HEAVY CROSSBOW
        ctx.rotate(-Math.PI / 2); // Pointing forward

        ctx.fillStyle = '#18181b';
        ctx.fillRect(-5, -30, 10, 40); // Stock

        // Bow Arms
        ctx.strokeStyle = '#7f1d1d';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-25, -25); ctx.lineTo(0, -30); ctx.lineTo(25, -25);
        ctx.stroke();

        // String
        ctx.strokeStyle = '#52525b'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, 0); ctx.lineTo(25, -25); ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // RITUAL DAGGER / WAND
        ctx.rotate(Math.PI / 6);

        ctx.fillStyle = '#450a0a';
        ctx.beginPath();
        ctx.moveTo(0, 10);
        ctx.lineTo(-5, -30); // Wavy blade
        ctx.lineTo(0, -50);  // Point
        ctx.lineTo(5, -30);
        ctx.fill();

        // Glow Tip
        ctx.fillStyle = '#ef4444';
        ctx.beginPath(); ctx.arc(0, -50, 3, 0, Math.PI*2); ctx.fill();
    }
}

export interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'RING' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP';
    targetX?: number; // For BEAM
    targetY?: number; // For BEAM
    delay?: number;
    image?: HTMLCanvasElement; // For SPRITE type (Unit parts)
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export interface GridFlash {
    q: number;
    r: number;
    color: string;
    life: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];
    public gridFlashes: GridFlash[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            p.image = undefined; // Reset image reference
            p.delay = 0; // Reset delay
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK',
            delay: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        this.particlePool.push(p);
    }
}

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderableItem } from "../grid";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    // --- Rendering Collections ---
    // Items here are sorted by Y with units and terrain
    public collectRenderables(
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Physical Particles (Sorted with World)
        // Move SPRITE, SHARD, DEBRIS, CHIP here so they can be occluded by units/terrain
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            // Only Physical types
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE'].includes(p.type)) {

                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (offset > 800) return;

                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);

                // Sorting Y is the Ground Y (p.y). 
                // We add a small z-bias (5) so they appear slightly "in front" of the tile center if sitting on it
                list.push({
                    y: p.y + offset, 
                    z: 5, 
                    draw: (ctx) => {
                        // We must manually apply the transition offset to the Y position for drawing
                        // Save original, modify, draw, restore
                        const originalY = p.y;
                        p.y = originalY + offset - p.z; // Apply Z height and transition
                        ParticleRenderer.drawSingleParticle(ctx, p, progress, isChaos);
                        p.y = originalY;
                    }
                });
            }
        });

        // 3. Projectiles (Delegated)
        list.push(...ProjectileRenderer.collect(engine, getTerrainHeight, transitionT, transitionPhase));

        return list;
    }

    // Items here are drawn ON TOP of everything (Overlay VFX)
    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            // Skip physical types handled in collectRenderables
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            const originalY = p.y;
            p.y = drawY; 

            ParticleRenderer.drawSingleParticle(ctx, p, progress, isChaos);

            p.y = originalY; 
        });
    }
}

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Shared translation
        ctx.translate(p.x, p.y);

        if (p.type === 'SPRITE') {
            // UNIT PARTS (Physics Objects)
            if (p.image) {
                // Fade out later
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;

                // Draw shadow if close to ground
                if (p.z < 20) {
                    ctx.save();
                    ctx.translate(0, p.z); // Go back to ground 0 relative to particle visual Y
                    ctx.scale(1, 0.5);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.arc(0, 0, p.size/3, 0, Math.PI*2); ctx.fill();
                    ctx.restore();
                }

                ctx.rotate(p.rotation);
                const scale = p.size / 64; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'CHIP') {
            // STONE CHIPS / SPARKS (Solid, Impactful)
            // No glow, no stretch. Just small, hard debris.
            ctx.rotate(p.rotation); 
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 4); // Stay solid long, snap fade

            // Draw a small irregular quad
            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2);
            ctx.lineTo(0, -s);
            ctx.lineTo(s, -s/2);
            ctx.lineTo(0, s);
            ctx.fill();

        } else if (p.type === 'SHARD') {
            // PHYSICAL FRAGMENTS (Base/Armor chunks)
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;

            // Add fake 3D depth to shard
            ctx.beginPath();
            const s = p.size;
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

            // Highlight edge
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const r = p.size * (0.5 + progress * 2); 
            ctx.globalAlpha = (1 - progress) * 0.4;
            ctx.fillStyle = p.color; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'BLAST') {
            ctx.scale(1, 0.55); 
            const r = p.size * (progress * 2); 
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 5; 
            ctx.globalAlpha = (1 - progress) * 0.8;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(-p.x, -p.y); 
                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'SPARK') {
            const r = p.size;
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);

        } else if (p.type === 'PILLAR') {
            ctx.translate(0, -20); 
            this.drawPillar(ctx, p, progress, isChaos);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawDomain(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.globalCompositeOperation = 'lighter';
        const lifeRatio = p.life / p.maxLife;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 
        const height = 1200; 
        const baseWidth = 60 * (1 + Math.sin(progress * 20) * 0.1);

        ctx.save();
        ctx.scale(1, 0.55); 
        const ringSize = baseWidth * 2;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.2, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : '#fff');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
        coreGrad.addColorStop(0, '#ffffff');
        coreGrad.addColorStop(0.3, p.color);
        coreGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha;
        ctx.fillRect(-baseWidth * 0.5, -height, baseWidth, height);
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';
        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress);
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
    },

    drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         ctx.scale(1, 0.55); 
         const r = 250;
         ctx.globalCompositeOperation = 'lighter'; 
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');
         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.5 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

export function spawnDirectionalImpact(
    system: VFXSystem, 
    x: number, y: number, z: number,
    dirX: number, dirY: number, 
    color: string, 
    type: 'PHYSICAL' | 'MAGICAL'
) {
    const isPhysical = type === 'PHYSICAL';

    // 1. KINETIC CHIPS (The "Stone Struck" effect)
    // Solid particles, no streak/stretch, just pure physics debris
    const baseAngle = Math.atan2(dirY, dirX);
    const count = isPhysical ? 8 : 10;
    const spread = 0.8; 

    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 250 + Math.random() * 250; 
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 200; // Good vertical pop

        p.life = 0.6 + Math.random() * 0.4; 
        p.maxLife = p.life;
        p.color = isPhysical ? '#e2e8f0' : color; // Physical = White/Grey chips
        p.size = 3 + Math.random() * 3; 
        p.type = 'CHIP'; // New solid type
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random()-0.5) * 20; // Tumbling
        p.delay = 0;

        system.state.particles.push(p);
    }

    // 2. Dust Puff (Impact absorption)
    spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');

    // 3. Tiny Flash (Just a pinpoint)
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = z;
    flash.vx = 0; flash.vy = 0; flash.vz = 0;
    flash.life = 0.1; flash.maxLife = 0.1;
    flash.color = '#fff';
    flash.size = 20;
    flash.type = 'GLOW';
    system.state.particles.push(flash);
}

export function spawnConnectorSlash(
    system: VFXSystem,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string,
    visual: string
) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;

    p.life = 0.25; 
    p.maxLife = 0.25;
    p.color = color;
    p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);

    // Helper for Physics Sprites
    const spawnSprite = (img: HTMLCanvasElement, scale: number, zBase: number, vZ: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = zBase; 

        const angle = Math.random() * Math.PI * 2;
        const dist = 100 + Math.random() * 150; 

        p.vx = Math.cos(angle) * dist;
        p.vy = Math.sin(angle) * dist;
        p.vz = vZ;

        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff';
        p.size = 64 * scale; 
        p.type = 'SPRITE';
        p.image = img;
        p.rotation = Math.random() * Math.PI * 2;
        p.vRotation = (Math.random() - 0.5) * 20; 

        system.state.particles.push(p);
    };

    // 1. BASE CRACKING (Stone/Metal shards sticking to ground)
    const baseColor = '#52525b'; // Stone grey
    for (let i = 0; i < 6; i++) {
        const p = system.state.getParticle();
        const angle = (i / 6) * Math.PI * 2 + (Math.random()-0.5)*0.5;
        p.x = x; p.y = y; p.z = 5;
        const speed = 100 + Math.random() * 100;

        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 100; // Low pop

        p.life = 3.0; p.maxLife = 3.0;
        p.color = baseColor;
        p.size = 10 + Math.random() * 10;
        p.type = 'SHARD';
        p.rotation = angle;
        p.vRotation = (Math.random()-0.5)*10;
        system.state.particles.push(p);
    }

    // 2. BODY PARTS (Weapon & Icon fly high)
    spawnSprite(assets.weapon, 0.7, 50, 400); // High arc weapon
    spawnSprite(assets.icon, 0.6, 70, 300);   // Medium arc head

    // 3. CORE DEBRIS (Meat/Circuits)
    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';
    for (let i = 0; i < 8; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 40;
        const angle = Math.random() * Math.PI * 2;
        const speed = 50 + Math.random() * 150;

        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 150 + Math.random() * 150;

        p.life = 2.0; p.maxLife = 2.0;
        p.color = coreColor;
        p.size = 6 + Math.random() * 6;
        p.type = 'DEBRIS'; 
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random()-0.5) * 15;
        system.state.particles.push(p);
    }

    // 4. Ground Scorch
    addDecal(system, x, y, '#000'); 

    // 5. Dust Cloud
    spawnExplosion(system, x, y, 10, 8, '#71717a', 0.5, 1.0, 'SMOKE');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); 

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 

        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 20 + Math.random() * 30;

        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Center "Poof"
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
    addImpact(system, x, y, 5, '#ffffff', 'RING', 0.15);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; 
    p.color = color; p.size = 4;
    p.type = 'BEAM';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);

    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd;
        p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4);
        p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type;
        p.delay = 0;

        system.state.particles.push(p);
    }
}

export function spawnDebris(system: VFXSystem, x: number, y: number, color: string, count: number) {
    // Disabled for normal hits
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnPillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    spawnPillar(system, x, y, color, life, delay);
}

export function spawnPillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100;
    p.type = 'PILLAR';
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addGridFlash(system: VFXSystem, q: number, r: number, color: string) {
    system.state.gridFlashes.push({ q, r, color, life: 0.5 }); 
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { GameEngine, Agent } from "../game";
import { GameEvent, Team } from "../../types";
import { HexUtils } from "../utils";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING, UNIT_BODY_OFFSET } from "../../constants";

// Systems
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import * as VFXSpawners from "./vfx/spawners";

const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20;
// TA TUNING: Increased from 5.0s to 12.0s. 
// Auto-battler units have move/cast times that make 5s too strict for a Penta.
const KILL_STREAK_WINDOW = 12.0; 

export class VisualEventListener {
    // Kill Streak State: AgentID -> { Count, LastTime }
    private killStreaks = new Map<string, { count: number, lastTime: number }>();
    private firstBlood = false;

    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        // Reset Logic: If battle just started or reset, clear streaks
        if (engine.battleTime < 0.1) {
            this.killStreaks.clear();
            this.firstBlood = false;
        }

        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
            // This is the GROUND visual Y
            const visualGroundY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualGroundY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     // Highlight high damage
                     const isCrit = val > 100;
                     color = isCrit ? '#ef4444' : '#fff'; 
                     size = isCrit ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualGroundY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         // Reduced cast impact
                         camera.addTrauma(0.2); 
                     }
                 }
            }

            // 2. Kill Streaks (New)
            if (event.type === 'KILL' && event.sourceId) {
                const now = engine.battleTime;
                const killer = event.sourceId;
                const killerAgent = engine.agents.find(a => a.id === killer);

                // FIRST BLOOD LOGIC
                if (!this.firstBlood) {
                    this.firstBlood = true;
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        hud.addFloatingText(
                            killerAgent.px, 
                            killerAgent.py - kH - HUD_TEXT_OFFSET - 60, 
                            "FIRST BLOOD", 
                            "#ef4444", 
                            36, 
                            'KILL_STREAK'
                        );
                        camera.addTrauma(0.3);
                    }
                }

                let streak = 1;
                const existing = this.killStreaks.get(killer);

                if (existing) {
                    if (now - existing.lastTime <= KILL_STREAK_WINDOW) {
                        streak = existing.count + 1;
                    } else {
                        streak = 1; // Expired
                    }
                }

                this.killStreaks.set(killer, { count: streak, lastTime: now });

                // Trigger Visual if Streak > 1
                if (streak >= 2) {
                    let streakText = "";
                    let streakColor = "#fff";
                    let trauma = 0;

                    if (streak === 2) { streakText = "DOUBLE KILL"; streakColor = "#cbd5e1"; trauma = 0.2; }
                    else if (streak === 3) { streakText = "TRIPLE KILL"; streakColor = "#fcd34d"; trauma = 0.3; }
                    else if (streak === 4) { streakText = "QUADRA KILL"; streakColor = "#fb923c"; trauma = 0.4; }
                    else if (streak >= 5) { streakText = "PENTA KILL"; streakColor = "#ef4444"; trauma = 0.6; } // Epic

                    // Display above unit
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        // Offset higher than damage numbers
                        hud.addFloatingText(
                            killerAgent.px, 
                            killerAgent.py - kH - HUD_TEXT_OFFSET - 40, 
                            streakText, 
                            streakColor, 
                            32 + (streak * 4), // Scale up size with streak
                            'KILL_STREAK'
                        );

                        camera.addTrauma(trauma);
                    }
                }
            }

            // 3. VFX Handling
            switch (event.type) {
                case 'VISUAL_SLASH':
                    if (event.sourceId && event.targetId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        const target = engine.agents.find(a => a.id === event.targetId);
                        if (source && target) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                            const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                            const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                            VFXSpawners.spawnConnectorSlash(
                                vfx,
                                source.px, source.py - sH,
                                target.px, target.py - tH,
                                event.color || '#fff',
                                event.skill?.visual || 'SLASH'
                            );
                        }
                    }
                    break;

                case 'DAMAGE': 
                    const dmg = Math.abs(event.value || 0);
                    const isHeavy = dmg > 50; 

                    // Directional Impact Logic
                    let handled = false;
                    if (event.sourceId && event.targetId) {
                        const s = engine.agents.find(a => a.id === event.sourceId);
                        const t = engine.agents.find(a => a.id === event.targetId);
                        if (s && t) {
                            // Calc direction
                            // We use world coordinates (px, py) from Agent, which are flat.
                            const dx = t.px - s.px;
                            const dy = t.py - s.py;
                            const len = Math.sqrt(dx*dx + dy*dy);
                            if (len > 0) {
                                const dirX = dx / len;
                                const dirY = dy / len;

                                const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';

                                // CALCULATE DYNAMIC HIT HEIGHT
                                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;

                                VFXSpawners.spawnDirectionalImpact(
                                    vfx,
                                    event.pos.x, visualGroundY,
                                    bodyHeight, // Pass Z-height explicitly
                                    dirX, dirY,
                                    event.color || '#fff',
                                    type
                                );
                                handled = true;
                            }
                        }
                    }

                    if (!handled) {
                        // Fallback generic explosion
                        // Reduced particle count via factory
                        VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
                    }

                    if (isHeavy) {
                        // Only shake on heavy hits
                        camera.addTrauma(0.15);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualGroundY - 30; // Aim at chest

                            VFXSpawners.spawnBeam(vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(vfx, tx, ty, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    const dyingAgent = engine.agents.find(a => a.id === event.sourceId);
                    if (dyingAgent) {
                        VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, team, dyingAgent.role);
                    }
                    camera.addTrauma(0.3); 
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    VFXSpawners.spawnDomainShatter(vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    camera.addTrauma(0.1);
                    break;
            }
        });
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        // Find target for Z correction
        const target = engine.agents.find(a => a.id === event.targetId);
        const hitZ = target ? (target.physics.z + UNIT_BODY_OFFSET) : 25;

        if (isUlt) {
            camera.addTrauma(0.4); // Ult impact
            VFXSpawners.spawnDivinePillar(vfx, event.pos.x, visualY, color, 1.2);
            VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, color, 1.5);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                // --- AOE RIPPLE EFFECT RESTORED ---
                // Every tile gets a pillar, but with delay based on distance
                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const dist = HexUtils.dist(centerHex, h);
                        const delay = dist * 0.1; // Ripple

                        if (isUlt) {
                            VFXSpawners.spawnDivinePillar(vfx, tilePos.x, tileVisualY, color, 0.8, delay);
                        } else {
                            VFXSpawners.addImpact(vfx, tilePos.x, tileVisualY, 0, color, 'RING', 0.5);
                        }
                    }
                });

            } else {
                // Single Target Ult
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 2.0);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, hitZ, 30, color, 1.5, 0.8, 'SPARK');
            }
        } else {
            // Normal Projectile
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affected = HexUtils.range(center, radius);

                // Normal AOE Ripple
                affected.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;
                        const dist = HexUtils.dist(center, h);

                        if (Math.random() < 0.8) {
                            const p = vfx.state.getParticle();
                            p.x = tilePos.x; p.y = tileVisualY; p.z = 5;
                            p.delay = dist * 0.08;
                            p.life = 0.3; p.maxLife = 0.3;
                            p.color = color;
                            p.size = 0; // expand
                            p.type = 'RING'; // Blast Ring
                            vfx.state.particles.push(p);
                        }
                    }
                });

                // Add Decal at center
                VFXSpawners.addDecal(vfx, event.pos.x, visualY, color);
            } else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, hitZ, color, 'RING', 0.6);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, hitZ, 12, color, 1.0, 0.5, 'SPARK');
            }
        }
    }
}

export interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'RING' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP';
    targetX?: number; // For BEAM
    targetY?: number; // For BEAM
    delay?: number;
    image?: HTMLCanvasElement; // For SPRITE type (Unit parts)
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export interface GridFlash {
    q: number;
    r: number;
    color: string;
    life: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];
    public gridFlashes: GridFlash[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            p.image = undefined; // Reset image reference
            p.delay = 0; // Reset delay
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK',
            delay: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        this.particlePool.push(p);
    }
}

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderableItem } from "../grid";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    // --- Rendering Collections ---
    // Items here are sorted by Y with units and terrain (World Space)
    public collectRenderables(
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Physical Particles (Sorted with World)
        // Move SPRITE, SHARD, DEBRIS, CHIP here so they interact with depth correctly
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            // Only Physical types that should be occluded by units
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE'].includes(p.type)) {

                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (offset > 800) return;

                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);

                // Sorting Y is the Ground Y (p.y). 
                // We add a small z-bias (5) so they appear slightly "in front" of the tile center if sitting on it
                // We subtract p.z from visual drawing, but for sorting, we use the ground projection mostly
                list.push({
                    y: p.y + offset, 
                    z: 5, 
                    draw: (ctx) => {
                        const originalY = p.y;
                        p.y = originalY + offset - p.z; // Apply Z height and transition for drawing
                        ParticleRenderer.drawSingleParticle(ctx, p, progress, isChaos);
                        p.y = originalY; // Restore
                    }
                });
            }
        });

        // 3. Projectiles (Delegated)
        list.push(...ProjectileRenderer.collect(engine, getTerrainHeight, transitionT, transitionPhase));

        return list;
    }

    // Items here are drawn ON TOP of everything (Overlay VFX like flashes, text, magic circles)
    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            // Skip physical types handled in collectRenderables
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            const originalY = p.y;
            p.y = drawY; 

            ParticleRenderer.drawSingleParticle(ctx, p, progress, isChaos);

            p.y = originalY; 
        });
    }
}

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Shared translation
        ctx.translate(p.x, p.y);

        if (p.type === 'SPRITE') {
            // UNIT PARTS (Physics Objects)
            if (p.image) {
                // Fade out only at the very end
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;

                // Draw shadow if close to ground
                if (p.z < 20) {
                    ctx.save();
                    ctx.translate(0, p.z); // Go back to ground 0 relative to particle visual Y
                    ctx.scale(1, 0.5);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.arc(0, 0, p.size/3, 0, Math.PI*2); ctx.fill();
                    ctx.restore();
                }

                ctx.rotate(p.rotation);
                const scale = p.size / 64; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'CHIP') {
            // STONE CHIPS / SPARKS (Solid, Impactful)
            // No glow, no stretch. Just small, hard debris.
            ctx.rotate(p.rotation); 
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 4); // Stay solid long, snap fade

            // Draw a small irregular quad
            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2);
            ctx.lineTo(0, -s);
            ctx.lineTo(s, -s/2);
            ctx.lineTo(0, s);
            ctx.fill();

        } else if (p.type === 'SHARD') {
            // PHYSICAL FRAGMENTS (Base/Armor chunks)
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;

            // Add fake 3D depth to shard
            ctx.beginPath();
            const s = p.size;
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

            // Highlight edge
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const r = p.size * (0.5 + progress * 2); 
            ctx.globalAlpha = (1 - progress) * 0.4;
            ctx.fillStyle = p.color; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'BLAST') {
            ctx.scale(1, 0.55); 
            const r = p.size * (progress * 2); 
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 5; 
            ctx.globalAlpha = (1 - progress) * 0.8;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(-p.x, -p.y); 
                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'SPARK') {
            const r = p.size;
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);

        } else if (p.type === 'PILLAR') {
            ctx.translate(0, -20); 
            this.drawPillar(ctx, p, progress, isChaos);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawDomain(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.globalCompositeOperation = 'lighter';
        const lifeRatio = p.life / p.maxLife;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 
        const height = 1200; 
        const baseWidth = 60 * (1 + Math.sin(progress * 20) * 0.1);

        ctx.save();
        ctx.scale(1, 0.55); 
        const ringSize = baseWidth * 2;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.2, 0, 0, ringSize);
        ringGrad.addColorStop(0, isChaos ? '#000' : '#fff');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
        coreGrad.addColorStop(0, '#ffffff');
        coreGrad.addColorStop(0.3, p.color);
        coreGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha;
        ctx.fillRect(-baseWidth * 0.5, -height, baseWidth, height);
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';
        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress);
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
    },

    drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
         ctx.scale(1, 0.55); 
         const r = 250;
         ctx.globalCompositeOperation = 'lighter'; 
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); 
         grad.addColorStop(0.95, p.color); 
         grad.addColorStop(1, 'transparent');
         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.5 * (1 - progress); 
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

export function spawnDirectionalImpact(
    system: VFXSystem, 
    x: number, y: number, z: number,
    dirX: number, dirY: number, 
    color: string, 
    type: 'PHYSICAL' | 'MAGICAL'
) {
    const isPhysical = type === 'PHYSICAL';

    // 1. KINETIC CHIPS (The "Stone Struck" effect)
    // Solid particles, no streak/stretch, just pure physics debris
    const baseAngle = Math.atan2(dirY, dirX);
    const count = isPhysical ? 8 : 10;
    const spread = 0.8; 

    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 250 + Math.random() * 250; 
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 200; // Good vertical pop

        p.life = 0.6 + Math.random() * 0.4; 
        p.maxLife = p.life;
        p.color = isPhysical ? '#e2e8f0' : color; // Physical = White/Grey chips
        p.size = 3 + Math.random() * 3; 
        p.type = 'CHIP'; // New solid type
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random()-0.5) * 20; // Tumbling
        p.delay = 0;

        system.state.particles.push(p);
    }

    // 2. Dust Puff (Impact absorption)
    spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');

    // 3. Tiny Flash (Just a pinpoint)
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = z;
    flash.vx = 0; flash.vy = 0; flash.vz = 0;
    flash.life = 0.1; flash.maxLife = 0.1;
    flash.color = '#fff';
    flash.size = 20;
    flash.type = 'GLOW';
    system.state.particles.push(flash);
}

export function spawnConnectorSlash(
    system: VFXSystem,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string,
    visual: string
) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;

    p.life = 0.25; 
    p.maxLife = 0.25;
    p.color = color;
    p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);

    // Helper for Physics Sprites
    const spawnSprite = (img: HTMLCanvasElement, scale: number, zBase: number, vZ: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = zBase; 

        const angle = Math.random() * Math.PI * 2;
        const dist = 100 + Math.random() * 150; 

        p.vx = Math.cos(angle) * dist;
        p.vy = Math.sin(angle) * dist;
        p.vz = vZ;

        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff';
        p.size = 64 * scale; 
        p.type = 'SPRITE';
        p.image = img;
        p.rotation = Math.random() * Math.PI * 2;
        p.vRotation = (Math.random() - 0.5) * 20; 

        system.state.particles.push(p);
    };

    // 1. BASE CRACKING (Stone/Metal shards sticking to ground)
    const baseColor = '#52525b'; // Stone grey
    for (let i = 0; i < 6; i++) {
        const p = system.state.getParticle();
        const angle = (i / 6) * Math.PI * 2 + (Math.random()-0.5)*0.5;
        p.x = x; p.y = y; p.z = 5;
        const speed = 100 + Math.random() * 100;

        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 100; // Low pop

        p.life = 3.0; p.maxLife = 3.0;
        p.color = baseColor;
        p.size = 10 + Math.random() * 10;
        p.type = 'SHARD';
        p.rotation = angle;
        p.vRotation = (Math.random()-0.5)*10;
        system.state.particles.push(p);
    }

    // 2. BODY PARTS (Weapon & Icon fly high)
    spawnSprite(assets.weapon, 0.7, 50, 400); // High arc weapon
    spawnSprite(assets.icon, 0.6, 70, 300);   // Medium arc head

    // 3. CORE DEBRIS (Meat/Circuits)
    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';
    for (let i = 0; i < 8; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 40;
        const angle = Math.random() * Math.PI * 2;
        const speed = 50 + Math.random() * 150;

        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 150 + Math.random() * 150;

        p.life = 2.0; p.maxLife = 2.0;
        p.color = coreColor;
        p.size = 6 + Math.random() * 6;
        p.type = 'DEBRIS'; 
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random()-0.5) * 15;
        system.state.particles.push(p);
    }

    // 4. Ground Scorch
    addDecal(system, x, y, '#000'); 

    // 5. Dust Cloud
    spawnExplosion(system, x, y, 10, 8, '#71717a', 0.5, 1.0, 'SMOKE');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); 

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 

        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 20 + Math.random() * 30;

        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Center "Poof"
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
    addImpact(system, x, y, 5, '#ffffff', 'RING', 0.15);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; 
    p.color = color; p.size = 4;
    p.type = 'BEAM';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);

    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd;
        p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4);
        p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type;
        p.delay = 0;

        system.state.particles.push(p);
    }
}

